-- ============================================================
-- Ozbek2b (2/6) — DB kontentinin UZ tərcüməsi
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Cəmi: 6145 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz tez orada ranglarni bir-biridan ajratishni va o‘zi yoqtirgan ranglarni tanlashni boshlaydi. Shu sababli ranglarning nomlarini o‘rganishi unga ham yangi so‘zlarni o‘zlashtirishga, ham ranglarni aniqroq farqlashga yordam beradi. Unga ranglarni o‘rgatayotganda kundalik suhbatlaringizda rang nomlaridan foydalaning. Masalan, tashqarida itni ko‘rganingizda: Qara, bu it! deyish o‘rniga, Qara, bu qora it! deb tasvirlashingiz mumkin. Chaqalog‘ingiz ranglarni qiziqarli tarzda kashf qilishi uchun unga kamalak ranglaridagi rangli qalamlar olib berishingiz mumkin. Rasm chizayotganda ranglarni o‘zi tanlashiga ruxsat bering va u tanlagan rang nomini birgalikda takrorlang. Bu qiziqarli mashg‘ulot davomida e’tibor berishingiz kerak bo‘lgan jihat — chaqalog‘ingizga ranglarni o‘rganishi uchun bosim o‘tkazmaslikdir. Shuningdek, chaqalog‘ingiz qisqa vaqt ichida barcha ranglarni mutlaqo to‘g‘ri o‘rganib ololmasligini unutmang.') WHERE id = '32be02db-2c4a-4a1c-a266-929a18f6c892';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu bosqichda chaqalog‘ingizning liqildog‘i butunlay yopilishi kutiladi. Liqildoqning qotishi o‘rtacha 12-18-oylar oralig‘ida sodir bo‘ladi. Agar shu vaqtgacha chaqalog‘ingizning liqildog‘i yopilgan bo‘lsa, xavotirlanishga asos yo‘q. Ammo u hali ham yopilmagan bo‘lsa, bu har doim ham muammo borligini anglatmaydi, biroq holatni yaqindan kuzatish va ayrim tekshiruvlarni o‘tkazish talab qilinishi mumkin. Shifokoringiz 18-oydagi ko‘rikda liqildoq yopilgan yoki yopilmaganini tekshiradi. Agar yopilmagan bo‘lsa, shifokoringizdan batafsil ma’lumot olishingiz mumkin. Mutaxassislar liqildoqning kech yopilishi sabablari qatorida D vitamini yetishmovchiligi va gipotireozni (qalqonsimon bez faoliyatining pasayishi) ko‘rsatadilar. Bunday holatda shifokoringiz qalqonsimon bez gormonlarini tekshirish va D vitamini yetishmovchiligi bor-yo‘qligini aniqlash uchun ayrim biokimyoviy tahlillarni buyurishi mumkin.') WHERE id = '34c66686-e288-4c81-acc0-070c8d4b0acc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Mana, 1.5 yildan beri onasiz. Sizni tabriklaymiz! Chaqalog‘ingiz avvalgidan ham harakatchan bo‘ladigan davrga qadam qo‘ydingiz. Bu davr chaqalog‘ingizning kundalik faoliyati yanada mazmunli va maqsadli bo‘lib boradigan bosqichning boshlanishidir. Kichkintoyingiz endi qaysi xatti-harakatlarga ruxsat berilishi va qaysilari taqiqlanishini tushunadi hamda shunga qarab sizga mamnunligi yoki noroziligini ko‘rsata oladi. Siz to‘sqinlik qilishingizga qaramay, o‘zi xohlagan narsaga erishish uchun muloqotga kirishishi va o‘zini alohida shaxs sifatida aniqroq his qilishi mumkin. Ehtimol, endi u xohlagan narsasini kutishni istamaydi. Chunki bu yoshdagi chaqaloqlarda vaqt tushunchasi hali to‘liq shakllanmagan bo‘ladi. Masalan, chaqalog‘ingiz ovqatlanayotganda o‘yinchog‘ini xohlasa, Hozir ovqatlanish vaqti, o‘yinchog‘ing bilan keyin o‘ynaysan, deyishingiz uni chalg‘itishi mumkin. Shu sababli bu davrda chaqalog‘ingizga nisbatan yanada sabrli bo‘lishingiz kerak. Uning birozdan so‘ng va keyin kabi tushunchalarni anglab yetishi uchun hali vaqt kerak.') WHERE id = '466241d8-ca2b-43a2-bf81-53a5de3a0ea0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu oydagi rejalashtirilgan ko‘rik vaqtida shifokor chaqalog‘ingizni batafsil tekshiradi. Bunga tayyor bo‘lishingiz kerak. Ko‘rikda shifokor chaqalog‘ingizning jismoniy va aqliy rivojlanishini, bo‘yi va vazni yoshiga mos me’yoriy chegaralarda ekanini tekshiradi. Shuningdek, mayda va yirik motorika ko‘nikmalaridan qay darajada foydalana olishini bilish uchun sizga ayrim savollar berishi mumkin. Shu oydan boshlab chaqalog‘ingiz vaznining quyi chegarasi 8000 gramm, yuqori chegarasi esa 14.000 gramm bo‘lishi mumkin. Bo‘yi esa 75 sm bilan 87 sm oralig‘ida bo‘lishi kutiladi. Albatta, bu ko‘rsatkichlar o‘zgaruvchan bo‘lishi va chaqalog‘ingiz ushbu raqamlar chegarasidan tashqarida bo‘lsa ham sog‘lom bo‘lishi mumkinligini unutmang. Chaqalog‘ingizni tug‘ilgan kunidan buyon kuzatib kelayotgan shifokor sizga eng aniq ma’lumotni beradi. Ko‘rikka borishdan oldin sizni qiziqtirayotgan savollarni qog‘ozga yozib qo‘yish yaxshi fikr bo‘lishi mumkin.') WHERE id = '533e198b-5f73-4c58-b031-2b0fc6d70ee4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizga energiya bersa-da, uning jismoniy va aqliy rivojlanishini qo‘llab-quvvatlovchi oziq moddalarga ega bo‘lmagan mahsulotlar bo‘sh kaloriyali oziq-ovqatlar deb ataladi. Bunday mahsulotlar chaqalog‘ingizda kelajakda semizlik (ortiqcha vazn) xavfini oshiradigan omillardan biridir. Shu sababli chaqalog‘ingizga oziqaviy qiymati past bo‘lgan oq non berish o‘rniga, butun donli mahsulotlarni tanlashingiz kerak. Butun donlarning glikemik indeksi past, ya’ni ular qondagi qand miqdorining keskin ko‘tarilishi va tushishiga sabab bo‘lmaydi. Shu tariqa qandli diabet va insulin rezistentligi kabi holatlarning oldini olishga yordam berishi mumkin. Tolaga boy butun donlar chaqalog‘ingizning ovqat hazm qilish tizimiga ijobiy ta’sir qiladi va qabziyatga olib kelmaydi. Chaqalog‘ingizning ovqatlanish ratsioniga butun bug‘doy uni, bulg‘ur, yorma, jigarrang guruch va javdarni muntazam ravishda kiritishingiz mumkin.') WHERE id = '2fec9266-9a6a-4223-a4c3-f290f9054c35';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning bu oyda ham emlash taqvimi ancha tig‘iz. Immunitet tizimini mustahkamlash uchun emlash jadvaliga rioya qilish juda muhim. Chaqalog‘ingiz 18 oylik (1.5 yosh) bo‘lganida qilinishi kerak bo‘lgan vaksinalar: DaBT-İPA-Hib (besh komponentli aralash vaksina), poliomiyelit va Gepatit A vaksinalaridir. Besh komponentli aralash vaksina difteriya, ko‘kyo‘tal, qoqshol, poliomiyelit va B turdagi gemofil infeksiyaga qarshi himoyani birlashtiradi. Faolsizlantirilgan poliomiyelit vaksinasi chaqaloqni poliomiyelitdan himoya qiladi. Shuningdek, B turdagi gemofil infeksiyaga qarshi vaksina meningit, pnevmoniya va o‘rta quloq yallig‘lanishiga qarshi immunitet hosil qiladi. Bu kasalliklar xavfli va doimiy asoratlarni keltirib chiqarishi mumkinligi sababli vaksinalarni o‘z vaqtida oldirish juda muhim.') WHERE id = '1e4a79c4-2aff-4769-bbbf-b7ed53e1716f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Shakar ko‘plab oziq-ovqatlar tarkibida tabiiy ravishda mavjud bo‘lishi yoki ularga keyinchalik qo‘shilishi mumkin. Shakar energiya bersa-da, hech qanday oziqaviy qiymatga ega emas. Shu sababli u chaqaloqning rivojlanishini qo‘llab-quvvatlamaydi va uning ovqatlanish ratsionidan o‘rin olmasligi kerak. Xarid qilayotgan mahsulotlaringiz tarkibida glyukoza, fruktoza, dekstroza va saxaroza kabi shakar turlari bo‘lmasligiga e’tibor bering. Shakar tez odatlantiradigan modda bo‘lib, chaqalog‘ingiz uchun mutlaqo xavfsiz emas. Meva va sabzavotlardagi tabiiy shakar chaqalog‘ingiz uchun yetarli bo‘ladi. Oddiy shakar iste’moli qondagi shakar miqdorini keskin o‘zgartirishi sababli qandli diabet va semirish xavfini oshiradi hamda yurak salomatligiga salbiy ta’sir ko‘rsatadi. Mutaxassislar bolalarni maktab yoshiga yetguniga qadar oddiy shakar bilan tanishtirmaslikni tavsiya qiladilar.') WHERE id = '8dac80f3-aaa2-47a7-bba0-611d73c7f97e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning shu oydagi emlash taqvimiga kiritilgan poliomiyelit muvaffaqiyatli emlash ishlari tufayli dunyoda 99% ga kamaygan kasallikdir. Asosan 3-5 yoshli bolalarga ta’sir qiladigan bu kasallik ovqat hazm qilish tizimi orqali yuqadi hamda isitma, mushak og‘rig‘i, ko‘ngil aynishi va bo‘yin qotishiga sabab bo‘ladi. Bu yuqumli virus bosh miya va orqa miyaga ta’sir qilib, falajlikni keltirib chiqarishi mumkin. Kasallangan bolalar yurishda qiynaladi va tanasining ayrim qismlarini harakatlantira olmaydi. Virus najasda haftalab yashay olgani uchun yuqish ehtimoli katta. Shu sababli chaqalog‘ingiz va barcha bolalarning bu vaksinani olishi jamiyat salomatligi uchun juda muhim.') WHERE id = '1a8e6e94-b6f4-462b-8ffe-8f3b0bd314c0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Piyoz va sarimsoq iste’molining, ayniqsa chaqaloqlar uchun zarurligi xalq orasida ko‘p bahs qilinadigan mavzudir. Biroq shuni ta’kidlash kerakki, keng tarqalgan qarashlardan farqli ravishda, bu mahsulotlar chaqalog‘ingiz organizmi uchun juda foydali organik va noorganik moddalarga boy. Piyoz chaqalog‘ingizning immunitet tizimini himoya qilishga yordam beradigan ko‘p miqdordagi yallig‘lanishga qarshi (anti-inflammatory) moddalarni o‘z ichiga oladi. Shuningdek, organizmda temirning o‘zlashtirilishini yaxshilaydigan piyoz chaqalog‘ingizning yurak va qon tomirlari salomatligi uchun juda muhim oziq-ovqatdir. Sarimsoq esa, ayniqsa, shamollash paytida qo‘llanadi. Chunki uning tarkibidagi allitsid deb ataladigan modda kuchli viruslarga va bakteriyalarga qarshi xususiyatga ega. Allitsin moddasi sarimsoqqa o‘tkir hid beradi, shuningdek, chaqalog‘ingizda astma rivojlanishi ehtimolini sezilarli darajada kamaytiradi. Shu sababli, chaqalog‘ingizda piyoz va sarimsoqqa allergiya bo‘lmasa, taomlariga mazali ta’m berish va foydali moddalardan bahramand bo‘lishi uchun ularni qo‘shishingiz mumkin.') WHERE id = 'f5208cf0-5ee3-4de4-b5a0-87ec5de504e3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz 16-30 oylik davrda tez-tez jahl xurujlarini boshdan kechirishi mumkin. Bu xurujlar yig‘lash, qaysarlik qilish, o‘zini yerga tashlash, buyumlarni uloqtirish va atrofdagilarga zarar yetkazish ko‘rinishida namoyon bo‘lishi mumkin. Hatto ayrim chaqaloqlarda nafasini bir muddat ushlab turish, sochi va kipriklarini tortish ham bu davrdagi jahl belgilariga kiradi. Aslida, bular chaqalog‘ingiz rivojlanishining tabiiy jarayonidir. Qisqacha aytganda, bu bog‘liqlik bilan mustaqillikka erishish va alohida shaxs bo‘lib shakllanish o‘rtasidagi ichki ziddiyatdir. Chaqalog‘ingiz endi o‘z qarorlari va atrofidagi muhitda siz kabi so‘z egasi bo‘lishni istaydi. Istaklari bajarilmaganda yoki o‘zini ifodalay olmaganda jahl xurujlari yuzaga keladi. Eng muhimi, chaqalog‘ingiz bu jarayondan sog‘lom xulq-atvor ko‘nikmalarini egallab chiqishidir. Shu sababli bu harakatlar odatga aylanmasligi uchun u jahl qilgan paytda istagan narsasini bermang va xotirjamligingizni saqlang. Uni quchoqlab, qanchalik qattiq sevishingizni aytishingiz mumkin. Chunki mehr har qanday qiyinchilikni yenga oladi! 😊') WHERE id = '9f0c0e63-5e12-470a-97c1-46850067a0b3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizni ovqatlantirishda qo‘llaydigan 3 kun kutish qoidasi qo‘shimcha ovqatga o‘tish jarayonida uning oziq-ovqatlarga bo‘lishi mumkin bo‘lgan reaksiyalarini kuzatish uchun juda muhimdir. Bu qoida chaqalog‘ingizning ovqatlanish odatlari to‘liq shakllanguniga qadar amal qilishingiz kerak bo‘lgan usuldir. Chaqalog‘ingizning immunitet tizimi hali to‘liq rivojlanmagani sababli u ilgari tatib ko‘rmagan oziq-ovqatga allergik reaksiya bildirishi mumkin. Ayniqsa, allergen mahsulotlar ko‘p miqdorda iste’mol qilinganda, organizmning reaksiyasi ham shunchalik kuchli bo‘ladi. Shu sababli yangi oziq-ovqatlarni berishda bu ehtiyot choralariga rioya qilish kerak. Chaqaloqdagi allergiya belgilari faqat fiziologik bo‘lmasligi mumkin, shuning uchun u qat’iy rad etayotgan ovqatni majburlab yedirmaganingiz ma’qul. Agar chaqalog‘ingiz yangi ovqatni yeganidan keyin bezovtalik, ko‘ngil aynishi, qusish, ich ketishi, yig‘lash yoki uyqu bilan bog‘liq muammolarni boshdan kechirsa, unda shu ovqatga allergiya bo‘lishi mumkin. Bunday holatda bir muddatdan keyin uni yana sinab ko‘ring. Agar ayni belgilar takrorlansa, bu ovqatni ratsiondan butunlay chiqarib tashlang.') WHERE id = '8608ab19-70eb-4523-8e11-483348dadd13';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning shu oydagi emlash taqvimiga kiritilgan gepatit A — gepatit A virusi keltirib chiqaradigan, o‘ta yuqumli jigar infeksiyasidir. Bu virus jigar faoliyatiga ta’sir qilib, yallig‘lanishga olib keladigan gepatit viruslaridan biridir. Gepatit A hali ham butun dunyoda keng tarqalgan bo‘lib, odatda kuzda va qishning dastlabki oylarida ko‘proq uchraydi. Undan himoyalanishning eng samarali usuli — 12 va 24 oylikda qilinadigan vaksinalardir. 6 oylik tanaffus bilan yuboriladigan ushbu ikki doza chaqalog‘ingizni taxminan 20 yil davomida mazkur kasallikdan himoya qiladi. Vaksinaning mahalliy nojo‘ya ta’sirlari sifatida ukol qilingan joyda og‘riq, sezuvchanlik yoki qizarish kuzatilishi mumkin; bunday holat chaqaloqlarning 15-20% ida uchraydi. Isitma, ich ketishi va holsizlik kabi holatlar esa 10% dan kam kuzatiladi. Zarurat tug‘ilganda shifokor tavsiyasi bilan tarkibida paratsetamol bo‘lgan dorilardan foydalanishingiz mumkin.') WHERE id = '6b1536bb-dc88-4b75-bf0c-4f8004f171e6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz hali ham butilkadan foydalansa, endi bu odatni asta-sekin kamaytirish vaqti keldi. Butilka o‘rnini bosqichma-bosqich o‘rgatuvchi stakanlar, oddiy stakan yoki qoshiq egallashi kerak. Unutmang, butilkaga bog‘lanib qolish qancha uzoq davom etsa, undan voz kechish shuncha qiyin va og‘riqli jarayonga aylanadi. Agar chaqalog‘ingiz butilkani so‘rib uxlab qolsa, har safar uyg‘onganida ayni odatni takrorlashni talab qiladi. Bu esa uxlashga qarshilik ko‘rsatishi va qaysarlik qilishiga olib keladi. Butilkadan voz kechish uchun eng yuqori yosh chegarasi 2 yosh bo‘lsa-da, mutaxassislarning aksariyati bu jarayonni 2 yoshga to‘lmasdan yakunlashni tavsiya qiladi. Butilkadan uzoq vaqt foydalanish chaqalog‘ingizning tishlari salomatligi va jag‘ tuzilishiga salbiy ta’sir ko‘rsatishi mumkin. Shu sababli chaqalog‘ingizni stakandan foydalanishga undang. Buni majburlamasdan, masalan, uning sevimli qahramonlari tasvirlangan rang-barang stakanlarni tanlab, jarayonni yanada qiziqarli qilishingiz mumkin.') WHERE id = '3558e6e1-3996-42d0-9094-3715d454af37';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Mutaxassislar ilgari surgan bog‘lanish nazariyasiga ko‘ra, ehtiyojlari o‘z vaqtida va muntazam qondirilgan chaqaloqlarda o‘ziga va tashqi dunyoga nisbatan ijobiy tasavvur shakllanadi. Shu nuqtayi nazardan, chaqalog‘ingiz hayotining muayyan davrida siz bilan bir xonada uxlashi, sizning borligingiz va mehringizni his qilishi kerak. Shuningdek, ehtiyojlari tezda qondirilishini bilishi uning yig‘lashi va bezovtalik davrlarini qisqartiradi. Bu esa chaqalog‘ingizda asosiy ishonch hissining faol rivojlanishiga yordam beradi. Ammo bir xonada uxlash davrining eng yuqori chegarasiga yaqinlashayotganingizni unutmasligingiz kerak. Mutaxassislarning aksariyati bolalar 2 yoki eng kechi bilan 3 yoshga yetganda ota-onasidan alohida uxlashi kerak, deb hisoblaydi. Bu muddat qancha cho‘zilsa, chaqalog‘ingizning alohida xonada uxlashga qarshiligi shuncha kuchayadi va odatlaridan voz kechishi ko‘proq vaqt oladi. Agar chaqalog‘ingizni hali alohida uxlashga o‘rgatishni boshlamagan bo‘lsangiz, asta-sekin harakatga o‘tishingiz kerak bo‘lishi mumkin. Masalan, chaqalog‘ingiz uxlab qolguniga qadar va uxlaganidan keyin ham bir muddat uning yonida qolishingiz bu bosqichni juda yumshoq o‘tishga yordam beradi.') WHERE id = '20063b79-c6ac-4e2d-80ba-90afeb71cf22';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz ayrim taomlarni tanlab yeyishi mumkin. Bunday paytda xayolingizga keladigan asosiy savol, ehtimol, uni ovqatlantirish uchun nima qilish kerakligi bo‘ladi. Avvalo, ovqat tanlaydigan chaqalog‘ingizga sabr bilan yondashishingiz kerak. Uni majburlash vaziyatni yanada murakkablashtirishi mumkin. Tadqiqotlarga ko‘ra, chaqaloq yangi tanishgan mahsulotni yoqtirish yoki yoqtirmasligini tushunishi uchun uni kamida 7, ko‘pi bilan 15 marta tatib ko‘rishi kerak. Biroq bu raqamlarni ketma-ket kunlar deb tushunmaslik lozim. Bir xil taomni 7 kun ketma-ket taklif qilishingiz chaqalog‘ingizning yanada keskin munosabat bildirishiga sabab bo‘lishi mumkin. Bu yerda maqsad — chaqalog‘ingiz yemagan mahsulotni muayyan tanaffuslar bilan turli usullarda qayta taklif qilish. Masalan, chaqalog‘ingiz karam yoki artishokdan tayyorlangan taomni yemasligi mumkin. Ammo bu uning karam yoki artishokli sho‘rvani ham yoqtirmasligini anglatadimi? Albatta, yo‘q. Shuning uchun chaqalog‘ingiz rad etgan mahsulotni qanday qilib boshqa shakllarda taklif qilish yoki qiziqarli tarzda bezatib taqdim etish mumkinligi haqida o‘ylab ko‘rishingiz mumkin.') WHERE id = '7f4447c8-54a4-4590-9ce6-4ab697ab8292';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz moddalar almashinuvining maqbul sharoitda ishlashi uning hozir ham, kelajakda ham sog‘lom va uzoq umr kechirishini ta’minlaydigan asosiy omillardan biridir. Qalqonsimon bez gormonlari chaqalog‘ingiz yurak mushagining qisqarish kuchi va nafas olish harakatlaridan tortib, ichaklarda moddalarning so‘rilishi va issiqlik hosil bo‘lishigacha, qizil qon hujayralarining yaratilishidan suyaklar rivojlanishigacha bo‘lgan ko‘plab muhim vazifalarda faol ishtirok etadi. Qalqonsimon bezning gormon ishlab chiqarishi chaqalog‘ingiz miyasida joylashgan gipofiz bezidan keladigan signallarga bog‘liq. Gipofiz bezidan ajraladigan tireotrop gormon qalqonsimon bezga yetib borib, unda gormonlar ishlab chiqarilishini ta’minlaydi. Chaqalog‘ingiz organizmi uchun juda muhim bo‘lgan bu tizim yod tanqisligi va ayniqsa qarindoshlar o‘rtasidagi nikoh tufayli yuzaga keladigan irsiy muammolar sababli ba’zan yetarlicha samarali ishlamasligi mumkin. Shu bois chaqalog‘ingizni muntazam ravishda shifokor ko‘rigidan o‘tkazib, qon tahlillarini nazorat qilib borishingiz muhim. Holsizlik, ishtahasizlik, vaznning tez ortishi yoki kamayishi, uyquchanlik va ko‘p terlash kabi holatlarni kuzatsangiz, albatta shifokoringizga murojaat qilishingiz kerak.') WHERE id = 'e05fab87-4d28-4824-90c1-9888d35bd222';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizni zararli ovqatlanish odatlari va nosog‘lom mahsulotlardan qanday himoya qilishingiz mumkin? Albatta, uni bunday mahsulotlar bilan umuman tanishtirmaslik orqali. Bu boradagi asosiy tamoyilingiz quyidagicha bo‘lishi kerak: chaqalog‘ingiz ta’mini bilmagan mahsulotni so‘ramaydi. Shu sababli chaqalog‘ingizda osongina qaramlik hosil qilishi mumkin bo‘lgan qovurilgan taomlar, shokolad, shakarli mahsulotlar va turli fastfudlarni hatto bir marta ham tatib ko‘rishiga yo‘l qo‘ymasligingiz kerak. Bu masalada turmush o‘rtog‘ingiz va yaqinlaringizdan yordam so‘rang. Fikringizni va buning sabablarini ularga tushuntiring. Agar chaqalog‘ingizda zararli odatlar paydo bo‘lishini istamasangiz, avvalo o‘z ovqatlanish tartibingizni yaxshilashdan boshlashingiz kerak. O‘zingiz iste’mol qiladigan mahsulotlarni chaqalog‘ingizga taqiqlash ham to‘g‘ri emas, ham muvaffaqiyatsizlikka olib keladigan yo‘ldir. Chaqalog‘ingiz, avvalo, oilada sizdan ko‘rgan xatti-harakatlarini o‘rnak qilib oladi. Shu sababli chaqalog‘ingiz uchun yaxshi namuna bo‘lishingiz kerak.') WHERE id = 'e3f55e9e-f1cb-4704-8833-dfaa00152285';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz, ayniqsa, kichik va yirik motorika ko‘nikmalari rivojlangani tufayli o‘z harakatlarini to‘liq boshqara boshladi. Ushbu rivojlanish natijasida kashf etgan yangi ko‘nikmalari chaqalog‘ingizning ota-onadan mustaqillashish va individuallashish davrini boshlab beradi. Yangi ko‘nikmalar chaqalog‘ingizga butunlay yangi dunyoni kashf etish imkonini yaratadi. Biroq individuallashishga intilishiga qaramay, chaqalog‘ingiz hamon ilk kunlardagidek ich-ichidan sizga qaytishni, bag‘ringizga panoh topishni istaydi. Chunki u kashf etayotgan bu yangi dunyo ayni paytda uni sizdan uzoqlashtirayotganini his qiladi va bu chaqalog‘ingizni bezovta qiladi. Aynan shu ichki ziddiyat tufayli chaqalog‘ingiz bu davrda ayrim tashvishli va ruhiy jihatdan og‘ir holatlarni boshdan kechirishi mumkin. Chaqalog‘ingizning bunday holatlariga qanday munosabat bildirishingiz juda muhim. Bu murakkab davrni tushunishingiz, chaqalog‘ingizga keraksiz to‘siqlar qo‘ymasligingiz va siz belgilagan chegaralar doirasida unga erkinlik berishingiz juda muhimdir.') WHERE id = '74802a2c-bfa6-467b-b33a-aee4b83ccdbc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ovqatlanish ratsioniga kiritgan tuxumning ham oqi, ham sarig‘i oziq moddalariga juda boy. Tuxum tarkibida A, B5, B12, B2, B6, D, E va K vitaminlari, shuningdek, kalsiy, rux, fosfor, selen va folat kislotasi mavjud. Biroq chaqalog‘ingiz uchun juda muhim bo‘lgan bu mahsulot yaxshi pishirilmasa, ayrim muammolarga olib kelishi mumkin. Salmonella bakteriyasi asosan qushlar, shuningdek, boshqa hayvonlar va odamlarning ichak tizimida yashaydi. Odatda u hayvon najasi bilan ifloslangan oziq-ovqatlarni iste’mol qilish orqali odamlarga yuqadi. Shu sababli tuxumni chaqalog‘ingizga berishdan oldin uni to‘g‘ri pishirishingiz kerak. Uni o‘rtacha 10 daqiqa qaynatish va hech bir qismi xom qolmaganiga ishonch hosil qilish muhim. Chunki tuxum, parranda go‘shti, xom sabzavot va mevalar kabi xavfli oziq-ovqatlarni yaxshilab pishirish salmonella bakteriyasini yo‘q qiladi. Biroq tuxum me’yoridan ortiq qaynatilsa, oziqaviy qiymatini yo‘qotishini ham hisobga olishingiz kerak. Shuning uchun pishirish vaqtini to‘g‘ri belgilashingiz lozim.') WHERE id = 'e467989b-610e-431a-a5b3-8aea02815e27';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizga bo‘lishishni o‘rgatish siz va turmush o‘rtog‘ingiz zimmasidagi vazifadir. Bu davrda chaqalog‘ingiz o‘z buyumlarini qizg‘anishi va ba’zan ularni boshqalar bilan bo‘lishishni istamasligi tabiiy holat. Biroq chaqalog‘ingiz bo‘lishishni ham o‘rganishi kerak. Ayniqsa, yolg‘iz o‘sayotgan bolalarda aka-uka yoki opa-singillari bilan ulg‘ayayotgan bolalarga qaraganda rashk va qizg‘anish hissi kuchliroq bo‘ladi. Bo‘lishishni biladigan chaqalog‘ingiz kelajakda do‘stlar orttirish va jamiyatga moslashishda o‘zini erkinroq his qiladigan, o‘ziga ishongan inson bo‘lib yetishishi mumkin. Aksincha, bunday tushunchaga ega bo‘lmagan chaqaloqlar kelajakda qizg‘anchiq, boshqalar bilan chiqisha olmaydigan, odamovi, muhitga moslashishi qiyin va hatto ayrim hollarda tajovuzkor xatti-harakatlarni namoyon qilishi mumkin. Shu sababli mutaxassislar oilalar chaqalog‘iga 3 yoshgacha bo‘lishish hissini va bu tushunchani qanday shakllantirishni o‘rgatishi kerak, deb hisoblaydi. Chaqalog‘ingiz uchun o‘rganishning eng samarali yo‘li — bo‘lishishni amalda sinab ko‘rish, uni boshdan kechirish va, eng muhimi, atrofdagilarni kuzatishdir. Shuning uchun ishni o‘z xatti-harakatlaringizdan boshlashingiz kerak.') WHERE id = '97d2971b-be18-4119-ba9c-e15cc4978bea';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Yog‘lar chaqalog‘ingiz tanasining energiyaga bo‘lgan ehtiyojini qondirish bilan birga A, D, E va K kabi vitaminlarning o‘zlashtirilishini ta’minlaydi. Shuningdek, chaqalog‘ingizga zarur energiya iste’mol qilgan uglevodlardan yetarlicha olinmasa, tanada to‘plangan yog‘lar sarflana boshlaydi. Oziq-ovqat orqali olinadigan yog‘lar organizmda ishlab chiqarilmaydigan yog‘ kislotalari bilan ta’minlaydi hamda o‘sish va rivojlanishni qo‘llab-quvvatlaydi. Bundan tashqari, ular ovqat hazm qilish tizimining to‘g‘ri ishlashiga yordam beradi, hujayra membranalari va terining elastikligini ta’minlaydi. Biroq chaqalog‘ingizning yog‘larga bo‘lgan ehtiyojini to‘yingan yog‘lardan emas, to‘yinmagan yog‘ kislotalaridan qondirishga e’tibor berishingiz kerak. Omega-3, Omega-6 va Omega-9 chaqalog‘ingizning sog‘lom rivojlanishi uchun eng foydali yog‘lar qatoriga kiradi. Bu yog‘lar eng ko‘p baliqda, shuningdek, ona suti, tuxum, sigir suti, zig‘ir urug‘i, funduq, avokado va zaytun moyida mavjud.') WHERE id = '026bfc7a-ffb1-444b-accf-fb194f005a8f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning immun tizimi infeksiyalarga yetarlicha qarshi kurasha olishi uchun organizmda yetarli miqdorda oq qon hujayralari (leykotsitlar) ishlab chiqarilishi kerak. Oq qon hujayralari organizmning eng muhim himoya vositalaridir. Ular chaqalog‘ingiz tanasiga kirgan zararli mikroorganizmlarni yo‘q qiladi. Organizmga kiradigan mikroorganizmlar soni oshgani sari suyak ko‘migi ko‘proq oq qon hujayralarini ishlab chiqara boshlaydi. Biroq oq qon hujayralari tuzilishi uchun zarur bo‘lgan oqsil yetishmasa, bu jarayon sekinlashadi. Shu sababli chaqalog‘ingiz har kuni oqsil iste’mol qilishi muhim. Qizil go‘sht, oq go‘sht va baliq yuqori sifatli oqsil manbalaridir. Ammo ularni me’yoridan ortiq iste’mol qilish nojo‘ya ta’sirlarga olib kelishi mumkin, chunki hayvonlardan olinadigan bu oqsilli mahsulotlarda to‘yingan yog‘lar ham ko‘p bo‘ladi. Shu sababli chaqalog‘ingiz menyusiga o‘simlik va hayvonlardan olinadigan oqsil manbalarini navbatma-navbat kiritishingiz kerak.') WHERE id = '4719da49-3633-43ff-be20-a04c8e0aa86d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Odatda chaqaloqlar uchun taomlar ziravorlarsiz va ta’mi kuchsiz qilib tayyorlanadi. Bunga ziravorlar chaqaloqlarga zarar yetkazishi mumkin, degan fikr sabab bo‘ladi. Mutaxassislarning fikricha, bu holat kelajakda chaqalog‘ingizning ovqat tanlaydigan bo‘lib qolishiga va ayrim ovqatlanish buzilishlariga olib kelishi mumkin. Ziravorlar antioksidant va yallig‘lanishga qarshi xususiyatlarga juda boy. Ya’ni ular yallig‘lanishga qarshi kurashish, qon bosimini tartibga solish va erkin radikallar yetkazadigan zararning oldini olishda juda foydali. Chaqalog‘ingiz taxminan 8 oylik bo‘lganidan keyin uning taomlariga istagan ziravorlaringizni qo‘shishingiz mumkin. Qora murch, rayhon, rozmarin, dolchin, yalpiz, zanjabil, shivit, zira, zarchava, tog‘jambil va shirin qizil qalampir chaqalog‘ingiz taomlarida bemalol ishlatishingiz mumkin bo‘lgan ziravorlar qatoriga kiradi. Biroq chaqalog‘ingizda ayrim moddalarga allergiya bo‘lishi mumkin. Shu sababli, agar ilgari ziravorlardan foydalanmagan bo‘lsangiz, shifokoringiz bilan maslahatlashganingiz ma’qul.') WHERE id = 'f9a4f3eb-06ba-4c9f-a773-98194dac485a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Har bir chaqaloqda defekatsiya (najas chiqarish) tezligi turlicha bo‘lishi mumkin. Bu davrda farzandingiz kuniga 3 marta yoki 3 kunda 1 marta najas chiqarishi mumkin. Chaqalog‘ingiz ovqat orqali olgan oziq moddalar hazm yo‘lida parchalanib, tarkibiy qismlarga ajraladi va organizmga zarur moddalar qonga o‘tadi. O‘zlashtirilmagan, organizm uchun keraksiz yoki zararli deb hisoblangan qoldiq moddalar esa yo‘g‘on ichakning oxirgi qismi — anus orqali tashqariga chiqariladi. Biroq bu mexanizm, asosan, ovqatlanish buzilishlari bilan bog‘liq muammolar sababli izdan chiqishi mumkin. Ayniqsa, qabziyat hayotning dastlabki yillarida juda ko‘p uchraydigan holatlardan biridir. Agar chaqalog‘ingiz tez-tez qabziyat bo‘lsa, ayrim jihatlarga e’tibor berishingiz kerak. Masalan, chaqalog‘ingizning ovqatlanish ratsionida kletchatka kam bo‘lsa, qabziyat yuzaga kelish ehtimoli juda yuqori. Bu holat chaqalog‘ingizda hatto anal yoriqlargacha bo‘lgan ayrim muammolarni keltirib chiqarishi mumkin. Kam suv ichishi va meva-sabzavotlarni yetarli miqdorda iste’mol qilmasligi ham qabziyatga zamin yaratadigan omillardandir.') WHERE id = '3f922ccb-ecc8-46e0-b9c5-bd13cc1f11df';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Hatto 1 donasi ham chaqalog‘ingizning C vitaminiga bo‘lgan kunlik ehtiyojining yarmini qoplaydigan brokkoli, ayniqsa, qish oylarida uning menyusida albatta bo‘lishi kerak bo‘lgan sabzavotlardan biridir. Kichkina daraxtga o‘xshash ko‘rinishi chaqalog‘ingizning e’tiborini jalb qilishi mumkinligi sababli, uni shaklini saqlagan holda pishirish yaxshi usuldir. Brokkoli tarkibidagi kletchatka tufayli chaqalog‘ingizning hazm qilish tizimini yengillashtirishga va uni qabziyat kabi noqulayliklardan himoya qilishga yordam beradi. Chaqalog‘ingizning kalsiy, magniy, temir, selen, marganes, kaliy va rux kabi minerallarga, shuningdek, C, A, B16, B2 va E vitaminlariga bo‘lgan ehtiyojini ham brokkoli yordamida oson qondirishingiz mumkin. Brokkoli tarkibidagi sulforafan moddasi chaqalog‘ingizning miya hujayralariga ijobiy ta’sir ko‘rsatadi. So‘nggi yillardagi tadqiqotlarga ko‘ra, sulforafan saqlovchi oziq-ovqatlarni iste’mol qilish miya faoliyati buzilishlarini davolashda foydalidir. Brokkolining eng yuqori qismidagi kurtaklari boshqa qismlariga qaraganda 20 marta ko‘proq sulforafan saqlaydi, shuning uchun chaqalog‘ingiz aynan shu qismini yeganiga ishonch hosil qilishingiz kerak.') WHERE id = 'fdc70af8-a3f8-4766-bbcc-b755e0c46b80';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz organizmi, xuddi kattalarniki kabi, kunning turli vaqtlarida tana muvozanatini ta’minlaydigan gormonlarni ishlab chiqaradi. Kun davomidagi mashg‘ulotlar, jismoniy faollik, ovqatlanish va ruhiy holat bu gormonlarning ajralishiga bevosita ta’sir qiladi. Juda sezgir bo‘lgan melatonin gormoni chaqalog‘ingiz organizmi faoliyatida muhim rol o‘ynaydi. Organizmning biologik ritmi va soatini tartibga soluvchi bu gormon faqat tunda ishlab chiqariladi. Shu sababli chaqalog‘ingiz eng kechi bilan soat 21:00-da uxlagan bo‘lishi kerak. Melatonin ajralishi 21:00-da boshlanadi, 02:00-04:00 oralig‘ida eng yuqori darajaga yetadi va quyosh chiqishi bilan tugaydi. Melatonin gormoni chaqalog‘ingiz organizmi kechki payt issiqlik yo‘qotmasligi uchun tana haroratini pasaytiradi, ertalab esa uni kundalik faoliyatga tayyorlash uchun oshiradi. Miyada ishlab chiqariladigan bu gormon organizmdagi ritmik kimyoviy reaksiyalar natijasida hosil bo‘ladigan zaharli chiqindilardan ham himoya qiladi. Shu sababli chaqalog‘ingiz muntazam va uzluksiz tungi uyquga muhtoj. Melatonin samarali ishlab chiqarilishi uchun uni tungi uyquga yaxshilab tayyorlashingiz kerak.') WHERE id = 'a646f4e5-416b-4526-927d-bbba8c238b7c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Avokado ta’mi hammaga ham yoqavermasa-da, u chaqalog‘ingiz uchun A, K, E, C va B6 vitaminlari jihatidan juda foydalidir. Oson hazm bo‘ladigan mahsulot bo‘lgani uchun avokado chaqalog‘ingiz har qanday davrda bemalol iste’mol qilishi mumkin bo‘lgan mevadir. Tarkibidagi kalsiy, temir, kaliy, natriy va magniy minerallari tufayli chaqalog‘ingizning immun tizimini mustahkamlashga va kasalliklarga chidamliligini oshirishga yordam beradi. Oshqozonda kislota ajralishini nazorat qiladigan avokado antioksidantlari tufayli chaqalog‘ingiz organizmini erkin radikallarning zararli ta’siridan himoya qiladi. Shuningdek, yallig‘lanishga qarshi ta’siri isbotlangani sababli yaralarning tez bitishiga va to‘qimalar hosil bo‘lishining kuchayishiga yordam beradi. To‘yinmagan yog‘larga boy avokado chaqalog‘ingizning ko‘zlari va miyasi salomatligi uchun foydali mahsulotlar orasida yetakchi o‘rinlardan birini egallaydi. Shu sababli chaqalog‘ingizning ovqatlanish ratsioniga avokadoni tez-tez kiritishingiz kerak.') WHERE id = '1969883b-6fe0-4fba-a431-9f9a2571a7b1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Antibiotiklarning kashf etilishi va insoniyat foydalanishi uchun taqdim etilishi dunyo tarixida millionlab odamlarning hayotini saqlab qolgani sababli burilish nuqtasi hisoblanadi. Biroq juda qisqa vaqt ichida antibiotiklardan noto‘g‘ri va haddan tashqari foydalanish oqibatida ko‘plab bakteriyalar ularga nisbatan chidamlilik (rezistentlik) hosil qilgani ma’lum bo‘ldi. Antibiotikni zaruratsiz qo‘llash chaqalog‘ingizga foydadan ko‘ra ko‘proq zarar yetkazishi mumkin. Antibiotiklar chaqalog‘ingizning ichak florasini o‘zgartirib, foydali mikroorganizmlarni yo‘q qiladi va eng muhim himoya mexanizmi bo‘lgan shilliq qavat immunitetini zaiflashtiradi. Shu sababli shifokoringiz tavsiya qilmaguncha chaqalog‘ingizga antibiotik bermasligingiz juda muhim. Anacan oilasi sifatida chaqalog‘ingiz salomatligi uchun bu masalada ehtiyotkor bo‘lishingizni tavsiya qilamiz.') WHERE id = '6e624b3e-94c9-432e-8301-03c5530ae9b0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqning siyish paytida yig‘lashi va og‘riq his qilishi ota-onalarni jiddiy tashvishga soladigan holatlardan biridir. Odatda siydik yo‘llari infeksiyasi tufayli yuzaga keladigan bu muammo o‘g‘il chaqaloqlarga qaraganda qiz chaqaloqlarda ko‘proq kuzatiladi. Buning sababi qizlarda siydik chiqarish kanalining qisqaroq bo‘lishidir. Siydik yo‘llarining tuzilishi bakteriyalarning oson ko‘payishi va yallig‘lanish keltirib chiqarishi uchun qulay muhit yaratadi. Odatda taglikdagi najas tarkibidagi bakteriyalar chaqaloq organizmiga kirib, siydik yo‘llari infeksiyasini keltirib chiqaradi. Shuning uchun chaqalog‘ingizning tagligini uzoq vaqt almashtirmay qo‘ymasligingiz va uni tez-tez almashtirishingiz kerak. Shuningdek, qiz chaqaloqlar sezgirroq bo‘lgani uchun ularning tagini old tomondan orqaga qarab tozalash lozim. Bu najasdagi bakteriyalarning siydik yo‘llariga o‘tish xavfini kamaytiradi.') WHERE id = 'a63b7d54-8539-443a-910e-c4d4fabbbddd';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz 2 yoshga to‘lishiga 6 oydan kam vaqt qoldi. Bu esa 2 yosh inqirozi belgilarini asta-sekin seza boshlashingiz mumkinligini anglatadi. Aslida, 2 yosh inqirozi chaqaloqning mustaqil bo‘lish istagi bilan yolg‘iz qolish qo‘rquvi o‘rtasidagi ichki kurash natijasida yuzaga keladi. Bu davr chaqalog‘ingiz atrofidagilar bilan ustunlik uchun kurashadigan, ikkilanishni boshdan kechiradigan va hamma narsaga «yo‘q» deydigan bosqichdir. Ehtimol, chaqalog‘ingizning rivojlanishi davomida sizdan eng ko‘p sabr talab qiladigan davrga qadam qo‘ymoqdasiz. Hamma narsaga qarshilik ko‘rsatadigan va aytganini qildirishni istaydigan kichkintoyingiz bu davrda uxlash va ovqatlanishga qarshilik qilishi mumkin. Gapga quloq solmaslik, injiqlik qilish yoki aytilgan narsaning teskarisini bajarish bu davrning tabiiy xususiyatlaridir. Siz qo‘yishingiz kerak bo‘lgan birinchi qadam — u bilan qaysarlashmaslik. Chunki bu qaysarlik hozircha chaqalog‘ingiz o‘z irodasi bilan boshqara oladigan darajada emas.') WHERE id = '7b32ecb7-fa8a-4af5-ac5a-5dca59e6ac47';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz tug‘ilganida tanasining taxminan 75%-i suvdan iborat bo‘lsa-da, 1 yoshdan keyin bu ko‘rsatkich kattalarnikiga tenglashadi. Uning suyuqlikka bo‘lgan ehtiyojini qondirish uchun turli usullarni sinab ko‘rishingiz mumkin, ammo tarkibida hech qanday xushbo‘ylantiruvchi yoki ta’m beruvchi qo‘shimcha bo‘lmagan suv chaqalog‘ingiz uchun eng yaxshi tanlov ekanini unutmang. Chaqaloq qancha suv ichishi kerakligi haqidagi savol sizni o‘ylantirishi mumkin. Bilishingiz kerak bo‘lgan asosiy jihat shuki, suvga bo‘lgan ehtiyoj yosh ulg‘aygani sari o‘zgaradi. Ona suti yoki sun’iy ozuqa miqdori kamayib, qattiq ovqatlar ulushi ortgani sayin chaqaloq organizmining suvga bo‘lgan ehtiyoji ham oshadi. Shuningdek, chaqaloqning bo‘yi, vazni, siydigining rangi va hidi unga qancha suv berishingiz kerakligi haqida ma’lumot beradi. Bu bosqichda chaqalog‘ingiz kuniga o‘rtacha 1000-1300 ml suv iste’mol qilishi tavsiya etiladi.') WHERE id = '673e0121-ceca-4086-948c-fac61558696d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz ovqatlanishida ishlatiladigan yog‘lar to‘yingan, bir to‘yinmagan va ko‘p to‘yinmagan kabi turli turlarga bo‘linadi. Go‘sht, tuxum, sut va sut mahsulotlaridan olinadigan yog‘lar hayvonlardan olinadi va to‘yingan yog‘lar guruhiga kiradi. Zaytun va funduq yog‘lari bir to‘yinmagan, makkajo‘xori va kungaboqar yog‘lari esa ko‘p to‘yinmagan yog‘lar sirasiga kiradi. Shifokorlar ko‘proq to‘yinmagan yog‘ kislotalarini iste’mol qilishni tavsiya etadilar. Bu yog‘lar chaqalog‘ingizning sog‘lom o‘sishi va rivojlanishida muhim rol o‘ynaydi. Biroq ortiqcha yog‘lar organizmda to‘planishiga e’tibor berishingiz kerak. Chaqalog‘ingiz organizmi ham kattalarniki kabi yog‘ni cheksiz miqdorda to‘plash xususiyatiga ega. Shu sababli chaqalog‘ingizning ovqatlanish tarziga e’tibor berishingiz va kelajakda semizlik kabi turli kasalliklardan himoyalanishi uchun uning kun davomida yetarlicha faol bo‘lishini ta’minlashingiz kerak.') WHERE id = '8f5d01a0-18e8-4008-8da6-4aa6dfa4f0b7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '19-oyiga qadam qo‘ygan chaqalog‘ingiz yangi yoshiga yana bir qadam yaqinlashdi. Bu davr hamon chaqaloq eng harakatchan bo‘ladigan paytdir. Shuning uchun chaqalog‘ingiz o‘z energiyasini sarflashi mumkin bo‘lgan faol muhitni yaratish va sarflagan energiyasini tiklashi uchun unga foydali oziq-ovqatlarni taklif qilish muhimdir. Chaqaloq tez o‘sishi uchun zarur energiyani oziq-ovqatlardan oladi, ammo ehtiyojdan ortiq olingan energiya organizmda to‘planishini unutmaslik kerak. Semizlik (obezite) butun dunyoda bo‘lgani kabi mamlakatimizda ham jiddiy salomatlik muammosidir. Semizlikning asosiy sababi sarflanadigan energiya olingan energiyadan kam bo‘lishidir. Bu davr juda faol o‘tsa-da, planshet, telefon va televizor chaqaloqning harakatini cheklaydigan asosiy omillardir. Jamiyatdagi vazni ko‘proq chaqaloq sog‘lomroq bo‘ladi degan tushuncha mutlaqo noto‘g‘ri. Agar bu vazn noto‘g‘ri ovqatlanish va kamharakatlik natijasida ortgan bo‘lsa, kelajakda jiddiy muammolarga olib kelishi mumkin.') WHERE id = 'ab96b17f-7a5e-402d-adf2-b939f4193cb3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqning bu oydagi vazni o‘g‘il bolalarda 9700 grammdan 14.500 grammgacha, qiz bolalarda esa 9300 grammdan 13.800 grammgacha bo‘ladi. Bo‘yi esa o‘g‘il chaqaloqlarda 77 sm dan 89 sm gacha, qizlarda 75 sm dan 87 sm gacha o‘zgaradi. 19 oylik chaqaloq bosh aylanasining o‘lchami 46.7 sm dan 48 sm gacha bo‘lishi mumkin. Shuningdek, liqildog‘i allaqachon to‘liq yopilgan bo‘lishi kutiladi. Agar chaqaloqning ko‘rsatkichlari bu oraliqlardan tashqarida bo‘lsa, bu har doim ham muammo borligini anglatmaydi. Ba’zan o‘lchamlar standartlardan farq qilishi mumkin va bunday holat shifokorning yanada muntazam nazoratini talab qilishi mumkin. Chaqaloq tanasining sog‘lom o‘lchamlari uning ovqatlanishi, kun davomida qanchalik faol bo‘lishi va yashash muhitiga qarab farq qilishi mumkinligini unutmang. Bundan tashqari, kichkintoyning o‘ziga xos gormonal muvozanati va ota-onasining tana tuzilishi ham bu ko‘rsatkichlarda muayyan farqlarni yuzaga keltirishi mumkin.') WHERE id = 'b2ab74b8-c58e-4be9-a2eb-0663883e5594';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz tish chiqarish davrida bo‘lsa, ayrim oziq-ovqatlarga nisbatan sezgirlik ko‘rsatsa yoki me’yoridan ko‘p meva yoxud meva sharbati iste’mol qilsa, ich ketishi odatiy hol deb hisoblanishi mumkin. Biroq bu sabablardan tashqari, chaqaloqda viruslar, bakteriyalar yoki parazitlardan kelib chiqadigan zararli mikroorganizmlar tufayli ham ich ketishi mumkin. Ich ketishi, eng oddiy ta’rif bilan aytganda, kunlik ich kelish sonining ko‘payishi va najasning suyuqlashishidir. Bunda najasda shilliq, ko‘pik, rang o‘zgarishi va yoqimsiz hid kuzatilishi mumkin. Shuningdek, ich ketishi bilan birga qorin og‘rig‘i va isitma ham tez-tez uchraydi. Ich ketishi chaqaloq organizmida minerallar va suyuqlikning tez hamda jiddiy yo‘qotilishiga olib keladi. Chaqaloq qanchalik kichik bo‘lsa, organizm uchun bu yo‘qotishning o‘rnini to‘ldirish shunchalik qiyin bo‘ladi. Shu sababli chaqaloqning ichi ketayotganini sezsangiz, uning yo‘qotgan suyuqlik va minerallarini albatta qayta to‘ldirishingiz kerak. Agar ich ketishi me’yoridan uzoqroq davom etmoqda deb hisoblasangiz, shifokorga murojaat qilish eng to‘g‘ri qaror bo‘ladi.') WHERE id = '23450294-8568-46fa-ae46-48adce4121ac';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz hozir juda serharakat davrda. Shu sababli uning tez charchab qolmasligi uchun ovqatlanish oralig‘ida va kunning birinchi yarmida beradigan yengil tamaddilaringiz katta ahamiyatga ega. Masalan, shinni (do‘shob) tarkibidagi tabiiy glyukoza va fruktoza tufayli chaqalog‘ingizga ko‘p energiya beradigan eng foydali mahsulotlardan biridir. U chaqaloqning kaliy, kalsiy va magniyga bo‘lgan kundalik ehtiyojining katta qismini qondirishi mumkin. Bundan tashqari, shinni tarkibida ko‘p miqdorda mis, marganes, temir, selen va B6 vitamini mavjud. Shinni o‘zining boy tarkibi bilan chaqaloqning ovqat hazm qilish tizimiga ijobiy ta’sir qiladi, qon aylanishini tartibga solib, yurak-qon tomir salomatligini qo‘llab-quvvatlaydi. Ayniqsa, fasllar almashinuvi va qish oylarida shinni iste’mol qilish immunitetni mustahkamlashning sinalgan usullaridan biridir. Biroq tarkibida uglevodlar ko‘p bo‘lgani sababli, chaqalog‘ingizga qancha shinni berish mumkinligi haqida shifokoringiz bilan maslahatlashganingiz ma’qul.') WHERE id = 'e24ba9b0-b589-4244-8a0c-fad5773debb9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu bosqichda chaqalog‘ingiz uxlash uchun o‘z xonasiga kirishni yoki beshigiga yotishni rad etishi mumkin. Uyqu tartibi butunlay buzilishi ehtimoli ham bor. Bularning barchasi sizni xavotirga solishi va uyqu tartibini qanday tiklash haqida savollar tug‘dirishi mumkin. U uxlab qolganidan ko‘p o‘tmay o‘rnidan turib, uy bo‘ylab sizni izlashi yoki yoningizga kelishi ham tabiiy holat. Shu sababli, chaqaloqning uyquga ketishini osonlashtiradigan va tun bo‘yi uzluksiz uxlashiga yordam beradigan usullarni sinab ko‘rishingiz mumkin. Masalan, uyqudan oldin chaqaloqqa haddan tashqari ko‘p qo‘zg‘atuvchi omillar ta’sir qilishini va uning juda serharakat o‘yinlar o‘ynashini cheklashingiz kerak. Kechki ovqat paytida iste’mol qiladigan ayron, sut va suyak iligi kabi mahsulotlar ham uning uyqusini keltirishi mumkin. Bundan tashqari, sokin musiqa, mehrli teginishlar va ertak o‘qib berish chaqaloqning tinchlanib, xotirjam uyquga ketishiga yordam beradigan ajoyib usullardir.') WHERE id = '99665c28-7011-4149-a303-4268bf5d91e2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloq ovqatlanishida mevalarning o‘rni juda katta. Tropik mevalar ham chaqaloq rivojlanishi uchun muhim moddalarga boy. Tropik mevalar deyilganda, avvalo, mango, avokado, banan, ananas, kivi, ajdar mevasi va kokos yodga tushadi. Ular orasida mango kaloriyasi pastligi va shamollashga qarshi samarali bo‘lgan karotinoidlarga boyligi bilan ajralib turadi. Ananas esa B vitaminlari va kamyob mineral — marganesga boy bo‘lgani uchun chaqaloq menyusidan albatta o‘rin olishi kerak. Marganes chaqaloq organizmida energiya ishlab chiqarish uchun zarur bo‘lgan mineral bo‘lib, tanadagi muhim fermentativ reaksiyalarda katta rol o‘ynaydi. Kivi tarkibidagi ko‘p miqdordagi C vitamini va antioksidantlar esa o‘pka kasalliklarining oldini olishga ko‘maklashadi va ayniqsa, astmasi borlar uchun foydalidir. Bu tropik mevalar yetilgan holda xarid qilinsa, pishirishga hojat qolmaydi va chaqalog‘ingiz uchun ham mazali, ham juda foydali oziq-ovqat bo‘la oladi.') WHERE id = '40757955-d7c5-4d49-9cae-8eaa0f33656e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz 1-2 yoshda kundalik oziq-ovqat ehtiyojining 40%ini ona sutidan, 60%ini esa qattiq ovqatlardan olishi kerak. Ushbu 60% ulush to‘liq sog‘lom va rivojlanishni qo‘llab-quvvatlaydigan mahsulotlardan iborat bo‘lishi lozim. Chaqalog‘ingiz taomlariga qo‘shadigan suyak bulyoni tarkibidagi vitaminlar, minerallar va ko‘p miqdordagi oqsil tufayli ovqatlanish ratsionida muhim o‘rin tutishi kerak. Ayniqsa, chaqalog‘ingiz infeksiyalar va kasalliklarga moyil bo‘lsa, suyak bulyonining immunitetni mustahkamlovchi ta’sirini unutmasligingiz kerak. Hali rivojlanayotgan ovqat hazm qilish tizimi suyak bulyonini oson o‘zlashtirgani uchun u yengil hazm bo‘ladigan oziq hisoblanadi. Shuningdek, suyak bulyoni tarkibidagi glitsin aminokislotasi chaqalog‘ingizning tinchlanishiga yordam beradi. Shu sababli, ayniqsa, kechki ovqatlarda suyak bulyonidan foydalanish chaqalog‘ingizning tun bo‘yi yaxshiroq va uzluksiz uxlashiga sharoit yaratadi.') WHERE id = 'a99c4566-939c-4943-915c-cf701b9d784c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu bosqichda chaqalog‘ingiz aytadigan so‘zlar hali to‘liq tushunarli bo‘lmasligi mumkin. Shunga qaramay, u siz aytgan gaplarni umuman olganda tushunadi. Bu chaqalog‘ingizning rivojlanib borayotgan nutq va idrok qobiliyatlari bilan bog‘liq. Masalan, chaqalog‘ingizga sanchqi desangiz, endi uning xayoliga qoshiq emas, aynan sanchqi keladi. Bu davrda chaqaloqlar o‘rtacha 10-30 ta ma’noli so‘zni ayta oladilar. Biroq bu so‘z boyligi ko‘pincha o‘zini to‘liq ifodalash uchun yetarli bo‘lmaydi. Shu sababli, chaqalog‘ingiz nima demoqchi ekanini tushunmaganingizda, u biroz jahli chiqib, injiqlik qilishi mumkin. Kamdan-kam hollarda bu holat yanada kuchayishi mumkin. Bunday paytlarda chaqalog‘ingiz nima demoqchi ekanini topishga harakat qilish va unga yordam berish vaziyatni yengillashtiradi. Uni diqqat bilan kuzatib, nimaga ehtiyoji borligini tushunishga harakat qiling; bu shunchaki qarab, kutib turishdan ko‘ra yaxshiroq yo‘ldir.') WHERE id = '062d06b6-6166-4367-8a34-fbca48b06a36';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz o‘sishi, moddalar almashinuvi to‘g‘ri ishlashi va sog‘lom immunitet tizimiga ega bo‘lishida vitaminlarning o‘rni beqiyos. C vitamini (askorbin kislotasi) tishlar, suyaklar va terining sog‘lom rivojlanishi uchun zarur bo‘lgan asosiy moddalardan biridir. Suvda eriydigan ushbu vitamin organizmda temirning so‘rilishi, kollagen ishlab chiqarilishi, qon tomirlarining himoyalanishi va ayrim gormonal bezlar sekretsiyasini ta’minlaydi. C vitamini organizmda to‘planmagani sababli, uni har kuni chaqalog‘ingizning ovqatlanish ratsioniga kiritish muhim. Bu vitamin immunitetni mustahkamlaydi, ko‘z salomatligini asraydi, temir tanqisligi anemiyasining oldini oladi va terini himoya qiladi. C vitaminiga boy mahsulotlar qatoriga limon, greypfrut, apelsin, qulupnay, ismaloq, kivi, yashil qalampir, pomidor va na’matak kiradi. Chaqalog‘ingiz ratsioniga ushbu mahsulotlarni muntazam kiritish orqali uning C vitaminiga bo‘lgan kundalik ehtiyojini qondirishingiz mumkin.') WHERE id = '26b228ac-1aa9-488c-8a24-c0b3f3f3a2a1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'So‘nggi yillarda ko‘plab mamlakatlarda tarqalgan qo‘l-oyoq-og‘iz kasalligi odatda yuqori harorat va teridagi toshmalar bilan namoyon bo‘ladi. Enteroviruslar sabab bo‘ladigan bu kasallik juda yuqumli bo‘lib, ayniqsa 3 yoshgacha bo‘lgan bolalarga ta’sir qiladi. Bahor va yoz oylarida ko‘proq uchraydigan ushbu kasallikning maxsus davosi yo‘q. Alomatlar holsizlik va charchoq bilan boshlanadi, so‘ngra 3-7 kun davom etadigan isitma kuzatilishi mumkin. Kasallik aksirish, yo‘talish va umumiy buyumlardan foydalanish orqali yuqishi sababli ayrim ehtiyot choralarini ko‘rishingiz kerak. Avvalo, chaqalog‘ingizga qo‘l yuvish odatini singdirish muhim. Shuningdek, park va bog‘cha kabi odamlar gavjum joylarda gigiyena qoidalariga e’tibor berishingiz lozim. Chaqalog‘ingizda ishtahasizlik, bezovtalik, yutishda qiyinchilik, terida toshmalar va isitmani sezsangiz, vaqtni boy bermay shifokorga murojaat qiling.') WHERE id = '19336517-e2f0-4382-a8b8-70339ad9e2b6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Juda serharakat chaqalog‘ingizning ovqatlanishdan bosh tortishi va o‘ynashda davom etishni istashi mutlaqo tabiiy. Bu bosqichda qilishingiz kerak bo‘lgan birinchi ish — ovqatlanish vaqtini qiziqarli qilishdir. Ayniqsa, ovqat stoliga o‘tirishni istamaydigan chaqalog‘ingiz uchun bu dastlab biroz qiyin bo‘lishi mumkin. Ko‘plab onalar bunday vaziyatda chaqaloqning e’tiborini chalg‘itish uchun televizorni yoqish yoki qo‘liga telefon berish kabi usullardan foydalanadilar. Biroq mutaxassislarning fikricha, bu juda zararli bo‘lishi mumkin. Tez orada odatga aylanadigan bu holat tufayli chaqalog‘ingiz bir muddatdan so‘ng xuddi shunday sharoit yaratilmasa, ovqatlanishdan bosh tortishi mumkin. Chaqalog‘ingizning likopchasiga u yeya oladiganidan ortiq ovqat solmaslik, oz miqdordagi turli xil taomlar bilan to‘yishini ta’minlash asosiy maqsadingiz bo‘lishi kerak. Meva va sabzavotlardan likopcha tayyorlashda tasavvuringizni ishga solib, turli hayvonlar shaklidagi qiziqarli bezaklar yaratishingiz mumkin. Bundan tashqari, chaqalog‘ingizning och qolishiga imkon berish uning ovqatlanishidagi eng muhim rag‘batlardan biridir. Agar chaqalog‘ingiz ovqatlanishni istamasa, ovqatlanish oralig‘ida berayotgan yeguliklaringizni qayta ko‘rib chiqishingiz kerak bo‘lishi mumkin.') WHERE id = '52d0e2f2-b989-4846-9b56-a7da0c0b96ca';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu davrda qiyin damlarni boshdan kechirayotganini bilamiz. Avvalgidan ko‘ra tez-tez qaysarlik qilishi, tajovuzkorlashishi va hamma narsaga yo‘q deyishi mutlaqo tabiiy. Bunday paytda chaqalog‘ingiz sizning yordamingiz, qo‘llab-quvvatlashingiz va mehrli bag‘ringizga muhtojligini unutmasligingiz kerak. Mustaqil shaxs sifatida shakllanish bosqichida ancha yo‘l bosgan bo‘lsa-da, chaqalog‘ingiz hali ham sizga bog‘liq ekanini eslatib o‘tmoqchimiz. Chaqalog‘ingizga mehringizni ko‘rsatishning eng samarali usuli — uni bag‘ringizga bosishdir. Quchoqlash chaqalog‘ingiz organizmida oksitotsin gormoni ajralishini ta’minlaydi. Qondagi oksitotsin miqdorining oshishi qisqa vaqt ichida chaqalog‘ingizning qon bosimini me’yorlashtira boshlaydi. Miyadagi zo‘riqishning kamayishi esa chaqalog‘ingizni tinchlantirib, stress va asabiylikni minimal darajaga tushiradi. Shu sababli, uning qaysarligini yenga olmayotgan va o‘zingizni chorasiz his qilayotgan paytingizda chaqalog‘ingizni bag‘ringizga bosish har ikkingizni ham ancha tinchlantiradi.') WHERE id = 'be155a78-d9a9-48f2-8fc6-0060381e54cd';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tug‘ilganidan boshlab dastlabki 3 yil chaqalog‘ingiz eng tez o‘sadigan davrdir. Shu sababli chaqaloqlik davridagi ovqatlanish uning kelajakda sog‘lom hayot kechirishi uchun juda muhim. Chaqalog‘ingiz jadal o‘sish uchun zarur bo‘lgan temir kabi minerallarni dastlab homiladorlik davrida organizmida to‘plangan zaxiralardan oladi. Keyinchalik qo‘shimcha ovqatga o‘tish davri boshlanganidan so‘ng, u barcha oziq-ovqat guruhlari orqali vitamin va minerallarga bo‘lgan ehtiyojini qoplaydigan ovqatlanish tartibiga ega bo‘lishi kerak. Temir chaqalog‘ingiz organizmida gemoglobin ishlab chiqarishda qatnashgani uchun qon hosil bo‘lishidagi asosiy moddalardan biridir. Bu mineralni qo‘shimcha preparat shaklida olish mumkin bo‘lsa-da, organizmga tabiiy yo‘l bilan tushadigan temir chaqalog‘ingiz uchun eng yaxshi tanlovdir. Temir tanqisligiga bog‘liq anemiya (kamqonlik) bolalar orasida keng tarqalgan muammodir. Shu sababli shifokoringiz belgilagan muddatlarda chaqalog‘ingizga muntazam ravishda qon tahlillarini topshirishingiz va u temirni tabiiy yo‘l bilan olishi mumkin bo‘lgan manbalarni yaxshilab o‘rganishingiz kerak.') WHERE id = '8ac73f53-1de0-40be-b034-69d10df7b9d6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Mutaxassislar tuvakka o‘rgatishni boshlash uchun eng maqbul vaqt taxminan 2 yosh deb hisoblasalar-da, bu jarayon chaqalog‘ingizning rivojlanishi va xohishiga qarab o‘zgarishi mumkin. Chaqalog‘ingiz tuvakka o‘rganishga tayyorligini ko‘rsatuvchi dastlabki belgilar — tagligi doimo toza bo‘lishini xohlashi va hojatga borishi kerakligini sizga bildirishidir. Bu davrda chaqalog‘ingiz qovug‘i yoki ichaklari to‘lganini his qila boshlaydi. Asab tizimi rivojlanishi bilan u qisqa vaqt bo‘lsa-da, hojatini ushlab tura oladi. Chaqalog‘ingizda bu belgilar hali kuzatilmasligi ham mutaxassislar tomonidan tabiiy holat deb hisoblanadi. Ayrim oilalar chaqalog‘ini tuvakka ertaroq o‘rgatishga shoshilishlari mumkin. Biroq tuvakka o‘rganishga tayyor bo‘lmagan chaqaloqni majburlash kelajakda o‘ziga ishonch, shaxsiyat va yaqin munosabat o‘rnatish bilan bog‘liq muammolarga sabab bo‘lishi mumkin. Shu sababli qilishingiz kerak bo‘lgan birinchi ish — chaqalog‘ingizni diqqat bilan kuzatishdir. Unutmang, tuvakka o‘rgatishni qachon boshlash masalasida sizning xohishingiz emas, chaqalog‘ingiz va uning rivojlanishi ustuvor ahamiyatga ega.') WHERE id = 'b7c4aaa4-3c12-4a76-a25b-a511c93b949a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingizni emizayotgan bo‘lsangiz, vitamin va minerallar bilan ta’minlash uchun emizishni 2 yoshgacha davom ettirish tavsiya etiladi. Agar emizmayotgan bo‘lsangiz, chaqalog‘ingiz organizmi kerakli moddalarni olishi uchun bir muddat sun’iy oziqlantirishni (keyingi bosqich sutli aralashmasini) davom ettirishingiz mumkin. Bulardan tashqari, ayniqsa mavsumiy mevalardan tayyorlanadigan sharbatlar chaqalog‘ingiz uchun juda foydali bo‘ladi. Uyda tayyorlagan qatiqdan qilingan ayron ham chaqalog‘ingiz menyusi uchun ajoyib tanlovdir. Agar chaqalog‘ingizga jo‘ka guli kabi o‘simlik choylarini berayotgan yoki bermoqchi bo‘lsangiz, shifokoringiz tavsiyasi bilan kuniga yarim stakandan oshirmagan holda ovqatlanish tartibiga kiritishingiz mumkin. Shuni unutmaslik kerakki, bu ichimliklarga ta’m berish maqsadida tuz yoki shakar qo‘shmaslik lozim. Shuningdek, chaqalog‘ingiz ichadigan ichimliklar uning kelajakdagi ta’mga bo‘lgan afzalliklarini shakllantirgani uchun bu davrda qo‘shimchalar va shakar saqlovchi ichimliklardan saqlanishingiz muhim.') WHERE id = 'a7ed9701-76a0-4a1a-9b67-c6c0cda6c5f1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ba’zan chaqalog‘ingiz odam gavjum joylarda yoki tengdoshlari orasida ular bilan muloqot qilish o‘rniga yolg‘iz qolishni afzal ko‘rayotganini kuzatishingiz mumkin. Bu davrda ayrim chaqaloqlar ijtimoiy muloqotdan chekinib, yolg‘iz o‘ynashni afzal ko‘rishi mumkin. Ayniqsa, anchadan beri yonida bo‘lgan va chaqalog‘ingiz o‘rganib qolgan o‘yinchoq uning muloqotga bo‘lgan ehtiyojini qondiruvchi vositaga aylangan bo‘lishi mumkin. Biroq buning o‘zi yetarli emas. Chaqalog‘ingiz boshqa tengdoshlari bilan muloqot qilishi va ijtimoiylashishni boshlashi uchun, avvalo, ularning ham o‘zi kabi alohida shaxs ekanini qabul qilishi lozim. Tengdoshlari bilan muloqot qilish, o‘yinchoqlarini baham ko‘rish va birga o‘ynash chaqalog‘ingizning kelgusi hayoti uchun yaxshi boshlanish bo‘ladi. Shu sababli chaqalog‘ingiz muntazam ravishda o‘yin guruhlariga qatnashishi yoki tengdoshlari bor boshqa muhitda bo‘lishi muhim. Bu davrda o‘yin chaqalog‘ingiz uchun juda samarali o‘rganish vositasidir. Anacan oilasi sifatida chaqalog‘ingizning ijtimoiylashishi uchun eng samarali usul sifatida o‘yindan foydalanishingizni tavsiya qilamiz.') WHERE id = '5f456e81-e768-4ef4-bab4-0c102aeccabb';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ayniqsa, havo soviganda yoki fasllar almashayotgan paytda chaqalog‘ingiz ovqatlanishiga ayrim o‘zgartirishlar kiritishingiz kerak bo‘lishi mumkin. Chaqalog‘ingiz iste’mol qiladigan oziq-ovqatlar uning immun tizimi va kasalliklarga qarshi kurashish mexanizmiga bevosita ta’sir qiladi. Shuning uchun mavsumiy sabzavotlar chaqalog‘ingiz uchun eng yaxshi tanlov bo‘lishi lozim. Qish oylarida chaqalog‘ingizning ovqatlanish ratsioniga kartoshka, sabzi va qalampir kabi sabzavotlarni tez-tez kiritish foydali. Agar chaqalog‘ingiz bu sabzavotlarni yeyishni yoqtirmasa, ularni tortish usulini o‘zgartirishingiz mumkin. Masalan, mavsumiy sabzavotlardan nachinka tayyorlab, butun donli undan xamir qorish orqali chaqalog‘ingiz uchun mini-pitsalar pishirishingiz mumkin. Bundan tashqari, turli souslar va ziravorlardan foydalanish ham chaqalog‘ingizga odatda yemaydigan sabzavotlarni yoqtirishiga yordam berishi mumkin.') WHERE id = 'f8162fd9-38d6-4525-aaf5-deae7bb7805e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz ayniqsa kasal bo‘lgan paytda burnining tez-tez bitishi yoki uxlayotganda xurrak otishi odatiy hol hisoblanishi mumkin. Bunga yuqori nafas yo‘llari infeksiyasi vaqtida hosil bo‘ladigan shilliq (mukus) nafas yo‘llarini to‘sib, nafas olishni qiyinlashtirishi sabab bo‘ladi. Biroq chaqalog‘ingizning burni tez-tez bitadigan bo‘lsa, bunga allergiya sabab bo‘lishi mumkin. Chaqalog‘ingizda biror allergik reaksiya kuzatilmasa ham, irsiy moyillikni hisobga olishingiz kerak. Mutaxassislarning fikricha, allergiyasi bor ota-onalarning farzandlarida xuddi shunday allergik belgilar paydo bo‘lish ehtimoli 70% gacha oshishi mumkin. Agar chaqalog‘ingiz ayniqsa uxlayotganda nafas olishda qiynalsa, shifokor bilan maslahatlashib, uning bosh tomonini biroz balandroq qilishingiz mumkin. Shunda chaqalog‘ingizning yuqori nafas yo‘llaridan havo osonroq o‘tadi va nafas olishi yaxshilanadi. Shuningdek, chaqalog‘ingiz kun davomida va ayniqsa tunda uxlaydigan xonadagi namlikni oshirish burun yo‘llarining ochiqroq turishiga yordam beradi.') WHERE id = 'be09f355-43f8-49f0-b63e-fac24b36b2bd';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz uchun BLW (mustaqil ovqatlanish) usulidan foydalanmayotgan bo‘lsangiz, uni boshlashga hali kech emas. BLW chaqalog‘ingiz shunchaki qornini to‘ydiradigan usul emas, balki uning jismoniy va aqliy rivojlanishiga ijobiy ta’sir ko‘rsatadigan yondashuvdir. Chaqalog‘ingiz mustaqil ovqatlanayotganida eng muhim jihat — beshta sezgi a’zosining ham faol ishlashidir. Chunki shu tariqa chaqalog‘ingiz oziq-ovqatlarning ta’mi, hidi va eng muhimi, teksturasini (tuzilishini) o‘rganadi, natijada uning sezgi rivojlanishi tezlashadi. Chaqalog‘ingizning mustaqil ovqatlanishi, nima va qancha yeyishini o‘zi hal qilishi uning shaxsiyati shakllanishi uchun poydevor yaratadi. An’anaviy ovqatlantirishdan farqli ravishda, chaqalog‘ingiz o‘zini cheklangandek his qilmaydi. Shu tariqa u ehtiyojiga yarasha ovqatlanadi va ortiqcha oziq-ovqat iste’mol qilishdan saqlanadi. Agar chaqalog‘ingizda to‘g‘ri ovqatlanish odati shakllanishini istasangiz, BLW eng yaxshi tanlovlardan biridir.') WHERE id = '5fba8804-2bcf-4056-a32b-0f60798a6016';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz juda sabrsiz bo‘lib, hamma narsa darhol sodir bo‘lishini yoki bajarilishini xohlashi mumkin. Odatda, bu holat uning vaqt qanday o‘tishi haqida hali tasavvurga ega emasligi bilan bog‘liq. Ayniqsa, o‘tmish va kelajak tushunchalari haqida hali to‘liq tasavvurga ega emas, ammo hozirgi vaqt tushunchasini yaxshi anglaydi. Chaqalog‘ingiz vaqtga oid boshqa tushunchalarni ham to‘g‘ri anglay olishi uchun hali taxminan 1 yil kerak bo‘ladi. Biroq bu bosqichda chaqalog‘ingizga sabr qilishni o‘rgatish uchun ayrim kichik usullardan foydalanishingiz mumkin. Masalan, chaqalog‘ingiz xohlagan narsasi darhol amalga oshishini talab qilsa, uning diqqatini boshqa tomonga yo‘naltirishga harakat qiling. «Kel, birga rasm chizamiz» yoki «Birga qo‘shiq aytamizmi?» kabi takliflar bering. Ayrim hollarda soatni ko‘rsatib, milning harakatini kuzatishini so‘rash ham foydali bo‘lishi mumkin. Agar chaqalog‘ingiz xohlagan narsani amalga oshirishning imkoni bo‘lmasa, unga bu istagini eslatadigan buyumni ko‘zdan yiroq joyga olib qo‘yganingiz ma’qul.') WHERE id = 'ea8f95c5-370c-4fef-9751-e75f7ae08232';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Shu oydan boshlab chaqalog‘ingizning ovqat hazm qilish tizimi kattalarniki kabi ishlay boshladi. Shunga qaramay, ovqat hazm qilish tizimining to‘liq shakllanishi 36-oygacha davom etishi mumkin. Chaqalog‘ingiz ovqat hazm qilish tizimining eng muhim qismi bo‘lgan ichaklarda bu rivojlanish yakunlangach, taxminan 100 million nerv hujayrasi bo‘ladi. Bu ichaklarda orqa miyaga nisbatan 10 marta ko‘proq nerv hujayrasi bo‘lishini anglatadi. Bugungi kunda ikkinchi miya deb ataladigan ichaklar salomatligi uchun chaqalog‘ingizning fermentlangan oziq-ovqatlarni iste’mol qilishi juda muhim. Fermentatsiya usulida tayyorlangan oziq-ovqatlar chaqalog‘ingizning ovqat hazm qilish tizimini tartibga solishga yordam beradi. Shu sababli chaqalog‘ingizning ovqatlanish ratsioniga qatiq, kefir va pishloq kabi fermentlangan oziq-ovqatlarni yetarli miqdorda kiritishingiz lozim.') WHERE id = 'f041f5ba-2299-4c38-afa9-5aced862a00f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz endi o‘yinchoqlari bilan yanada faolroq o‘ynay boshladi. Masalan, rivojlanishiga mos qiziqarli kitoblarning sahifalarini varaqlab, har bir yangi sahifadagi narsalarni uzoq vaqt sinchiklab tomosha qilishi mumkin. Kublar yoki qirrali o‘yinchoqlardan minoralar qura oladi. Bu minoralarni yoki ustma-ust terilgan o‘yinchoqlarni buzish esa uning eng sevimli mashg‘ulotlaridan biriga aylanishi mumkin. U qaysi o‘yinchog‘i qaysi tortmada ekanini eslab qolishi, o‘ynab bo‘lgach esa eslatishingiz bilan o‘yinchoqlarini joyiga yig‘ishi mumkin. Bularning barchasi chaqalog‘ingizning muloqot ko‘nikmalari va fikrini og‘zaki ifodalash qobiliyati ancha rivojlanganidan dalolat beradi. Chaqalog‘ingizning rivojlanishini qo‘llab-quvvatlash va turli yo‘nalishlarga qiziqishini oshirish uchun yangi o‘yinchoqlar izlay boshlashingiz mumkin. Masalan, barmoq bo‘yoqlari, LEGO, sodda pazllar, o‘yin xamiri va uycha o‘yinlari uchun kerakli jihozlar chaqalog‘ingizning rivojlanishi uchun juda mos tanlovdir. E’tibor berishingiz kerak bo‘lgan jihat shuki, chaqalog‘ingiz, ayniqsa, o‘yin xamiri kabi yangi materiallar bilan ilk bor o‘ynayotganida uni nazoratsiz qoldirmang. Maroqli o‘yinlar tilaymiz! 😊') WHERE id = '0094e862-06ed-4386-a5cf-c1f9439c8d66';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bugungi kunda semizlik ko‘payib borayotgan barcha mamlakatlarda diabet xavfi mavjud. Ilgari u eng erta 5-7 yoshda uchragan bo‘lsa, insulin yetishmovchiligi sababli rivojlanadigan 1-tip diabet hozir hatto chaqaloqlarda ham kuzatilishi mumkin. 1-tip diabet rivojlanganda hujayralar darajasida ochlik yuzaga keladi va jigarga ko‘proq energiya ishlab chiqarish uchun signallar yuboriladi. Bunday vaziyatda jigar energiya hosil qilish maqsadida yog‘larni tez sur’atda parchalashni boshlaydi. Yog‘lar parchalanishi natijasida organizmda ketonlar deb ataladigan kislotali moddalar paydo bo‘ladi. Ketonlar ko‘pincha ko‘ngil aynishi va qusishga sabab bo‘ladi. Ko‘p ovqatlanish va ishtaha oshishiga qaramay, vazn yo‘qotish ham tez-tez uchraydigan alomatdir. Bundan tashqari, qondagi qand miqdorining yuqoriligi tufayli yaralarning sekin bitishi, qiz chaqaloqlarning jinsiy a’zolari sohasida zamburug‘li infeksiyalar bilan bog‘liq qichishish va qizarishning tez-tez paydo bo‘lishi ham diabet alomatlari bo‘lishi mumkin. Shu sababli diabetni erta aniqlash juda muhim. Chaqalog‘ingizni muntazam ravishda shifokor ko‘rigidan o‘tkazish va tahlillarini o‘z vaqtida topshirish ehtimoliy diabetni erta aniqlashga yordam beradi.') WHERE id = 'fc4caf55-748d-4981-b396-817290848621';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning mavhum fikrlash qobiliyati bu bosqichda hali to‘liq rivojlanmagan. Shu sababli mantiqiy mulohaza yuritib, yangi xulq-atvorni o‘zlashtirishi ko‘pincha imkonsiz bo‘ladi. O‘zligini anglash va individuallashuv davrida chaqalog‘ingiz siz undan kutayotgan to‘g‘ri odat yoki xatti-harakatlarni bajarmasligi mumkin. Hatto o‘sha paytda bajarsa ham, bu har doim ham odatga aylanmasligi mumkin. Chaqalog‘ingizga singdirmoqchi bo‘lgan odat haqida uzoq gapirish va tushuntirish ham o‘zgarish qilish uchun yetarli bo‘lmasligi mumkin. Bunday holatlarga duch kelganingizda qilishingiz kerak bo‘lgan birinchi narsa — chaqalog‘ingizga yaxshi namuna bo‘lish! Chunki chaqaloqlar mavhum fikrlash orqali emas, balki to‘liq kuzatish orqali yangi odatlarni o‘zlashtiradilar. Agar yaqinlaringizdan biror narsa so‘raganingizda «iltimos» demasangiz, chaqalog‘ingizdan ham bu so‘zni odat qilishini kutmasligingiz kerak. Chaqalog‘ingiz uchun uning atrofida ko‘rib turgan xatti-harakatlar to‘g‘ri namuna hisoblanadi. Shuning uchun chaqalog‘ingiz o‘zlashtirishini istagan xatti-harakatni avvalo o‘zingiz namoyon qilishingiz kerak.') WHERE id = 'd637a9d3-9bc2-4e75-bc5f-06b90b92798a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Rotavirus odatda kichik yoshdagi bolalarga ta’sir qiladigan, oshqozon-ichak infeksiyasini keltirib chiqaradigan va ko‘proq kuz-qish oylarida uchraydigan kasalliklardan biridir. Agar chaqalog‘ingizda rotavirusga qarshi immunitet shakllanishi uchun uni emlatgan bo‘lsangiz, kasallik yuqqan taqdirda, ehtimol, uni yengilroq o‘tkazadi. Biroq vaksina to‘liq immunitet hosil qilmasligini, faqat virus yuqqanda alomatlarning yengilroq kechishini ta’minlashini unutmasligingiz kerak. Shu sababli immuniteti hali to‘liq mustahkamlanmagan chaqalog‘ingizni rotavirusdan himoya qilish juda muhim. Rotavirus odatda ifloslangan suv, yetarlicha zararsizlantirilmagan oziq-ovqat, umumiy suzish havzalari va qo‘l orqali tegish natijasida yuqishi mumkin. Agar sizga rotavirus yuqsa va chaqalog‘ingizni emizayotgan bo‘lsangiz, shu sababli emizishni to‘xtatishingiz shart emas. Chunki o‘tkazilgan tadqiqotlarda rotavirusning ona suti orqali onadan chaqaloqqa yuqishiga oid hech qanday dalil aniqlanmagan.') WHERE id = '408371ed-7459-4486-8982-de0e6127b2cc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'So‘nggi tadqiqotlarda sun’iy shirinlashtiruvchilarning saraton bilan bevosita aloqasi aniqlanmagan bo‘lsa-da, ular uzoq muddat davomida organizmda ortiqcha insulin ajralishiga sabab bo‘lishi va gormonal muvozanatni buzishi mumkin, deb hisoblanadi. Shu sababli mutaxassislar shirinlashtiruvchilarni, ayniqsa, chaqaloqlar, homilador ayollar va bolalar ovqatida ishlatishni tavsiya etmaydi. Shirinlashtiruvchilar chaqaloqlar organizmiga qo‘zg‘atuvchi ta’sir ko‘rsatib, uyqu tartibiga salbiy ta’sir qilishi haqida tadqiqotlar mavjud. Shuning uchun chaqalog‘ingiz tarkibida shirinlashtiruvchi bo‘lgan tayyor qadoqlangan mahsulotlarni iste’mol qilmasligi juda muhim. Bu moddalarning hech qanday ozuqaviy qiymati yo‘q, shu bois chaqalog‘ingiz uchun tabiiy shakar manbalarini tanlash foydaliroq bo‘ladi. Mavsumiy mevalar va pekmez (quyuq meva sharbati) bilan shirinlashtirilgan taomlar chaqalog‘ingizning uglevodlarga bo‘lgan ehtiyojini to‘liq qondiradi.') WHERE id = 'f3e8fd10-f90c-4115-b3d0-88adbf06800b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz endi yaqin atrofida tez-tez ko‘radigan odamlarning yuzlarini yaxshi taniy boshladi. Bu uning begona odamlardan yoki ilk bor ko‘rayotgan tanishlaringizdan qo‘rqishi mumkinligini ham anglatadi. Begonalardan qo‘rqish deb ataladigan bunday xatti-harakatlar chaqalog‘ingizning odatiy rivojlanish jarayonining bir qismidir, shuning uchun xavotir olmang. Aksincha, bu holat chaqalog‘ingiz sizni va o‘zi o‘rgangan odamlarni boshqalardan ajrata olishini hamda siz bilan yaqin rishta o‘rnatganini ko‘rsatadi. Chaqalog‘ingizni avval tanimagan odam bilan tanishishga majburlamang, chunki bu vaziyatni yanada qiyinlashtirishi mumkin. Begona odamlar bor joylarda chaqalog‘ingiz o‘zini xavfsiz his qiladigan muhit yarating. Vaqt o‘tishi bilan u yangi odamlarni uchratib, o‘zini xavfsiz his qilgani sari bu qo‘rquv asta-sekin kamayadi. Sabrli bo‘ling va uni tushunishga harakat qiling.') WHERE id = '06b42174-c457-4e70-9b49-6845b506cc6c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Kattalar va chaqaloqlarda qabziyat tushunchasi turli belgilar bilan namoyon bo‘ladi. Masalan, kattalarda hojatga kam chiqish qabziyat deb hisoblansa-da, aslida hojatga chiqish tezligidan qat’i nazar, najasning qiyinchilik bilan kelishi qabziyatdir. Agar chaqaloq 3 kunda bir marta hech qanday qiyinchiliksiz hojatga chiqsa, bu qabziyat hisoblanmaydi. Ammo chaqalog‘ingiz kuniga 2-3 marta hojatga chiqsa ham, kuchanish, gaz, qattiq najas, spazm, zo‘riqish va bezovtalik kuzatilsa, qabziyat haqida gapirish mumkin. Odatda najas ichaklar va anus orqali oson chiqishi kerak. Najasning haddan tashqari suyuq yoki qattiq bo‘lishi yoxud hojatga chiqish oralig‘i 7 kundan oshishi ovqat hazm qilish tizimidagi ayrim muammolardan darak berishi mumkin. Agar chaqalog‘ingizda fiziologik muammo bo‘lmasa, qabziyat katta ehtimol bilan noto‘g‘ri ovqatlanish odatlari bilan bog‘liq. Bunday holatda chaqalog‘ingiz menyusiga kletchatkaga boy mahsulotlarni ko‘proq qo‘shishingiz, shakarli va tayyor qadoqlangan mahsulotlardan voz kechishingiz kerak.') WHERE id = 'a55a0cb8-4bf1-4b31-acf7-9e3ccdc65901';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning jismoniy rivojlanishi va mustaqillik hissi ortib borayotgani sababli uning uyqu tartibi buzilishi va u uxlashga qarshilik ko‘rsatishi mumkin. Uxlamaslik, uxlaganidan ko‘p o‘tmay uyg‘onish, qayta uxlab qolishga qiynalish va kunduzgi uyquning butunlay buzilishi bu davrda tez-tez uchraydi. Buning asosiy sababi — chaqalog‘ingizning qiziqishi butunlay tashqi olamga qaratilganidir. Har bir yangi kashfiyot chaqaloqda qo‘rquv tushunchasi shakllanishiga ham zamin yaratadi. Bu qo‘rquvlar o‘ta jiddiy muammo tug‘dirmasa, rivojlanishning bir qismi hisoblanadi. Biroq chaqalog‘ingizning tez-tez qo‘rqinchli tush ko‘rib uyg‘onishi, yolg‘iz qolishni istamasligi yoki uyqusida turib yurishi uni charchatishi mumkin. Bunday vaziyatda, agar hali olib bermagan bo‘lsangiz, chaqalog‘ingizga uyqudagi hamroh (o‘yinchoq) olib berish yoki xonasida kichik o‘zgarishlar qilish yaxshi samara berishi mumkin. Unga Qo‘rqishning hojati yo‘q yoki Buning nimasi qo‘rqinchli? kabi savollarni berish o‘rniga, Sen uxlab qolguningcha yoningda bo‘laman, Uyg‘onganingda meni chaqirsang, yoningga kelaman kabi jumlalar bilan o‘zini xavfsiz his qilishiga yordam bering.') WHERE id = '81d78316-8e96-4fa7-97ae-ef09552b8f7c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz endi 20 oylik. Tabriklaymiz! 2 yoshga yaqinlashib qolgan chaqalog‘ingiz endi his-tuyg‘ular haqida ko‘proq tushunchaga ega. Har bir chaqaloq hayotining ma’lum davrida faqat xursandchilik, hayajon va qayg‘u hislarini tushunadi. Ayniqsa, yura boshlaydigan 12 oylik davrdan boshlab bu hislarga qo‘rquv ham qo‘shiladi. Endi esa chaqalog‘ingizning his-tuyg‘ulari yanada rang-barang bo‘lib bormoqda. Begona odamlarni ko‘rganda bezovtalanishi bunga yaqqol misoldir. Tashqi olamni faol o‘rganayotgan va o‘zini alohida shaxs sifatida anglayotgan bu davrda u jahl va hafsalasi pir bo‘lishi kabi hislarni kuchli boshdan kechirishi mumkin. Sizning, turmush o‘rtog‘ingizning va yaqinlaringizning his-tuyg‘ulari, shuningdek, uydagi umumiy muhit chaqalog‘ingizga bevosita ta’sir qiladi. Ota-ona sifatida sizning xatti-harakatlaringiz chaqaloqning hissiy rivojlanishida katta rol o‘ynaydi. Bu bosqichda chaqalog‘ingiz turli his-tuyg‘ularni boshdan kechirar ekan, siz uni tushunayotganingizni his qilishni istaydi.') WHERE id = '556907e3-8565-4588-b437-8a867d4880bd';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Shu oydan boshlab chaqalog‘ingizning vazni qiz bo‘lsa, o‘rtacha 10.900 gramm, o‘g‘il bo‘lsa, taxminan 11.500 gramm bo‘ladi. Biroq bular o‘rtacha ko‘rsatkichlar bo‘lib, JSST standartlariga ko‘ra, chaqalog‘ingizning vazni kamida 8500 gramm va ko‘pi bilan 14.000 gramm oralig‘ida bo‘lishi kutiladi. Bu oyda bo‘yi qizlarda o‘rtacha 82.7 sm, o‘g‘il bolalarda esa 84.2 sm bo‘ladi. Xuddi shu standartlarga ko‘ra, bo‘y uzunligining 77 sm bilan 89.5 sm oralig‘ida bo‘lishi me’yor hisoblanadi. Unutmang, har bir chaqaloq o‘ziga xos va uning rivojlanishi individualdir. Chaqalog‘ingizning ko‘rsatkichlari shu oraliqda bo‘lsa, xavotirlanishga hojat yo‘q. Agar uning rivojlanish ko‘rsatkichlari bu chegaralardan tashqarida deb hisoblasangiz, shifokoringiz bilan maslahatlashishingiz mumkin.') WHERE id = 'f02ccd26-c16b-414b-97d4-105108ef9968';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz tug‘ilgan ilk ondan boshlab u bilan o‘tkazgan vaqtingiz va birgalikdagi mashg‘ulotlaringiz uning rivojlanishi uchun juda qadrlidir. Chaqalog‘ingiz tashqi olamga faol moslashishga urinayotgan bu davrda uning ijtimoiy va hissiy rivojlanishi atrofidagi odamlar bilan muloqotining sifatiga bog‘liq. Sifatli muloqot uchun siz va turmush o‘rtog‘ingiz u bilan ko‘p vaqt o‘tkazishingiz hamda bu vaqtni uning rivojlanish darajasiga mos mashg‘ulotlar bilan boyitishingiz muhim. Bu mashg‘ulotlar jismoniy, aqliy va hissiy ko‘nikmalarni rivojlantirishi kerak. Qisqacha aytganda, oila davrasida televizor qarshisida o‘tirish chaqalog‘ingizga hech qanday foyda bermaydi. Sifatli vaqt — bu butun e’tiboringizni chaqalog‘ingizga qaratganingiz, boshqa ish bilan shug‘ullanmaganingiz va uning istaklariga muvofiq yo‘l tutganingizdir. Masalan, u bilan kun davomida yuz bergan voqealar haqida suhbatlashish, o‘zini ifoda etishiga imkon berish va bularning barchasini qilayotganda ko‘zlariga qarab, uni qadrlashingizni his qildirish juda foydali bo‘ladi.') WHERE id = 'b65936ff-1ea6-49a0-9aee-5eb1e936b860';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu davrda dastlabki oylardagidek tez o‘smasa ham, hali ham faol rivojlanish bosqichida. Uning o‘sishda davom etishi va kundalik energiyaga bo‘lgan ehtiyojini qondirishi uchun ovqatlanish juda muhim. U har bir oziq-ovqat guruhidan yetarli miqdorda iste’mol qilayotganiga ishonch hosil qilishingiz kerak. Ya’ni kun davomida tuxum, go‘sht va baliq kabi hayvonot mahsulotlari, meva-sabzavotlar, donli va sut mahsulotlari ratsionda bo‘lishi lozim. Biroq, ayniqsa, tish chiqarish davrida chaqaloq ovqatlanishdan bosh tortishi mumkin. Bunday hollarda u bilan o‘jarlashmasligingiz, tushunish bilan munosabatda bo‘lishingiz va sog‘lom muqobillarni taklif qilishingiz kerak. Masalan, sabzavot yemasa, yaxshi ko‘radigan mevasining porsiyasini biroz ko‘paytirishingiz mumkin.') WHERE id = '20ce1fe9-8b2d-4594-843f-1ce4823d8bfa';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ichaklari uning hissiy holatini boshqaradigan gormonlar ishlab chiqarilishiga ham javobgardir. Qizig‘i shundaki, baxt gormoni hisoblangan serotoninning atigi 5% i miyada, 95% i esa ichaklarda ishlab chiqariladi. Demak, chaqalog‘ingiz sog‘lom va baxtli bo‘lishining kaliti — muvozanatli ichak mikroflorasidir. Hazm qilish tizimi yaxshi ishlaydigan chaqaloq tinchroq va quvnoqroq ulg‘ayadi. Ichaklar salomatligini asrash uchun ratsionga fermentlangan mahsulotlarni kiritish kerak. Bu mahsulotlar tarkibidagi prebiotiklar tufayli foydali bakteriyalarni saqlab, hazm qilishni yengillashtiradi. Fermentatsiya usulida tayyorlangan mahsulotlar vitamin va minerallarning ichaklarda yaxshiroq so‘rilishini ta’minlab, chaqalog‘ingizning hayot sifatini oshiradi.') WHERE id = '43699df8-5258-442b-90de-b5aaf7cb47ca';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz uy ishlarida sizga yordam berishga qanchalik ishtiyoqmand ekanini kuzatayotgan bo‘lsangiz kerak. Jismoniy ko‘nikmalari rivojlangani sari u ko‘proq ishlarni bajara olishini anglaydi. U idishlarni idish yuvish mashinasidan olish, kir kiyimlarni olib kelish yoki dasturxonni yig‘ishtirishga yordam berish kabi ishlarni bajarishi mumkin. Siz bundan mamnun bo‘lib, uni maqtayotganingizni ko‘rishi esa unga katta quvonch bag‘ishlaydi. Hatto ba’zida yordamingizni rad etib, ishni butunlay o‘zi bajarishni istashi mumkin. Chaqalog‘ingizning bu ishtiyoqidan foydalanib, unga o‘yinchoqlarini yig‘ishtirishni o‘rgatishingiz mumkin. Shunda u ham mustaqil ish bajarish quvonchini his qiladi, ham mas’uliyat tuyg‘usini anglaydi.') WHERE id = '721ffc29-7197-44f5-88ee-2f200062abbc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizda tish yuvish odatini shakllantirish vaqti keldi! Dastlabki urinishlar muvaffaqiyatsiz chiqishi mumkinligini hisobga olishingiz kerak. Chaqalog‘ingiz bu davrda atrofidagilarning xatti-harakatlariga taqlid qilish orqali o‘rganishga moyil bo‘ladi. Shu sababli avvalo unga o‘rnak bo‘lishingiz kerak. Dastlab chaqalog‘ingiz uchun yumshoq tukli, kichik o‘lchamli, egiluvchan va sevimli qahramon tasviri tushirilgan tish cho‘tkasini xarid qiling. Keyin chaqalog‘ingizni qarshingizga olib, tishlaringizni yuvishni boshlang. U bir muddat nima qilayotganingizni kuzatadi. Uni tishlarini yuvishga majburlamang va bir muddat sizni shunchaki kuzatishiga imkon bering. Ba’zida uning diqqati chalg‘ishi mumkin, bunday hollarda e’tiborini yana o‘zingizga qaratishga harakat qiling. Chaqalog‘ingiz dastlab tishlarini to‘g‘ri yuva olmasligi mumkin, bu esa unda tish yuvishdan qo‘rqish hissini uyg‘otishi mumkin. Shuning uchun uni ruhlantirishingiz kerak. Ko‘zgu qarshisida kulgili yuz ifodalarini ko‘rsatib, tish yuvishni qiziqarli o‘yinga aylantirishingiz mumkin! 😊') WHERE id = '4637000e-4134-4115-9ea0-8e59506a6219';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu haftalarda chaqalog‘ingizning oziq tishlari chiqa boshlaydi. Jami 20 ta bo‘ladigan sut tishlarining to‘liq chiqishi o‘rtacha 30-oygacha davom etadi. Oziq tishlari kattaroq bo‘lgani sababli ularning chiqishi boshqa tishlarga qaraganda qiyinroq kechishi mumkin. Chaqalog‘ingizning ishtahasi ancha pasayganini, hatto ovqatni ko‘rganda yig‘lab, uni rad etayotganini ko‘rishingiz mumkin. Ovqatlanishni rad etishining eng muhim sababi — milklarining o‘ta sezgir bo‘lib qolishidir. Milklariga tekkan har qanday narsa unga og‘riq keltirishi mumkin. Shu sababli tish chiqish davrida chaqalog‘ingizga qattiq ovqatlar o‘rniga suyuqroq taomlar berishni tavsiya qilamiz. Dovg‘a, meva pyuresi va yogurt kabi mahsulotlarni chaqaloq chaynamasdan yuta oladi. Shu tariqa chaqalog‘ingiz milklariga ortiqcha ta’sir qilmasdan, kerakli vitamin va minerallarni yetarli miqdorda qabul qila oladi.') WHERE id = '23f535f9-e4d0-471e-96ba-f603b329cdb3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz kelajakda o‘ziga ishongan va boshqa insonlar bilan yaxshi munosabat o‘rnata oladigan katta odam bo‘lishini istashingizni bilamiz. Uning o‘ziga ishongan va birovning yo‘l-yo‘rig‘iga muhtoj bo‘lmagan shaxs bo‘lib ulg‘ayishi uchun bu davrda unga qanday munosabatda bo‘lishingizga e’tibor qaratishingiz kerak. Masalan, chaqalog‘ingiz ko‘chada gapingizga quloq solmasa, «Qara, amaki senga jahli chiqadi», yoki uyda ovqatini yemasa, «Otangga aytaman», deyishingiz ham tahdid hisoblanadi. Bunday jumlalar tahdid qilish maqsadida aytilmasa ham, o‘z mazmuniga ko‘ra qo‘rquvga asoslangan vaziyatni yuzaga keltiradi. Natijada tahdid bilan boshqarilgan chaqaloqning ongida ayrim qo‘rquvlar beixtiyor o‘rnashib qoladi. Buning o‘rniga chaqalog‘ingizga tanlash huquqini berish va his-tuyg‘ularini erkin ifodalashiga imkon yaratish juda muhim. Chaqalog‘ingiz ovqat yemasa, «Mayli, unda keyingi ovqatlanish vaqtigacha kutishingiz kerak», deyishingiz unga o‘z tanlovining mas’uliyatini his qilishga yordam beradi va o‘ziga bo‘lgan ishonchiga zarar yetkazmaydi.') WHERE id = 'dbc49c55-d342-48d1-a126-983d66df0425';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz ichini bo‘shatishda qiynalayotgan bo‘lsa va buning sababi ovqatlanish tartibidagi xato emas deb hisoblasangiz, shifokor bilan maslahatlashish vaqti keldi. Ayniqsa, chaqalog‘ingiz qattiq baqirib yig‘lasa, qorni haddan tashqari shishsa va najasi otilib chiqsa, unda fiziologik jihatdan orqa chiqaruv teshigi torligi bo‘lishi mumkin. Bu tashxisni ko‘z bilan ko‘rish yoki asboblar yordamida qo‘yib bo‘lmaydi. U faqat orqa chiqaruv teshigini barmoq bilan tekshirganda ichki anal halqaning torligi sezilishi orqali aniqlanadi. Orqa chiqaruv teshigi torligi qiz bolalarda o‘g‘il bolalarga qaraganda 80% ko‘proq uchraydi va uni davolashning yagona yo‘li jarrohlik amaliyotidir. Bundan tashqari, chaqaloqning ayrim oziq-ovqatlarga sezgirligi ham qabziyatga sabab bo‘lishi mumkin. Tahlillarda aniqlanishi qiyin bo‘lgan bu holat siz shubha qilayotgan mahsulotni ratsiondan chiqarib tashlagandan keyin muammo bartaraf bo‘lishi orqali aniqlanadi. Allergiyadan farq qiladigan bu holatda chaqalog‘ingiz qaysi mahsulotni iste’mol qilgandan keyin qiynalayotganini diqqat bilan kuzatishingiz kerak.') WHERE id = '9ea3b778-8061-4fc9-a899-eb839a41dde7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Kalsiy minerali chaqaloq organizmida eng ko‘p uchraydigan noorganik birikmadir. Bu bosqichda chaqaloq qonining har 10 millilitrida taxminan 1 mq kalsiy bo‘ladi. Kalsiy chaqaloqning rivojlanayotgan suyak metabolizmi va mushaklari uchun eng muhim moddalardan biridir. U yangi suyaklarning hosil bo‘lishi, tishlar tuzilishi, qon ivishi, asab tizimining boshqarilishi va sog‘lom gormonal muvozanatni saqlashda katta rol o‘ynaydi. Chaqalog‘ingiz o‘ziga zarur kalsiyni oziq-ovqat orqali oladi. Agar u yetarli miqdorda kalsiy qabul qilmasa, organizm tishlar va to‘qimalardagi kalsiydan foydalana boshlaydi. Bu esa chaqaloq tishlari va suyaklarining mo‘rtlashib, oson sinishiga olib kelishi mumkin. Chaqaloqqa kuniga 800 mq kalsiy kerak. Sut va sut mahsulotlari, yashil bargli sabzavotlar, sarsabil, pekmez, mayiz, qora olxo‘ri qoqisi, dukkaklilar, brokkoli, bamiya, qovoq, karam, yong‘oq va baliq chaqalog‘ingiz uchun ajoyib kalsiy manbalaridir.') WHERE id = '2b51d001-1cfb-4b5b-bddc-35b70fcc2c0e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ayrim ishlarni mustaqil bajara olishi, albatta, uni maqtashingizga arziydi. Ammo bu maqtov qanday maqsadga xizmat qilishi yanada muhimdir. Chaqalog‘ingizni maqtash — uni bu xatti-harakatni takrorlashga yoki shu yo‘nalishda rivojlanishga rag‘batlantirish va undash demakdir. Ota-onalar ko‘pincha chaqaloqni bajargan ishi uchun emas, balki umumiy bir qolip asosida maqtash xatosiga yo‘l qo‘yadilar. Masalan, chaqalog‘ingiz tishlarini yuvganida Sen juda aqlli bolasan, barakalla! deyish uning bajargan ishini maqtash hisoblanmaydi. Buning o‘rniga Tishlaringni juda yaxshi yuvibsan, tabriklayman deyish chaqalog‘ingizda bu ishni yanada yaxshiroq bajarishga motivatsiya uyg‘otadi. Bunday rag‘bat mehnati qadrlangan chaqalog‘ingizda muvaffaqiyat hissini shakllantirib, uning o‘ziga bo‘lgan ishonchini oshiradi. Chaqaloqning shaxsiyatiga emas, bajargan ishiga qaratilgan maqtovlar uning ishtiyoqini yanada kuchaytiradi.') WHERE id = 'b90e13fc-da18-4d18-9cf7-084289311535';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingizni hali ham tungi ovqatlanishdan chiqarmagan bo‘lsangiz, bu jarayonni imkon qadar tezroq boshlashingizni tavsiya qilamiz. Uzoq vaqt davom etadigan tungi ovqatlanish chaqaloqlarda, ayniqsa, reflyuks va boshqa ko‘plab oshqozon muammolariga sabab bo‘lishi mumkin. Shuningdek, tungi ovqatlanish tufayli tishlarning chirishi ham tezlashishi mumkin. Bu davrda chaqalog‘ingiz kechasi umuman uyg‘onmasdan uxlashi kerak. Kechasi ovqatlanish uchun uyg‘onishi gormonal muvozanatga salbiy ta’sir ko‘rsatishi mumkin. Bundan tashqari, tungi ovqatlanish chaqalog‘ingizning kunduzi ishtahasiz bo‘lishiga va ayrim ovqatlanish buzilishlariga olib kelishi mumkin. Tungi ovqatlanishni qanday to‘xtatish butunlay sizning tanlovingiz: uni birdaniga yoki asta-sekin kamaytirib to‘xtatishingiz mumkin. Eng muhimi, qaysi usulni tanlamang, qaroringizda qat’iy turishingiz kerak. Faqat izchil bo‘lsangizgina muvaffaqiyatga erishasiz. Bu jarayonni boshlaganingizda kunduzgi ovqatlanish miqdori yoki sonini oshirish kechasi uyg‘ongan chaqalog‘ingizni tinchlantirishda sizga katta yordam beradi.') WHERE id = '5d817069-0b19-4915-834b-0e07f7c81bb8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizga chegaralar belgilashda qiynalayotganingizni bilamiz. Biroq chaqaloq qayerda to‘xtash kerakligini va o‘z chegaralarini bilishi uning rivojlanishiga katta hissa qo‘shadi. Ko‘plab oilalar chaqalog‘i baxtli bo‘lsin va erkin muhitda o‘ziga ishongan holda ulg‘aysin, deb chegaralar belgilashdan qochadi. Aslida esa bu holat chaqalog‘ingizning kelajakda duch keladigan to‘siqlarni yengish mexanizmini zaiflashtiradi. Qoida va chegaralar bo‘lmagan muhitda ulg‘aygan bola maktab davrida ijtimoiy hayotda o‘zini qanday tutishni bilmaydi. Chegarasiz muhit chaqaloqning hamma narsaning markazida bo‘lishini anglatadi, bu esa unga o‘ziga ishonch emas, aksincha, zo‘riqish olib keladi. Aslida chaqalog‘ingiz chegaralar va qoidalar mavjud muhitda o‘zini xavfsizroq his qiladi. Chaqalog‘ingiz yaxshi ijtimoiy munosabatlar o‘rnatishi, o‘z erkinligining chegaralarini tushunishi va boshqalarning huquqlarini buzmasligi uchun aniq chegaralar va qoidalarga ehtiyoj sezadi.') WHERE id = '8292fe03-48c0-4b8d-8f79-32796a621a8a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning tishlari chiqayotgan bu kunlarda ovqatlanish va uyqu muvozanati ancha buzilishi mumkin. Bu holat chaqalog‘ingiz immun tizimining zaiflashishiga va kasalliklarga nisbatan sezgirroq bo‘lib qolishiga sharoit yaratadi. Immun tizimi kasalliklarga qarshi himoya mexanizmini shakllantiradigan, mikroblarni tanib, yo‘q qiladigan va organizmni himoya qiladigan tizimdir. Immun tizimining tarkibiy qismlari chaqalog‘ingiz iste’mol qiladigan oziq-ovqatlardan olgan birikmalar hisobiga ishlab chiqariladi. Shu sababli ovqatlanishda muammo yuzaga kelsa, organizmda yetarli miqdorda himoya hujayralari ishlab chiqarilmaydi. Bunday holatda chaqalog‘ingizning kasalliklarga qarshiligi pasayadi va hatto oddiy mikroblar ham uning kasallanishiga sabab bo‘lishi mumkin. Chaqalog‘ingiz immunitetini mustahkamlash uchun bu davrda antioksidant hisoblangan A, C, D, E vitaminlari, shuningdek, temir, rux va selen elementlarini yetarli miqdorda olishiga e’tibor berishingiz kerak.') WHERE id = 'deafb12c-0312-478f-84da-f12b3548eb14';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz tishlarini siz yuvib berishingizni yoki o‘zi yuvishni yoqtirmasa, ayrim usullarni qo‘llash vaqti keldi. Chaqalog‘ingiz o‘yin davrida va taqlid qilishni juda yaxshi ko‘radi. Shu sababli chaqalog‘ingizni yoningizga olib, uning sevimli o‘yinchog‘ining tishlarini yuvishingiz mumkin. Biroz vaqt o‘tgach esa chaqalog‘ingizga o‘yinchoqning tishlarini yuvishni taklif qiling. Shuningdek, haftalik reja tuzish ham foydali bo‘ladi. Buning uchun rangli qog‘ozlar, rangli qalamlar va qiziqarli stikerlar kerak! 😊 Tuzadigan rejangizda har bir kunni rangli qalamlar bilan ajratib ko‘rsating. Rang tanlashda chaqalog‘ingizdan yordam so‘rash yaxshi fikr. Chaqalog‘ingiz tishlarini yuvgan har bir kuni o‘zi tanlagan stikerni o‘sha kunning katagiga yopishtirishi mumkin. Shunday qilib, chaqalog‘ingiz keyingi kun kelishini va yangi stikerlarni yopishtiradigan paytni qiziqish bilan kutadi! 😊') WHERE id = 'aa88eedf-fb72-41a6-b61c-927d17332a52';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz juda serharakat bo‘lsa, doimo uning ortidan yugurishingizga va tez-tez charchashingizga to‘g‘ri keladi. Ammo ortiqcha vazn va semizlikning asosiy sabablaridan biri kamharakat turmush tarzi ekanini unutmang. Bu davrda chaqalog‘ingizda shakllantiradigan turmush tarzi uning kelajakdagi odatlarini belgilovchi eng muhim omillardan biridir. Shu sababli, zarurat bo‘lmasa, chaqalog‘ingizning harakatlariga aralashmang va energiyasini sarflashi uchun u bilan birga turli faol o‘yinlar o‘ynang. Semizlikka olib keladigan yana bir omil — ovqatni juda tez yeyish. Chaqalog‘ingizni ovqatini tugatishga shoshirmang. Ovqat tez yeyilganda, oshqozon to‘lgan bo‘lsa ham, miyaga to‘qlik signali kech yetib boradi. Bu esa chaqalog‘ingiz ehtiyojidan ortiq ovqatlanishiga olib keladi. Ortiqcha olingan kaloriyalar jismoniy faollik orqali sarflanmasa, tanada yog‘ zaxirasi sifatida to‘planib, kelajakda semizlikka zamin yaratadi.') WHERE id = 'e705ddac-9bb9-4f4e-a8cb-b34adbf75868';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning o‘sishi va rivojlanishi uchun uyqu paytida ajralib chiqadigan gormonlar juda katta ahamiyatga ega. Shu oydan boshlab chaqalog‘ingiz bir sutkada kamida 13 soat uxlashi kerak. Bu vaqtga kelib kunduzgi ikki mahal uyqudan bir mahal uyqu tartibiga o‘tgan bo‘lishingiz kerak. Agar chaqalog‘ingiz hali ham kunduzi ikki marta uxlasa, ehtimol, yaqin orada bu o‘z-o‘zidan bir martaga tushadi. Ayrim chaqaloqlar esa kunduzgi uyqudan butunlay voz kechishi mumkin. Agar bu holat ishtahasizlik, bezovtalik va jizzakilik bilan kechsa, demak, chaqalog‘ingiz hali ham kunduzgi uyquga muhtoj. Agar kunduzi uxlamasa ham kayfiyati yaxshi va ishtahasi joyida bo‘lsa, bu tartibni davom ettirishingiz mumkin. Ammo tungi uyqusi uzluksiz va sifatli bo‘lishiga alohida e’tibor berishingiz kerak. Tunda yetarlicha uxlamagan chaqaloq kun davomida o‘rgangan yangi ma’lumotlarini xotirasida mustahkamlay olmaydi. Ayniqsa, tungi ovqatlantirishni to‘xtatish uyquning yanada tinch va uzluksiz bo‘lishiga yordam beradi.') WHERE id = '83bdbf1c-c0eb-40ca-9642-c6234b186654';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizga o‘yinchoq sotib olayotganda endi oddiy va bir qismli o‘yinchoqlar o‘rniga murakkabroq hamda muayyan ko‘nikmalarni talab qiladiganlarini tanlang. Uning mayda motorikasini rivojlantiradigan, fikrlashga undaydigan va ijodkorligini oshiradigan o‘yinchoqlarni izlang. Masalan, bir-biriga biriktiriladigan legolar, kiyimlarini almashtirish mumkin bo‘lgan qo‘g‘irchoqlar, ko‘p qismli o‘yinchoq oshxona to‘plamlari yoki yukxonasi ochiladigan mashinalar juda yaxshi tanlovdir. Chaqalog‘ingiz bu o‘yinchoqlar bilan o‘ynayotganda bo‘g‘ilib qolish yoki jarohatlanish kabi xavflarning oldini olishingiz va uni nazorat qilib turishingiz kerak, ammo o‘yin jarayoniga aralashmang. Qiziqish, fikrlash, savol berish, qismlarni birlashtirish va ajratish kabi jarayonlar chaqalog‘ingiz mustaqil ravishda egallashi lozim bo‘lgan ko‘nikmalardir. U biror joyda qiynalsa yoki xato qilsa, darhol vaziyatni o‘z qo‘lingizga olishga urinmang. Topshiriqni bajarishi uchun unga yetarlicha vaqt va imkoniyat bering. Shunda chaqalog‘ingiz sinab ko‘rish va xato qilish orqali to‘g‘ri yechimni o‘zi topishni o‘rganadi.') WHERE id = 'b496bbf8-f02b-4983-949c-f678a34f52e1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz tug‘ilgan kundan buyon ham jismonan, ham aqlan katta rivojlanish yo‘lini bosib o‘tgan bo‘lsa-da, u hali ham ona sutidagi foydali moddalarga muhtoj. Sut ishlab chiqarish uchun sut bezlarini faollashtiradigan prolaktin gormoni miyaning old qismida joylashgan gipofiz bezi tomonidan ajratiladi. Chaqalog‘ingiz ema boshlashi bilan bu gormon nervlar orqali orqa miyani qo‘zg‘atadi. U yerdan kelgan signal ta’sirida miyadagi gipotalamus sohasi faollashib, oksitotsin va vazopressin gormonlari ishlab chiqarila boshlaydi. Bu gormonlar qon orqali ko‘krak va sut bezlariga yetib boradi. Sut bezlaridagi hujayralarning qisqarib-bo‘shashishi natijasida sut sut yo‘llariga o‘tadi. Bu murakkab jarayonning barchasi atigi 30 soniya ichida yuz beradi va sutingiz kela boshlaydi. Ushbu gormonlar tungi soatlarda eng faol ishlaydi. Shu sababli, sutingiz kamayib qolmasligi va muntazam ishlab chiqarilishi uchun tungi uyqu tartibiga e’tibor berishingiz juda muhim.') WHERE id = '743884b4-17a1-4059-ab54-1551b9471069';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning uyqusi borasida ancha realistik kutilmalarga ega bo‘lishingiz kerak. Uzluksiz va sifatli uyqu, albatta, 13 soat davomida uyg‘onmay uxlash degani emas. Masalan, soat 20:00-da uxlagan chaqaloqning 00:00-da uyg‘onishi, birozdan so‘ng yana uxlab, ertalab 06:00-gacha uxlashi bu bosqich uchun mutlaqo tabiiy. Undan kechqurundan ertalabgacha uyg‘onmay uxlashini kutmaslik sizni hafsalangiz pir bo‘lishidan asraydi. Ammo chaqalog‘ingiz tunda haddan tashqari ko‘p uyg‘onsa va har safar ovqatlanishni istasa, ovqatlantirishda ayrim xatolar bo‘lishi mumkin. Bunday holatda, avvalo, chaqalog‘ingizning kunduzgi ovqat porsiyalarini va uxlashdan oldingi ovqatini biroz ko‘paytiring. Tunda ovqatlanish uchun uyg‘onganida esa, agar emizayotgan bo‘lsangiz, emizish vaqtini asta-sekin qisqartiring, agar sun’iy ozuqa berayotgan bo‘lsangiz, porsiyasini sekin-asta kamaytiring. Kunduzgi ovqatlanishni ko‘paytirish va tungi ovqatlanishni bosqichma-bosqich kamaytirish chaqalog‘ingizga bu o‘tish davrini yengilroq o‘tkazishga yordam beradi.') WHERE id = 'e37054f4-9e98-4f6d-9bff-391e03a99243';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizda biror ishni uddalash hissi paydo bo‘lishi uchun kun davomida bajaradigan kundalik yumushlaringizdan unga ham topshiriq berishingiz mumkin. Masalan, do‘kondan qaytayotganda chaqalog‘ingizga yengil paketni ko‘tarishiga to‘sqinlik qilmang, aksincha, uni bunga rag‘batlantiring. Kiyimlarini almashtirayotganda undan yordam so‘rashingiz va yechgan kiyimlarini kir savatiga olib borishini aytishingiz juda muhim. Shuningdek, dasturxon yozayotganda, ovqatdan keyin stolni yig‘ishtirayotganda va kir idishlarni idish yuvish mashinasiga joylayotganda ham chaqalog‘ingizdan yordam so‘rashingiz mumkin. Bunday topshiriqlar chaqalog‘ingizda biror ishni uddalash hissini rivojlantiradi va o‘zini qadrlangan deb his qilishiga yordam beradi. Chaqalog‘ingiz biror ishni bajarganidan so‘ng uning o‘zini emas, bajargan ishini maqtashingiz bu xatti-harakatlarning davom etishiga yordam beradi. Shunday qilib, chaqalog‘ingiz mas’uliyatlarini erta yoshdan anglab, kelajakda yanada tartibli va rejali inson bo‘lib ulg‘ayishi mumkin.') WHERE id = 'bedb8c25-bf2f-4e64-85f1-ca4820365207';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz organizmi har kuni siydik, ter va ko‘z yoshlari orqali ma’lum miqdorda suyuqlik yo‘qotadi. Suyuqlik bilan birga ko‘plab minerallar ham yo‘qoladi. Ayniqsa, chaqalog‘ingizdagi suv va mineral muvozanati kattalarnikiga qaraganda ancha sezgir ekanini hisobga olsak, suvsizlanish unga tezroq ta’sir qilishi mumkin. Chaqalog‘ingiz ichishi kerak bo‘lgan suv miqdorini uning qancha va qanchalik tez-tez ovqatlanishi hamda kun davomidagi faolligini hisobga olgan holda belgilashingiz kerak. Agar chaqalog‘ingiz yo‘qotayotgan suyuqlik miqdori ichayotgan suvidan ko‘p bo‘lsa, organizmida ayrim o‘zgarishlar yuz beradi. Masalan, siydikning to‘q rangli va o‘tkir hidli bo‘lishi, bezovtalik, kamharakatlik hamda yig‘laganda ko‘z yoshining kam chiqishi suvsizlanish belgisi bo‘lishi mumkin. Shu sababli chaqalog‘ingizga kun davomida tez-tez, ammo majburlamasdan suv taklif qilishingiz mumkin. Buyraklariga ortiqcha yuk tushirmaslik va organizmda suv to‘planishiga (shish paydo bo‘lishiga) yo‘l qo‘ymaslik uchun tuz iste’molini kamaytirishingiz mumkin.') WHERE id = '836c1705-2d21-4dae-a3cb-901aac3487af';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz hali dunyoga kelmasidan avval, ona qornidagi 9 oylik davrda milliardlab asab hujayralari hosil bo‘ladi. Tug‘ilgandan keyin chaqalog‘ingiz miyasida yangi asab hujayralarining paydo bo‘lishi kamaysa-da, bu jarayon yana bir muddat davom etadi. Taxminan 6 oydan so‘ng asab hujayralarining bo‘linishi butunlay to‘xtaydi va miyadagi hujayralarning umumiy soni o‘zgarmay qoladi. Chaqalog‘ingiz sezgi a’zolari orqali yangi ma’lumotlarni o‘rgangan sari bu asab hujayralari o‘rtasida sinaps deb ataladigan bog‘lanishlar hosil bo‘ladi va aqliy rivojlanish davom etadi. Shu bilan birga, chaqalog‘ingiz bosh aylanasi kattalashgani sayin miyadagi asab hujayralari ayrim gormonlar ta’sirida hajman kattalasha boshlaydi. Boshqacha aytganda, chaqalog‘ingiz tanasi o‘sgani sari o‘sish gormoni asab hujayralarining ham hajman kattalashishiga turtki beradi. Bu o‘sish chaqalog‘ingizning rivojlanish davri yakunlanguniga qadar davom etadi. Rivojlanish tugagach, asab tizimi ham o‘zining yakuniy holatiga keladi.') WHERE id = 'bf83a43a-3e8b-4dd1-9abe-1c19d8ca30a2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz, ayniqsa, fasllar almashganda, qish oylarida, tish chiqarish davrida va epidemiya paytida grippni yuqtirib olishi mumkin. Gripp — viruslar keltirib chiqaradigan kasallik bo‘lib, uni davolashda antibiotiklar samara bermaydi. Shu sababli grippni davolashdan maqsad viruslarni yo‘q qilish emas, balki alomatlarni yengillashtirish bo‘lishi kerak. Chaqalog‘ingiz gripp bo‘lganda, avvalo, uning yetarlicha dam olishi va ko‘proq suyuqlik ichishini ta’minlashingiz kerak. Shuningdek, immun tizimini mustahkamlash va zarur antitanalar hosil bo‘lishi uchun uning ovqatlanishiga yanada ko‘proq e’tibor berishingiz lozim. Gripp paytida chaqalog‘ingiz C vitamini, antioksidantlar va kletchatka manbalariga muhtoj bo‘ladi. Bu moddalar chaqalog‘ingiz immunitetini mustahkamlab, organizmiga viruslarga qarshi osonroq kurashishda yordam beradi. Apelsin, mandarin va greypfrut kabi mevalar C vitaminiga hamda foydali oziq moddalarga boy. Shuningdek, sabzavotlar, sarimsoq, zanjabil, asal va go‘shtli bulyon kabi hayvonot mahsulotlari qo‘shib tayyorlangan sho‘rvalar chaqalog‘ingiz organizmining himoya kuchlarini mustahkamlaydi.') WHERE id = '8e404bc8-ce50-47a3-9ba5-932f7b372cec';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz hayotining dastlabki uch yili nafaqat jismoniy o‘sish, balki aqliy rivojlanish ham eng tez kechadigan davrdir. Ushbu dastlabki uch yil ichida chaqalog‘ingizning idrok etish qobiliyati, mayda va yirik motorikasi, nutqi hamda hissiy rivojlanishi juda tez taraqqiy etadi. Bu ko‘nikmalarning barchasi chaqalog‘ingizning atrof-muhitga moslashishini osonlashtiradigan, ma’lumot olishiga va o‘rganganlarini eng yaxshi tarzda qo‘llashiga yordam beradigan tajribalardir. Chaqalog‘ingiz bu davrda egallaydigan ko‘nikmalar irsiy moyillikdan tashqari, atrof-muhit omillari va sizning yondashuvingiz ta’sirida ham shakllanadi. Chaqalog‘ingiz o‘z salohiyatidan to‘liq va samarali foydalanishi, hatto undan ham yuqori natijalarga erishishi sizga bog‘liq. Chaqalog‘ingiz tashqi ta’sirlarga qanchalik ko‘p duch kelsa, o‘zini rivojlantirish imkoniyati shunchalik ortadi. Shu ma’noda, chaqalog‘ingizni turli muhitlarga olib borishingiz, birgalikda yangi mashg‘ulotlar bilan shug‘ullanishingiz, uning ijtimoiylashishiga ko‘maklashishingiz hamda unga qoidalar va chegaralarni o‘rgatishingiz uning kelajagi uchun kiritishingiz mumkin bo‘lgan eng yaxshi sarmoyadir.') WHERE id = 'f53f49e9-b83a-4928-bf28-5f85fef3ea2d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Meva sharbatlari rangli, shirin va ichish oson bo‘lgani uchun chaqalog‘ingizning sevimli ichimliklaridan biri hisoblanadi. Ayniqsa, mavsumga mos mevalardan yangi siqilgan sharbat ichishi sog‘lom ovqatlanishning bir qismi bo‘lishi mumkin. Biroq uning miqdori kuniga bir kichik stakan bilan cheklanishi kerak. Meva sharbatini haddan tashqari ko‘p ichish chaqalog‘ingizning ochlik va to‘qlikni his qilish mexanizmiga ta’sir qilishi mumkin. Bundan tashqari, tarkibida fruktoza (meva shakari) ko‘p bo‘lgani sababli tishlarning chirishiga olib kelishi mumkin. Tayyor meva sharbatlarining oziqaviy qiymati esa uyda siqilgan sharbat yoki butun mevanikiga qaraganda pastroq. Shu sababli chaqalog‘ingiz ichadigan meva sharbati miqdorini cheklashingiz va unga mevani butun holda berishni afzal ko‘rishingiz kerak. Shunda chaqalog‘ingiz mevalar tarkibidagi kletchatkani ham qabul qiladi. Meva tarkibidagi kletchatka chaqalog‘ingizning oshqozon-ichak tizimiga juda ijobiy ta’sir ko‘rsatadi.') WHERE id = '822c2875-bf97-4464-96c5-25165de770cc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Har bir bola kabi, sizning chaqalog‘ingiz ham dunyoga ijodiy salohiyat bilan keladi. Biroq uni tarbiyalash jarayonidagi ayrim xatolar, atrofdagilarning munosabati va o‘zingiz sezmagan holda qo‘yadigan ortiqcha cheklovlaringiz uning ijodkorligiga jiddiy zarar yetkazishi mumkin. Masalan, nima qilayotganingizni ko‘rish uchun oshxona stoliga chiqishga urinayotgan chaqalog‘ingizni yiqilib tushishidan qo‘rqib darhol pastga tushirishingiz uning qiziqishi va kashf etishga bo‘lgan intilishini so‘ndirishi mumkin. Buning o‘rniga zarur xavfsizlik choralarini ko‘rib, uning qiziqishini qondirishiga imkon yaratish eng yaxshi tanlov bo‘ladi. Bu davrda chaqalog‘ingiz siz belgilagan chegaralardan chiqishga urinishi mumkin. Masalan, rasm bo‘yayotganda stulda o‘tirishdan bosh tortib, mashg‘ulotni polda davom ettirishi mumkin. Chunki tajribasi hali kam bo‘lgan chaqalog‘ingiz sinab ko‘rish va xato qilish orqali o‘rganadi. Bunday paytda uni tanqid qilishingiz yoki keskin munosabat bildirishingiz unda xato qilishdan qo‘rqadigan fe’l-atvor shakllanishiga sabab bo‘lishi mumkin.') WHERE id = 'c2c48251-d60f-4d39-bbe0-186388b64af6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Sut va sut mahsulotlari chaqalog‘ingiz rivojlanishida katta rol o‘ynaydigan muhim kalsiy va oqsil manbaidir. Ayniqsa, sut yog‘idagi qisqa zanjirli yog‘ kislotalari o‘sish davridagi chaqalog‘ingiz uchun nihoyatda muhim. Biroq foydaliroq deb hisoblanib, norasmiy sotuvchilardan ochiq holda olinadigan sut muayyan xavflarni tug‘dirishi mumkin. Manbasi to‘liq noma’lum bo‘lgan bunday sut qaynatilganda foydali mikroorganizmlar nobud bo‘ladi, ammo zararli spora hosil qiluvchi bakteriyalar saqlanib qolishi mumkin, bu esa xavflidir. Shuningdek, ishlab chiqarish va tashish sharoitlari noma’lum bo‘lgan sutda antibiotiklar hamda kasallik qo‘zg‘atuvchi bakteriyalar bo‘lish xavfi yuqori. Shu nuqtayi nazardan, chaqalog‘ingiz ovqatlanishi uchun eng ishonchli tanlov — qadoqlangan pasterizatsiyalangan sut. Pasterizatsiyalangan sut nazorat ostida sog‘ib olingan xom sutni zamonaviy texnologik uskunalarda 12–16 soniya davomida yuqori haroratda isitib, so‘ng sovitish orqali olinadi. Shu tariqa sutning foydali xususiyatlari saqlanadi, zararli mikroorganizmlar esa butunlay yo‘q qilinadi.') WHERE id = 'cf2c9950-a55b-42b0-9405-349503832e7b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning kun davomidagi jismoniy faoliyati, iste’mol qilgan ovqatlari, kayfiyati va uyqu vaqti organizmidagi gormonlar ajralishiga bevosita ta’sir qiladi. Masalan, o‘sish gormoni tungi uyquning dastlabki bosqichlarida faolroq ajraladi. Chaqalog‘ingiz organizmida yangi hujayralar hosil bo‘lishi, to‘qimalar o‘sishi va umumiy rivojlanish uchun bu gormon muntazam ajralib turishi zarur. Uyqu, ochlik va qondagi qand miqdori pasaygan paytlarda ham o‘sish gormoni ajralishi kuchayadi. Chaqalog‘ingiz organizmi sog‘lom ishlashi uchun, avvalo, o‘sish gormoni, shuningdek, barcha boshqa gormonlar o‘z vaqtida va yetarli miqdorda ajralishi muhim. Shu sababli uyqu vaqtini, muntazam ovqatlanish tartibini hamda kun davomidagi jismoniy va aqliy mashg‘ulotlarni rejalashtirish juda muhim. Kundalik ishlarning muayyan vaqtlarda bajarilishi chaqalog‘ingizning sog‘lom o‘sishi uchun muhim asosdir.') WHERE id = '20d5c4d1-0748-4522-a578-ae19bc9366d7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz allaqachon 21 oylik. Bu 2 yosh inqirozi belgilarini tez-tez kuzatishingiz mumkinligini anglatadi. Mayda motorikasi rivojlanayotgan chaqalog‘ingiz endi qoshiq va sanchqidan to‘g‘riroq foydalana boshladi. Uning chizgan rasmlari va o‘yinlarida ko‘proq tafsilotlar paydo bo‘lganini ko‘rishingiz mumkin. Shu bilan birga, chaqalog‘ingiz oyoq kiyimining tagini ushlashi, shkafdagi kiyimlarni yerga tashlashi yoki kir qo‘llarini kiyimiga artishi mumkin. Ayniqsa, siz munosabat bildiradigan holatlarda u sizni sinash uchun bu xatti-harakatlarni o‘jarlik bilan takrorlashi mumkin. Shuning uchun chaqalog‘ingiz qilishini istamagan harakatlarga haddan tashqari keskin munosabat bildirishdan saqlaning. Biroq umuman e’tiborsiz qolish ham to‘g‘ri emas. Uni o‘sha joydan olib ketish, e’tiborini boshqa narsaga qaratish va bu harakat sizga yoqmasligini tushuntirishga urinish foydaliroq bo‘ladi.') WHERE id = '60bd837f-fdec-4844-be98-fa359c556025';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning, ayniqsa, barcha oila a’zolari birga jam bo‘ladigan dasturxon atrofida faol qatnashishi uning rivojlanishi uchun juda muhim. Shu orqali chaqaloq ijtimoiylashadi, o‘zini oilaning bir qismi deb his qiladi va o‘ziga bo‘lgan ishonchi ortadi. Biroq oilaviy dasturxon atrofida chaqalog‘ingiz sizni diqqat bilan kuzatgani uchun ayrim jihatlarga e’tibor berishingiz kerak. U sizning ovqatlanish odatlaringizdan bevosita ta’sirlanadi. Sizning nosog‘lom ovqatlanishingiz chaqalog‘ingizda ham shunday odatlar shakllanishiga sabab bo‘lishi mumkin. Masalan, chaqalog‘ingizga ichishga ruxsat bermasangiz ham, dasturxonda gazli va nordon ichimliklar bo‘lishi to‘g‘ri emas. Chunki chaqalog‘ingiz uchun eng muhim namuna — sizsiz. Xatti-harakatlaringiz noto‘g‘ri bo‘lsa ham, uning nazarida ular to‘g‘ri hisoblanadi. Shu sababli chaqalog‘ingizga nima qilish kerakligini aytish o‘rniga, undan qanday xatti-harakat kutayotgan bo‘lsangiz, o‘zingiz ham shunday yo‘l tuting.') WHERE id = '26559994-9ac2-46f1-966d-f214b38c785b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning bu oydagi vazni qiz bo‘lsa 9700 - 13.800 gramm, o‘g‘il bo‘lsa 9300 - 14.300 gramm oralig‘ida bo‘lishi kerak. Bo‘yi esa qizlarda 77.9 - 89.4 sm, o‘g‘il bolalarda 79.7 - 90.5 sm oralig‘ida bo‘lishi mumkin. Biroq chaqalog‘ingizning ko‘rsatkichlari bu raqamlardan farq qilsa, bu har doim ham muammo borligini anglatmaydi. Irsiy omillardan tashqari, ovqatlanish odatlari va kundalik jismoniy faollik ham vaznga bevosita ta’sir qiladi. Bo‘y uzunligi esa asosan irsiyatga bog‘liq. Ya’ni siz va turmush o‘rtog‘ingizning bo‘yi o‘rtacha ko‘rsatkichdan baland bo‘lsa, chaqalog‘ingizning ham tengdoshlariga qaraganda biroz balandroq bo‘lishi tabiiy. Shuningdek, chaqalog‘ingiz muddatidan oldin tug‘ilgan bo‘lsa, bu ko‘rsatkichlar hozircha pastroq bo‘lishi kutiladi. Agar shifokoringiz ko‘rik paytida hammasi joyida ekanini aytsa, xavotirlanishga asos yo‘q.') WHERE id = '7bc6e8b6-b844-4ad2-aa4e-838b8a4cdf1d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tarkibidagi Omega-3 yog‘ kislotalari, D vitamini, kalsiy, fosfor va sifatli oqsil tufayli baliq chaqalog‘ingiz ovqatlanishida muhim o‘rin tutadi. Biroq chaqaloqqa baliqni yoqtirishga o‘rgatish ba’zan ota-onalar uchun qiyin kechishi mumkin. Chaqalog‘ingiz hozir biror mahsulotni yemasligi uni hech qachon yemaydi degani emas. Uning ta’miga o‘rganishi uchun vaqt kerak. Shu sababli chaqalog‘ingiz baliq yemasa ham, uni taklif qilishdan voz kechmang. Likopchadagi baliqqa umuman tegmasa ham, haftasiga kamida 2 marta yana taklif qilib ko‘ring. Makaron kabi sevimli taomlariga oz miqdorda baliq qo‘shib, uning miqdorini asta-sekin oshirish sinalgan usullardan biridir. Ammo ehtiyot bo‘ling: agar chaqalog‘ingiz baliqni mutlaqo istamasa, majburlamang. Uni zo‘rlab yedirishga urinsangiz, unda baliqqa nisbatan umrbod davom etadigan ruhiy salbiy munosabat shakllanishi mumkin.') WHERE id = '65d0ee78-f4e8-408f-81b6-d461622ab8cc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz jismonan ulg‘ayib, kuchayganini his qila boshladi. U bu kuchini avval o‘ziga, keyin esa sizga isbotlashni istashi mumkin. Ovqatlanish stolini joyidan siljitishga urinish, uydagi buyumlarni ko‘chirish, hatto tengdoshlarini ko‘tarishga harakat qilish bunga misol bo‘la oladi. U o‘z kuchining chegaralarini sinab ko‘rish uchun turli yo‘llarni sinab ko‘radi. Agar chaqalog‘ingiz og‘ir buyumni qisqa muddatga ko‘tarishga urinayotgan bo‘lsa, ko‘p aralashmang. Ammo u o‘zini haddan tashqari zo‘riqtirayotgan bo‘lsa, buning sababini tushunishga harakat qiling. Ba’zan chaqaloqlar ko‘proq e’tibor jalb qilish uchun shunday yo‘l tutishadi. Bunday vaziyatda unga keskin munosabat bildirish o‘rniga, bu xatti-harakat ortida qanday ehtiyoj borligini tushunishga harakat qiling.') WHERE id = '19034df5-63aa-4566-9b70-59143f344fa9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz iste’mol qiladigan mahsulotlar mavsumga mos va tabiiy bo‘lishiga e’tibor berishingiz kerak. Masalan, yoz oylarida yetiladigan semizo‘t baliqdan keyin eng ko‘p Omega-3 saqlaydigan oziq-ovqatlardan biridir. Agar chaqalog‘ingiz baliqni yoqtirmasa, semizo‘t ajoyib tanlov bo‘ladi. Kuzga o‘tish davrida chaqalog‘ingiz menyusiga xom yong‘oq va funduq qo‘shib, uning immun tizimini qishga tayyorlashingiz mumkin. Kuzda chaqaloqlar juda yaxshi ko‘radigan qovoq mavsumi ham boshlanadi. Qovoqni sho‘rva va taomlarga qo‘shishingiz yoki pyure qilib, yong‘oq va funduq bilan birga tamaddi sifatida berishingiz mumkin. Qish oylarida esa go‘shtli bulyonda tayyorlangan sho‘rvalar chaqalog‘ingiz organizmining qarshilik ko‘rsatish qobiliyatini oshirish uchun eng yaxshi vositalardan biridir.') WHERE id = '1738d682-243e-48b6-aebf-069b7de44903';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz 2 yosh inqirozi tufayli har doim o‘zi aytganidek bo‘lishini istashi mumkin. U ko‘pincha siz aytgan narsaning mutlaqo teskarisini qilishi va o‘z qarorlarini amalga oshirishda siz bilan o‘jarlashishi mumkin. Bu holat chaqalog‘ingiz ulg‘ayayotgani va nima qilishni hal etishda o‘ziga ko‘proq ishona boshlaganining belgisidir. Uni butunlay o‘z holiga tashlab qo‘yish vaqt o‘tishi bilan chaqalog‘ingizda e’tibordan chetda qolganlik hissini paydo qilishi mumkin. Aksincha, sizning ortiqcha o‘jarlik qilishingiz ham unda jahl xurujlariga zamin yaratishi mumkin. Shu sababli chaqalog‘ingizga muayyan xavfsizlik chegaralari doirasida erkinlik berishingiz kerak. Biroq bu chegaralarga nisbatan izchil va qat’iy bo‘lishingiz shart. Masalan; biror joyga ketayotganda qaysi kiyimni kiyishi va kunlik ovqatlanishlardan birida nima yeyishini tanlashni chaqalog‘ingizning o‘ziga topshirishingiz mumkin.') WHERE id = 'db959888-c226-4ece-83bc-9cdcc0c9a618';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizda sog‘lom ovqatlanish odati shakllanishi uning kelajakda sog‘lom inson bo‘lishi uchun juda muhimdir. Biroq sog‘lom ovqatlanish odatini mukofotga bog‘langan shart orqali shakllantirmaslik kerak. Masalan; chaqalog‘ingiz yoqtirmaydigan, ammo siz yedirishni istagan sabzavotni yeganidan keyin unga sevimli taomini mukofot sifatida berish to‘g‘ri usul emas. Chunki bunday tizim bir martalik natija beradi, ammo uni davom ettirish va odatga aylantirish imkonsiz. Chaqalog‘ingiz sog‘lom ovqatlanish odatini egallashi uchun, avvalo, sabzavotlarni yaxshi ko‘rishi kerak. Bu davrda ovqat tayyorlayotganda chaqalog‘ingizdan yordam so‘rashingiz mumkin. Masalan, undan sabzavotlarni sizga uzatishini yoki pishirish jarayonida sizning nazoratingiz ostida aralashtirishini so‘rash yaxshi tanlov bo‘lishi mumkin. Jarayonda ishtirok etgan va o‘z hissasini qo‘shgan chaqalog‘ingiz o‘z mehnati natijasini sinab ko‘rish uchun sabzavotlarni tatib ko‘rishni istaydi.') WHERE id = 'a29ffc6c-9f51-4d1f-9099-df4361738d5a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz hojatga ehtiyoji kelganida bir chetga o‘tib olishi mumkin. Shuningdek, unda kuchanish, cho‘kkalash va uyalish kabi xatti-harakatlarni kuzatishingiz mumkin. Ammo bularning barchasi chaqalog‘ingiz hojatxonaga o‘rgatishga to‘liq tayyor degani emas. Shu sababli chaqalog‘ingizni hojatxonaga o‘rgatishga shoshirmasligingiz va eng to‘g‘ri vaqtni kutishingiz kerak. Ko‘plab mutaxassislar chaqaloq 2 yoshga to‘lmasdan uni hojatxonaga o‘rgatishni boshlash yaxshi fikr emas, deb hisoblaydi. Buning sababi — siydik pufagining hali yetarli miqdorda siydikni ushlab turish imkoniyatiga ega emasligi va shu tufayli siyishni nazorat qilish qiyinligidir. Chaqalog‘ingiz hojatxonaga o‘rgatish uchun fiziologik jihatdan ham tayyor bo‘lishini kutishingiz kerak. Barcha belgilar paydo bo‘lmasdan turib o‘rgatishni boshlash jarayonni yanada qiyinlashtirishi mumkin. Chaqalog‘ingiz hojatxonaga o‘rgatishga to‘liq tayyor bo‘ladigan davr o‘rtacha 24 va 30-oylar orasida boshlanadi.') WHERE id = 'a39ea810-7420-4e1c-a518-23a50b1d1c6e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Karob ekstrakti — balandligi taxminan 8 metrga yetadigan doim yashil daraxt mevalarini texnologik usullar yordamida siqib, suyuq konsentrat holiga keltirish orqali olinadigan mahsulotdir. Karob shinnisidan farqli ravishda, bu ekstrakt qaynatilmagani va boshqa hech qanday ishlovdan o‘tkazilmagani sababli tarkibidagi oziq moddalar saqlanib qoladi. B guruhi kompleks vitaminlari bilan birga A va E vitaminlari, kaliy, rux, natriy, oqsil, temir, magniy va fosfor saqlaydigan karob ekstrakti kalsiyga ham juda boy. Tarkibidagi antioksidantlar tufayli u chaqalog‘ingizning immun tizimini mustahkamlashga va uni kasalliklardan himoya qilishga yordam beradi. Chaqalog‘ingizning aqliy va jismoniy rivojlanishiga hissa qo‘shish bilan birga, kamqonlikning oldini olishga ham ko‘maklashadi. Shuningdek, karob ekstrakti allergiya alomatlarini yengillashtirishi hamda tarix davomida astma va bronxitni davolashda tabiiy vosita sifatida qo‘llangani ma’lum. Chaqalog‘ingiz nonushtada 1-2 choy qoshiq karob ekstrakti iste’mol qilishi uning tarkibidagi kletchatka tufayli ovqat hazm qilish tizimining samarali ishlashiga va kun bo‘yi zarur bo‘lgan quvvatni olishiga yordam beradi.') WHERE id = 'cee447ef-1683-40f9-aaa6-1503f753e5fb';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz aqliy rivojlanishi tufayli endi mayda detallarga ko‘proq e’tibor bera boshlaydi. Masalan, avval uning e’tiborini umuman tortmagan pardangiz chetidagi munchoqlar, yerda ko‘rgan kichkina hasharot yoki likopchasidan tushgan ovqat ushoqlari… Bu detallarning barchasi endi chaqalog‘ingizning faol qiziqish doirasiga kiradi. Bu esa siz e’tibor berishingiz kerak bo‘lgan jihatlar ko‘payganini anglatadi. Chaqalog‘ingiz o‘zi topgan barcha mayda narsalarni yaqindan o‘rganishni istaydi. U hali ham oral bosqich deb ataladigan davrda bo‘lgani uchun o‘rganish vositasi sifatida ko‘proq og‘zidan foydalanadi! 😊 Pardangiz chetidagi munchoqlarni o‘rganish uchun ularni og‘ziga solayotganini ko‘rishingiz mumkin. Agar munchoqlarning uzilib ketish xavfi bo‘lmasa, bu sizga xavfsizdek ko‘rinishi mumkin. Biroq uning hasharotlarni payqashi va ularni o‘rganishni istashi vaziyatni yanada sinchkovlik bilan kuzatishni talab qiladi. Chaqalog‘ingizga hasharotni yaqindan ko‘rib o‘rganishiga ruxsat berishingiz, ammo unga tegmoqchi yoki og‘ziga solmoqchi bo‘lganida aralashishingiz ma’qul.') WHERE id = '9069fb16-d889-49ff-94bd-38c462c7266b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Yong‘oq boshqa mag‘izli mahsulotlarga qaraganda ko‘p miqdorda Omega 3 va Omega 6 yog‘ kislotalarini o‘z ichiga oladi. Bundan tashqari, yong‘oq tarkibida B guruhi kompleks vitaminlari, folat, magniy, mis, fosfor, E vitamini va sifatli oqsil mavjud. Chaqalog‘ingizga beradigan o‘rtacha 50 gramm yong‘oq tarkibida 8 gramm oqsil, 4500 mg Omega 3, 19.000 mg Omega 6, 1.6 mg temir, 78 mg magniy va 180 mg fosfor mavjud. Shu sababli chaqalog‘ingizning yong‘oq iste’mol qilishi juda muhim. Biroq u yeydigan yong‘oqning ayrim xususiyatlariga e’tibor berishingiz kerak. Ochiq holda sotiladigan yoki po‘chog‘i archilgan yong‘oqlar o‘rniga, og‘irligiga e’tibor bergan holda po‘chog‘i bilan sotiladigan yong‘oqlarni tanlashingiz kerak. Agar chaqalog‘ingiz yong‘oqni bemalol yeya olsa, uni yengil maydalab, tamaddiga berishingiz mumkin. Blenderda kukun holiga keltirilgan yong‘oqni yogurtga aralashtirib berish ham juda to‘yimli tanlov bo‘lishi mumkin.') WHERE id = '27105655-fd01-456e-bb71-4a01714e9449';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz tug‘ilgan paytdan boshlab u bilan o‘rnatgan munosabatingiz uning shaxsiyati shakllanishidagi eng muhim omillardan biridir. Ehtiyojlari o‘z vaqtida qondiriladigan va sizdan yetarli mehr ko‘radigan chaqalog‘ingiz bilan orangizda asosiy ishonch hissi paydo bo‘ladi. Chaqalog‘ingizning shaxsiyati sog‘lom rivojlanishi uchun faqat uning jismoniy ehtiyojlarini o‘z vaqtida va to‘liq qondirish yetarli emas. Unga yetarlicha mehr berilmasa, shaxsiyati shakllanishida ayrim salbiy holatlar yuzaga kelishi mumkin. Shuningdek, bu g‘amxo‘rlik, e’tibor va mehrning uzluksiz bo‘lishi juda muhim. Shu bilan birga, xatti-harakatlaringiz ham izchil bo‘lishi kerak. Chaqalog‘ingizga nisbatan munosabatingiz izchil va ijobiy bo‘lsa, unda hayotdan mamnun bo‘lishiga doir asosiy ishonch hissi shakllana boshlaydi. Asosiy ishonch hissining shakllanishi chaqalog‘ingiz shaxsiyatining sog‘lom rivojlanishida eng muhim o‘rinlardan birini egallaydi.') WHERE id = '34e65f61-d1c2-4a9e-8715-5a4ccba0a4d1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Propolis — asalarilar o‘simliklarning poyalari, barglari va kurtaklaridan to‘playdigan, kuchli antibakterial va antioksidant ta’sirga ega modda. Dunyoda kashf etilgan eng kuchli antioksidant xususiyatli bu modda anor sharbatiga qaraganda 80 baravar ko‘proq antioksidantni o‘z ichiga oladi. Asalarilar yopishqoq tuzilishga ega bu moddadan ko‘proq uyalarini sterilizatsiya qilish va zararli mikroorganizmlarni zararsizlantirish uchun foydalanadi. To‘g‘ri qayta ishlanganda esa propolisning inson immuniteti uchun isbotlangan ko‘plab foydalari mavjud. Ayniqsa, immuniteti hali to‘liq shakllanmagan chaqalog‘ingizni himoya qilish uchun propolisning immunitetni mustahkamlovchi ta’siridan foydalanishingiz mumkin. Agar chaqalog‘ingiz asal iste’mol qilsa va asalga allergiyasi bo‘lmasa, propolisni ham bemalol qabul qilishi mumkin. Propolis muntazam qo‘llanilganda chaqalog‘ingizning immunitetini mustahkamlaydi, kasallik paytida organizmdagi virus va bakteriyalarni yo‘q qiladi hamda kasalliklarni yuqtirish xavfini sezilarli darajada kamaytiradi.') WHERE id = '91bdc58d-0298-42d1-becf-b47ed9613a9c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz qiz bo‘lsa, u qo‘g‘irchoqlardan ko‘ra mashinalarga, o‘g‘il bo‘lsa esa mashinalardan ko‘ra qo‘g‘irchoqlarga ko‘proq qiziqayotganini ko‘rishingiz mumkin. Bunday vaziyatda ayrim ota-onalar xavotirga tushib, bu moyillikni o‘zgartirishga va chaqalog‘iga aralashishga harakat qiladi. Ayniqsa, har ikki jinsdagi chaqaloqlaringiz bo‘lsa yoki chaqalog‘ingiz boshqa jinsdagi tengdoshlari bilan tez-tez vaqt o‘tkazsa, buni ko‘proq kuzatishingiz mumkin. Chaqalog‘ingiz bu davrda o‘z jinsini anglay boshlagan. Biroq jinsini payqash va jins tushunchasini anglash boshqa-boshqa narsalardir. Qisqacha aytganda, bu davrda chaqalog‘ingiz jins tushunchasini hali to‘liq anglay olmaydi. Buni tushunishi uchun unga yana taxminan bir yil kerak bo‘ladi. O‘g‘il va qiz bolalarga xos xatti-harakatlar esa eng erta 3.5-4 yoshda farqlana boshlaydi. Shu sababli chaqalog‘ingizni muayyan yo‘nalishga undashga harakat qilishingiz shart emas.') WHERE id = 'ed2e24a4-c2b1-4d6f-86c8-6f25e802ef0a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'So‘nggi yillarda rivojlangan texnologiyalar tufayli endi barcha meva va sabzavotlarni yilning istalgan faslida topish mumkin. Biroq hammaga ma’lumki, o‘z mavsumida yetishtirilgan sabzavot va mevalar ham mazaliroq, ham foydaliroq bo‘ladi. Bundan tashqari, ular tabiiy ravishda yetishtirilgani uchun mavsumiy meva va sabzavotlar vitaminlar hamda minerallarga boyroqdir. Ayniqsa, gap chaqalog‘ingizning ovqatlanishi haqida ketganda, mahsulotlarning mavsumga mos bo‘lishiga ko‘proq e’tibor berishingiz kerak. Masalan, qish oylarida tabiiy ravishda yetishtirilgan ismaloq tarkibida yozda yetishtirilgan ismaloqqa qaraganda 3 baravar ko‘proq C vitamini bo‘ladi. Mavsumdan tashqari yetishtiriladigan sabzavot va mevalarda gormonal qo‘shimchalar va ayrim zararli kimyoviy preparatlar ham qo‘llaniladi. Bunday moddalar chaqalog‘ingiz organizmiga toksik ta’sir ko‘rsatishi mumkinligi sababli uning ovqatlanish dasturini mavsumiy sabzavot va mevalar asosida tuzishingiz juda muhim.') WHERE id = 'cb687d0d-1a07-40e8-8dc8-33e46be11729';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz uchun uyda oson topiladigan buyumlardan rivojlantiruvchi materiallar tayyorlashingiz mumkin. Sizga kerak bo‘ladi: shisha butilka, plastik butilka, biroz suv, guruch, quruq loviya va yasmiq kabi turli dukkakli mahsulotlar. Avvalo, barcha buyumlarni chaqalog‘ingizga tanishtirishdan boshlang. Shisha va plastik butilkalarning qopqog‘ini ochib, ularga navbat bilan puflashini so‘rang. Har ikkala idishdan nima uchun turli tovushlar chiqayotganini chaqalog‘ingizdan so‘rashingiz mumkin. Keyin bu butilkalarga ozgina suv quyib, tajribani takrorlang va tovushlar nima sababdan o‘zgargani haqida bir-biringizga savollar bering. So‘ng shisha butilkaga guruch kabi mayda donlarni solib, chaqalog‘ingizga uni chayqatib ko‘rishni taklif qiling. Xuddi shu jarayonni plastik butilka bilan ham bajaring va donalar bir xil bo‘lsa-da, nima uchun shisha butilkadan chiqayotgan tovush jarangdorroq ekanini so‘rang. Bu mashg‘ulotni boshqa don mahsulotlari bilan ham takrorlab, tovushlarning o‘zgarish sabablarini birgalikda tushunishga harakat qiling. Vaqtingizni maroqli o‘tkazing! 😊') WHERE id = '8b5577e9-8555-46ea-9858-e2aca89ca5d4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz tug‘ilganidan keyingi dastlabki 24 oy — uning tashqi dunyodagi fiziologik va aqliy rivojlanishi eng jadal kechadigan davrdir. Ushbu tez o‘sish jarayonida chaqalog‘ingizning makro va mikro oziq moddalarga bo‘lgan ehtiyoji kattalarnikiga qaraganda yuqoriroq bo‘ladi. Shu sababli uning yetarli va muvozanatli ovqatlanishi salomatligi hamda izchil rivojlanishi uchun juda muhimdir. 2 yoshga to‘lish arafasida bo‘lgan chaqalog‘ingizning ichak mikrobiotasi kattalarnikiga o‘xshash yakuniy shaklga kelish bosqichida. Shuningdek, uning aqliy funksiyalari ham 90% darajada rivojlangan. Bu davrda chaqalog‘ingiz organizmi uchun zarur miqdordagi organik va noorganik moddalarni muvozanatli ravishda olishi kerak. Tuxum tarkibida kalsiy, temir, rux va B vitaminlari ko‘p. Shu sababli tuxumni chaqalog‘ingiz ratsionida qo‘shimcha oziq sifatida ishlatishingiz mumkin. Agar chaqalog‘ingizda tuxumga allergiya bo‘lmasa, shu tariqa u eng sifatli oqsil manbalaridan birini iste’mol qilgan bo‘ladi.') WHERE id = '9f49e07d-85c6-4330-803a-53c01fdd33b1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz kun davomida sizning nazoratingiz ostida bo‘lishi bilan birga, siz nazorat qila olmaydigan ko‘plab voqealarni ham boshdan kechirishi mumkin. Bunday holatlar, ayniqsa u ilk bor duch kelayotgan bo‘lsa, qo‘rqinchli tuyulishi mumkin. Kun davomidagi mashg‘ulotlar tufayli o‘sha paytda bunga munosabat bildirmasa ham, his qilgan qo‘rquvi sababli kechasi yolg‘iz qolishdan va uxlashdan qochishi mumkin. Uxlab qolganida esa ong ostiga muhrlangan bu qo‘rquvni tushida ko‘rib, qichqirib uyg‘onishi mumkin. Chaqalog‘ingiz bu bosqichda tushlarni haqiqiy deb o‘ylaydi. Boshqacha aytganda, u tushida ko‘rganlari haqiqat ekanini va uyg‘onganida yo‘qolib qolganini o‘ylaydi. Taxminan 7 yoshgacha tush bilan haqiqatni farqlay olmaydigan chaqalog‘ingizni bunday vaziyatlarda tinchlantirishingiz muhim. Uni quchoqlashingiz, tushini aytib berishini so‘rashingiz va bir muddat yonida qolishingiz yaxshi yordam berishi mumkin.') WHERE id = '9b4f4b9b-e87e-40ab-829d-b7915986e8b3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Juda qadim zamonlardan beri oziq-ovqat mahsulotlarini ozuqaviy qiymatini yo‘qotmasdan saqlash uchun quritish usulidan foydalaniladi. Ayniqsa, quritilgan mevalar chaqalog‘ingizning ovqatlanish ratsionida albatta bo‘lishi kerak. Bu mevalar o‘z mavsumida terilib, quyosh nuri ostida tarkibidagi suv bug‘lantirilishi orqali tayyorlanadi. Quritish jarayonida mevalarning suv miqdori 85% dan 15% gacha kamayadi, shakar miqdori esa oshadi. Kalsiy va kletchatkaning yaxshi manbai bo‘lgan bu mevalar chaqalog‘ingizning ovqat hazm qilish tizimi hamda suyaklari rivojlanishiga katta hissa qo‘shadi. Tarkibidagi kuchli antioksidantlar tufayli ular immunitet tizimini himoya qilishda ham samarali. Bundan tashqari, quruq mevalar yangi mevalarga qaraganda uzoqroq saqlanishi sababli zaxiralash uchun qulaydir. Tarkibidagi tabiiy shakar tufayli esa chaqalog‘ingiz ularni iste’mol qilganidan ko‘p o‘tmay kerakli energiyani oladi.') WHERE id = 'd3489a97-b65f-4aae-ab71-7ebccc7eca0f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ayrim davrlarda ishtahasi pasayishi va ovqatlanishdan bosh tortishiga og‘zida paydo bo‘ladigan afta deb ataluvchi yaralar sabab bo‘lishi mumkin. Aftalar og‘iz shilliq qavatining istalgan qismida turli shakllarda paydo bo‘ladigan va og‘riq keltirib chiqaradigan shikastlanishlardir. Buning asosiy sababi chaqalog‘ingiz yaqinda qabul qilgan dorilar yoki boshdan kechirgan infeksiya bo‘lishi mumkin. Boshqa sabablar qatoriga emizikli onalarning ko‘krak sohasi yetarlicha toza bo‘lmasligi, butilka va o‘yinchoqlar tozaligiga e’tibor berilmasligi hamda immunitet tizimining zaiflashishi kiradi. Tekkanda og‘riq beradigan bu yaralar hech qanday davolashsiz 1-2 haftada o‘tib ketishi mumkin. Biroq gap chaqalog‘ingiz haqida ketayotgan bo‘lsa, shifokor bilan maslahatlashib qo‘llanadigan dorilar yordamida aftalarni 1-2 kunda davolash mumkin. Shuningdek, shifokor ruxsati bilan xalq tabobati usullaridan biri sifatida suyultirilgan ichimlik sodasiga (karbonat) namlangan tamponni yara bor joyga qo‘yishingiz mumkin.') WHERE id = '2ccbc797-3a7f-4d46-86ba-8a535032d851';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'So‘nggi yillarda o‘tkazilgan tadqiqotlarga ko‘ra, ayrim mutaxassislar bolalarga dastlabki ikki yil davomida sigir suti yoki undan tayyorlangan muzqaymoq berishga ehtiyotkorlik bilan yondashishni tavsiya qiladilar. Buning asosiy sababi — ichaklar rivojlanishi faqat 2 yosh atrofida to‘liq shakllanishi va sigir suti kamqonlik xavfini oshirishi mumkinligidir. Chaqalog‘ingiz endi 2 yoshga yaqinlashmoqda. Agar unda sut va sut mahsulotlariga ma’lum allergiya bo‘lmasa, shifokoringiz bilan maslahatlashgan holda muzqaymoq yeyishiga ruxsat berishingiz mumkin. Oqsil va uglevodlarga boy muzqaymoq deyarli barcha vitaminlarni, shuningdek, kalsiy, kaliy, fosfor, magniy, temir va rux kabi minerallarni o‘z ichiga oladi. Ayniqsa, chaqalog‘ingiz suyaklari rivojlanishi uchun muhim bo‘lgan kalsiyni boshqa oziq-ovqatlardan yetarli miqdorda ololmasa, muzqaymoq yaxshi muqobil bo‘lishi mumkin. Biroq chaqalog‘ingiz muzqaymoqni me’yoridan ortiq iste’mol qilmasligiga e’tibor berishingiz kerak. Tarkibidagi uglevod va shakar tufayli ko‘p miqdorda iste’mol qilingan muzqaymoq ortiqcha kaloriya berishini unutmang.') WHERE id = '6fd1f804-625f-4260-ad27-7db11651d8f4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2 yoshga to‘lishiga oz qolgan chaqalog‘ingiz shu kunlarda oyoqlarini ko‘rsatib, ko‘p harakat qilishni istamayotganini sezishingiz mumkin. Chaqalog‘ingiz tug‘ilganidan boshlab taxminan 12-13 yoshgacha suyaklarning epifiz plastinkalari sohasidan uzayishi hisobiga jismonan o‘sadi. Bu o‘sish jarayonida, ayniqsa, yelka sohasi, bilaklar hamda oyoqlarning tizzadan pastki va yuqori qismlarida og‘riq paydo bo‘lishi odatiy hol hisoblanadi. Qiz va o‘g‘il bolalarda bir xil darajada uchraydigan bu og‘riqlar suyaklarning o‘sish sohasida yuz beradigan o‘zgarishlar natijasida kelib chiqadi. Aniqroq aytganda, suyaklar atrofidagi mushak, pay va boylam kabi yumshoq to‘qimalarning o‘sish paytida yuzaga keladigan shish tufayli sezgir bo‘lib qolishi bu og‘riqlarga sabab bo‘ladi. Chaqalog‘ingiz kunduzgi faollik tufayli o‘sish og‘riqlarini kechki payt kuchliroq his qilishi mumkin. Odatda davolashni talab qilmaydigan bu og‘riqlarni dam oldirish va og‘riqli sohani yengil uqalash orqali kamaytirishingiz mumkin.') WHERE id = 'c6878c04-fea4-41bf-9978-ffa27c8ba4e7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ba’zi oilalar chaqalog‘ida qorin dam bo‘lishidan qo‘rqib, turli rangdagi yasmiq turlarini berishga ikkilanadilar. Biroq to‘g‘ri pishirish usuli yordamida hazm qilish va qorin dam bo‘lishi bilan bog‘liq muammolarsiz yasmiqning foydalaridan bahramand bo‘lish mumkin. Yasmiqni bir kun oldin ivitib qo‘ysangiz va pishirish paytida suvini almashtirsangiz, qorin dam bo‘lish ehtimoli ancha kamayadi. Qizil yasmiq tez pishishi va yumshoqroq bo‘lishi sababli chaqalog‘ingiz uchun tayyorlanadigan sho‘rva va pyurelarga ko‘proq mos keladi. Tarkibida temir, oqsil, fosfor, B vitaminlari va ko‘p miqdorda minerallar mavjud bo‘lgan yasmiq folatga ham boy. Bir kosa yasmiqning o‘ziyoq chaqalog‘ingizning oqsilga bo‘lgan kunlik ehtiyojining deyarli yarmini qoplaydi. Shu sabablarning barchasiga ko‘ra, chaqalog‘ingizning ovqatlanish ratsioniga yasmiqni kiritishingiz uning rivojlanishi uchun juda muhimdir.') WHERE id = '15714a3a-d1f3-4262-b777-caa9b8b65081';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu bosqichda chuqur uyquga o‘tish paytida ayrim xurujlarni boshdan kechirishi mumkin. Bu uyqu bosqichlari o‘rtasidagi o‘tish jarayoni hali to‘liq shakllanmaganidan kelib chiqadi. Agar chaqalog‘ingiz tunda qichqirib uyg‘onsa va bir muddat nima qilsangiz ham uni tinchlantira olmasangiz, bu tungi qo‘rquv xuruji bo‘lishi mumkin. Bu holat 5 daqiqa yoki yarim soatdan ko‘proq davom etishi mumkin. Bu vaqt davomida chaqalog‘ingizning yonidan ketmasligingiz, uning o‘ziga va atrofidagilarga zarar yetkazishining oldini olishingiz kerak. Chunki xuruj paytida chaqalog‘ingiz to‘liq uyg‘oq bo‘lmagani uchun ongli ravishda harakat qilmaydi. Shu sababli jarohatlanish ehtimoli yuqori bo‘ladi. Tungi qo‘rquv xurujlari odatda o‘smirlik davriga kelib kamayadi, ammo ularning tez-tez takrorlanishi boshqa muammoning belgisi bo‘lishi mumkin. Agar chaqalog‘ingizda bu holatni tez-tez kuzatsangiz, shifokoringiz bilan maslahatlashish foydali bo‘ladi.') WHERE id = 'df85d749-c950-4fca-8bdc-a3b2e555941f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tabiiy shakar, oqsil, ko‘p miqdordagi kletchatka hamda turli vitamin va minerallarni o‘zida jamlagan xurmo insoniyatga ma’lum eng qadimiy o‘simlik turlaridan birining mevasidir. Xurmo chaqalog‘ingizning rivojlanishi uchun qondagi qizil qon hujayralari (eritrotsitlar) muvozanatini saqlashga yordam beradi. Shuningdek, xurmo tarkibidagi kalsiy va fosfat chaqalog‘ingizning rivojlanayotgan skelet tizimi va suyak tuzilishini mustahkamlashda muhim rol o‘ynaydi. Xurmo ichaklarda A vitaminiga aylanadigan Beta-karotinga boy. Beta-karotin, ayniqsa, miya rivojlanishi uchun juda muhimdir. Bu moddani muntazam qabul qilish aqliy faoliyatni tartibga soladi va saratondan himoya qiluvchi qalqon hosil qiladi. Xurmo tarkibida taxminan 15% kletchatka mavjud bo‘lib, u chaqalog‘ingizning ovqat hazm qilish tizimi faoliyatini yengillashtiradi va qabziyatga qarshi samarali vosita hisoblanadi. Kletchatkaga boy oziq-ovqatlar saraton xavfini kamaytirgani uchun chaqalog‘ingiz menyusida xurmo kabi kletchatkali mahsulotlarga ustunlik berishingiz muhimdir.') WHERE id = '4303bdd7-56ec-4a2e-93fe-7dba4f34f12e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz kelajakda o‘z mas’uliyatini anglaydigan inson bo‘lib ulg‘ayishini istashingizni bilamiz. Farzandingiz kelajakda qanday shaxs bo‘lib yetishishi ona qornidagi davrdan boshlab maktab yoshigacha shakllanadi. Chaqalog‘ingizda mas’uliyat hissining poydevorini yaratish uchun hozirdanoq bajarishingiz mumkin bo‘lgan juda oddiy mashg‘ulotlar bor. Masalan: o‘simlik o‘stirish! Loviya yoki no‘xat kabi oson unadigan dukkaklilar, biroz suv, bitta idish va ozgina paxta. Sizga kerak bo‘ladigan narsalar shulardan iborat! 😊 Chaqalog‘ingiz bilan birga idish ichiga biroz paxta soling. So‘ng urug‘ni paxtaning o‘rtasiga joylashtiring va ustini xuddi shuncha paxta bilan yoping. Tayyorlagan narsangizga chaqalog‘ingiz sizning nazoratingiz ostida oz miqdorda suv quyishi mumkin. Keyin idishni qorong‘i joyda taxminan 48 soat davomida unib chiqishi uchun qoldiring. Chaqalog‘ingiz o‘simligini vaqti-vaqti bilan tekshirib turishiga amin bo‘lishingiz mumkin. 😊 Nihol unib chiqqach, o‘simligingizni mos tuvakka ekishingiz va chaqalog‘ingizdan unga qanday nom berishini so‘rashingiz mumkin. Vaqtingiz maroqli o‘tsin! 😊') WHERE id = '45b4dd3a-d197-4577-bd56-c783da7250c0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz hayotining dastlabki 1 yilidan tashqari, uning ovqatlanish ratsioniga har doim asal qo‘shishingiz mumkin. Ko‘plab vitamin va minerallarga boy bo‘lgan asal tarkibidagi clostridium botulinum nomli sporali bakteriya sababli uni dastlabki bir yil davomida chaqaloqlarga berish tavsiya etilmaydi. Bu bakteriya dastlabki 1 yil ichida immun tizimi hali to‘liq shakllanmagan va organizmi juda ta’sirchan bo‘lgan chaqalog‘ingizda jiddiy muammolarni keltirib chiqarishi mumkin. Biroq bu bosqichdan keyin hayotiy muhim moddalarga boy asalni chaqalog‘ingiz ovqatlanishida bemalol qo‘llashingiz mumkin. Ayniqsa, chaqalog‘ingizda ishtaha bilan bog‘liq muammo bo‘lsa, asal hazm qilishni yengillashtirishi va ishtahani ochishini ko‘rsatadigan tadqiqotlar mavjud. Shuningdek, asal tarkibidagi aminokislotalar va fermentlar tufayli chaqalog‘ingiz tanasida turli sabablarga ko‘ra paydo bo‘lgan yaralarning tezroq bitishiga yordam beradi. Bundan tashqari, tadqiqotlar 1 yoshdan keyin muntazam asal iste’mol qiladigan chaqaloqlar boshqalarga qaraganda tezroq rivojlanishini ko‘rsatadi.') WHERE id = 'ff1e9f61-df65-4064-8df5-c43b49055772';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz o‘yinchoqlari och qolgan deb o‘ylab, ularni ovqatlantirmoqchi bo‘lishini yoki biror buyumi yerga tushsa, uni olib o‘pishini kuzatishingiz mumkin. Chaqalog‘ingiz ulg‘aygani sayin yoshiga xos ayrim fikrlash usullarini namoyon qiladi. Bu davrda u jonsiz buyumlarga xuddi jonlidek munosabat bildirishi mumkin. Kognitiv rivojlanish bosqichlarida bu davr animizm deb ataladi. Bu jonsiz buyumlarga jonli mavjudotlarga xos xususiyatlarni berishga moyillikdir. Buning sababi — chaqalog‘ingiz tiriklikni belgilovchi xususiyat nima ekanini hali to‘liq anglay olmasligidir. Masalan, o‘zi yerga yiqilganda og‘riq his qiladigan chaqalog‘ingiz o‘yinchog‘i ham yerga tushganda uning joni og‘ridi, deb o‘ylashi mumkin. Taxminan ikki yil davom etadigan bu jarayon keyinchalik chaqalog‘ingiz tiriklikni harakat bilan bog‘lay boshlashi bilan yakunlanadi. Taxminan maktab yoshigacha harakatlanadigan barcha narsalarni jonli deb hisoblaydigan chaqalog‘ingiz faqat 6-7 yoshlarida tiriklik tushunchasini to‘liq anglay boshlaydi.') WHERE id = 'b8c5e8a1-fa66-481e-a257-382cebe56450';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning nonushtasida tovuq tuxumi bilan birga bedana tuxumidan foydalanish ham yaxshi tanlov bo‘lishi mumkin. Bedana tuxumi kichik bo‘lgani uchun uning oziqaviy qiymati tovuq tuxumidan past degan keng tarqalgan fikr noto‘g‘ri. Tovuq tuxumidagi kabi bedana tuxumida ham oqsil bir xil nisbatda mavjud. Bundan tashqari, bedana tuxumidagi temir, rux va kaliy miqdori tovuq tuxumidagiga qaraganda yuqoriroq. Biroq so‘nggi yillarda o‘tkazilgan tadqiqotlar bedana tuxumidagi estrogen gormoni bolalarda erta balog‘atga yetishga sabab bo‘lishi mumkinligini ko‘rsatmoqda. Erta balog‘atga yetish chaqalog‘ingizning sut bezlari vaqtidan oldin kattalashishiga va tanasida tuklar ko‘proq o‘sishiga olib kelishi mumkin. Shu sababli chaqalog‘ingiz bedana tuxumini har kuni emas, haftasiga ko‘pi bilan 2 kun iste’mol qilishi yetarli.') WHERE id = 'b265a8fe-9ad6-4889-9714-f72792f5fc6a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz ancha sabrsiz bo‘ladigan va egotsentrizm (o‘zini markaz deb bilish) eng yuqori darajaga chiqadigan 22-oyga xush kelibsiz! 😊 Taxminan 2 yoshda boshlanib, 6 yoshgacha davom etadigan bu davrda chaqalog‘ingiz dunyo va atrofidagilarni faqat o‘z nuqtayi nazaridan talqin qila boshlaydi. U hamma voqealarga o‘zi kabi qaraydi, deb o‘ylaydi va o‘zidan boshqalarning fikrlariga ahamiyat bermaydi. Egotsentrizm kattalarda psixologik buzilishning bir turi hisoblansa-da, bu yoshdagi bolalar uchun tabiiy rivojlanish jarayonidir. Doimo o‘zi bilan faxrlanadigan chaqalog‘ingiz bo‘lishishni yoqtirmaydi va undan tez-tez men, meniki, menga tegishli kabi so‘zlarni eshitishingiz mumkin. O‘ziga haddan tashqari e’tibor qaratadigan chaqalog‘ingiz hamma narsaning markazida o‘zi va o‘z qarorlari turadi, deb hisoblaydi. Bu davrda chaqalog‘ingizga nisbatan yanada xotirjam va sabrli bo‘lishingiz kerak. Uni tushunishga harakat qilish egotsentrizm davrini yengilroq o‘tkazishingizga yordam beradi.') WHERE id = 'cdeb8d0f-e8d6-42f6-b726-3cb574c7ad31';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Kobalamin deb ataladigan B12 vitamini chaqalog‘ingiz organizmida qizil qon hujayralari (eritrotsitlar) hosil bo‘lishi, hujayralar metabolizmi, asab tizimi faoliyati va DNK ishlab chiqarilishida muhim rol o‘ynaydi. Suvda eriydigan vitamin bo‘lgan kobalaminni B guruhidagi boshqa vitaminlardan ajratib turadigan eng muhim xususiyat — tarkibida kobalt mavjud bo‘lgan yagona vitamin ekanidir. Tez o‘sish bosqichidagi chaqalog‘ingiz har daqiqada millionlab qizil qon hujayralarini ishlab chiqaradi. Bu hujayralar B12 vitaminisiz to‘g‘ri ko‘paya olmaydi. B12 vitamini darajasi juda pasayib ketsa, qizil qon hujayralari ishlab chiqarilishi kamayadi va kamqonlikdan boshlab ko‘plab muammolar yuzaga kelishi mumkin. Chaqalog‘ingiz tug‘ilgandan keyingi dastlabki 6 oy davomida bu ehtiyojini homiladorlik davrida organizmida to‘plangan zaxiralar hisobidan qoplaydi. Keyinchalik esa uni qo‘shimcha oziq-ovqatlardan olishi kerak. B12 vitamini meva va sabzavotlarda deyarli mavjud emas. Shu sababli chaqalog‘ingizning B12 vitaminiga bo‘lgan ehtiyojini oqsilga boy hayvon mahsulotlari orqali qoplashingiz kerak. Agar chaqalog‘ingizda hayvon mahsulotlariga allergiya bo‘lsa yoki boshqa biror sababga ko‘ra bu mahsulotlarni iste’mol qilmasa, B12 vitamini bilan boyitilgan don mahsulotlaridan foydalanishingiz mumkin.') WHERE id = '64cdc31d-80de-4ea5-bd52-b34349ce73c3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Persentil jadvaliga ko‘ra, chaqalog‘ingizning bu oydagi o‘rtacha vazni qizlarda 11.800 gramm, o‘g‘il bolalarda esa 12.400 grammni tashkil etadi. Bu bosqichdan keyin chaqalog‘ingizning vazn qo‘shish sur’ati yanada sekinlashganini yoki bir muddat vazni o‘zgarmay qolganini sezishingiz mumkin. Chaqalog‘ingiz faol harakatlanishi tufayli kunlik sarflaydigan kaloriyasi ko‘payishi tabiiy holat hisoblanadi. Shu sababli uning qabul qiladigan va sarflaydigan kaloriyalari o‘rtasida deyarli muvozanat yuzaga keladi. Ayrim istisnolardan tashqari, chaqalog‘ingiz ishtahasining pasayishi ham taxminan 2 yoshda kuzatiladigan odatiy holatdir. Shu sabablarning barchasi tufayli chaqalog‘ingizning vazn qo‘shishi to‘xtashi, hatto biroz vazn yo‘qotishi ham tabiiy deb hisoblanishi mumkin. Ammo uzoq vaqt davomida vazn qo‘shmaslik yoki xavotir uyg‘otadigan darajada vazn yo‘qotish kabi holatlarni kuzatsangiz, shifokoringiz bilan maslahatlashishingiz kerak.') WHERE id = '6d7daca4-fa1d-4f35-8fb6-2e31e98f98b2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz uchun eng foydali meva va sabzavotlarni tanlash hamda uning ovqatlanish tartibiga jiddiy e’tibor berish qanchalik muhim bo‘lsa, ularni qanday tayyorlashingiz va qaysi usulda saqlashingiz ham shunchalik muhimdir. So‘nggi yillarda aluminiy haqida ko‘plab tadqiqotlar o‘tkazildi. Tadqiqot natijalariga ko‘ra, Alsgeymer kasalligi rivojlanishining sabablaridan biri aluminiyning haddan tashqari ta’siriga duchor bo‘lish ekani aniqlandi. Voyaga yetgan inson organizmi kuniga 50 mg gacha aluminiyni hech qanday zarar ko‘rmasdan siydik orqali chiqarib yubora oladi. Aluminiy tabiatda eng ko‘p uchraydigan metall bo‘lib, biz ichadigan suvda, iste’mol qiladigan meva va sabzavotlarda ham ma’lum miqdorda mavjud. Aluminiy tova va qozonlarda pishirilgan taomlarga taxminan 2-3 mg aluminiy o‘tishi mumkin. Bu miqdor alohida olinganda zararsizdek ko‘rinsa-da, uzoq muddatda organizm ko‘proq metall ta’siriga duchor bo‘lishini anglatadi. Ayniqsa, chaqaloqlar organizmi kattalarnikiga qaraganda ancha sezgir bo‘lgani uchun ovqat tayyorlashda aluminiy idishlardan foydalanmaslik yaxshi qaror bo‘lishi mumkin.') WHERE id = 'e9dafa7a-dbe9-4ea9-83e2-ee717a327062';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz, ayniqsa, fasllar almashinuvi va qish oylarida osongina shamollashi mumkin. Shamollashga 200 ga yaqin turli virus sabab bo‘lishi va u har bir chaqaloqda turlicha alomatlar bilan namoyon bo‘lishi mumkin. Hatto sog‘lom chaqaloqning ham yiliga o‘rtacha 5-6 marta shamollashi odatiy hol hisoblanadi. Shamollash odatda 1 haftada butunlay o‘tib ketishi mumkin, ammo ba’zan 3 haftagacha davom etadi. Burun bitishi, aksirish, yo‘tal va balg‘am kabi alomatlar bilan namoyon bo‘ladigan shamollashni davolashning maxsus usuli yo‘q. Buning sababi shamollashni keltirib chiqaradigan viruslarning mavjud dorilarning ko‘piga chidamlilik hosil qilganidir. Chaqalog‘ingiz o‘z immuniteti yordamida shamollashni yengib o‘tishi uchun u yotgan xonani tez-tez shamollatishingiz, burnini muntazam tozalashingiz va ko‘p suyuqlik ichishini ta’minlashingiz kerak.') WHERE id = '30d86d17-88ba-44a4-83aa-4077d27f7fa2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Meva sharbatlari chaqalog‘ingiz uchun juda muhim C vitamini manbaidir. Bundan tashqari, meva sharbatlari chaqaloqlar eng yaxshi ko‘radigan mahsulotlar qatoriga kiradi va ular odatda uni rad etmaydi. Masalan, shaftoli sharbati beta-karotinga boy bo‘lib, chaqalog‘ingizning kasalliklarga qarshi himoya tizimi, ya’ni immuniteti mustahkamlanishiga yordam beradi. Bir stakan o‘rik sharbati chaqalog‘ingizning A vitaminiga bo‘lgan kunlik ehtiyojining deyarli yarmini qoplashi mumkin. Olma sharbati kuchli antioksidant manbai bo‘lib, tadqiqotlarga ko‘ra, olmaning hujayralar shikastlanishining oldini olish xususiyati isbotlangan. Anor sharbati esa tarkibidagi kalsiy, kaliy va boshqa moddalar tufayli chaqalog‘ingiz uchun juda kuchli antioksidant hisoblanadi. Tarkibida ko‘p miqdorda C vitamini bo‘lgan apelsin sharbati chaqalog‘ingizning immun tizimini qo‘llab-quvvatlab, uni infeksiyalardan himoya qiladi. Ammo meva sharbatlarini haddan tashqari ko‘p iste’mol qilish ularning tarkibidagi shakar tufayli tishlar kariyesiga sabab bo‘lishi mumkinligini unutmasligingiz kerak.') WHERE id = 'f63fb22f-332c-41cc-bd05-f7461cef0189';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ayniqsa, so‘nggi yillarda bolalar orasida uzoqni yaxshi ko‘ra olmaslik bilan kechadigan miopiya ancha keng tarqaldi. Miopiya uzoqni yaxshi ko‘ra olmaslik yoki xira ko‘rishga sabab bo‘ladigan kasallikdir. U davolanmasa va erta aniqlanmasa, tez rivojlanishi mumkin. Miopiya ko‘z olmasining old-orqa o‘qi odatdagidan uzunroq bo‘lishi tufayli yuzaga keladi. So‘nggi tadqiqotlarga ko‘ra, bu farq quyosh nuri yetishmasligi bilan ham bog‘liq ekani aniqlangan. Shuningdek, chaqaloqlarning televizor, telefon va planshet kabi texnologik qurilmalar qarshisida ko‘p vaqt o‘tkazishi miopiya uchrashini ko‘paytiradigan omillardan biridir. Ko‘zdagi har qanday nuqsonni erta aniqlash va uning oldini olish uchun chaqalog‘ingizni ko‘pi bilan har 6 oyda ko‘z tekshiruviga olib borishingiz muhim. E’tiborsiz qoldirilsa, miopiya maktab davrida chaqalog‘ingizda yanada jiddiy ko‘rish muammolariga sabab bo‘lishi mumkin.') WHERE id = '8b3f6818-28e3-4c63-890f-86f37d302ed7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Qizil-binafsha rangli meva va sabzavotlarni iste’mol qilish chaqalog‘ingiz turli vitaminlar, minerallar va antioksidantlarni olishi uchun juda muhim. Chernika, maymunjon, malina, qoraqat, qulupnay, tarvuz, pomidor va qalampir kabi mahsulotlar chaqalog‘ingiz salomatligini asrash hamda uning muntazam o‘sib-rivojlanishi uchun zarur. Qizil va binafsha rangli mahsulotlar tarkibidagi antioksidantlarning yuqori miqdori tufayli chaqalog‘ingizni saraton hujayralarining ko‘payishidan himoya qiladi. Tadqiqotlar qizil mevalardagi antioksidantlar, ayniqsa, yo‘g‘on ichak saratoniga qarshi samarali ekanini ko‘rsatadi. Bu rangdagi meva va sabzavotlar xolesterin miqdorini muvozanatlashtiradi, shuningdek, gipertoniya, infarkt va yurak ritmining buzilishi kabi yurak-qon tomir kasalliklari rivojlanishi xavfini kamaytiradi. Bundan tashqari, qizil-binafsha mevalarning kaloriyasi boshqa mevalarga qaraganda kamroq. Tarkibining yarmidan ko‘pi suvdan iborat bo‘lgan bu mevalar, ayniqsa, vazn muammosi bo‘lgan chaqaloqlar uchun foydali tamaddi bo‘lishi mumkin.') WHERE id = 'b211c72f-eb05-4bbd-bed8-55956213cfa9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizni ovqatlantirishda foydalanadigan oshxona anjomlarini tanlashda, avvalo, sog‘liq uchun xavfsiz mahsulotlarga e’tibor berishingiz kerak. Shisha, po‘lat va tarkibida BPA bo‘lmagan plastik mahsulotlar chaqalog‘ingiz uchun asosiy tanlov bo‘lishi lozim. Shuningdek, idish yuvish mashinasida yuvishga yaroqsiz materiallardan tayyorlangan mahsulotlar odatda sog‘liq uchun zararli bo‘ladi. Chaqalog‘ingizning ovqatini pishirish vaqtida aralashtirish uchun ishlatadigan anjomlaringiz issiqqa chidamli bo‘lishi kerak. Plastik va shunga o‘xshash materiallar issiqlik ta’sirida ovqatga zararli moddalar ajratishi mumkinligi sababli, ko‘proq zanglamaydigan po‘latdan tayyorlangan mahsulotlardan foydalanishingiz kerak. Ovqat pishirishda ishlatadigan tova va qozonlaringiz qoplamali bo‘lsa, ular tirnalib qolmasligiga e’tibor bering. Tirnalgan qoplama orasida suv to‘planib, bakteriyalar ko‘payishi va zararli moddalar ovqatga o‘tishi mumkin. Chaqalog‘ingizning likopchasi esa yerga tashlaganda yoki stolga urganda sinmaydigan darajada mustahkam bo‘lishi kerak.') WHERE id = '21cf7dfe-5ee8-4bdf-adb1-a494b5e0b192';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Shifokoringiz muntazam tekshiruvlar vaqtida chaqalog‘ingizning bo‘yi va vaznini o‘lchaydi. Bu natijalarni shu yoshdagi bolalarning o‘rtacha ko‘rsatkichlari bilan taqqoslab, chaqalog‘ingizning rivojlanishini tahlil qiladi. Agar chaqalog‘ingizning rivojlanish ko‘rsatkichlari me’yordan yuqori bo‘lsa yoki ikki tekshiruv oralig‘idagi vazn ortishi kutilganidan ko‘p bo‘lsa, bu unda vazn bilan bog‘liq muammo borligini anglatishi mumkin. Tengdoshlariga nisbatan ortiqcha vaznga ega chaqaloqlarda odatda qorin, son va yuz sohalarida yog‘ to‘planishiga moyillik kuzatiladi. Rivojlanish davridagi chaqalog‘ingiz ortiqcha vaznga ega bo‘lsa, bu uni kamroq ovqatlantirishingiz kerakligini anglatmaydi. Bunday usul chaqalog‘ingizning rivojlanishiga salbiy ta’sir ko‘rsatishi va gormonal muvozanatini buzishi mumkin. Uning ovqatlanish tartibini qayta ko‘rib chiqish, shirin va yog‘li mahsulotlar o‘rniga sabzavot hamda mevalarni tanlash muhim. Shuningdek, chaqalog‘ingizning faolroq bo‘lishini ta’minlaydigan o‘yinlar va kun davomida ochiq havoda sayr qilish qisqa vaqt ichida vazn muammosining oldini olishga yordam beradi.') WHERE id = '82494ee8-a29f-47cd-888b-4c024afa1a5c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqlarga televizor ko‘rsatish, ayniqsa, bolasini ovqatlantirishda qiynalayotgan onalar tez-tez qo‘llaydigan usullardan biridir. Texnologiyalar davrida bolalarni planshet, telefon va televizordan butunlay uzoq tutish ba’zan qiyin bo‘ladi. Biroq tadqiqotlar shuni ko‘rsatadiki, ayniqsa 2 yosh va undan kichik bolalarning televizor ko‘rishi autizm va boshqa jiddiy rivojlanish buzilishlari xavfini oshiradi. Bundan tashqari, chaqaloqlarning kognitiv rivojlanishiga salbiy ta’sir ko‘rsatishi, til va nutq ko‘nikmalarining kechikishi, diqqat yetishmasligi va giperfaollik kabi muammolar ham yuzaga kelishi mumkin. Shu sababli Amerika Pediatriya Akademiyasi va boshqa ko‘plab tashkilotlar 0-2 yoshli chaqaloqlarni ekranli texnologik qurilmalardan uzoq tutishni tavsiya qiladi. Televizor ko‘rish odati o‘rniga chaqalog‘ingiz bilan birga suratli kitoblar o‘qish, rasm chizish, nutq mashqlarini bajarish, tengdoshlari va o‘rgatuvchi o‘yinchoqlar bilan o‘ynash kabi mashg‘ulotlarga ustunlik berishingiz kerak. Ovqatlanish vaqtida esa chaqalog‘ingizning e’tiborini jalb qilish uchun taomni rang-barang va qiziqarli tarzda bezatishingiz yoki unga sevimli qahramonlari tasvirlangan idishlar olib berishingiz mumkin.') WHERE id = '94c13633-51b3-4740-9eed-f9195f6997ac';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Shirin kartoshka chaqalog‘ingizning rivojlanishi uchun zarur bo‘lgan eng asosiy oziq moddalarni o‘zida mujassam etgan sabzavotdir. Juda oson hazm bo‘ladigan bu sabzavot tarkibida ko‘p miqdorda kaliy, C vitamini, A vitamini, kalsiy, temir va foliy kislotasining tabiiy shakli bo‘lgan folat mavjud. Kartoshka tolali tuzilishga ega bo‘lib, chaqalog‘ingizning ovqat hazm qilish tizimini zo‘riqtirmasdan oson parchalanadi va organizm tomonidan tezda energiyaga aylantiriladi. Tarkibidagi antioksidantlar tufayli chaqalog‘ingizning immun tizimini mustahkamlashga ham yordam beradi. Barcha ushbu vitamin va minerallardan tashqari, beta-karotinga boy kartoshka chaqalog‘ingizni turli kasalliklardan himoya qilishga ko‘maklashadi. Ayniqsa, kaloriyasi yuqori bo‘lgani sababli, chaqalog‘ingiz vazn olishda qiynalayotgan bo‘lsa, uning vazni sog‘lom tarzda ortishiga yordam berishi mumkin. Chaqalog‘ingiz uchun shirin kartoshkani tayyorlashning eng foydali usuli — uni bug‘da pishirishdir. Bug‘da pishirish tufayli uning tarkibidagi vitamin va minerallar maksimal darajada saqlanib qoladi.') WHERE id = '7906e1c0-3862-429f-8a6c-67791d53795e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Shu oydan boshlab chaqalog‘ingizning o‘jarligi ancha yaqqol namoyon bo‘lishi mumkin. Buning asosiy sababi — chaqalog‘ingiz endi o‘z irodasini boshqara boshlaganidir. Shu bilan birga, rivojlanayotgan til ko‘nikmalari yordamida istak va fikrlarini ifodalay olishi ham ko‘plab masalalarda siz bilan tortishib, o‘jarlik qilishiga sabab bo‘lishi mumkin. Bolaning o‘jarligi ko‘plab onalar uchun boshi berk ko‘chaga aylanishi mumkin. Shu sababli, avvalo imkon qadar xotirjam, qat’iyatli va vazmin bo‘lib qolishingiz kerak. Chaqalog‘ingizning o‘jar xatti-harakatlariga javoban siz ham o‘jarlik qilishingiz muammoni hal etmaydi. Aksincha, chaqalog‘ingiz yanada injiqlashishi va jahli chiqib, tutqanoqdek yig‘lashga moyil bo‘lishi mumkin. Ammo nazoratni butunlay chaqaloqqa topshirish ham to‘g‘ri emas. Masalan, chaqalog‘ingiz ovqat yeyishdan bosh tortib, o‘jarlik qilsa, undan Ovqat yeysanmi? yoki Ovqatingni yeb qo‘yasanmi? deb so‘rash o‘rniga, Oldingga qo‘ygan ovqatlarimdan qaysi birini tugatasan? deb so‘rashingiz mumkin. Bunday holatda chaqalog‘ingiz nazorat sizda ekanini, biroq shu nazorat doirasida o‘z tanlovlariga ham ega ekanini tushunadi.') WHERE id = '5b073dd7-301e-41fc-a4c7-a27f4387f1d3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz uchun tayyorlayotgan mevalarni to‘g‘rashda imkon qadar metall pichoq ishlatmasligingiz kerak. Buning asosiy sababi — mevalar tarkibidagi vitaminlar metall bilan aloqa qilganda o‘z ta’sirini katta darajada yo‘qotishidir. Mevalarni bambuk yoki plastik pichoq bilan to‘g‘rash buzilishning to‘liq oldini olmasa-da, vitaminlar yo‘qolishini ma’lum muddatga kechiktiradi. Bundan tashqari, kislorod bilan aloqaga kirishgan mevalarda ham vitamin va minerallar kamayadi. Bu vitaminlarning kislorodga chidamsizligi bilan bog‘liq. Ayniqsa, olma, nok va behi kabi mevalar kesilganda kislorod bilan aloqaga kirishgani sababli biroz vaqtdan keyin qoraya boshlaydi. Bu holat meva tarkibidagi fermentlarning kislorod bilan aloqasi natijasida yuz beradigan oksidlanishdir. Oksidlanish jarayonida mevaning kesilgan qismlari jigarrang tus ola boshlaydi. Tayyorlash jarayonida kesilgan mevalarni suv ichida saqlash ularning kislorod bilan aloqasini uzib, oksidlanishni sekinlashtiradi.') WHERE id = '6947348f-e44b-494e-9348-b828857829f0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz endi ishonch bilan yurish va yugurishdan tashqari, sakrash kabi harakatlarni ham faol bajara oladi. Dastlabki sakrash urinishlarida muvozanatini yo‘qotib, chayqalib ketishi mumkin, ammo qisqa vaqt ichida muvozanatini saqlashni o‘rganadi. Sakrash vaqtida chaqalog‘ingiz miyaning miyacha deb ataladigan qismidan foydalanadi. Bu qism miyaning pastki orqa tomonida joylashgani uchun orqa miya deb ham ataladi. Miyachadagi nervlar qabul qilgan signallarni sakrash paytida chaqalog‘ingizning muvozanatini saqlashga yordam beradigan mushaklarga uzatadi. Miyacha chaqalog‘ingizning muvozanatini saqlashi va yirik motorika ko‘nikmalarini bajarishidan tashqari, diqqat va diqqatni jamlash uchun ham javobgardir. Shu nuqtai nazardan, chaqalog‘ingizning sakrash harakatini bajara olishi uning diqqatini jamlashda ham muvaffaqiyatli ekanining ko‘rsatkichi hisoblanishi mumkin. Aqliy funksiyalar va sakrash ko‘nikmasining parallel rivojlanishi har ikki turdagi ko‘nikma bir xil markaz tomonidan boshqarilishi tufayli mumkin bo‘ladi.') WHERE id = 'd993b593-9436-4f3b-85f9-b80333c24034';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingizning ishtahasi umuman past bo‘lishi mumkin. Ayniqsa, yoz faslida va kasallik paytida ishtaha yanada pasayishi ehtimoli bor. Issiq ob-havo tufayli ko‘proq suyuq ovqat iste’mol qilish, ko‘p suv ichish va sovuq ichimliklarga moyillik chaqalog‘ingizning oshqozonida doimiy to‘qlik hissini yuzaga keltirgani uchun ishtahaning pasayishi odatiy hisoblanadi. Agar chaqalog‘ingizda ishtahasizlikni kuzatsangiz, ishtahasini oshirishga urinishdan oldin bu muammo biror kasallik tufayli kelib chiqmaganini aniqlashingiz kerak. Ko‘plab muammolar ishtahasizlikka sabab bo‘lishi mumkin. Masalan, oziq tishlari hali chiqmagan bo‘lsa, chaqaloq ovqatdan bosh tortishi mumkin. Isitma bilan kechadigan kasalliklar, kamqonlik, ichak parazitlari, qabziyat va siydik yo‘llari infeksiyasi kabi muammolar ham chaqalog‘ingizning kam ovqatlanishiga olib keladi. Shuningdek, chaqaloq yetarlicha ovqatlanmayapti degan xavotir bilan ovqat masalasida haddan tashqari qattiq turib olishingiz vaziyatni yanada og‘irlashtirishi mumkin. Agar ovqat yeyish evaziga mukofotlash yoki jazolash tizimini qo‘llasangiz, bu chaqalog‘ingizning ovqatlanish masalasida o‘jarlik qilishiga sabab bo‘lishi mumkin.') WHERE id = '39b05855-5c29-415a-9d4e-b6d9c28b1572';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Maktab yoshiga yetguniga qadar chaqaloqlarda ko‘plab kasalliklar kuzatilishi mumkin. Ular orasida eng ko‘p uchraydigani yuqori nafas yo‘llari kasalliklaridir. Chaqalog‘ingiz yil davomida hatto 9 martagacha yuqori nafas yo‘llari infeksiyasini boshdan kechirishi mumkin. Bu infeksiyalarning asosiy sababi viruslardir. Agar bu kasalliklar ko‘pincha yuqori harorat bilan kechsa va isitma muayyan davriylik bilan takrorlansa, davriy isitma sindromidan shubhalanish mumkin. Bu sindrom odatda 2-5 yoshli bolalarda namoyon bo‘ladi. Bunday hollarda 40 darajadan yuqori isitma, bo‘yin sohasida shish, og‘iz ichida afta deb ataladigan yaralar va faringit kuzatiladi. Isitma to‘satdan boshlanib, 39-41 daraja oralig‘ida o‘zgaradi. Odatda 3-6 kun davom etadi va 1 haftadan oshmaydi. Bunday xurujlar taxminan oyiga bir marta takrorlanishi mumkin. Davolashda steroid tarkibli dorilar qo‘llanadi. Steroidlar keyingi xurujlarning oldini olmasa-da, ayrim hollarda bodomsimon bezlarni olib tashlash operatsiyasi bu sindromni butunlay bartaraf etishi mumkin.') WHERE id = 'eca0a9e7-b59d-4519-bf64-570cbfe10ed1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Don mahsuloti sifatida tanilgan bo‘lsa-da, aslida urug‘ hisoblangan kinoa chaqalog‘ingiz menyusiga qo‘shishingiz mumkin bo‘lgan ajoyib oziq-ovqatdir. Janubiy Amerikadan kelib chiqqan kinoa guruch va bulg‘urga qaraganda to‘yimliroq hamda oqsilga boyroq. Tarkibidagi ko‘p miqdordagi kalsiy, temir va folat tufayli u butun dunyoda bolalar ovqatidagi guruch va bug‘doyning eng yaxshi muqobillaridan biri hisoblanadi. Kinoa, shuningdek, chaqaloq organizmi uchun muhim bo‘lgan to‘qqizta asosiy aminokislotaning barchasini o‘z ichiga oladi. Tolaga boy bo‘lgani uchun oson hazm bo‘ladi va qabziyat paytida ich kelishini yengillashtirish maqsadida tez-tez qo‘llanadi. Kinoadan chaqalog‘ingiz ovqatlarini quyuqlashtirish va ularning ozuqaviy qiymatini oshirish uchun foydalanishingiz mumkin. Pishirishdan oldin uni bir muddat iliq suvda ivitib qo‘yish o‘ziga xos taxir ta’mini yo‘qotadi. Yoqimli ishtaha! 😊') WHERE id = 'b325d022-da2a-4ff6-9978-1ed8bee88324';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Endi chaqalog‘ingiz go‘daklik davridan chiqib, bolalik bosqichiga qadam qo‘yayotgan paytdasiz. 23-oyda chaqalog‘ingizning vazni deyarli o‘zgarmaydi, ammo bo‘yi o‘sishda davom etadi. Bu davrning eng e’tiborga molik xususiyati — chaqaloqda individual xarakter va hissiy moyilliklar shakllana boshlashidir. U endi nimalarni yoqtirmasligini va nimalardan zavqlanishini aniq biladi hamda buni sizga ham his qildiradi. O‘z qobiliyatlarini kashf qilayotgan chaqalog‘ingiz tobora mustaqil bo‘lishga intiladi. Bu mustaqillik hissi uning o‘ziga bo‘lgan ishonchi va rivojlanishi uchun juda muhim. Shuning uchun chaqalog‘ingizni doimiy ravishda cheklash o‘rniga, uni yangi narsalarni kashf etishga undashingiz kerak. Chaqalog‘ingiz endi mustaqil shaxs ekanini qabul qilish va shunga mos munosabatda bo‘lish uning kelajakda o‘ziga ishongan inson bo‘lib ulg‘ayishiga yordam beradi.') WHERE id = '9f9032ef-0837-4725-940d-1bfe4dd93438';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Butun dunyoda bo‘lgani kabi, mamlakatimizda ham mutaxassislar chaqaloqlarni dastlabki 6 oy davomida faqat ona suti bilan oziqlantirishni va emizishni o‘rtacha 24 oygacha davom ettirishni tavsiya qiladilar. Biroq emizishni qachon to‘xtatish kerakligi haqida yagona to‘g‘ri javob yo‘q. Bu muddat 2 yildan qisqaroq yoki 2 yildan uzoqroq bo‘lishi mumkin. Emizishni to‘xtatish uchun siz ham, chaqalog‘ingiz ham bunga tayyor bo‘lishingiz muhim. Bu chaqalog‘ingizning ulg‘ayish bosqichlaridagi eng muhim qarorlardan biridir. Ayniqsa, emizishni to‘xtatishga qaror qilganda, ko‘plab onalar biroz qayg‘u yoki xavotir his qilishlari mumkin. Bu juda nozik davr bo‘lgani uchun uni oldindan rejalashtirish foydali bo‘ladi. Chaqalog‘ingiz bilan ko‘proq jismoniy yaqinlikda bo‘lish, birga o‘tkazadigan vaqtingizni ko‘paytirish va bu jarayonni unga tushunarli tilda izohlashga harakat qilish sizga yengillik yaratadi.') WHERE id = '3f0a45ad-f763-4336-92e9-52283443a724';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2 yosh sindromi taxminan 1.5 yoshdan boshlanib, 3.5 yoshgacha davom etishi mumkin bo‘lgan jarayondir. Ko‘plab ota-onalar uchun farzand tarbiyasidagi eng qiyin bosqich hisoblangan bu davr go‘daklikdan bolalikka o‘tish bosqichidir. Belgilar 18-oydan boshlab ko‘rinsa-da, taxminan 2 yoshda eng yuqori darajaga yetadi. Bu davrda chaqalog‘ingizda paydo bo‘ladigan qaysarlik va hamma narsaga qarshilik ko‘rsatish holatlari aslida ataylab qilinmaydi. U endi ulg‘ayayotganini his qiladi va sizga qaram bo‘lmagan mustaqil shaxs ekanini isbotlashga urinadi. Agar bu davrda unga o‘zini namoyon qilish imkonini bermasangiz, yig‘i va g‘azab xurujlari, boshini devorga urish, sochlarini yulish, buyumlarni uloqtirish, ovqatlanish va uxlashdan bosh tortish holatlariga duch kelishingiz mumkin. Bu xatti-harakatlar, ayniqsa, chaqaloq uni tushunishmayotganini his qilganida yuzaga keladi. Unutmang, u shunchaki rivojlanish bosqichidan o‘tmoqda va sizning yordamingizga muhtoj.') WHERE id = '8f1b03fc-aab4-4c14-82c8-07a348b01b4a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloq tanasida hosil bo‘ladigan yog‘ hujayralarining umumiy soni uning kelajakdagi salomatligini belgilovchi eng muhim omillardan biridir. Chaqaloqlarning vazn orttirish mexanizmi kattalarnikidan farq qiladi. Kattalarda ortiqcha energiya qabul qilinganda mavjud yog‘ hujayralari kattalashadi. Ammo chaqaloqlarda sarflanmagan energiya miqdori oshgani sayin yog‘ hujayralarining umumiy soni ko‘payadi. Kamdan-kam holatlarni hisobga olmaganda, bu hujayralar tanada doimo saqlanib qoladi va kelajakda ortiqcha vazn hamda u bilan bog‘liq kasalliklarga zamin yaratadi. Tadqiqotlar shuni ko‘rsatadiki, semizlikdan aziyat chekadigan insonlarning aksariyati bolalikdan noto‘g‘ri ovqatlanish odatlariga ega bo‘lgan. Shu sababli «Semiz chaqaloq — sog‘lom chaqaloq» degan qarashdan voz kechib, chaqalog‘ingiz uchun yetarli va muvozanatli ovqatlanish tartibini tuzishingiz kerak.') WHERE id = '1a13218f-56a9-4fd9-9d16-4afe6930ed48';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz birinchi farzandingiz bo‘lsa va ikkinchi farzandli bo‘lishni rejalashtirayotgan bo‘lsangiz, oldindan bilishingiz kerak bo‘lgan muhim jihatlar bor. Avvalo, o‘zini olamning markazi deb biladigan chaqalog‘ingiz uchun diqqat markazida boshqa birovning paydo bo‘lishi juda qiyin. Odatda, uyga yangi chaqaloq kelganda, bolalar imkon qadar unga o‘xshab harakat qilishga urinadi. Har kuni yugurib yurgan bolangiz birdan yurishdan bosh tortib, doimo quchoqda bo‘lishni xohlashi mumkin. U yangi chaqaloq uchun olingan kiyimlarni kiyishni va uning buyumlaridan o‘zinikidek foydalanishni istashi mumkin. Agar hojatxonaga o‘rgatishni boshlagan bo‘lsangiz, u mashg‘ulotlardan bosh tortishi, tagini ho‘l qilib qo‘yishi va yana taglik taqishni so‘rashi mumkin. Bularning barchasi bolangizning e’tiborni yana o‘ziga qaratish istagidan kelib chiqadi. Aslida uning niyati yomon emas, u shunchaki aka-uka yoki opa-singil bo‘lish nimani anglatishini hali to‘liq tushunmaydi.') WHERE id = 'd3098156-f9a6-445a-8b64-a1ca3ee248d8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizdagi yo‘tal, odatda, qisqa vaqt ichida o‘tib ketadigan holatdir. Biroq yo‘tal uzoq davom etishi va kuchayishi ko‘kyo‘tal belgisi bo‘lishi mumkin. Ko‘kyo‘tal, ayniqsa, 5 yoshgacha bo‘lgan bolalarda og‘ir kechadigan o‘tkir va yuqumli nafas yo‘llari kasalligidir. Butun dunyoda tarqalgan bu kasallikni Bordetella pertussis bakteriyasi keltirib chiqaradi. Ko‘kyo‘tal uzoq davom etadigan yo‘tal xurujlariga sabab bo‘ladi va kasallangan odam yo‘talganda havoga tarqaladigan tomchilar orqali yuqadi. Ko‘kyo‘talning oldini olishning eng yaxshi usuli — emlash. Shuningdek, chaqaloqlar va ko‘kyo‘tal asoratlari xavfi yuqori bo‘lgan boshqa shaxslarni kasallangan odamdan uzoq tutish kerak. Ko‘kyo‘talga qarshi vaksina Sog‘liqni saqlash vazirligining emlash taqvimiga muvofiq 2-, 4- va 12-oylarda besh komponentli kombinatsiyalangan vaksina shaklida qilinadi. So‘nggi doza esa boshlang‘ich maktabning 1-sinfida to‘rt komponentli kombinatsiyalangan vaksina shaklida yuboriladi va jami 5 marta qo‘llanadi.') WHERE id = '401eecb4-6ff0-4a6b-b5b2-6f546861d6f5';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tadqiqotlar shuni ko‘rsatadiki, muntazam musiqa tinglaydigan chaqaloqlarda miya va nutq rivojlanishi boshqa chaqaloqlarga qaraganda tezroq kechadi. Shu sababli chaqalog‘ingizga qo‘shiq va alla aytib berish u bilan mazmunli va quvnoq vaqt o‘tkazishingizga yordam beradi, shuningdek, uning so‘z boyligi va nutq qobiliyati shakllanishini tezlashtiradi. Bu davrda tez-tez musiqa tinglagan chaqalog‘ingiz kelajakda musiqa asboblariga ko‘proq qiziqish bildiradi. Shuningdek, chaqalog‘ingiz o‘zi kuylar to‘qib, xirgoyi qila boshlashi orqali nutq ko‘nikmalari va ritmni his qilish qobiliyatini rivojlantiradi. Musiqa chaqalog‘ingizning uxlab qolishiga ham yordam berishi mumkin. Ayniqsa, chaqalog‘ingiz qiyin uxlaydigan bo‘lsa, sekin ohangli musiqa uni ancha tinchlantirishi mumkin. Bu davrda e’tibor berishingiz kerak bo‘lgan jihat — baland ovozli va tez sur’atli qo‘shiqlardan saqlanishdir. Bunday musiqa chaqalog‘ingizning eshitish qobiliyati va eshitish a’zolariga zarar yetkazishi mumkin.') WHERE id = 'f49ca159-fcc5-4fc3-970d-e7b1bcdc0f16';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqlar ifloslangan suv bilan aloqa qilishi natijasida yuqishi mumkin bo‘lgan asosiy kasalliklar — vabo, amyobali dizenteriya, bakterial dizenteriya va ich terlama (tif)dir. Bakterial dizenteriya issiq iqlim sharoitida, ayniqsa yoz oylarida tez-tez uchraydi va asosan 1–4 yoshli bolalarga ta’sir qiladi. Shigella deb ataladigan mikroorganizmlar keltirib chiqaradigan bu kasallik ifloslangan suv, kasallangan odamlar va pashshalar orqali yuqadi. Amyobali dizenteriya esa gigiyena qoidalariga rioya qilinmaydigan va toza ichimlik suvi yetishmaydigan joylarda ko‘proq tarqaladi. Vabo bolalarda toza bo‘lmagan suv bilan sug‘orilgan mahsulotlarni iste’mol qilish natijasida yuzaga kelishi mumkin. Ich terlama esa odam chiqindilari bilan ifloslangan suv hamda bunday suvdan qishloq xo‘jaligida foydalanish oqibatida kelib chiqadigan jiddiy kasallikdir. Ifloslangan suv orqali yuqadigan bu kasalliklarning barchasi chaqalog‘ingizda ich ketishi, isitma, qorin og‘rig‘i hamda ko‘p miqdorda suyuqlik va elektrolitlar yo‘qotilishiga sabab bo‘lishi mumkin. Shu bois, agar chaqalog‘ingiz shubhali suv bilan aloqa qilgan deb o‘ylasangiz, darhol shifokoringiz bilan maslahatlashing.') WHERE id = '2939358c-07a1-4bb3-8bed-d3d00dfe6abc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqlar quyosh nurlarining zararli ta’siriga kattalarga qaraganda ancha sezgir bo‘ladi. Shu sababli har bir faslda chaqalog‘ingizni quyoshdan himoya qilishingiz kerak. Ayniqsa, yoz oylarida zarur ehtiyot choralari ko‘rilmasa, chaqalog‘ingizning terisida quyoshdan kuyish va toshmalar paydo bo‘lishi mumkin. Shuningdek, quyoshdan himoya qiluvchi kremlarni erta yoshdan qo‘llash kelajakda quyoshning zararli ta’sirini kamaytirishi ma’lum. Chaqalog‘ingiz uchun ishlatadigan quyoshdan himoya qiluvchi krem terining sezgirligi hisobga olingan holda ishlab chiqarilgan maxsus mahsulot bo‘lishi kerak. Fizik filtrli quyoshdan himoya qiluvchi vositalar chaqalog‘ingiz uchun tanlashingiz mumkin bo‘lgan eng samarali turlardan biridir. Krem teriga to‘liq singib, himoya ta’sirini ko‘rsatishi uchun taxminan 30 daqiqa kerak bo‘ladi. Shuning uchun ko‘chaga chiqishdan kamida yarim soat oldin quyoshdan himoya qiluvchi kremni surtishingiz kerak.') WHERE id = 'efce01a9-ede6-4b7c-ba9c-059f7e1fa4ae';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz sut va sut mahsulotlari, go‘sht, tuxum, dukkaklilar, don mahsulotlari, sabzavotlar va mevalar kabi barcha oziq-ovqat guruhlaridan yetarli miqdorda va muntazam iste’mol qilishi kerak. Biroq har bir oziq-ovqat guruhini chaqalog‘ingiz ratsioniga yetarli va muvozanatli miqdorda kiritishingiz lozim. Chunki mahsulotlarning foydali ekani ularni chaqalog‘ingizga ko‘proq yedirishingiz kerakligini anglatmaydi. Sog‘lom ovqatlanish — kichik yoshdan shakllanadigan odat. Chaqalog‘ingizning ovqatlanish tartibini ushbu bosqichda shakllantirishingiz kelajakda uning sog‘lomroq inson bo‘lib ulg‘ayishiga yordam beradi. Agar chaqalog‘ingizda kun davomida asosiy ovqatlanish va tamaddi qilish odatini shakllantirsangiz, u ulg‘aygach ham bu odatni davom ettiradi. Tamaddilar asosiy ovqatlanish vaqtida ehtiyojdan ortiq ovqat iste’mol qilishning oldini oladi. Bu, ayniqsa, semizlik va boshqa ko‘plab kasalliklar rivojlanishi xavfini kamaytiradi. Bundan tashqari, chaqalog‘ingizni shakar bilan qancha kech tanishtirsangiz, shuncha yaxshi. Oddiy shakarning inson salomatligi uchun ma’lum bo‘lgan hech qanday foydasi yo‘q.') WHERE id = '2651d066-b743-4662-b034-75fe5243d7e0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz kir bo‘lishni va atrofni iflos qilishni juda yaxshi ko‘rishi, hatto bundan katta zavq olishi mumkin. Biroq chaqalog‘ingiz 2 yoshga yaqinlashayotgan bu davrda unga to‘g‘ri gigiyena odatlarini singdirish vaqti keldi. To‘g‘ri gigiyena odatlari, avvalo, chaqalog‘ingizning kasallik yuqtirish xavfini kamaytiradi. Hojatxonadan keyin, ovqatlanishdan oldin va ko‘chadan uyga kelganda qo‘llarini yuvish odati uning butun umri davomida hayot sifatini oshiradi. Shuningdek, bu bosqichda chaqalog‘ingiz aksirishi yoki yo‘talishini biroz oldindan his qila oladi. Shuning uchun unga aksirgandan keyin gigiyena qoidalariga qanday rioya qilishni o‘rgatishingiz kerak. Buni o‘rgatishning eng samarali usuli, albatta, o‘zingiz namuna bo‘lishingizdir. Taqlid qilish orqali o‘rganadigan chaqalog‘ingiz sizdan ko‘rgan bu xatti-harakatni osonlik bilan o‘zlashtiradi.') WHERE id = 'c6f0d795-8d9b-48f9-a845-2a90ac3ad87e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ona suti tengi yo‘q mo‘jizaviy ozuqadir. Agar chaqalog‘ingizni shu vaqtgacha emizgan bo‘lsangiz, sizni tabriklaymiz! 😊 Chaqalog‘ingiz yaqinda 24 oylik bo‘lishi uni darhol ko‘krakdan ajratishingiz kerakligini anglatmaydi. Emizishni qachon tugatish o‘zingizning qaroringiz, ammo hammasi yaxshi bo‘lsa, uni 2 yoshgacha davom ettirish eng ma’qul yo‘ldir. Ayrim mutaxassislar 2 yoshdan keyin ko‘krakdan ajratish muhimligini ta’kidlashadi, chunki bu davrdan so‘ng emizishni davom ettirish bolaning mustaqil shaxs sifatida shakllanishini kechiktirishi va xarakteri rivojiga ta’sir qilishi mumkin. E’tibor berishingiz kerak bo‘lgan eng muhim jihat — bu jarayonni birdaniga amalga oshirmaslikdir. Chaqaloqning eng asosiy odatlaridan birini to‘satdan to‘xtatish uning ruhiyatida chuqur iz qoldirishi mumkin.') WHERE id = 'a12dbbd5-adef-4bb7-9633-097569e91a68';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Qusish va reflyuks muammolari yangi tug‘ilgan chaqaloqlarda tez-tez uchraydigan fiziologik holatlardan biridir. Odatda qattiq ovqatga o‘tish bilan kamayib boradigan bu muammo ayrim chaqaloqlarda yana bir muddat davom etishi mumkin. Agar chaqalog‘ingizda bu davrda qusish kuzatilsa yoki shifokor unga reflyuks tashxisini qo‘ygan bo‘lsa, bir nechta ehtiyot choralarini ko‘rish foydali bo‘ladi. Avvalo, chaqaloqni ovqatlantirish paytida uni imkon qadar tikroq holatda tutishingiz kerak. Oz-ozdan, ammo tez-tez ovqatlantirish tartibini yo‘lga qo‘yish ham samarali bo‘ladi. Ovqatlantirgandan so‘ng darhol chaqaloqning sakrashi yoki dumalashi kabi harakatlarga yo‘l qo‘ymaslik yegan ovqatining qaytib chiqishining oldini olishi mumkin. Taglikni juda qattiq bog‘lash ham chaqaloqning qornidagi bosimni oshirib, gaz va reflyuksga sabab bo‘lishi mumkin. Bundan tashqari, agar chaqaloq yotog‘ini sozlash mumkin bo‘lsa, uning bosh tomonini biroz balandroq qilishingiz yoki reflyuksga qarshi maxsus yostiqlardan foydalanishingiz mumkin.') WHERE id = 'cfd2fffc-165b-4343-a449-c5ce0daed80c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Go‘daklikdan bolalikka o‘tish aslida sindrom emas. Biroq noto‘g‘ri yondashuvlar bu davrni qiyinlashtirishi mumkin. Chaqaloq erkin harakatlanishi va kuchini sarflashi uchun unga zarur sharoit yaratish tajovuzkorlikning oldini olishning eng yaxshi usulidir. Qisqasi, uning harakatlarini cheklash o‘rniga, faolroq bo‘lishi uchun sharoit yaratishingiz kerak. Chaqalog‘ingiz jahli chiqqanda uni ayblash o‘rniga, his-tuyg‘ularini ifodalashiga yordam bering. U hali o‘z his-tuyg‘ularini to‘liq nomlay olmasa ham, ko‘zlariga qarab, uni chin dildan tinglayotganingizni his qildiring. Ovqatlanish yoki uxlash kabi masalalarda o‘jarlik qilsa, uni tushunishga harakat qiling. Biroz tinchlanishini kutgach, nima uchun buni qilish kerakligini u tushunadigan sodda tilda izohlang.') WHERE id = 'e3e8fd28-dc5c-46c8-ad5b-1a55f00eab80';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz uchun muvozanatli va tartibli ovqatlanish qanchalik muhim bo‘lsa, turli xil oziq-ovqatlarni iste’mol qilish ham shunchalik muhimdir. Meva va sabzavotlarning ranglari aslida o‘simliklar ultrabinafsha nurlar va radiatsiyadan himoyalanish uchun rivojlantirgan o‘ziga xos himoya mexanizmidir. Shu tufayli har bir meva va sabzavot o‘ziga xos rang, hid va ta’mga ega bo‘ladi. Masalan, yashil meva va sabzavotlar ko‘p miqdordagi fitokimyoviy moddalarga boy. Bu moddalar chaqaloq organizmida toksinlar to‘planishining oldini oladi. Yashil mahsulotlar, shuningdek, qon ivishi va suyaklarning mustahkamligi uchun muhim bo‘lgan K vitaminiga boy. Sariq meva va sabzavotlar tarkibidagi ko‘p miqdordagi C vitamini tufayli chaqaloq terisining sog‘lom bo‘lishiga yordam beradi. To‘q sariq rangli mahsulotlar esa beta-karotinga boyligi bilan chaqaloqning immun tizimini qo‘llab-quvvatlaydi hamda uni infeksiyalar va turli kasalliklardan himoya qiladi.') WHERE id = '57ff12a3-c056-48ff-9445-c6afc0710bb9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Endi chaqalog‘ingizning ovqatlanishida uning turmush tarzi va ijtimoiy muhiti muhim rol o‘ynaydi. Chaqalog‘ingiz, ayniqsa, uydan tashqarida bo‘lgan paytlarida ham sog‘lom ovqatlanishda davom etishi uchun siz e’tibor berishingiz kerak bo‘lgan ayrim jihatlar bor. Agar chaqalog‘ingiz o‘yin guruhiga yoki bog‘chaga qatnay boshlagan bo‘lsa, u yerda taqdim etiladigan taomnomani kuzatib borishingiz mumkin. Taomnomada chaqalog‘ingizning ovqatlanish tartibiga mos kelmaydigan yoki chaqaloqlar uchun zararli deb hisoblagan mahsulotlar bo‘lsa, boshqa ota-onalar bilan birgalikda bu haqdagi fikringizni rahbariyatga bildirishingiz mumkin. Ko‘pincha «bir martadan hech narsa bo‘lmaydi» deyishsa-da, aslida chaqalog‘ingiz bu davrda yangi odatni juda oson o‘zlashtirib olishi mumkinligini unutmasligingiz kerak. Oilangiz bilan birga ovqatlanishga borganingizda, chaqalog‘ingiz iste’mol qilishini istamaydigan mahsulotlarni buyurtma qilmaganingiz ma’qul. Eng muhimi, chaqalog‘ingizga yaxshi namuna bo‘lish uchun, avvalo, o‘z ovqatlanish odatlaringizni qayta ko‘rib chiqishingiz kerak.') WHERE id = 'b5f7b4a9-f30e-4e71-8607-76ba35a2e8c5';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2 yosh inqirozi alomatlari kuchli namoyon bo‘layotgan bu davrda chaqalog‘ingizga nisbatan tushunish bilan yondashishingiz va sabrli bo‘lishingiz kerak. Agar u qaysarlik qilayotgan narsa mantiqqa to‘g‘ri kelmasa, shunchaki "yo‘q" deb rad etish o‘rniga, "Shu sababli hozir istagan narsangizni qila olmaymiz, keling, yana nima qilishimiz mumkinligini birgalikda o‘ylab ko‘ramiz" deb, oqilona yondashishingiz lozim. Qisqasi, siz ham o‘z fikringizni tushuntirishingiz, ham uning o‘zini ifodalashiga imkon yaratishingiz kerak. Chaqalog‘ingiz namoyon qilayotgan tajovuzkor xatti-harakatlar aslida o‘zini ifodalay olmayotganidan dalolat beradi. Bunday vaziyatda uni ayblab munosabat bildirishingiz holatni yanada og‘irlashtirishi mumkin. Hatto uni tushunmaslik chaqalog‘ingizning shaxsiyati rivojlanishida chuqur iz qoldirishi va bu uning butun hayotiga ta’sir qilishi mumkin. Bu jarayonda imkon qadar chaqalog‘ingizga e’tibor berish, mehr ko‘rsatish va uni tez-tez quchoqlash sizga yordam beradi. Agar chaqalog‘ingizning xatti-harakatlari haddan tashqari keskin bo‘lsa va buni uddalay olmayotganingizni his qilsangiz, mutaxassisdan yordam olishingiz tavsiya etiladi.') WHERE id = 'ecae68e6-10b6-42ea-9ce8-5db5804efd92';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz, ko‘plab tengdoshlari kabi, tez-tez yo‘q so‘zini ishlatadi. Endi biroz xotirjam bo‘lib, ortga suyaning. Avvalo, chaqalog‘ingizning bu xatti-harakati o‘zini alohida shaxs sifatida anglash jarayonining natijasi ekanini va u sizga o‘zini namoyon etishni istayotganini bilishingiz kerak. Masalan, chaqalog‘ingiz ovqatlanish vaqtida mehr bilan tayyorlagan sabzavotli taomingizga yo‘q! desa, nima qilishingiz mumkin? Chaqalog‘ingiz och qolishidan xavotirlanib, Sabzavotingizni yeng, keyin sizga shokolad beraman desangiz, bu o‘sha paytda uning qornini to‘ydirishga yordam berishi mumkin. Ammo bunday holat chaqalog‘ingizning keyingi, hatto barcha ovqatlanish paytlarida faqat shart evaziga ovqatlanishiga olib keladi. Qisqasi, bir mahalgi ovqatni yedirish uchun uning butun ovqatlanish tartibini xavf ostiga qo‘yishingiz mumkin. Mutaxassislar bunday vaziyatda chaqaloqning qarorini hurmat qilish va ovqatni uning oldidan olib qo‘yishni tavsiya etadilar. Chaqalog‘ingiz bir mahal ovqat yemasa, uning rivojlanishi darhol to‘xtab qolmaydi. Keyingi ovqatlanish vaqtida u yoqtirmaydigan sabzavotlarni omlet yoki kotlet ichiga qo‘shib, boshqacha shaklda taqdim etib ko‘rishingiz mumkin.') WHERE id = 'a47c0ef8-59a6-4a41-82ce-272ba68b1ac4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizni katta ishtiyoq bilan kiyintirasiz-u, bir qarasangiz, kiydirgan kiyimlarini qo‘lida ko‘tarib yuribdi! Bu davrda chaqalog‘ingiz qiziqadigan va zavq bilan bajaradigan mashg‘ulotlardan biri kiyinish va yechinishdir. Ayniqsa, zamoklar va tugmalar qanday ishlashini tushunib yetgach, bu uning uchun go‘yo o‘yinga aylanadi. Hatto yopishqoq ilgakli kiyimlarni faqat ochilganda chiqadigan ovoz yoqqani uchun qayta-qayta yechib-kiyishi mumkin. Chaqalog‘ingiz yechinishni yaxshi uddalasa-da, kiyinishda unchalik muvaffaqiyatli bo‘lmasligi mumkin. Chunki kiyinish chaqalog‘ingiz uchun murakkabroq jarayondek tuyuladi. Uni kiyintirayotganingizda qo‘llarini ko‘tarib, boshini burib va oyoqlarini ko‘tarib sizga yordam berishi mumkin. Ammo yechingani kabi mustaqil ravishda kiyina olishi uchun unga hali biroz vaqt kerakligini bilishingiz lozim.') WHERE id = '1f1eb57e-db71-4c23-9b07-7b41a8115750';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz allaqachon mustaqillik poydevorini qo‘ygan va bu jarayon yana bir muddat davom etadi. O‘zini oilaning alohida bir a’zosi deb biladigan va qarorlari hurmat qilinishini kutadigan chaqalog‘ingiz ovqatlanish odatlarini ham o‘z xohishiga ko‘ra tartibga solishni istashi mumkin. Chaqalog‘ingizni ko‘proq ovqat yeyishga majburlash, unga yoqtirmaydigan taomni zo‘rlab yedirishga urinish, mukofotlash yoki jazolash kabi usullarni qo‘llash foyda bermasligi, aksincha, vaziyatni yanada yomonlashtirishi mumkin. Chaqalog‘ingiz ham xuddi siz kabi bir kuni ishtahasi yaxshi bo‘lsa, ertasi kuni umuman hech narsa yegisi kelmasligi mumkin. Bunday holatda chaqalog‘ingizning istagini hurmat qilish va unga bosim o‘tkazmaslik kerak. Chaqalog‘ingiz endi tug‘ilgandan keyingi dastlabki oylardagidek oyiga 600-700 gramm vazn olmasligini unutmasligingiz lozim. O‘rtacha hisobda 2 yoshdan o‘smirlik davrigacha chaqalog‘ingizning yillik vazn ortishi 2000 grammdan oshmaydi.') WHERE id = '403d2c2b-732a-4c92-81e8-0a52e24c7139';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning biror voqea yoki vaziyat haqida nega, nima uchun yoki qanday kabi savollar berishi uning aqliy rivojlanishidagi burilish nuqtasi hisoblanishi mumkin. Chunki bu holat chaqalog‘ingiz faol ravishda savol berish bosqichiga o‘tganini ko‘rsatadi. Mavjud ma’lumot bilan cheklanib qolmaslik, qoniqarli javob olish, voqeani tushunish va qiziqishini qondirishda savollar katta rol o‘ynaydi. Shu tariqa chaqalog‘ingiz o‘rgangan narsalari o‘rtasida bog‘liqlik o‘rnata oladi va avval e’tibor bermagan jihatlarni payqay boshlaydi. Masalan, chaqalog‘ingizga tish yuvishni ko‘rsatyapsiz. Chaqalog‘ingiz nega? deb so‘ragan paytda tushuntirib berishingiz uning tish yuvish bilan tishlar salomatligi o‘rtasidagi bog‘liqlikni anglashiga yordam beradi. Shu sababli chaqalog‘ingizning savollarini javobsiz qoldirish yoki yuzaki javob berish o‘rniga, uning ko‘zlariga qarab, tushunadigan so‘zlar bilan izohlashga harakat qilishingiz kerak. Shunda chaqalog‘ingiz o‘rganish orqali aqliy rivojlanishda davom etadi, yangi so‘zlar yordamida esa uning til va nutq ko‘nikmalari ham rivojlanadi.') WHERE id = '4c355533-2fff-44de-b7a5-b39358099c69';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizga kunduz kuni hojatxonadan foydalanish odatini o‘rgatish bo‘yicha ayrim rejalaringiz bo‘lishi mumkin. Ammo kechasi hojatxonadan foydalanishni qanday o‘rgatish haqida o‘ylab ko‘rganmisiz? Bu yerda sizni xotirjam qiladigan bir jihatni aytib o‘tamiz. Aslida, eng muhimi — chaqalog‘ingizga kunduz kuni hojatxonadan foydalanish odatini o‘rgatishdir. Kunduz kuni hojatxonadan foydalanishga odatlangan chaqalog‘ingiz sizdan hech qanday qo‘shimcha harakat talab qilmasdan, kechasi tagini ho‘llashni ham osonlik bilan to‘xtatadi. Qisqasi, tungi hojatxona ta’limi degan alohida jarayon yo‘q. Kunduz kuni shakllangan odat tunda ham o‘z-o‘zidan namoyon bo‘ladi. Shuningdek, chaqalog‘ingizga hojatxonadan foydalanishni o‘rgatayotgan paytingizda kutgan natijalaringiz real bo‘lishi kerak. Kamdan-kam holatlarni hisobga olmaganda, hech bir chaqaloq bir necha kun ichida hojatxonadan foydalanishga to‘liq odatlana olmaydi. To‘g‘ri qadamlar bilan harakat qilsangiz, chaqalog‘ingiz o‘rtacha 2-3 hafta ichida hojatxonadan foydalanish odatini bemalol o‘zlashtiradi. Shu sababli sabrli bo‘lishingiz muhim.') WHERE id = '55d12594-4a57-49fb-a454-05ab50e660cd';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz kelajakda jamiyatga foydali va yaxshi tarbiya topgan shaxs bo‘lib voyaga yetishi uchun 0-6 yosh davridagi shaxsiyat shakllanishini to‘g‘ri baholashingiz kerak. Uning o‘zini oilaga mansub va alohida his qilish ehtiyojini qondirish uchun chaqalog‘ingiz sizga muhtoj bo‘lgan har bir paytda yonida bo‘lishga harakat qiling. U o‘zini xavfsiz his qiladigan muhit yarating va bu muhitning barqarorligini ta’minlang. Xavfsizlik hissi va shu muhitda baxtli bo‘lish chaqalog‘ingizning rivojlanishi uchun nihoyatda muhimdir. Har bir inson kabi sizning hayotingizda ham ko‘tarilish va pasayishlar bo‘lishi tabiiy. Ammo hissiy muammolaringizni imkon qadar chaqalog‘ingizga sezdirmaslikka harakat qilishingiz kerak. Chaqalog‘ingiz oila hamma narsadan muhimroq ekanini bilishi lozim. Buning uchun birga o‘tkazayotgan vaqtingiz sifatli bo‘lishiga e’tibor bering. Mas’uliyat hissi ham chaqalog‘ingiz rivojlanishida asosiy o‘rin tutadigan jihatlardan biridir. Shu sababli unga uddalay oladigan vazifalarni bering, toki muvaffaqiyat quvonchini his qilsin. 😊 Eng muhimi, chaqalog‘ingiz bilan muntazam jismoniy aloqada bo‘ling. E’tibor, teginish va quchoqlash uning hissiy ehtiyojlarini qondiradi.') WHERE id = '851123b6-5c41-4adf-9869-410006ae22db';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz sog‘lom o‘sayotganining eng muhim ko‘rsatkichi — uning bo‘yi va vazni mutanosib ravishda ortib borishidir. Chaqalog‘ingiz bo‘yining o‘sishi suyaklarning uchlarida joylashgan va o‘sish zonalari deb ataladigan tog‘ay to‘qimasining rivojlanishi hisobiga yuz beradi. Bu rivojlanish jarayonidagi birinchi omil — urug‘lanish vaqtida siz va juftingizdan o‘tadigan ikki guruh genlardir. Qisqacha aytganda, sizning bo‘yingiz genetik jihatdan chaqalog‘ingiz bo‘yiga bevosita ta’sir qiladi. Rivojlanishni ta’minlaydigan ikkinchi omil esa ovqatlanishdir. Genetik jihatdan mavjud bo‘lgan bo‘y imkoniyatining eng yaxshi tarzda namoyon bo‘lishida ovqatlanish muhim rol o‘ynaydi. Chaqalog‘ingiz bazal metabolizm va kundalik faollik natijasida sarflaydigan energiya hisobga olinib, zarur miqdorda kaloriya olishi shart. Bu davrda chaqalog‘ingiz yetarlicha kaloriya olmasligi, muvozanatli va sog‘lom ovqatlanmasligi rivojlanishdan ortda qolish deb ataladigan holatga sabab bo‘lishi mumkin.') WHERE id = 'e44ac09f-18ca-44ae-bc3d-9e4035e1db5d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz organizmi muvozanatli rivojlanishni davom ettirishi uchun ko‘p miqdorda oqsil va temirga ehtiyoj sezadi. Bu bosqichda chaqalog‘ingiz baliq, buzoq go‘shti, mol go‘shti, qo‘y go‘shti, tovuq va kurka go‘shti kabi mahsulotlarni muntazam iste’mol qilib, yetarlicha oqsil va temir olishi kerak. Buzoq go‘shtimi yoki qo‘y go‘shti? yoxud Qizil go‘shtmi yoki oq go‘sht? kabi bahslar o‘rniga hayvon oqsilining barcha guruhlariga xos xususiyatlarga e’tibor qaratish lozim. Masalan, yog‘lilik jihatidan qo‘y go‘shti buzoq go‘shtiga qaraganda boyroq. Shu nuqtai nazardan, chaqalog‘ingizning kun davomida zarur bo‘lgan energiyaga ehtiyojini qondirish uchun qo‘y go‘shti yaxshi tanlov bo‘lishi mumkin. Xuddi shuningdek, buzoq go‘shti ham qo‘y go‘shtiga qaraganda ko‘proq oqsil saqlagani uchun rivojlanishga katta hissa qo‘shadi. Chaqalog‘ingiz har bir oziq-ovqat guruhi kabi har bir oqsil manbasidan ham muvozanatli va muntazam ravishda foydalanishi uning sog‘lom bo‘lishi va zarur energiyani olishi uchun muhimdir.') WHERE id = '615c6205-aab5-4619-80ef-02dd20b724f7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tengdoshlariga nisbatan sekinroq o‘sayotgan yoki belgilangan persentil jadvaliga ko‘ra 3-persentildan past bo‘lgan chaqaloqlarda rivojlanishdan ortda qolish muammosi bo‘lishi mumkin. Bu muammo muntazam ravishda o‘tkazilgan bo‘y va vazn o‘lchovlari asosida tuzilgan grafikda oson aniqlanadi. Rivojlanishdan ortda qolishni davolashdagi birinchi qadam muammoning sababini topishdir. Odatda o‘sish gormoni bilan bog‘liq gormonal muammolar va ovqatlanish buzilishlari asosiy sabablar qatorida turadi. Ovqatlanish buzilishi holatlarida diyetolog va pediatr nazorati ostida maxsus dastur tuziladi. O‘sish gormoni yoki qalqonsimon bez (tiroid) gormonlari bilan bog‘liq muammolarda esa yetishmayotgan gormonni chaqaloqqa qo‘shimcha ravishda berish rivojlanishdan ortda qolish muammosini qisqa muddatda bartaraf etadi. Rivojlanishdan ortda qolish oson davolanadigan, ammo davolash kechiktirilsa, salomatlik bilan bog‘liq jiddiy va doimiy muammolarga olib kelishi mumkin bo‘lgan holatdir. Shu sababli chaqalog‘ingizning muntazam shifokor ko‘riklarini e’tiborsiz qoldirmang.') WHERE id = 'b62b2d36-7ebf-4e11-9bed-226c4b783fbe';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Maktab yoshiga yetgan har 10 bolaning birida nutq nuqsonlari kuzatiladi. Bu holat ko‘pincha bolalarning o‘z fikrini ifoda eta olmasligiga sabab bo‘ladi. His-tuyg‘ulari va fikrlarini yetkaza olmaydigan bola uni tushunishmayotganini his qilganda tajovuzkor bo‘lib qolishi mumkin. Bu odatda oilalarning noto‘g‘ri yondashuvidan kelib chiqadi. Til va nutq ko‘nikmalari faol rivojlanadigan davrda ota-onalar chaqalog‘iga o‘zini ifoda etish uchun yetarlicha imkon bermasligi bunga misol bo‘la oladi. Shuningdek, doimiy janjallar bo‘ladigan muhitda ulg‘aygan chaqaloqlar nutqni shunchaki bahslashish vositasi sifatida qabul qiladi. Ota-onalar befarq bo‘lgan va yetarlicha suhbatlashilmaydigan muhitda ham sog‘lom nutq ko‘nikmalari shakllanmaydi. Boshqa tomondan, chaqalog‘ini haddan tashqari avaylaydigan oilalar bola gapirishiga imkon bermasdan uning har bir istagini bajarganda, nutq ko‘nikmalari yetarlicha rivojlanmaydi. Shuning uchun muvozanatni saqlagan holda, salbiy holatlardan xoli muhitda va to‘g‘ri yondashuv bilan chaqalog‘ingizning til hamda nutq ko‘nikmalarini rivojlantirishga harakat qilishingiz juda muhimdir.') WHERE id = 'a1da3103-38bb-409a-b6a8-60cff787aea4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar biror-bir qarshi ko‘rsatma bo‘lmasa, chaqalog‘ingiz to‘g‘ri usullar yordamida bir necha hafta ichida hojatxonadan foydalanish odatini o‘zlashtiradi. Biroq bu jarayon yakunlanguniga qadar shimini ho‘llab qo‘yish kabi kichik ko‘ngilsiz holatlar yuz berishi mumkin. Bunday vaziyatlarda sizning munosabatingiz chaqalog‘ingiz o‘zini qanday his qilishi nuqtai nazaridan juda muhimdir. Bunday holat yuz berganda ishlatadigan so‘zlaringizga, hatto yuz ifodalaringizga ham nihoyatda ehtiyot bo‘lishingiz kerak. Haddan tashqari bo‘rttirilgan yuz ifodalari va ayblovchi munosabat chaqalog‘ingizning rivojlanishiga yordam berish o‘rniga, unda muvaffaqiyatsizlik hissini uyg‘otib, o‘rgatish jarayonini sekinlashtiradi. Shuningdek, farzandingizga muntazam ravishda Hojatxonaga borishingiz kerakmi? kabi savollar berib, uni stressga tushirmasligingiz kerak. Uni xavotirga solish va chaqalog‘ingizning o‘zi istamasa ham doimo tepasida kutib turish bolani taranglashtiradigan boshqa xatti-harakatlardir.') WHERE id = 'e4ec1981-d0f3-401a-8422-6e105994d820';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Emizishni birdaniga to‘xtatish chaqalog‘ingizga hissiy jihatdan qiyinchilik tug‘dirishi va ko‘krakda sut to‘planishi oqibatida mastit kabi muammolarga olib kelishi mumkin. Shu sababli bu usul tavsiya etilmaydi. Bundan tashqari, ko‘krakka tomat yoki achchiq modda surtib, chaqaloqni ko‘krakdan ajratishga urinish uning bu dunyoda eng qattiq bog‘langan insoni — onasiga bo‘lgan ishonchini susaytirishi mumkin. Xuddi shuningdek, ko‘krakka yoqimsiz ko‘rinadigan moddalarni surtib, chaqaloqda jirkanish hissini uyg‘otishga urinish ayrim ruhiy jarohatlarga sabab bo‘lishi mumkin. Emizishni asta-sekin kamaytirish eng yaxshi usul hisoblanadi. Masalan, chaqaloqqa ham, sizga ham eng kam ta’sir qiladigan jarayon o‘rtacha 4-6 hafta davom etadi. Dastlabki bosqichda har 2 yoki 3 kunda, chaqaloqqa sezdirmasdan, emizishlar sonini bittadan kamaytirish yaxshi boshlanish bo‘lishi mumkin. Emizishlar sonini kamaytirish bilan birga, chaqaloqning ko‘krak emish vaqtini ham asta-sekin qisqartirishga harakat qilishingiz mumkin.') WHERE id = '3d5ea030-23eb-46a7-94ed-7537bc1bbbf9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Hojatxonaga o‘rgatishni qachon boshlash kerakligini tushunishning eng yaxshi usullaridan biri — chaqalog‘ingiz siyayotgan paytda yurishdan to‘xtayotganini payqashdir. Siydik chiqarish yo‘llari mushaklari hali rivojlanmagan chaqaloq harakatlanayotganida siygisi kelsa, to‘xtamasdan bemalol siyadi. Bu mushaklarni boshqara boshlagach va hojati kelganini biroz oldindan his qila olgach, «to‘xtab qolish» deb ataladigan xatti-harakat kuzatiladi. Qisqacha aytganda, chaqalog‘ingiz biror ish bilan mashg‘ul bo‘lganida yoki qayergadir ketayotganida bir zum to‘xtab, biroz egilayotganini ko‘rsangiz, demak, u hojatxonaga o‘rganishga tayyor! 😊 Hojatxonaga o‘rgatishni qanday boshlashni bilmasangiz, mutaxassislar tavsiya qiladigan uch kunlik usulni sinab ko‘rishingiz mumkin. Bu usulga ko‘ra, birinchi kuni namlikni o‘tkazadigan taglik ishlatiladi, shunda chaqaloq namlikdan noqulaylik sezadi. Ikkinchi kuni esa taglik taqilmaydi, natijada chaqaloq namlikni yanada ko‘proq his qiladi va bundan bezovta bo‘ladi. Uchinchi kuni bu noqulaylikni qayta his qilmaslik uchun yechim izlayotgan chaqaloqni «Hojatxonaga borishni xohlaysizmi? Shunda namlikni his qilmaysiz» kabi jumlalar bilan qo‘llab-quvvatlash kerak.') WHERE id = '2d14dd63-aabc-4645-bf9f-275bd8acabb6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Qanchalik harakat qilmang, ayrim hollarda chaqalog‘ingiz siz istamagan xatti-harakatlarni namoyon qilishi mumkin. Bunday vaziyatlarda sizning tutgan yo‘lingiz va qat’iyligingiz juda muhim. Biroq haddan tashqari munosabat bildirish, jahllanish, to‘sqinlik qilish va jazolash kabi xatti-harakatlar vaziyatni yanada qiyinlashtirishi mumkin. Eng yaxshi usul — chaqalog‘ingizning e’tiborini boshqa tomonga yo‘naltirish. Buning uchun farzandingiz nimalarga qiziqishini diqqat bilan kuzatishingiz kerak. Masalan, u ovqatlanishdan bosh tortsa, sevimli o‘yinchog‘i bilan birga ovqatlanishi uchun sharoit yaratishingiz mumkin. Rasm chizishni yoqtiradigan chaqalog‘ingiz uchun esa likopchadagi pomidor sousidan qiziqarli shakllar yasashingiz mumkin. Qisqasi, bunday qiziqarli usullar chaqalog‘ingizning e’tiborini jalb qiladi va muammolar kamayishiga yordam beradi.') WHERE id = '232af561-cec2-4585-8cda-9355fd410687';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Har bir ota-ona chaqalog‘iga chegaralar belgilash masalasiga turlicha yondashadi. Bu yondashuvlarni uch guruhga ajratish mumkin: chegara belgilay olmaydiganlar, chegaralar masalasida qat’iy qarorga kela olmaydiganlar va keskin chegaralar belgilaydiganlar. Chegara belgilay olmaydigan oilalar, odatda, chaqalog‘i baxtli bo‘lishi va cheklovlarga duch kelmasligi uchun unga to‘liq erkinlik berib tarbiyalash usulini tanlaydi. Biroq chegaralarni bilmaydigan bolalar maktab davrida va voyaga yetganida jamiyatga moslashishda juda qiynaladi. Qat’iy qarorga kela olmaydigan oilalar esa turgan muhiti va o‘sha paytdagi kayfiyatiga qarab turlicha yondashadi. Chegaralar belgilanishi va bola ularni o‘zlashtirishi uchun izchillik zarur. Izchil bo‘lmagan qoidalar chaqaloqni chalg‘itishi mumkin. Keskin chegaralar belgilaydigan oilalar esa farzandining erkinligini katta darajada cheklaydi va bu bolaning butunlay ota-ona nazorati ostida bo‘lishini anglatadi. Shuning uchun chaqalog‘ingiz uchun chegaralarni uning yoshi va rivojlanishiga mos ravishda belgilashingiz kerak. Farzandingiz o‘ziga berilgan erkinlik doirasini va bu doira qayerda tugashini bilishi lozim. Izchil va qat’iyatli bo‘lish chaqalog‘ingizning rivojlanishi uchun juda muhim.') WHERE id = '2a7f4e56-4746-44ba-a23e-5b21fa398b44';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning juda tez ovqatlanishi yoki ovqatlanish vaqti yarim soatdan ko‘proq davom etishi ayrim salbiy holatlarga olib kelishi mumkin. So‘lak tarkibidagi amilaza fermentlari, ayniqsa, uglevodlarning bir qismini hazm qiladi. Bu, shuningdek, oshqozonning hazm qilish jarayoniga tayyorgarlik bosqichidir. Chaqalog‘ingiz yetarlicha chaynamasdan tez yegan ovqat oshqozonga hazm bo‘lmagan va yirikroq bo‘laklar holida tushadi. Natijada oshqozon va ichaklar bu ovqatni hazm qilish uchun ko‘proq ishlashiga to‘g‘ri keladi. Qisqasi, tez ovqatlanish oqibatida chaqalog‘ingizda hazm qilish qiyinlashishi, jig‘ildon qaynashi, qorin dam bo‘lishi va gaz sanchiqlari yuzaga kelishi mumkin. Boshqa tomondan, ovqatlanish vaqtining keragidan ortiq cho‘zilishi bolaning keyingi safar och qolishi va ovqatlanish vaqtini kechiktiradi. Chaqalog‘ingiz sizga faol taqlid qiladigan bu davrda qanday mahsulotlarni iste’mol qilishingiz bilan birga, ularni qanday yeyishingizga ham e’tibor qaratishingiz kerak.') WHERE id = 'df961caa-4d98-4df5-a5a0-5f406bf41593';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizda tish chiqishi odatda 6-oydan keyin boshlanadigan va suyaklar rivojlanishi bilan bir vaqtda kechadigan jarayondir. Chaqalog‘ingizning yuz va bosh suyagi rivojlanishi bilan tug‘ilganidan beri mavjud bo‘lgan tish kurtaklari vaqt o‘tishi bilan og‘iz bo‘shlig‘i tomon siljiydi. Jag‘ suyaklari ustidagi milkni yorib chiqadigan tishlar taxminan 2.5 yoshgacha to‘liq chiqib bo‘ladi. Biroq chaqalog‘ingizning ikkinchi sut oziq tishlari hozirdanoq chiqqan bo‘lishi mumkin. Bunday holatda xavotirlanishga hojat yo‘q. Chunki o‘rtacha 6-oyda boshlanib, 30-oyda yakunlanishi kutiladigan sut tishlarining chiqish vaqtida 6 oygacha farq kuzatilishi mumkin. Ya’ni chaqalog‘ingizning 4 oyligida oldingi kesuvchi tishlari chiqishi qanchalik tabiiy bo‘lsa, 24-oyida ikkinchi sut oziq tishlari chiqishi ham shunchalik tabiiy hisoblanadi. Bunday farqlar kechikish ko‘rinishida ham bo‘lishi mumkin. Qisqasi, chaqalog‘ingizning jami 20 ta sut tishi 3 yosh atrofida ham to‘liq chiqib bo‘lishi mumkin.') WHERE id = '15d59f5c-8023-4040-b4f8-dbb2186a2bc6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ovqatlanish tartibiga uyda amal qilish juda oson. Biroq ko‘chaga chiqadigan kunlaringizda chaqalog‘ingizning ovqatini uyda tayyorlab, o‘zingiz bilan olib ketmoqchi bo‘lsangiz, foydalanayotgan saqlash usullaringizni qayta ko‘rib chiqishingiz kerak bo‘lishi mumkin. Ayniqsa, oziq-ovqatni saqlashda tez-tez ishlatiladigan alyuminiy folga tova va qozonlar kabi maxsus ishlov berish jarayonidan o‘tmaydi. Masalan, olma yoki sabzini butunligicha o‘raganda alyuminiy folga nisbatan zararsiz bo‘lishi mumkin. Biroq issiqlik bilan ta’sirlashganda folga tarkibidagi alyuminiy jadal ajralib chiqadi. Issiq ovqatni folgaga o‘raganda oziq-ovqatga ko‘p miqdorda alyuminiy o‘tadi. Saqlash muddati qancha uzoq va ovqat qancha issiq bo‘lsa, alyuminiyning o‘tish darajasi shuncha ortadi. Tarkibida ko‘p miqdorda alyuminiy bo‘lgan oziq-ovqatlarni iste’mol qilish esa chaqalog‘ingizning sog‘lig‘iga jiddiy zarar yetkazishi mumkin. Shu sababli shisha idishlar kabi sog‘liq uchun xavfsizroq ekani ma’lum bo‘lgan saqlash vositalaridan foydalanishingiz chaqalog‘ingizning salomatligi uchun juda muhim.') WHERE id = '99249fa2-1976-4010-a97c-d6cb7198f3f3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning bo‘yi past yoki balandligini aniqlash uchun muntazam bo‘y o‘lchovlari, uning jinsi va persentil (rivojlanish) jadvali birgalikda baholanishi kerak. Bo‘y pastligi odatda chaqalog‘ingizning ko‘rsatkichi persentil jadvalida 3 birlikdan past bo‘lganida aniqlanadigan muammodir. Chaqalog‘ingiz bo‘yining yillik o‘sish sur’ati o‘rtacha 1 yoshgacha 25 sm, 1 yoshdan 2 yoshgacha 10 sm, keyingi yoshlarida esa yiliga kamida 5 sm bo‘lishi kerak. Yillik bo‘y o‘sishi me’yordan kam bo‘lsa, rivojlanishdan ortda qolish haqida so‘z yuritish mumkin. Bo‘yi me’yordan baland bo‘lsa, avvalo irsiy moyillik hisobga olinadi. Agar ota-onaning bo‘yi baland, chaqaloqning ovqatlanishi va gormonal muvozanati me’yorda bo‘lsa, u bu salohiyatdan maksimal darajada foydalanadi. Bo‘yning haddan tashqari o‘sishi kamdan-kam hollarda akromegaliya kabi gormonal muammolar tufayli ham yuzaga kelishi mumkin. Akromegaliya — o‘sish gormonining me’yordan ortiq ishlab chiqarilishi va ajralishi natijasida rivojlanadigan surunkali kasallik.') WHERE id = '03b2f142-4194-4c82-b5dd-f72012624ef1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2 yoshga kelib, chaqalog‘ingizning ovqatlanish tartibi ko‘p jihatdan kattalarnikiga o‘xshay boshlaydi. Ayniqsa, ijtimoiylashuv ortib, atrofdagilar gazli ichimliklar, limonadlar va tayyor qadoqlangan mahsulotlarni iste’mol qilayotganini ko‘rgach, chaqalog‘ingiz ham bu mahsulotlarga qiziqa boshlaydi. Bu qiziqishni muqobil mahsulotlar taklif qilish yoki zararini imkon qadar kamaytirish orqali qondirganingiz ma’qul. Masalan, tayyor limonadlarda ko‘p miqdorda shakar va qo‘shimchalar bo‘lishi mumkin. Agar chaqalog‘ingiz limonad xohlasa, uyda osongina tabiiy limonad tayyorlashingiz mumkin. Gazli ichimliklar esa chaqalog‘ingizdan imkon qadar uzoq tutishingiz kerak bo‘lgan mahsulotlar guruhiga kiradi. Ularning tarkibida ko‘p miqdorda bo‘yoqlar, ta’m beruvchi moddalar va konservantlar bor. Buning o‘rniga meva sharbati va oz miqdordagi tabiiy mineral suvdan tayyorlangan aralashma sog‘lomroq muqobil bo‘ladi. Mineral suvlar tarkibi jihatidan tabiiy mineral manbai hisoblanadi, ammo uning miqdoriga e’tibor berish kerak. Ortiqcha iste’mol qilinishi chaqalog‘ingiz buyraklarida tosh paydo bo‘lishiga sabab bo‘lishi mumkin.') WHERE id = 'f07f1c96-bc65-46e5-aee7-1f4704bbe735';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz endi ikki yoshga to‘lish arafasida. Bu esa rivojlanish eng tez kechadigan davr asta-sekin ortda qolayotganini anglatadi. Tug‘ilgan kunidan boshlab dastlabki 12 oy ichida chaqalog‘ingizning bo‘yi o‘rtacha 25 sm o‘sadi, vazni esa uch baravar ortadi. 12-oydan 24-oygacha bo‘lgan davrda o‘sish nisbatan sekinlashsa-da, bu hali ham jadal rivojlanish davridir. 24 oylik bo‘lgan bolalar, kamdan-kam holatlar bundan mustasno, o‘smirlik davrigacha barqaror sur’atda rivojlanadi. Shu nuqtai nazardan, chaqalog‘ingizning rivojlanish egri chizig‘i yana yuqorilaydigan navbatdagi bosqich o‘smirlik davridir. O‘smirlikning ilk belgilari qizlarda o‘rtacha 11 yoshda, o‘g‘il bolalarda esa 12 yoshda boshlanadi. Aynan shu yoshda bo‘y yana tez o‘sa boshlaydi. O‘smirlik davrigacha chaqalog‘ingizning bo‘yi har yili o‘rtacha 6-7 sm o‘sadi va u 2000-3000 gramm atrofida vazn qo‘shadi. Muhimi, uning qanchalik ko‘p o‘sishi emas, balki rivojlanish mutanosib ravishda davom etishidir.') WHERE id = 'aff1da93-456e-48a8-9491-2359d0f1819f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz imkon qadar choy ichmasligi sog‘lomroqdir. Biroq sizning choy ichayotganingizni ko‘rib, qat’iy talab qilsa, suv bilan suyultirilgan choydan bir necha qultum ichishi muammo tug‘dirmaydi. Choy organizmda temirning so‘rilishini kamaytirib, chaqalog‘ingizda temir tanqisligiga sabab bo‘lishi mumkin. Temir tanqisligi gemoglobin ishlab chiqarilishini sekinlashtiradi va organizmning sog‘lom o‘sishi uchun yetarli miqdorda kislorod yetkazib berilmaydi. Natijada anemiya, ya’ni kamqonlik rivojlanishi mumkin. Shu sababli chaqalog‘ingizga ko‘p miqdorda choy ichishga ruxsat bermasligingiz kerak. Bundan tashqari, choy tarkibidagi shakar vitamin va minerallarning qabul qilinishini cheklaydi hamda chaqaloq organizmiga ozuqaviy qiymati bo‘lmagan ortiqcha kaloriya tushishiga sabab bo‘ladi. Choy tarkibidagi kofein tufayli chaqaloq organizmiga qo‘zg‘atuvchi ta’sir ham ko‘rsatishi mumkin. Qisqa muddatda uyqusizlik va giperfaollikka, uzoq muddatda esa yurak urishining tezlashishi va ayrim yurak kasalliklariga olib kelishi mumkin. Shuning uchun choy bermaslik yoki juda oz miqdorda suv qo‘shib berish kerak.') WHERE id = '1bee19ec-571c-4174-99b3-cd8351c86d71';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Amerika Pediatriya Akademiyasining ma’lum qilishicha, qiz chaqaloqlar o‘g‘il bolalarga qaraganda hojatxonadan foydalanish odatini ertaroq o‘zlashtiradi. Buning sababi o‘g‘il bolalarning harakatchanroq bo‘lishi va o‘tirishga kamroq moyillik ko‘rsatishidir. Har ikki jins uchun hojatxonadan foydalanish odatlari va gigiyena qoidalari farq qilishini unutmasligingiz kerak. O‘g‘il bolalarga siyishni tik turgan holda emas, o‘tirib bajarishni o‘rgatish kerak; bu yuz berishi mumkin bo‘lgan kichik noxush holatlarning oldini olishni osonlashtiradi. Agar u tik turib siyishni xohlasa, otasi yoki katta akasi bo‘lsa, undan namuna ko‘rsatishini so‘rashingiz mumkin. Qiz chaqaloqlarda esa eng muhim jihat tozalashni old tomondan orqa tomonga qarab amalga oshirishdir. Bu qoida zararli mikroorganizmlarning jinsiy a’zolarga o‘tishiga yo‘l qo‘ymay, infeksiya xavfini minimal darajaga tushiradi.') WHERE id = 'ae97b92b-a7d9-475b-9849-10e43e2e1c73';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Likopin — pomidor, tomat pastasi, tarvuz, pushti greypfrut va na’matak kabi mahsulotlarga qizil rang beruvchi pigmentdir. Likopin eng kuchli antioksidantlardan biri bo‘lib, pomidor ushbu moddaga eng boy mahsulotdir. Boshqa sabzavotlardan farqli ravishda, pishirish pomidor tarkibidagi likopin miqdoriga salbiy ta’sir qilmaydi, aksincha, uning organizm tomonidan o‘zlashtirilish darajasini oshiradi. Shu jihatdan antioksidantlarga boy mahsulotlarni iste’mol qiladigan chaqalog‘ingiz organizmdagi erkin radikallarning zararli ta’siridan himoyalanadi. Tadqiqotlar bu mahsulotlarni muntazam iste’mol qilish organizmdagi antioksidantlar muvozanatini saqlashini ko‘rsatadi. Bu esa chaqaloqni kelajakda ichak va boshqa saraton turlaridan, shuningdek, yurak kasalliklaridan himoya qilib, yangi hujayralar hosil bo‘lishini qo‘llab-quvvatlaydi.') WHERE id = '41b94477-7ace-4910-a0f5-44deccc75aca';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqning har bir istagiga yo‘q deyish orangizdagi munosabatlarga putur yetkazishi mumkin. Bundan tashqari, siz yo‘q degan narsaga turmush o‘rtog‘ingiz ha desa, bu chaqaloqni chalg‘itadi va taranglikni oshiradi. Shu sababli yo‘q degan vaziyatlaringizda izchil va qat’iyatli bo‘lishingiz juda muhim. Ba’zan ota-onalar «yo‘q» so‘zini ishlatmaslik bolaning o‘ziga bo‘lgan ishonchini oshiradi, deb o‘ylashadi, ammo bu so‘zni o‘z o‘rnida va vaqtida aytish aslida rivojlanishga hissa qo‘shadi. Chunki har bir istagi bajariladigan chaqaloq qayerda to‘xtash kerakligini va chegaralarini bilmaydi. Chaqalog‘ingizga «yo‘q» deyishni o‘rgatishning bir yo‘li — uning «yo‘q»lariga ham hurmat bilan munosabatda bo‘lishdir. Shunda u bu so‘zni eshitganda qaysarlik qilish o‘rniga kelishishga ko‘proq moyil bo‘ladi.') WHERE id = '98b637d9-7d59-44a7-bf65-65315858e258';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu davrga kelib sakrash kabi yangi harakat ko‘nikmalarini egallagan. Uning ijtimoiy va hissiy holati esa fe’l-atvoriga mos ravishda shakllana boshlagan. Biroq u tushunadigan so‘zlar soni ishlatadigan so‘zlaridan ancha ko‘p. So‘z boyligining kamligi unga his-tuyg‘ulari va o‘zgarishlarni to‘g‘ri ifodalashga xalaqit beradi. Har qanday inson kabi, chaqalog‘ingiz ham uni tushunishmayotganini his qilganda asabiylashishi mumkin, bu esa hafsalasi pir bo‘lishi va jahli chiqish xurujlariga olib keladi. Bunday xatti-harakatlar 2 yosh sindromining odatiy belgilaridir. Agar chaqalog‘ingizning bu his-tuyg‘ularini bostirsangiz, ichida to‘plangan energiya tishlash kabi zararli harakatlarga aylanishi mumkin. U hozircha g‘azabini boshqara olmaydi, shuning uchun u bilan his-tuyg‘ulari haqida ko‘proq suhbatlashishingiz kerak.') WHERE id = 'adf73ed7-c816-4db3-ac27-af97090fdb24';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Qisqa vaqt ichida katta yo‘lni bosib o‘tgan chaqalog‘ingiz uchun 2 yosh chinakam burilish nuqtasidir. U mustaqil bo‘lib borayotganiga qaramay, hali ham ilk kundagidek sizning yordamingizga muhtojligini unutmang. Uni doimo alohida shaxs sifatida qabul qilishingiz, nimalarni uddalay olishi va nimalarni hali uddalay olmasligini farqlashingiz kerak. Uddalay oladigan ishlarini bajarishi uchun imkoniyat yaratish, qo‘lidan kelmaydiganlari uchun esa koyimaslik — rivojlanish yo‘lidagi eng muhim qadamdir. Har bir bolaning muvaffaqiyat qozonadigan sohasi turlicha ekanini unutmang. Chaqalog‘ingizning qiziqishlarini aniqlashga harakat qiling. Masalan, u bo‘yashni yoqtirmasa, bu legolardan minora qura olmaydi degani emas. Balki uning musiqiy qobiliyati juda kuchlidir! 😊 Chaqalog‘ingizni qanday bo‘lsa, shundayligicha qabul qilish va salohiyatini yuzaga chiqarishi uchun sharoit yaratish — Anacan oilasi sifatida sizga beradigan eng muhim tavsiyamizdir.') WHERE id = '30b012e1-5c89-4c18-b6fd-8796dd3ea562';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Har bir bola o‘ziga xos rivojlanish xususiyatlariga ega bo‘lsa-da, 2 yosh, umuman olganda, muloqot jadal rivojlanadigan davrdir. Bu yoshdagi bolalar o‘rtacha 20-30 ta turli so‘zni ayta oladi va ikki-uch so‘zdan iborat gaplar tuza oladi. Qisqa vaqt ichida sodda gaplar tuzish qobiliyati yanada rivojlanadi va u tildan samaraliroq foydalana boshlaydi. Chaqalog‘ingiz bu davrda so‘zlarni chalkashtirishi, birlashtirishi, yangi narsalarni o‘rganishga va aytishga urinishi mumkin. O‘rganish tezligiga mos ravishda u siz aytgan deyarli hamma narsani tushunadi, ko‘rsatmalaringizni bajaradi va savollaringizning sababini anglaydi. Ba’zan esa, go‘yo o‘ziga qulay bo‘lmaganda, sizni eshitmaganga olishi ham mumkin! 😊 Bu xatti-harakatlarning barchasi uning rivojlanish jarayonining bir qismidir. Shuning uchun farzandingizning individual rivojlanish sur’atiga hurmat bilan yondashishingiz va unga nisbatan tushunuvchanroq bo‘lishingiz kerak.') WHERE id = '9051f36c-fed8-4ab1-82c1-a9cb54f63349';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Emlash taqvimiga ko‘ra, farzandingiz bu oy avval birinchi dozasi qilingan Gepatit A vaksinasining ikkinchi dozasini olishi kerak. Gepatit A — jigarni zararlaydigan va sariqlik bilan kechadigan yuqumli kasallikdir. Virus najas orqali tarqalgani sababli iflos suv manbalari va shu suvda yuvilgan oziq-ovqatlar katta xavf tug‘diradi. Bu kasallikdan himoyalanishning eng yaxshi yo‘li — yuqtirishdan oldin emlanishdir. Gepatit A belgilari ba’zan yaqqol namoyon bo‘lmagani uchun 2 yoshdagi emlashni albatta qildirish kerak. Vaksina chap son sohasiga qilinadi va nojo‘ya ta’sir sifatida biroz isitma kuzatilishi mumkin. Shuningdek, chaqalog‘ingizda bezovtalik va ishtahasizlikni ham sezishingiz mumkin, ammo bular vaqtinchalik va odatiy holatlardir.') WHERE id = 'd08455f4-14d3-4090-ae21-9de34395199f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz 2 yoshdan oshgan bu davrda ishtaha bilan bog‘liq muammolar kuzatilishi mutlaqo tabiiy. Endi bolangiz tanasida dastlabki oylarga xos bo‘lgan do‘mboq qatlamlar va burmalar kamayganini ko‘rishingiz mumkin. Buning sababi jismoniy o‘sishning jadal bosqichi nisbatan sekinlashgani va organizmga avvalgidek ko‘p kaloriya kerak emasligidir. 24 oylik qiz bolalarning vazni minimum 9100 gramm, maksimum 15.100 gramm oralig‘ida bo‘lishi kerak (o‘rtacha ko‘rsatkich 12.200 gramm). 24 oylik o‘g‘il bolalarning vazni esa minimum 9500 gramm, maksimum 15.700 gramm orasida bo‘ladi (o‘rtacha ko‘rsatkich 12.600 gramm).') WHERE id = '5e4362b2-06e5-4df6-8936-71c5d239e1a4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingizni shu paytgacha emizgan bo‘lsangiz, sizni tabriklaymiz! JSST chaqaloqlarni 2 yoshgacha ona suti bilan oziqlantirishni tavsiya qiladi. Biroq emizishni qachon to‘xtatish butunlay ona va chaqaloqning qaroriga bog‘liq. Bu yerda asosiy masala emizishni qachon emas, qanday to‘xtatishdir. Agar endi sutdan ajratish vaqti keldi deb hisoblasangiz, mutaxassislar buni birdaniga emas, balki asta-sekin, muayyan vaqt davomida o‘rgatib amalga oshirish kerakligini ta’kidlaydi. Bu jarayonda sabrli bo‘lish siz uchun ham, chaqalog‘ingiz uchun ham eng sog‘lom yo‘ldir.') WHERE id = 'ab8fb6ce-5c13-4d03-8479-2cff8ada8d51';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqning idrok etish qobiliyati juda kuchli va nutq rivoji jadal bo‘lgani uchun bu davrda unga ingliz tilini o‘rgatishni boshlashingiz mumkin. Kichik yoshda o‘rganilgan chet tili kelajakda bola uchun katta ustunlik yaratadi. Bolalar tilni avval alohida so‘zlar, keyin so‘z birikmalari va oxirida gaplar orqali o‘rganadilar. Bu jarayonda farzandingizga yordam berish uchun uni diqqat bilan kuzatishingiz kerak. Ingliz tilini o‘zlashtirishi uchun uyda qisqa vaqt davomida shu tilda muloqot qilinadigan muhit yaratish yoki birgalikda ingliz tilidagi qo‘shiqlar va allalarni tez-tez tinglash juda foydali. Agar farzandingiz multfilm tomosha qilsa, ularni ingliz tilida tanlash ham tilni o‘zlashtirishiga yordam beradi.') WHERE id = 'ad97f664-295a-40e4-a267-0055f05130e8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Emizishdan chiqarish davrida sabrli bo‘lish va umidsizlikka tushmaslik juda muhim. Buning uchun chaqaloqni emizishdan chiqarishdan oldin jarayonni to‘g‘ri rejalashtirish va yaxshilab o‘ylab chiqish kerak. Bu davrda yuz beradigan keskin o‘zgarishga moslasha olmay, qiyinchiliklarga bardosh berishda qiynalgan onalar ba’zan taslim bo‘lishlari mumkin. Biroq taslim bo‘lish va buning natijasida yuzaga keladigan tartibsizlik bola uchun jarayonni yanada qiyinlashtirishi mumkin. Agar chaqaloqni emizishdan chiqarishga qaror qilgan bo‘lsangiz, uning har doimgidan ko‘ra ta’sirchanroq va injiqroq bo‘lishini qabul qilishingiz kerak. U ko‘p yig‘lashi mumkin, bu esa sizni xafa qilib, emizishdan chiqarish jarayonini qiyinlashtirishi mumkin. Shu sababli uni ko‘proq bag‘ringizga bosish, orqasini silash, quchoqlash va o‘pishga alohida e’tibor berishingiz kerak.') WHERE id = '4edac414-47f5-4ace-b884-331a8009248b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz o‘yinchoqlari bilan yoki o‘z-o‘zi bilan gaplashayotganini kuzatishingiz mumkin. 2 yosh — o‘z-o‘zi bilan gaplashish ko‘p uchraydigan davr. Shu sababli xavotirlanishga hojat yo‘q. Bu davrda bolalarning tildan doimiy foydalanishi ularning so‘z boyligi juda tez rivojlanishiga yordam beradi. Tadqiqotlarga ko‘ra, o‘z-o‘zi, ota-onasi, atrofidagi odamlar yoki o‘yinchoqlari bilan gaplashadigan bolalarning nutqi boshqa bolalarnikiga qaraganda tezroq rivojlanadi. Shu bilan birga, agar chaqalog‘ingiz qisqa gaplar tuzsa yoki aytganlari to‘liq tushunarli bo‘lmasa, gapini tugatishga majburlamasligingiz kerak. Qistash va jahlingiz chiqishi uni ranjitib, gapirishga bo‘lgan qiziqishini so‘ndirishi mumkin. Shu sababli chaqalog‘ingizni siqmasdan, u bilan tez-tez o‘zaro suhbat qurishga harakat qiling. Gapirishi va savol berishi uchun unga imkon yarating. Ba’zan uning savollaridan charchasangiz ham, buni unga sezdirmasligingiz juda muhim.') WHERE id = '76dbf32a-12ec-49d7-ab16-15fdada3d51f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2 yosh davrining eng yaqqol xususiyati — mustaqillikka intilishdir. Chaqalog‘ingiz bu davrda endi boshqa odamlarga to‘liq qaram bo‘lmagan, mustaqil shaxs ekanini anglaydi. Buning natijasida u hamma ishni o‘zi bajarishga urinayotganini ko‘rishingiz mumkin. Chunki chaqalog‘ingiz endi sizga alohida shaxs ekanini isbotlash uchun qo‘lidan kelganicha harakat qiladi. Bu bosqichda chaqalog‘ingizning istaklarini hurmat qilishni o‘rganishingiz va zarur bo‘lmasa, uning ishlariga aralashmasligingiz kerak. Aralashish zarur bo‘lganda esa, ko‘proq uning e’tiborini boshqa tomonga yo‘naltirishga harakat qiling. 2 yosh inqirozi va yangi shakllanayotgan mustaqillik tuyg‘usi fonida o‘jarlik ota-onalar uchun juda charchatadigan va asabiylashtiradigan holat bo‘lishi mumkin. Sabrsiz, o‘jar va faqat o‘z bilganini qiladigan bola bilan shug‘ullanish ko‘plab ota-onalarni toliqtiradi. Biroq bu davrdagi o‘jarlikni bosim bilan yengishga urinish bolaning o‘zini anglashiga zarar yetkazadi va o‘zini namoyon qilishga urinayotgan paytda rad etilgandek his qilishiga sabab bo‘ladi.') WHERE id = '6ba61781-1ee0-4e31-8537-9186df6efc0e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz o‘ng qo‘lidan foydalanadimi yoki chap qo‘lidanmi — bilishni istaysizmi? Bolalar miyasining qaysi qismi faolroq ishlashi va buning natijasida kundalik ishlarni bajarishda qaysi qo‘lidan ko‘proq foydalanishi kichik yoshdayoq namoyon bo‘la boshlaydi. Qaysi qo‘l yetakchi ekani taxminan 1 yoshda sezila boshlasa-da, bu odatda 3-4 yoshda to‘liq shakllanadi. Chaqalog‘ingiz hozirdanoq qaysi qo‘lidan foydalanishga moyil ekanini uni kuzatib bilishingiz mumkin. Masalan, chaqalog‘ingiz o‘yinchoqlarga qaysi qo‘li bilan intilishi, buyumlarni qaysi qo‘lida ko‘proq ushlashi yoki ovqatni qaysi qo‘li bilan yeyishini kuzatish yaxshi boshlanish bo‘lishi mumkin. Agar chaqalog‘ingiz chap qo‘lidan faolroq foydalanadi deb o‘ylasangiz, xavotir olmang. Chapaqaylik haqidagi noto‘g‘ri qarashlar bolani yetakchi bo‘lmagan qo‘lidan foydalanishga majburlashga olib kelishi mumkin, ammo bu uning rivojlanishida ko‘plab muammolarni keltirib chiqaradi.') WHERE id = 'c72377ae-83c6-42fd-be3d-7ba1f89c4920';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Sog‘lom ovqatlanish — bolalik davridan shakllana boshlaydigan odat. Boshqacha aytganda, chaqalog‘ingizning ovqatlanish tartibini hozir qanday yo‘lga qo‘ysangiz, kelajakda ham shu tarzda davom etadi. Masalan, agar chaqalog‘ingizda kun davomida tamaddi qilish odatini shakllantirsangiz, u voyaga yetganida ham bunga ehtiyoj sezadi. Agar kun davomida asosiy ovqatlanishlardan birini o‘tkazib yuborsangiz, kelajakda ham shu mahal ovqatlanmaslik odati paydo bo‘lishi mumkin. Shu sababli chaqalog‘ingizning asosiy ovqatlanishlari va tamaddilari muayyan tartib asosida bo‘lishiga harakat qilishingiz kerak. Bu masalada yon bermaslik va qat’iyatli bo‘lish chaqalog‘ingizda odatning osonroq shakllanishiga yordam beradi. Bu davrda ishtahasizlik ko‘p uchragani sababli, agar chaqalog‘ingiz bir mahal ovqatlanishni istamasa, muqobil variant sifatida foydali yeguliklarni taklif qilishingiz mumkin.') WHERE id = '20150dab-66b0-4920-818c-13a3e7136048';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz 2 yoshga yaqinlashar ekan, bir muddatdan beri o‘z his-tuyg‘ularini ovozi, mushtlari, yer tepayotgan oyoqlari va ko‘z yoshlari orqali ochiq namoyon etayotgan bo‘lishi mumkin. Avvaliga xavotirlanishingiz tabiiy, ammo baxtli bo‘lish qanchalik tabiiy bo‘lsa, xafa bo‘lish ham shunchalik tabiiy tuyg‘u ekanini unutmang. Shu sababli chaqalog‘ingiz qovog‘ini solganida yoki yig‘laganida uni darhol tinchlantirishga shoshilmang. Ortiqcha aralashmasdan, unga xafa bo‘lish ham tabiiy ekanini tushunishi uchun imkon yaratganingiz ma’qul. Xafalikni yo‘qotishga haddan tashqari urinish farzandingizga "jahldor yoki xafa bo‘lish noto‘g‘ri" degan yanglish xabarni berishi mumkin. Farzandingizning barcha muammolarini o‘zingiz hal qilishingiz uni o‘z his-tuyg‘ularini anglash va muammolarni yengishni o‘rganish imkonidan mahrum qiladi. Agar u jahli chiqqanida baqirsa yoki ursa, unga his-tuyg‘ularini ifodalashning tinchroq va maqbulroq usullarini ko‘rsatishingiz mumkin.') WHERE id = 'd1b69dfc-0c51-40d4-ab46-57e12080ec1e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz ishtahasining o‘zgaruvchanligi ba’zan sizni hayratda qoldirishi mumkin. Ayrim kunlari ovqatini to‘liq yeb qo‘yganini, boshqa kunlari esa juda kam yeganini yoki umuman ovqatdan bosh tortganini ko‘rishingiz mumkin. 1.5-2 yosh davrida shifokorga murojaat qilish sabablari orasida ishtahasizlik shikoyati juda ko‘p uchraydi. Farzandingizning ishtahasiga ovqatlanadigan muhit, taomning ko‘rinishi va taqdim etilish usuli, avvalgi tajribasi hamda oilaning ovqatlanish madaniyati bevosita ta’sir qiladi. Shuning uchun ishtahasizlikdan xavotirlanayotgan bo‘lsangiz, shifokorga murojaat qilishdan oldin ushbu omillarni hisobga olganingiz foydali bo‘ladi. Masalan, avval rad etgan mahsulotni boshqacha shaklda taqdim etish yoki ovqatlanish muhitini o‘zgartirib ko‘rishingiz mumkin.') WHERE id = '90f2176f-d469-499a-9a1d-3e82e805f900';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Maktabgacha yoshdagi farzandingizning miyasi o‘ziga xos tezlikda ishlaydi. Uning tanasi va miyasida tuganmas energiya bor. Bu muammo emas, aksincha, rivojlanishning tabiiy belgisidir. Eng muhimi, bu energiyani to‘g‘ri yo‘naltirishdir. Masalan, oddiy o‘yinchoqlar o‘rniga funksionalroq variantlarni tanlashingiz mumkin: itarib yoki minib yuriladigan katta o‘yinchoqlar, yig‘iladigan mexanizmlar, bloklar, boshqotirmalar (pazllar), qo‘g‘irchoq kiyimlari, qo‘g‘irchoqlar va rangli bo‘yoqlar kabi ijodiy materiallar. O‘yinchoqlar unga qiziqarli bo‘lib qolishi uchun barchasini bir paytda berish o‘rniga navbat bilan taqdim etishingiz mumkin. Energiyasini chiqarishi va sezgilarini rag‘batlantirishi uchun loy yoki bolalar uchun maxsus qum ham ajoyib vositadir.') WHERE id = 'f6438f5c-5190-493d-b6e8-a062c6c8373c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2 yosh davri uydagi xavfsizlik qoidalarini qayta ko‘rib chiqish uchun ayni muddao. Avval ham uyda ko‘plab xavfsizlik choralarini ko‘rganingizni bilamiz, ammo farzandingizning bo‘yi o‘sib, u yanada sarguzashtsevar bo‘lib borgani sari yangi xavflar paydo bo‘lishi mumkin. Uning jismoniy rivojlanishini hisobga olib, uyni uning nigohi bilan qaytadan ko‘zdan kechiring. Endi farzandingizning muammolarni hal qilish qobiliyati rivojlangani sababli, u xayolingizga ham kelmagan joylarga kirishi mumkin. "Qo‘li yetmaydi" deb xavfsizlik choralarini kechiktirish o‘rniga, kesuvchi va sanchuvchi asboblarni qo‘li yetmaydigan joyga olib qo‘ying, dori-darmonlar va vitaminlarni esa albatta bolalar ocholmaydigan idishlarda saqlang.') WHERE id = '7c251dbc-3324-4894-adb1-12e3963965fc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ona sutidan ajratish davridagi eng muhim jihatlardan biri — chaqaloqning e’tiborini emishdan chalg‘itadigan mashg‘ulotlarni topishdir. Bunday mashg‘ulotlar har bir bola uchun turlicha bo‘lishi mumkin. Masalan, birgalikda do‘konga borib, unga yoqqan qiziqarli likopcha yoki piyola sotib olishingiz mumkin. Agar chaqalog‘ingiz emib uxlashga o‘rgangan bo‘lsa, kechki ovqati to‘yimli bo‘lishiga e’tibor bering. Emizish vaqti kelganida esa kitob o‘qish, tinch o‘yinlar o‘ynash, alla aytish yoki ertak so‘zlab berish orqali uning e’tiborini chalg‘iting. Agar uni doim muayyan kresloda emizsangiz, bir muddat o‘sha kresloda o‘tirmaslikka harakat qiling. Tunda emish uchun uyg‘onsa, orqasini silab yoki mehrli so‘zlar bilan uni tinchlantirishga harakat qiling. Anacan oilasi sifatida ushbu o‘tish davrida yoningizdamiz.') WHERE id = '4a81e876-e127-40b0-8888-e4bf91cbafc4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Hozir farzandingiz juda faol bo‘lgan davrni boshdan kechiryapsiz. Shu sababli vaqti-vaqti bilan turmush o‘rtog‘ingiz bilan bola tarbiyasi borasida fikrlaringiz bir joydan chiqmasligi mumkin. Bunday holatlarda farzandingiz uchun eng ma’quli — unga birgalikda qabul qilingan qaror asosida munosabat bildirishdir. Muammo yuzaga kelganda, hodisaga guvoh bo‘lgan ota yoki onaning o‘zi ma’qul deb bilgan tarzda aralashishi eng oqilona yo‘ldir. Agar bu borada kelisha olmasangiz, masalani keyinroq farzandingiz eshitmaydigan joyda muhokama qilishingiz mumkin. Izchillik va barqarorlik — intizomning asosidir. Shuning uchun qoidalar va jazo choralari haqidagi asosiy qarashlaringizni muhokama qilib, umumiy fikrga kelganingiz ma’qul. Bahslashish o‘rniga, yondashuvingizni va nima uchun u samara beradi deb o‘ylashingizni bir-biringizga tushuntirishingiz mumkin. Muhokamani shaxsiy hujumga aylanadigan umumlashtirishlar asosida emas, aniq masalalar yuzasidan olib borish va murosaga kelishga harakat qilish to‘g‘riroq bo‘ladi.') WHERE id = '237018c6-9f32-4ad2-bdf7-fd0aaaeb2f68';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2 yosh — bolalar zararli taomlar va turli gazaklar bilan faol tanishadigan davr. Biroq farzandingizning ovqatlanishini sog‘lom tarzda tartibga solish va bu masalada yon bermaslik hali ham o‘z qo‘lingizda. Farzandingiz ratsionida to‘rt bargli beda modelidan namuna sifatida foydalanib, u har bir oziq-ovqat guruhidan yetarli miqdorda olayotganiga ishonch hosil qilishingiz mumkin. Ushbu modelning har bir bargi bitta oziq-ovqat guruhini ifodalaydi: yuqori barg — sut va sut mahsulotlarini; o‘ng barg — go‘sht, tuxum va dukkaklilarni; pastki barg — sabzavot va mevalarni; chap barg esa don mahsulotlarini ifodalaydi. Bu guruhlarning har birini bolangiz ovqatlanishiga yetarli va muvozanatli miqdorda kiritishingiz kerak. Farzandingiz kelajakda sog‘lomroq inson bo‘lib ulg‘ayishi uchun uni zararli gazaklar bilan qancha kech tanishtirsangiz, shuncha yaxshi.') WHERE id = '467c9786-4914-430a-9924-35e942ff8361';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingiz jismonan faol bo‘lsa va rivojlanishida hech qanday kechikish kuzatilmasa, 2 yosh unga velosiped olib berish uchun mos vaqt hisoblanadi. Shu yoshdagi bolalar uchun mo‘ljallangan xususiyatlarga ega velosipedlar bolangizning energiyasini sarflashi uchun ajoyib vositadir. Velosiped haydash bola uchun juda maroqli. Shu bilan birga, bu mashg‘ulotdan qo‘l va ko‘z muvofiqligini, mayda va yirik motorikani, o‘ziga bo‘lgan ishonchni hamda muvaffaqiyat hissini rivojlantirish uchun ham foydalanishingiz mumkin. Bu yosh guruhida muvozanat velosipedi deb ataladigan mahsulotlar farzandingiz uchun eng to‘g‘ri tanlovlardan biri bo‘lishi mumkin. Muvozanat velosipedi — bolalar 2 yoshdan boshlab muvozanatni saqlashni o‘rganadigan velosiped turidir. Eng ma’quli, farzandingiz oddiy velosipedga o‘tishidan oldin muvozanat velosipedidan taxminan 2-3 yil foydalanishi mumkin.') WHERE id = '039fea2a-271b-4d91-ab26-1321bf9ae441';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ishtahasizlik shu yoshdagi farzandi bor har bir ota-onani tashvishga soladigan masaladir. Tish chiqishi, ko‘chib o‘tish kabi yangi muhitga moslashish, onaning ish boshlashi yoki bola parvarishlovchisining almashishi singari keskin o‘zgarishlar bolalarning ishtahasiga bevosita ta’sir qilishi mumkin. Shu bilan birga, farzandingizning ishtahasi va yeydigan ovqat miqdori haqidagi kutuvlaringiz haqiqatga mos bo‘lishi muhim. Chunki bolalarda bir yoshdan keyin o‘sish sur’atining sekinlashishi va natijada energiyaga bo‘lgan ehtiyojning kamayishi tabiiy holatdir. Tabiiyki, energiyaga ehtiyoj kamayganda bolalar kamroq kaloriya qabul qiladi va tezroq to‘yadi. Biroq temir tanqisligi, reflyuks, siydik yo‘llari infeksiyalari, seliakiya kasalligi va qalqonsimon bez faoliyatining buzilishi kabi turli kasalliklar ham ishtahasizlikka sabab bo‘lishi mumkin. Shuning uchun kutuvlaringiz haqiqatga mos bo‘lsa-da, kuchli ishtahasizlik 3 haftadan ko‘proq davom etsa, shifokor bilan maslahatlashishingiz kerak bo‘lishi mumkin.') WHERE id = 'dca414d3-e320-48c8-8813-fff940ae46cb';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrdan boshlab farzandingizning tasavvuri jadal rivojlana boshlaydi. Buni uning o‘yinlarini bir muddat kuzatib ham sezishingiz mumkin. Chunki bolangizda shakllanayotgan savol berish va sabab-oqibat bog‘liqligini tushunish qobiliyati o‘yinlarida ijodkorlik ko‘rinishida namoyon bo‘ladi. Shu sababli farzandingizning rivojlanayotgan tasavvur olamini yanada boyitadigan o‘yinchoqlardan foydalanishingiz mumkin. Masalan, qo‘l ko‘nikmalari bilan bir qatorda aqliy qobiliyatlarini ham ishga soladigan o‘yinchoqlar sotib olish haqida o‘ylab ko‘rishingiz mumkin. Bular boshqa o‘yinchoqlarini solib yurishi mumkin bo‘lgan do‘kon aravachasi, o‘yinchoq telefon, qo‘g‘irchoqlari uchun kiyimlar, barmoq bo‘yoqlari, turli shakllar yasash mumkin bo‘lgan legolar va o‘yin xamirlari bo‘lishi mumkin. Bulardan tashqari, bolalar uchun mo‘ljallangan pianino yoki fleyta kabi musiqa asboblari yordamida uning musiqaga qiziqishi va iste’dodini ham rivojlantirishingiz mumkin.') WHERE id = '57b8155c-5ee1-41d1-934a-7cebf0187e62';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar siz hozirda farzandingizni faol emizayotgan ona bo‘lsangiz, emizishni birdan to‘xtatganingizda ko‘kraklaringiz haddan tashqari to‘lib, shishib, sizga noqulaylik tug‘dirayotganini sezishingiz mumkin. Bu holatning sabablari ko‘p bo‘lishi mumkin, ammo ko‘pincha u bu jarayonda juda shoshganingizni va emizishni juda tez to‘xtatganingizni ko‘rsatadi. Ko‘kraklaringizda noqulaylik sezmaslik uchun emizishni bosqichma-bosqich kamaytirish usulini tanlashingiz juda muhim. Emizishni asta-sekin kamaytirsangiz, sut ishlab chiqarilishi ham pasayadi va shu tariqa bunday muammolarning oldi olinadi. Agar butun jarayonni to‘g‘ri boshqarayotganingizga ishonsangiz-u, shunga qaramay sut ishlab chiqarilishi kamaymasa, ayrim usullardan foydalanishingiz mumkin. Masalan, o‘zingizni qulay his qiladigan darajada sut sog‘ish ko‘krakdagi og‘riqning oldini oladi. Ammo ehtiyot bo‘lishingiz kerak: agar sutni kerakli miqdordan ortiq sog‘sangiz, sut ishlab chiqarilishi kamayish o‘rniga yanada ortishi mumkin.') WHERE id = '0d192335-07c1-48ae-b0c1-73b57c665f7d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Hozir chaqalog‘ingizning qo‘l va oyoqlaridagi burmalar yo‘qolib, boshi tanasiga nisbatan mutanosibroq ko‘rinadigan davrdasiz. Bu yil davomida chaqalog‘ingizning oyoqlari va gavdasi ham uzaya boshlaydi hamda u chaqaloqqa xos ko‘rinishdan to‘liq bolalarga xos ko‘rinishga o‘tadi. Qorin qismining yanada tekislanishi esa uning orqasi ham tikroq ko‘rinishiga yordam beradi. Tashqi ko‘rinishdagi bu o‘zgarishlar chaqalog‘ingiz hali ham faol o‘sayotganidan dalolat beradi. Shunga qaramay, dastlabki ikki yil bilan solishtirganda bolangiz kamroq ovqat yeb, kamroq kaloriya qabul qilayotganini kuzatishingiz mumkin. Aslida, bu bosqichda bolangizning bo‘yi va tana o‘lchamlariga mos kaloriya ehtiyoji dastlabki oylardagi o‘sish sur’atiga nisbatan kamroq bo‘ladi. Unga muntazam ravishda to‘yimli va sog‘lom taomlar taklif qilsangiz, rivojlanishi me’yorida davom etishini unutmang.') WHERE id = '9f4e48f3-4698-48db-86e2-c05bac7cae8f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2 yoshli bola kuniga o‘rtacha 1150-1450 kaloriya olishi kerak. Bu miqdordagi kaloriya moddalar almashinuvining me’yorida ishlashi va rivojlanishning belgilangan doirada davom etishi uchun muhimdir. Biroq chaqalog‘ingiz bu kaloriyalarni oziqaviy qiymati past mahsulotlardan olmasligi kerak. Masalan, shakarning oziqaviy qiymati nol bo‘lsa-da, u yuqori kaloriyali mahsulotlar qatoriga kiradi. Yong‘oq va mag‘izlar esa, aksincha, kaloriyasi ham, oziqaviy qiymati ham eng yuqori mahsulotlar sirasidandir. Chaqalog‘ingiz sog‘lom ulg‘ayishi uchun bo‘sh kaloriyalar emas, oziqaviy qiymati yuqori mahsulotlar kerak. Shu sababli farzandingizning kundalik ovqatlanish tartibini tuzishda raqamlarga haddan tashqari berilib ketmay, mahsulot qanchalik foydali ekaniga e’tibor qaratishingiz juda muhim.') WHERE id = 'c5185021-525c-412b-89be-7978a0800fb0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingizning yarim tunda to‘satdan uyg‘onishi, qayta uxlab qolishga qiynalishi va kunduzgi uyqu tartibining buzilishi kabi muammolarni kuzatishingiz mumkin. 2 yoshli bolalar bir kunda taxminan 12-13 soat uxlashi mumkin. Bu davrda kunduzgi uyqu qisqarib, tungi uyqu uzayishi mumkin. Agar farzandingizning tunda uyg‘onishidan shikoyat qilsangiz, kunduzgi uyquni qisqartirish vaqti kelgan bo‘lishi mumkin. Kunduzgi uyquni bosqichma-bosqich qisqartirish tunda sog‘lomroq va sifatliroq uxlashga yordam beradi. 2 yoshli bolalarning aksariyati tunda 10-11 soat, kunduzi esa taxminan 2 soat uxlaydi. Bunda kunduzgi uyqudan qisqartirilgan vaqt tungi uyquga qo‘shilishi kerakligiga e’tibor berish lozim. Chunki farzandingiz sog‘lom hayot kechirishi uchun bir sutkada zarur bo‘lgan umumiy uyqu vaqtini to‘liq uxlashi juda muhim.') WHERE id = '26503615-41cd-4d9a-ab25-64f208211b61';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu yosh guruhidagi bolalarning aksariyatida kundalik ovqatlanish tartibsiz bo‘lishi mumkin. Bu bir mahal kam yeb, keyingi mahalda uning o‘rnini to‘ldirish tarzida namoyon bo‘ladi. Ba’zan bola bir kun kam yeb, ertasi kuni ishtahasi juda ochilishi yoki ovqatdan oldin shirinlik va zararli yeguliklarni so‘rashi mumkin. Oziqaviy qiymati past, ammo kaloriyasi yuqori bunday yeguliklarni iste’mol qilganda ishtahasi bo‘g‘ilib, asosiy ovqatlanish vaqtini o‘tkazib yuboradi. Agar siz ham shunday muammoga duch kelsangiz, buning oldini olishingiz, zararli yog‘lar va oddiy shakar iste’molini cheklashingiz hamda bu holat odatga aylanishiga yo‘l qo‘ymasligingiz kerak. Chaqalog‘ingizning kundalik ehtiyojlarini qondirish qanchalik muhim bo‘lsa, unda muntazam ovqatlanish odatini shakllantirish ham shunchalik muhimdir. Ovqatlanish tartibiga rioya qilish va ovqatlanish vaqtlarini o‘tkazib yubormaslik bolalikdan singdirilishi lozim bo‘lgan eng muhim odatlardan biridir.') WHERE id = '999e50f0-32f5-409b-95b1-57d5bb7ccc27';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Shu davrdan boshlab farzandingiz, ayniqsa, o‘yin maydonchalarida tengdoshlari bilan birga o‘ynayotganini kuzatishingiz mumkin. U atrofidagi boshqa bolalarning nima qilayotgani va qanday o‘ynayotganini tomosha qilishni yoqtiradi. Hatto ularga taqlid qilishi ham mumkin. Biroq boshqa bolalar bilan vaqt o‘tkazishi o‘yinchoqlarini ular bilan bo‘lishishga rozi bo‘ladi degani emas. Ba’zan qisqa muddatga bo‘lishganini ko‘rsangiz ham, odatda u bundan qochishni afzal ko‘radi. Bo‘lishishni istamaslik bu yoshdagi bolalar uchun mutlaqo tabiiy xatti-harakatdir. Shunga qaramay, uni haddan tashqari majburlamasdan bo‘lishish odatini singdirishga harakat qilishingiz mumkin. Masalan, uyda o‘tirganingizda o‘yinchoqlarni navbat bilan bir-biringizga berishingiz, birozdan so‘ng esa o‘zaro kichik almashinuvlar qilib, bu ko‘nikmani qiziqarli tarzda mashq qilishingiz mumkin.') WHERE id = '228c8956-54f6-42b1-91c3-92700a15abf3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tadqiqotlar maktabgacha yoshdagi bolalarning 60%-i kuniga uch martadan ko‘p ovqatlanishini ko‘rsatadi. Kuniga to‘rt mahaldan kam ovqatlanadigan bolalarda energiya, kalsiy, oqsil, C vitamini va temir yetishmovchiligi kuzatilgan. Shu sababli chaqalog‘ingizning rivojlanishi uchun nonushta, tushlik va kechki ovqatni yetarli hamda muvozanatli qilib rejalashtirishingiz, ehtiyojiga qarab kun davomida oraliq yeguliklar bilan to‘ldirishingiz lozim. Farzandingizning oshqozon sig‘imi kattalarniki bilan bir xil emasligini unutmang. Shu bois uning porsiyalari siz iste’mol qiladigan miqdorning 1/4-i bilan 1/3-i oralig‘ida bo‘lishi kerak. Bola dasturxon atrofida o‘tirganda, avvalo ovqatning ko‘rinishiga baho beradi. Ayniqsa, chaqalog‘ingiz ishtahasiz bo‘lsa, har bir mahalda sog‘lom va rang-barang likopcha tamoyiliga amal qilishingiz kerak. Likopchadagi turli rangli mahsulotlarning o‘zaro uyg‘unligi hamda ularga turli shakllar berib, qiziqarli ko‘rinishga keltirilishi kichkintoyning ishtahasini ochadi.') WHERE id = '146da55d-f9f1-483e-8342-8aa377d3cf2c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalarning aksariyati 2 yoshdan boshlab hojatxonaga o‘rgatishga tayyor bo‘ladi. Biroq bu muddat bolaning individual xususiyatlariga bog‘liq. Masalan, 18 oylik chaqaloq bunga tayyor bo‘lishi, 24 oylik bola esa hali tayyor bo‘lmasligi mumkin. Bunday farqlar bolaning individual rivojlanishi bilan bog‘liq. Qisqasi, 2 yoshga to‘lgan farzandingiz hali hojatxonaga o‘rganishga tayyor emas deb hisoblasangiz, xavotirlanmang. Uni bir muddat kuzatishingiz, bosim o‘tkazmasdan va talab qilmasdan rag‘batlantirishingiz kerak. Qattiq turib olish yoki bolani koyish uning qo‘rqib qolishiga va o‘zini qobiliyatsiz his qilishiga sabab bo‘lishi mumkin. Chunki hojatxonaga o‘rganish chaqalog‘ingiz uchun juda katta o‘zgarishdir va bunday o‘zgarishlar har qanday bolani qo‘rqitishi mumkin. Shuningdek, farzandingizning sog‘lig‘i va rivojlanishi izchil davom etishi uchun sut guruhiga mansub mahsulotlar albatta zarur.') WHERE id = '12f09593-bf34-4be0-bc69-2dfdea7442a0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Sut mahsulotlari guruhi farzandingizning suyaklari, tishlari va mushaklari mustahkam bo''lishi uchun muhim oqsil va kalsiy manbaidir. Bu guruhdagi oziq-ovqatlar oqsil va kalsiydan tashqari, moddalar almashinuvi uchun hayotiy ahamiyatga ega bo''lgan magniy, foliy kislotasi, B1, B2, B6, B12, A va D vitaminlariga ham boy. Sut mahsulotlaridagi oqsil hayvonlardan olinishi sababli yuqori sifatli hisoblanadi va organizm tomonidan juda yaxshi o''zlashtiriladi. Shu bois farzandingiz kun davomida sut mahsulotlari guruhidan 2-3 porsiya iste''mol qilishi juda muhim. 1 stakan sut, 1 kosa qatiq yoki 1,5 stakan ayron bilan chaqalog''ingizning kunlik ehtiyojini qondirishingiz mumkin. Agar farzandingiz sut mahsulotlarini bevosita iste''mol qilmasa, sho''rvalariga sut yoki qatiq qo''shish yaxshi muqobil bo''lishi mumkin.') WHERE id = '9f64f831-67cc-4be0-97ce-2205dfe840a9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Endi 25 oylik bo''lgan chaqalog''ingiz bu davrda tasavvurga asoslangan o''yinlarni yanada ko''proq yoqtiradi. Uning o''yinchoqlari bilan tez-tez gaplashayotganini, ularni ovqatlantirishga va uxlatishga urinayotganini, hatto ularga jahli chiqayotganini ko''rishingiz mumkin. Bu mutlaqo tabiiy holat ekanini bilishingiz kerak. O''yinchoqlari bilan xuddi ular tirikdek muloqot qilishi sizni xavotirga solmasin. Bu davrda farzandingiz bilan uy-uy, shifokor-shifokor yoki do''kon-do''kon kabi haqiqiy hayotga asoslangan o''yinlarni o''ynashingiz mumkin. O''yin paytida u sizga yoqmagan biror harakatni qilsa, xato qilayotganini aytish o''rniga, qanday qilish to''g''ri ekanini ko''rsating. Chunki bunday o''yinlar chaqalog''ingizning aqliy rivojlanishiga bevosita yordam beradi va shaxsiyati shakllanishida muhim rol o''ynaydi.') WHERE id = '7e1b66ed-5e66-4aa1-b4a6-f41e10ded050';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '25 oylik bolalarning vazni bir-biridan ancha farq qilishi mumkin. Bu davrda qiz bolalar vaznining quyi chegarasi 9300 gramm, yuqori chegarasi esa 15.500 grammni tashkil qiladi. 25 oylik qizlarning o''rtacha vazni taxminan 12.200 gramm. O''g''il bolalarda esa vaznning quyi chegarasi 9600 gramm, yuqori chegarasi 16.000 grammni tashkil qiladi. O''g''il bolalarning o''rtacha vazni taxminan 12.600 gramm atrofida bo''ladi. Vazndagi bunday farqlarning asosiy sababi qo''shimcha ovqatga o''tish davridan buyon qo''llab kelayotgan ovqatlantirish usulingiz bilan bevosita bog''liq. Bundan tashqari, chaqaloqning jinsi, irsiyati va turmush tarzi kabi ko''plab omillar ham vazn shakllanishida muhim rol o''ynaydi.') WHERE id = 'a2bfd1ad-4106-4f9b-8d0d-cdce4a5cf06d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Taxminan 1 yoshidan boshlab mustaqil ovqatlanishiga sharoit yaratilgan bola 18-oyida qoshiq bilan ovqatlana boshlashi mumkin. 25-oyda esa chaqaloq qoshiq va sanchqidan bemalol foydalana olishi kutiladi. Agar bolaga avval bu imkoniyat yetarlicha berilmagan bo''lsa, ushbu ko''nikma hali to''liq shakllanmagan bo''lishi mumkin. Bolaning mayda motorikasi rivojlanishi bilan qoshiq ushlash qobiliyati bevosita bog''liq ekanini unutmang. Shuning uchun chaqalog''ingiz hali ham qoshiq va sanchqidan faol foydalana olmasa, mayda motorikani rivojlantiradigan mashg''ulotlarga ko''proq e''tibor berishingiz kerak. Nazoratingiz ostida biri suv bilan to''ldirilgan, ikkinchisi esa bo''sh bo''lgan ikkita idish tayyorlab, farzandingizga suvni qoshiq yordamida bo''sh idishga o''tkazishda ko''maklashishingiz mumkin. Bu birga mazmunli vaqt o''tkazishingizga ham, uning zavqlanib rivojlanishiga ham yordam beradi.') WHERE id = '8f4758cd-90b9-472e-8df7-d37b3ac362c8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ikki yoshdagi uyqu muammolarining asosiy sabablari rivojlanishdagi o''zgarishlar va mustaqillik hissining kuchayishidir. Bolalarda uyqu muammolari yurish va gapirishni boshlagan davrda paydo bo''ladi hamda 2 yoshda eng yuqori darajaga yetadi. Rivojlangan sari atrofida yuz berayotgan voqealarni yaxshiroq anglaydigan bola ulardan bevosita ta''sirlanadi. Ayniqsa, u guvoh bo''lgan salbiy holatlar tunda qo''rqishiga va dahshatli tushlar ko''rishiga sabab bo''lishi mumkin. Ba''zan bu holat shunchaki yomon tush emas, balki jismonan uyg''onish va ichki bezovtalikning namoyon bo''lishi sifatida ham baholanishi mumkin. Shu bilan birga, televizor va videolar kabi media vositalari ham bolani haddan tashqari hayajonlantirishi yoki uyqusini qochiradigan tasvirlarning xotirasida muhrlanib qolishiga sabab bo''lishi mumkin. Chaqaloqning tinch va xotirjam uxlashi uchun nafaqat tunda, balki kun davomida ham osoyishta muhitda bo''lishi juda muhim.') WHERE id = 'a576e8d4-a044-40f6-9103-4fbc7ac08bc4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Go''sht, tovuq go''shti, baliq, tuxum va dukkaklilar farzandingizning aqliy hamda jismoniy rivojlanishi uchun juda muhim. Bu oziq-ovqatlar oqsil, temir, rux va B guruhi vitaminlariga boy. Farzandingiz bu bosqichda go''sht, tovuq go''shti yoki baliqni taxminan 2-3 kotlet kattaligidagi miqdorda iste''mol qilishi kerak. Tuxum esa ona sutidan keyin eng sifatli oqsilga ega bo''lgan yagona oziq-ovqatdir; u bolaning taomnomasida muhim o''rin tutishi va nonushtada tez-tez berilishi kerak. Porsiyalar borasida ikkilansangiz, quyidagi miqdorlar ishingizni osonlashtirishi mumkin: 2-3 dona pishirilgan kotlet kattaligidagi go''sht, 3-4 kichik bo''lak tovuq soni, 3-4 osh qoshiq pishirilgan dukkakli mahsulot va 1 dona tuxum farzandingiz uchun bir porsiya hisoblanadi.') WHERE id = 'a66e9b59-566b-45ea-b98a-39eeae68efc4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz hojatxonaga o‘rganishga tayyor ekanini bir necha belgi orqali bilishingiz mumkin. Eng muhim belgilar — taglikning 2-3 soat davomida quruq qolishi va bolaning o‘ynayotgan paytida qisqa muddat bo‘lsa ham peshob yoki najasini ushlab tura olishidir. Shuningdek, hojati kelganda bir chetga chiqib ketishi, uyalib orqasini o‘girishi yoki yolg‘iz qolishni istashi ham muhim belgilardir. Agar chaqalog‘ingiz kiyimini almashtirayotganingizda sizga yordam bersa, shimini tushirib, qayta ko‘tara olsa, demak, mashg‘ulotni boshlashga tayyorsiz. Dastlab bolaga tuvak sotib olishingiz mumkin. Uni kuniga 1-2 marta tuvakka o‘tirishga undang. Xohlasangiz, sevimli qahramonlari tasvirlangan stikerlarni tuvakka birgalikda yopishtirishingiz ham mumkin. Dastlab bolaga kiyimi yoki tagligi bilan o‘tirishga ruxsat bering, ammo bu masalada aslo majburlamang.') WHERE id = 'a75526ab-d8f7-4d2d-95ac-987058ff01a0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Sabzavotlar farzandingizning ovqatlanishi uchun zarur bo‘lgan vitaminlar, minerallar va fitokimyoviy birikmalarga juda boy. Bu bosqichda farzandingiz kun davomida taxminan 3 porsiya sabzavot iste’mol qilishi kerak. 3 osh qoshiq pishirilgan taom, bir likopcha yaxshilab yuvilgan sabzavotli salat, tamaddi paytida to‘g‘ralgan sabzi yoki sabzavot sharbatlarini tanlashingiz mumkin. Xuddi shuningdek, mevalarda ham chaqalog‘ingizning terisi, ko‘zlari va milklarining salomatligi uchun muhim bo‘lgan A va C vitaminlari, kaliy, kalsiy hamda boshqa minerallar mavjud. Mutaxassislar bu davrda bolalarga kuniga 2 porsiya meva berishni tavsiya qiladi. Shu sababli farzandingizga tamaddi paytida zararli mahsulotlar o‘rniga foydali yegulik sifatida 1-2 bo‘lak meva yoki bodring berishingiz mumkin. 1 ta kichik olma, 8-10 dona o‘rtacha kattalikdagi qulupnay, yarim stakan ko‘k meva yoki 1 ta o‘rtacha kattalikdagi apelsin bir porsiya meva hisoblanadi.') WHERE id = '181a660f-adf3-4c1d-b661-7b1e99455b57';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizni hojatxonaga o‘rgatayotgan yoki bu jarayonni yakunlagan davringizda kichik ko‘ngilsiz holatlar yuz berishi mumkin. Peshob yoki najas dog‘lari ko‘plab onalar uchun noxush holatlardan biridir. Ammo dog‘larni yangiligida tozalash osonroq va tezroq ekanini unutmang. Farzandingiz kiyimidagi najas va peshob dog‘larini ketkazish uchun sovuq suvga dog‘ ketkazuvchi vosita qo‘shib, kiyimlarni bir muddat ivitib qo‘yishingiz mumkin. Agar bu usul yordam bermasa, universal dog‘ ketkazuvchi vositani bevosita dog‘ tushgan joyga surtishingiz mumkin. Yana bir usul — 1 stakan suvni 1 osh qoshiq novshadil spirti (ammiak) bilan aralashtirib, dog‘ga surtishdir. Bu jarayon kiyimlarning rangini o‘chirishi mumkin, shuning uchun avval uni kiyimning kichik qismida sinab ko‘rganingiz ma’qul.') WHERE id = 'fde67b77-39bc-4fff-8eb0-e8ebcbe7b5be';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingiz tez-tez yig‘lab yoki qichqirib uyg‘onayotganini kuzatishingiz mumkin. Mushaklar spazmi va yiqilayotgandek tuyulish bolalarning qattiq qo‘rqib, uyg‘onishiga sabab bo‘lishi mumkin. Ayniqsa, kun davomida o‘ynayotganda yoki sayr qilayotganda yiqilgan bolalar tunda bu qo‘rquvni kuchliroq his qilishlari mumkin. Ayrim bolalarning tunda yarim uyqu holatida karavot ustida o‘rnidan turishi ham kuzatiladi. Karavot cheti bo‘ylab yurayotib, to‘satdan uyg‘ongan chaqalog‘ingiz qayerda ekanini va yana qanday uxlab qolishni anglashga qiynalib, qichqirishi va yig‘lashi mumkin. Bunday vaziyatlarda imkon qadar xotirjamlikni saqlashingiz farzandingiz uchun qilishingiz mumkin bo‘lgan eng foydali ishdir. Chunki nima bo‘layotganini tushunmay turgan chaqalog‘ingizga vahima bilan yaqinlashsangiz, vaziyat yanada murakkablashishi mumkin.') WHERE id = 'b4c378f2-23ac-470c-8fa7-75b6a433a8f8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Maktabgacha yoshdagi bolalar muntazam o‘sish va rivojlanish davrida bo‘ladi. Bu jarayon me’yorida kechishi uchun kunlik kaloriya, makro va mikro oziq moddalar miqdori bolaning ehtiyojlariga mos bo‘lishi muhim. Tadqiqotlar shuni ko‘rsatadiki, kattalarda uchraydigan diabet, yurak kasalliklari va saratonning ayrim turlari ko‘pincha bolalik davridagi noto‘g‘ri ovqatlanish odatlari bilan bog‘liq. Shu sababli ovqatlanish masalasida farzandingizga to‘g‘ri yo‘l ko‘rsatishingiz kerak. Zarur bo‘lsa, mutaxassisdan yordam olishingiz mumkin. Bu davrda farzandingiz ovqatlanish, kiyinish va hojatxona kabi ehtiyojlari uchun sizga kamroq qaram bo‘ladi. Biroq boshqa barcha masalalarda bo‘lgani kabi, ovqatlanishda ham siz va otasidan o‘rnak oladi. Shu ma’noda aytganlaringizdan ko‘ra qilayotgan ishlaringiz ko‘proq ta’sir ko‘rsatadi. Agar farzandingizda sog‘lom ovqatlanish odatini shakllantirmoqchi bo‘lsangiz, avvalo bu odatlarga uyda o‘zingiz amal qilishingiz kerak.') WHERE id = '71a028e9-244b-4bb2-828b-adb6991c70a4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalarning uyqu tartibi deyarli 2 yoshgacha me’yorida davom etsa-da, 2 yoshga yaqinlashgan sari uyqu bilan bog‘liq muammolar ko‘paya boshlaydi. 2 yoshda uyquga o‘rgatish ham ota-onalar, ham bolalar uchun qiyin kechishi mumkin. Bu masalada yolg‘iz emasligingizni biling. 2 yosh inqirozi belgilari hali ham kuchli namoyon bo‘ladigan bu oylarda uxlashga qarshilik ko‘rsatish, qo‘rqib uyg‘onish va kam uxlash kabi holatlar kuzatilishi mumkin. Bu davrda uyqu muammolari odatda qo‘rquv va xavotir tufayli yuzaga kelishini unutmang. Ba’zan bunga jismoniy og‘riqlar ham sabab bo‘lishi mumkin. Farzandingiz yaxshiroq uxlashi uchun uyqudan oldin u bilan birga qorong‘i muhitda vaqt o‘tkazishingiz mumkin. Qorong‘i muhit melatonin gormoni ajralishi va miyaning uyquga tayyorlanishi uchun juda muhim.') WHERE id = '57c7a36d-f4d1-4633-b6cf-7d31210afabf';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingizni ko‘krakdan ajratmoqchi bo‘lsangiz va avval sinab ko‘rgan usullaringiz samara bermagan bo‘lsa, emizish sonini kichik o‘zgarishlar bilan kamaytirish yordam berishi mumkin. Buning uchun chaqalog‘ingiz qaysi paytlarda emishga eng ko‘p va eng kam ehtiyoj sezishini kuzatishingiz kifoya. Boshqacha aytganda, farzandingiz kun davomida necha marta emishi va qaysi emizish seansiga ko‘proq bog‘langanini hisobga olib, jarayonni boshlashingiz mumkin. Bu usulda eng kam ahamiyatli seanslardan boshlab, emizish sonini birma-bir kamaytirish kerak. Seanslar sonini kamaytirish bilan birga, har bir emizish davomiyligini qisqartirish ham yechim bo‘lishi mumkin. Masalan, odatda 10 daqiqa emizsangiz, avval 7, keyin 5, undan so‘ng 3 daqiqagacha qisqartirib, oxirida esa butunlay to‘xtatishingiz mumkin. Shu tariqa, farzandingizning bu jarayonga osonroq moslashishiga va uni imkon qadar kam ruhiy jarohat bilan o‘tkazishiga yordam berasiz.') WHERE id = 'b2d2a191-cfa2-4680-b7fa-56aec3d43443';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '25 oylik bolalarda atrofni o‘rganishga bo‘lgan qiziqish eng yuqori darajada bo‘ladi. Bu davrda chaqalog‘ingiz uchun hamma narsa qiziqarli: u hech kimga qaram bo‘lmasdan, har bir mayda tafsilotni qiziq deb topib, uni o‘rganishga harakat qilishi mumkin. Bolada tushunchalar chalkashib ketmasligi uchun 2 yoshga mo‘ljallangan mashg‘ulotlar farzandingizning rivojlanish darajasiga mos bo‘lishi kerak. Uyda mavjud materiallar yordamida ular uchun bemalol mashg‘ulotlar uyushtirishingiz va o‘yinlar o‘ynashingiz mumkin. Masalan, tarkibi mutlaqo tabiiy bo‘lgan bolalar bo‘yoqlarini xarid qilishingiz mumkin. Qo‘lingizga sellofan paket kiyib, bu bo‘yoqlarni qog‘ozga xohlagan shaklda surtish orqali farzandingizning ranglar bilan aloqasini mustahkamlashingiz va unda estetik did shakllanishiga yordam berishingiz mumkin. Qisqasi, shu yo‘l bilan ta’lim, tasavvurni rivojlantirish va ko‘ngilochar mashg‘ulotni birlashtirgan bo‘lasiz! :)') WHERE id = '3bc058c0-b2b8-4d01-8dfe-9d742de7ca23';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingiz har kuni go‘sht, sut, don mahsulotlari, meva, sabzavot va yog‘li oziq-ovqatlarni muvozanatli ravishda ma’lum miqdorda iste’mol qilishi muhim. Ushbu bosqichda bolaning kunlik kalsiyga ehtiyoji o‘rtacha 350 mq ni tashkil qiladi. 250-300 gramm sut, qatiq va gugurt qutisidek hajmdagi oq pishloq farzandingizning kunlik kalsiyga bo‘lgan ehtiyojini qondirishi mumkin. Shu bilan birga, suyaklar rivojlanishi davom etishi uchun bu davrda ham D vitaminiga ehtiyoj bor. Tarkibida D vitamini mavjud mahsulotlar soni cheklangani va qishda quyosh nuridan foydalanish imkoniyati kamaygani sababli, bu yosh guruhida ham 400 vahid D vitamini qabul qilishni davom ettirish kerak. Temirga bo‘lgan ehtiyoj ham bu davrda e’tibor berilishi lozim bo‘lgan jihatlardan biridir. Temir yaxshiroq o‘zlashtirilishi uchun temirga boy oziq-ovqatlarni C vitamini bilan birga berishga harakat qiling. C vitamini organizmda to‘planmagani uchun uni har kuni qabul qilish foydalidir.') WHERE id = '32027992-7ca5-4f41-9e94-b756c09c029b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '25 oylik farzandingiz harakat, ijtimoiy va kognitiv ko‘nikmalarda katta yutuqlarga erishayotgan bo‘lsa-da, ayniqsa, nutq rivoji bu oylarda juda tezlashadi. Harakat ko‘nikmalari rivojlangani sari chaqalog‘ingizning yurishi, sakrashi va hatto yugurishini ko‘rishingiz mumkin. U endi zinadan chiqishga ham o‘rgangan va vaqt o‘tishi bilan bu ko‘nikmalari yanada rivojlanadi. Endi yordamsiz tishlarini tozalashni boshlagan farzandingiz qo‘llarini ham mustaqil yuva oladigan darajaga yetishi kerak. Bu bolangiz hayotidagi katta qadamdir, chunki u sizning yordamingizga ko‘p ehtiyoj sezmasdan o‘ziga g‘amxo‘rlik qila oladi. Shuningdek, bu davrda u siz aytgan bir necha so‘zdan iborat oddiy topshiriqlarni bajara oladi. Farzandingizning gaplari hali to‘liq tushunarli bo‘lmasligi va u to‘g‘ri jumlalar tuzishda qiynalishi mumkin. Uning jumlalari to‘liq tushunarli bo‘lishi uchun taxminan yana 1.5-2 yil kutishingizga to‘g‘ri keladi.') WHERE id = 'ba59a28d-3a83-4205-ae5d-916e1a3c9cd4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Xalq orasida bolani ko‘krakdan ajratish uchun ko‘krak uchiga pomidor yoki qalampir kabi achchiq mahsulotlarni surtish keng tarqalgan usuldir. Biroq barcha mutaxassislar bu yondashuv noto‘g‘ri ekaniga qo‘shiladilar. Emizishni bolada jirkanish yoki qo‘rquv uyg‘otish, ya’ni keskin usullar orqali to‘xtatish bola uchun ruhiy jarohatga aylanishi mumkin. Chunki emizish chaqaloq hayotining boshida asosiy oziqlanish manbai bo‘lish bilan birga, ona va bola o‘rtasida alohida rishta yaratadigan hissiy jarayondir. Shu sababli, ko‘krakdan ajratish vaqti kelganda keskin usullar o‘rniga, emizishni asta-sekin kamaytirib to‘xtatish eng ko‘p tavsiya etiladigan usuldir. Unutmang, bu jarayon bolaning yoshi va emizishga bog‘liqlik darajasiga qarab bir necha hafta, ba’zan esa bir necha oy davom etishi mumkin. Sabrli bo‘lish bu yo‘lning eng muhim qismidir.') WHERE id = '1e6cc207-c282-439c-9382-edd1bb9f0fbf';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalarda 18-30 oylar oralig‘ida rivojlanadigan qaysarlik ota-onalarni ancha qiynaydigan davrlardan biridir. Chunki bolalar bu davrda bir vaqtning o‘zida ko‘plab his-tuyg‘ularni boshdan kechiradi va ularni atrofdagilarga bevosita namoyon qiladi. Qaysarlik davrida bolalar o‘z mustaqilligi va kuchini sinab ko‘rish, siz uchun qanchalik muhim ekanini ko‘rsatish maqsadida chegaralarni buzishga urinadilar. Nutq rivoji tezlashadigan, bola his-tuyg‘ular, fikrlar va voqealar o‘rtasida bog‘liqlik o‘rnatadigan bu davr uzoq muddatda unda turli ko‘nikmalarni shakllantiradi. His-tuyg‘u va fikrlarini asta-sekin ifoda eta boshlagan bola har bir istagi ham amalga oshmasligini anglaydi. Bu to‘siqlar bolaning keskin munosabat bildirishiga va oiladagi muloqotning buzilishiga sabab bo‘lishi mumkin. Ota-onaning qat’iy va izchil yondashuvi tufayli chaqalog‘ingiz har bir istagi ham amalga oshmasligini va xohishlarini kechiktirishni o‘rganadi, shuningdek, muammolarni hal qilish ko‘nikmalarini rivojlantiradi.') WHERE id = 'f7c23bf2-ec35-4dd7-9dc0-07a8b4bba0ce';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloq organizmiga oz miqdorda tuz kerak. Biroq hayotining dastlabki yillarida unga bo‘lgan ehtiyoj unchalik katta emas. Shu sababli bolalarga ilk 1 yoshda tuz bermaslik, 1 yoshdan keyingi ovqatlanish davrida ham dasturxonga tuzdon qo‘ymaslik kerak. Bolani sho‘r va shirin ta’mlarga o‘rgatmaslik — uni kelajakda tuz va shakar bilan bog‘liq kasalliklardan himoya qilish uchun kiritiladigan eng muhim sarmoyadir. Mamlakatimizda yod tanqisligi keng tarqalganini hisobga olib, 2 yoshdan oshgan bolangizning taomlariga oz miqdorda yodlangan tuz qo‘shishingiz mumkin. Bu bosqichda bolangizning kunlik tuzga bo‘lgan ehtiyoji taxminan 1-2 grammni tashkil etadi. Yosh ulg‘aygani sari tuzga bo‘lgan ehtiyoj oshsa-da, odatda 3-4 grammdan oshmaydi. Shuningdek, yod bug‘lanib ketmasligi uchun tuzni taom pishganidan keyin qo‘shganingiz ma’qul. Shu bilan birga, chaqalog‘ingizning yodga bo‘lgan ehtiyojini qondirish uchun uning baliq, sut, sut mahsulotlari va go‘shtni muvozanatli iste’mol qilishini ta’minlashingiz kerak.') WHERE id = 'e16dcc56-eb7e-4fc3-973b-a0196af2cc6b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '25 oylik chaqalog‘ingiz endi qo‘liga kitob berganingizda uning sahifalarini bemalol varaqlash imkonini beradigan mayda motorika ko‘nikmalariga ega. Shuningdek, shisha yoki bankalarning qopqoqlarini burab ochish uchun yetarli kuch va ko‘nikma ham shakllangan. Bu yoshdagi bolalar televizor kabi tugmalari ko‘p buyumlarning tugmalarini bosib, yoqib-o‘chirishdan juda zavqlanadilar. Bunday rivojlanish har bir ota-onani quvontiradi, biroq endi e’tibor berish kerak bo‘lgan yangi xavflar ham mavjud. Masalan, bolangizning yanada rivojlangan motorika ko‘nikmalari va kuchi ayrim holatlarda uning xavfsizligini xavf ostiga qo‘yishi mumkin. Shu sababli dori-darmonlar va tozalash vositalarini bolangiz yeta olmaydigan joylarda saqlashni unutmang. Agar bunday xavfli moddalarni saqlash uchun baland joylaringiz bo‘lmasa, yanada mustahkam qulflar o‘rnatib, xavfsizlikni ta’minlashingiz mumkin.') WHERE id = '68ecf8cd-54e7-4312-816c-db417c732ac3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ko‘krakdan chiqarish yoki emizishni to‘xtatish bu davrda onalarni eng ko‘p o‘ylantiradigan masalalardan biridir. Agar chaqalog‘ingizni hali ham emizayotgan bo‘lsangiz, uni ko‘krakdan chiqarish usullarini faol izlayotgan bo‘lishingiz mumkin. Ona emizishni, bola esa emishni istar ekan, bu jarayon mamnuniyat bilan davom etadi. Ammo ona biror sababga ko‘ra emizishni to‘xtatmoqchi bo‘lsa-yu, bola bunga hali tayyor bo‘lmasa, jarayon ancha qiyinlashishi mumkin. Aksincha, bola tayyor bo‘lib, ona bu o‘ziga xos rishtani davom ettirishni istaganida ham qiyinchiliklar yuzaga kelishi mumkin. Bu charchatadigan jarayonni imkon qadar yengil o‘tkazish uchun zarur bo‘lsa, ko‘krakdan chiqarishni yana bir muddatga kechiktirishingiz mumkin. Ayrim mutaxassislar emizishni qachon to‘xtatishni ona va bola birgalikda hal qilishi hamda ikkalasi ham o‘zini bunga to‘liq tayyor his etishini tavsiya qiladilar.') WHERE id = '5e6fd373-9ca1-43c3-bef0-2470cbfda2a2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '25 oylik bolalar 2 yoshga to‘lishi bilan o‘z shaxsiyatini namoyon etish uchun jiddiy kurasha boshlaydilar. Bu davrda aytilgan gapning mutlaqo aksini qilish kabi nomaqbul xatti-harakatlar tez-tez kuzatilishi mumkin. “Bolalik o‘smirligi” deb ham ataladigan “O‘jarlik davri” 2-4 yosh oralig‘ida kuzatiladi. Bu davrda bolalar o‘jarlik qiladi, o‘z bilganidan qolmaydi, muloqot qilishda qiynaladi va istagan narsasiga erishish uchun tez-tez yig‘lab, jahl xurujlarini namoyon qiladi. Chaqalog‘ingiz ilgari o‘jarlik qilmagan bo‘lsa ham, bu davrda kuchli o‘jarlikka duch kelishingiz mumkin. Bu bosqich bolalar o‘zlarining mustaqil shaxs ekanini anglay boshlaydigan va o‘z shaxsiyatini tasdiqlashga urinadigan rivojlanish pog‘onasidir. Umuman olganda, bu bolaning shaxsiyati rivojlanishi uchun muhim va sog‘lom jarayondir. Biroq ota-onaning noto‘g‘ri yondashuvi bu jarayonning salbiy tus olishiga sabab bo‘lishi mumkin. Shu bois bolangizni keraksiz ravishda siquvga olish o‘rniga, bunday xatti-harakatlar rivojlanishning bir qismi ekanini tushunish va unga mehr bilan yondashish juda muhim.') WHERE id = '263f0565-7a52-428a-8087-e11f47811c14';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '1 yoshdan keyin boshlanadigan va 2 yosh atrofida eng ko‘p uchraydigan muammolardan biri bolalardagi ishtahasizlikdir. Buning sababi — bolangiz 1 yoshdan oshgach, uning o‘sish sur’ati sekinlashishi va fiziologik ishtahasizlik davri boshlanishidir. Qisqacha aytganda, har bir bola boshdan kechiradigan bu davrni sizning farzandingiz ham o‘tkazishi mutlaqo tabiiy. 6-9 oylik davrda oyiga 400 gramm vazn qo‘shgan bolangizning 1 yoshdan keyin oyiga 200 gramm qo‘shishi, ayrim oylarda esa umuman vazn qo‘shmasligi me’yoriy holat hisoblanadi. Ota-onalar ko‘pincha “ishtahasizlik” deb hisoblaydigan bu bosqich aslida aksariyat bolalar uchun tabiiydir. Agar bolangizning vazni uzoq vaqt davomida o‘zgarmay qolmasa, vazni muntazam kamaymasa va jismoniy tekshiruv natijalari me’yorida bo‘lsa, uni ko‘proq yedirishga majburlashning hojati yo‘q. Shifokoringiz bilan bolangiz uchun yetarli bo‘lgan porsiyalar va ovqatlanish sifati haqida gaplashib, batafsil ma’lumot olishingiz mumkin.') WHERE id = '2530ccd6-7ee5-40e4-96e7-b2eaadf767b1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu bosqichda uy ishlariga yordam berishga juda ishtiyoqmand va hayajonlangan bo‘lishi mumkin. Ammo unga ayrim ishlarni topshirish orqali uning rivojlanishiga ham hissa qo‘shishingiz mumkinligini bilasizmi? Masalan, kiyimlar yuvilgach, ularni taxlash va dazmollash har bir uyda bajariladigan ishdir. Paypoqlarni juftlash bolangizni ham xursand qiladigan, ham unga sizga yordam berayotganini his ettiradigan mashg‘ulot bo‘lishi mumkin. Bu mashg‘ulot chaqalog‘ingizga sezgi a’zolaridan faol foydalanish imkonini beradi va mayda motorika ko‘nikmalarini rivojlantirishning ajoyib usulidir. Buning uchun barcha paypoqlarni aralashtirib polga qo‘ying va bolangizdan bir xil juftlarni topishini so‘rang. U juftlarni topgan sari sizga bersin, siz esa ularni taxlang. Shunda bolangiz ham o‘rganadi, sizning uy ishlaringiz ham yengillashadi! :)') WHERE id = '16247942-6521-4d3c-b412-05d1285066ab';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bu davrda ancha tajovuzkor xatti-harakatlarni namoyon qilishi mumkin. Bu tajovuz boshqalarni urish, tishlash, ovqat solingan likopchani ag‘darish yoki istagi bajarilmaganda jazavaga tushish ko‘rinishida namoyon bo‘lishi mumkin. Bunday xatti-harakatlar bolaning o‘z his-tuyg‘ularini boshqara olmasligi natijasidir. Aslida, bolalar tug‘ilgan paytidan boshlab his-tuyg‘ularini boshqarishni biladilar, ammo ayrim noto‘g‘ri munosabatlar bu qobiliyatga putur yetkazishi mumkin. Boshqacha aytganda, ota-ona sifatida farzandingizning his-tuyg‘ularini o‘zingiz bilmagan holda bostirsangiz, u ularni yashirishni yoki nosog‘lom usullar bilan ifodalashni o‘rganadi. Masalan, yondashuvingiz to‘g‘ri bo‘lsa ham, farzandingiz siz tomondan tajovuz yoki salbiy munosabatni ko‘rsa, buni odatiy hol deb qabul qila boshlaydi. Bir-biringizga yoki boshqalarga nisbatan g‘azabingizni haqoratli so‘zlar bilan emas, balki vaziyatni tushuntiruvchi so‘zlar orqali ifodalab, farzandingizga o‘rnak bo‘lishingiz muhim.') WHERE id = '0102cad4-afdc-443f-9c50-810c77e5f6b0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tabriklaymiz! Farzandingiz bilan birga 26 oyni ortda qoldirdingiz. Farzandingiz endi 26 oylik! Bu davrda u stakanni bir qo‘li bilan yanada oson ushlay oladi, mustaqil ravishda yeb-icha oladi. Jismoniy rivojlanishida harakatlari avvalgi oylarga qaraganda faolroq bo‘ladi. Endi u bemalol yugurishi, to‘p o‘ynashi va sakrashi mumkin. Uning tuganmas energiyasi hamon eng yuqori darajada. Harakat qilsa, oyoq kiyimi va paypoqlarini mustaqil ravishda kiyib-yecha oladi. Yordamingizsiz qo‘llari va yuzini yuvib, tishlarini tozalashi mumkin. Agar farzandingizning bunday kundalik ishlarini hali ham o‘zingiz bajarishni afzal ko‘rsangiz, endi unga biroz mustaqillik berish vaqti keldi! :)') WHERE id = 'c1200e82-5b42-4c10-b000-d86a0a9bfcb9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '26 oylik bolalarda bo‘y va vazn o‘sishi avvalgi oylarga nisbatan rivojlanishning boshqa bosqichiga o‘tadi. Qisqacha aytganda, farzandingizning o‘sish sur’ati endi o‘zgargan. Shu sababli tarozida vazn ortishini ko‘rmasangiz, xavotirga tushmasligingiz kerak. 2 yoshdan keyin bolalarning vazni barqarorroq bo‘lib qoladi, bo‘yi esa o‘sishda davom etadi. Bu ularning tana tuzilishi kattalarnikiga o‘xshab borishi uchun tabiiy jarayondir. Vazn ortmasdan bo‘y o‘sishi bolaning ozg‘inroq ko‘rinishiga sabab bo‘lishi mumkin. 26 oylik qiz bolalarda vazn 9600 grammdan 15400 grammgacha, o‘g‘il bolalarda esa 10200 grammdan 15900 grammgacha bo‘ladi. Agar farzandingizning bo‘yi va vazni shu me’yorlar doirasida bo‘lsa, xavotirlanishingizga hech qanday asos yo‘q.') WHERE id = 'c91fefd7-5188-4567-b316-4d37d49bdc9f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingiz vazn olishda qiynalayotgan bo‘lsa, avvalo sut, meva sharbati va suv kabi ichimliklarni ovqatdan oldin yoki ovqatlanish paytida ichishini cheklashingiz kerak. Shu bilan birga, agar bolangiz gazlangan ichimliklar va choy kabi yoshiga mos kelmaydigan ichimliklarni iste’mol qilsa, buni darhol to‘xtatish lozim. Farzandingizga beradigan porsiyalarni o‘z xohishingizga ko‘ra emas, balki uning ehtiyojiga mos ravishda belgilashingiz muhim. Agar bola tayyorlagan taomingizni rad etsa, boshqa taom taklif qilishingiz mumkin. Biroq u o‘sha ovqatlanish paytida hech narsa yeyishni istamasa, uni majburlamang. Bolalarda ham kattalar kabi vaqti-vaqti bilan ishtaha yo‘qolishi mumkin. Agar bu holat sizni tashvishga solsa, uning e’tiborini tortadigan rang-barang va bezatilgan likopchalar tayyorlang. Oziq-ovqatlarning foydasini o‘yinlar orqali tushuntirishingiz mumkin; unga tanlash imkoniyatini berish juda muhimligini unutmang.') WHERE id = '15c24f02-d146-4c26-955a-b36ec124d9fb';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '26 oylik farzandingiz uchun ham qiziqarli, ham o‘rgatuvchi mashg‘ulot tayyorladik! :) Deyarli har bir bola 1 yoshidan boshlab yuz qismlarini taniy boshlaydi, 2 yoshida esa bu borada haqiqiy ustaga aylanadi. Bu o‘yinni o‘ynash uchun sizga 5-6 dona rangli A4 qog‘oz kerak bo‘ladi. Bir varaqdan yuz shaklini kesib tayyorlang (xohlasangiz, bu qog‘ozni teri rangiga bo‘yashingiz mumkin). So‘ng boshqa qog‘ozlardan 3-4 xil shakldagi burun, og‘iz, ko‘zlar, quloqlar va qoshlarni kesib tayyorlang. Bu qismlarni istagan rangingizga bo‘yang. Farzandingizga ko‘z, burun, soch, og‘iz, mo‘ylov yoki ko‘zoynak kabi qismlarni berib, ularni bo‘sh yuz andozasiga o‘zi xohlagandek joylashtirishini so‘rang. Anacan oilasi sifatida sizga maroqli hordiq tilaymiz! :)') WHERE id = '030305b5-b63d-4484-a47e-c90776cee51b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Har bir bola o‘ziga xos va rivojlanish xususiyatlarining turlicha bo‘lishi tabiiy. Biroq bir xil yoshdagi bolalarda kuzatiladigan o‘rtacha ko‘nikmalar bu borada muayyan mezonlarni belgilaydi. Farzandingiz bo‘lgan 2-3 yosh davrida uning faol lug‘at boyligi o‘rtacha 450 tagacha so‘zni tashkil qilishi kerak. Bu ko‘rsatkichning quyi chegarasi taxminan 50 ta so‘zdir. Qisqacha aytganda, agar farzandingiz 50 tadan kam so‘z aytsa, bu nutq rivojlanishining kechikishi belgisi bo‘lishi mumkin. Nutq rivojlanishining kechikishi vaqtni boy bermasdan mutaxassisga murojaat qilishni talab qiladigan holatdir. Bu holat kichik yoshda aniqlanib, terapiyani erta boshlagan bolalar qisqa vaqt ichida katta yutuqlarga erishib, tengdoshlariga yetib olishlari mumkin. Agar bolangiz nechta so‘z ishlatishiga ishonchingiz komil bo‘lmasa, bir hafta davomida u aytgan aniq va turli so‘zlarni yozib borib, tekshirishingiz mumkin.') WHERE id = '6d292b09-fdd7-410b-a261-f55fbb6b64f8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz sog‘lom rivojlanishi uchun kun davomida iste’mol qiladigan barcha taomlar va porsiyalar katta ahamiyatga ega. Shu nuqtai nazardan, nonushtaga 2/3 stakan sut, 1 dona tuxum yoki gugurt qutisidek hajmdagi pishloq, 1 choy qoshiq sariyog‘, 1-2 choy qoshiq murabbo / asal / shinni / yong‘oq pastasi va 2-3 dona zaytun berishingiz mumkin. Bundan tashqari, 1 yupqa bo‘lak butun donli non hamda bir necha bo‘lak pomidor yoki mandarin kabi muqobil mahsulotlarni taklif qilishingiz mumkin. Tushlikka 4-5 osh qoshiq qiymali sabzavotli taom, 1-2 osh qoshiq palov va 2 osh qoshiq qatiq yetarli bo‘ladi. Kechki ovqatga esa 1 dona kotlet yoniga 1 kosa yasmiq sho‘rva yoki yarim bo‘lak non yaxshi tanlovdir. Asosiy ovqatlardan tashqari, tamaddi uchun 1 kosa qatiq, 1 dona kichik meva, 2-3 dona uyda tayyorlangan pechenye, yong‘oq va boshqa mag‘izlar hamda keyingi bosqich sutli aralashmasini berishingiz mumkin. Bu menyuda e’tibor berishingiz kerak bo‘lgan jihat: zaytun danaklarini olib tashlash, yong‘oq va boshqa mag‘izlar tomoqqa tiqilib qolmasligi uchun ularni biroz maydalashdir.') WHERE id = 'f17d2eda-9f54-40f8-8442-4a42173f4c40';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz hozir nihoyatda serg‘ayrat va uning olami qiziqishga to‘la. Siz uchun oddiy tuyuladigan kundalik hayot tafsilotlari uning uchun kashf etilishini kutayotgan ulkan sarguzashtdir. Shu sababli chaqalog‘ingizni doimo “yo‘q!” deb cheklamasligingiz kerak. Chunki bolalar o‘yin-kulgiga va jiddiy zarurat bo‘lmasa, erkinlikka muhtoj. Farzandingiz o‘ynayotganida yoki sho‘xlik qilib dunyoni o‘rganayotganida unga “yo‘q” deyish uchun 3 mezonga tayanishingiz kerak: Uning harakati boshqalarga zarar yetkazadimi? Uning harakati nazorat ostida bo‘lsa ham xavflimi? Uning harakati chindan ham tashvish uyg‘otadimi yoki odob-axloqqa zidmi? Shu savollarni o‘ylab, kun davomida farzandingizga necha marta “yo‘q” deganingizni va bu taqiqlar haqiqatan ham zarur bo‘lgan-bo‘lmaganini tahlil qiling.') WHERE id = '67f098da-7fda-41a8-92dc-91e2b7af2b79';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz ozib ketayotgani yoki avvalgidek tetik ko‘rinmayotganini o‘ylab, tez-tez xavotirga tushishingiz mumkin. Biroq har bir bolaning rivojlanish sur’ati o‘ziga xos va uning irsiy salohiyatiga bog‘liq ekanini unutmang. Agar farzandingiz rivojlanishida ortda qolish yoki ishtahasi keskin pasayganini sezsangiz, shifokor bilan maslahatlashish eng to‘g‘ri qadamdir. Avvalo, muntazam borib turadigan pediatringiz ko‘rigidan o‘ting. Agar tekshiruv natijalari me’yorda bo‘lsa va bolaning bo‘yi hamda vazni o‘sishi (persentil) yoshiga mos kelsa, shifokor bilan oziq-ovqat tarkibi va porsiyalar miqdorini muhokama qiling. Bola iste’mol qiladigan ovqat miqdori sizni qoniqtirishiga qarab emas, uning ehtiyojlariga ko‘ra belgilanilishi kerak. Agar ishtahasizlik bilan birga o‘sish sur’ati sekinlashsa va rivojlanish egri chizig‘ida pasayish kuzatilsa, umumiy qon tahlili, siydik tahlili va shifokor zarur deb hisoblagan boshqa tekshiruvlar yordamida buning sabablarini aniqlash mumkin.') WHERE id = 'eecab972-e990-4a43-b73c-ca756216bc2e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz hojatxonadan foydalanishga tayyor ekanini tushunishning turli yo‘llari va usullari mavjud. Ular orasida eng muhimi — chaqalog‘ingiz siz aytgan oddiy topshiriqlarni tushunishi va ularni bajara olishidir. Hojatxonaga o‘rgatishda muloqot juda muhim o‘rin tutadi. Shu sababli farzandingiz siz aytgan so‘zlarni to‘liq tushuna olishi muhimdir. Bundan tashqari, chaqalog‘ingiz tagligi ifloslanganidan bezovta bo‘lsa va buni darhol ishora yoki so‘z bilan sizga bildirsa, bu ham uning hojatxonaga o‘rganishga tayyorligini ko‘rsatadi. Odatda, 2 yosh atrofidagi bolalar kattalarning hojatxonada nima qilishiga qiziqa boshlaydi. Bu chaqalog‘ingiz uchun qiziqarli mavzu, shuning uchun uni ayblamang yoki koyimang. Chunki bunday qiziqish farzandingiz hojatxonaga o‘rganishga tayyor ekanini ko‘rsatadigan yana bir belgidir.') WHERE id = '7e8892e7-dddb-4acc-8056-5a75077c9cb9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Montessori mashg‘ulotlari farzandingizning rivojlanishi uchun juda muhim. Bu bosqichda kundalik uy yumushlari asosida bajarishingiz mumkin bo‘lgan Montessori mashg‘ulotini tavsiya qilamiz! :) Buning uchun avval idish yuvish mashinasini bo‘shatayotganda chaqalog‘ingizni yoningizga chaqiring va sizga yordam berishni xohlash-xohlamasligini so‘rang. 2 yosh atrofidagi bolalarning barchasi yordam berishga ishtiyoqmand bo‘ladi. Ammo chaqalog‘ingiz buni xohlamasa, uni majburlamang. Sanchuvchi va kesuvchi buyumlarni chetga olib qo‘ygach, sanchqi va qoshiqlar solingan savatni chaqalog‘ingizga berishingiz mumkin. Undan sanchqi va qoshiqlarni oshxona tortmasidagi tegishli joyiga qo‘yishini so‘rang. Bir necha urinishdan so‘ng farzandingiz bu ishni qanchalik muvaffaqiyatli bajarayotganidan hayratlanasiz. Shuningdek, bu mashg‘ulot orqali chaqalog‘ingizning guruhlash va tasniflash ko‘nikmalari ham rivojlanadi.') WHERE id = 'a21412bd-7f9d-4cd0-8052-99c4370e5744';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz hozir bo‘lgan 2 yosh davrida ishtahasizlik ham, ortiqcha vazn va semizlik ham tez-tez uchraydi. Ovqatlanish — odat, shu sababli chaqalog‘ingizda to‘g‘ri ovqatlanish odatlarini shakllantirishingiz juda muhim. Bu yoshda shakllantirilgan sog‘lom ovqatlanish odati chaqalog‘ingizni kelajakda yuzaga kelishi mumkin bo‘lgan ko‘plab kasalliklardan himoya qilishi mumkin. To‘g‘ri odatlarni shakllantirish uchun o‘zingiz namuna bo‘lishingiz shart. So‘nggi paytlarda semizlik holatlarining ko‘payishi ovqatlanish odatlariga yanada e’tiborli bo‘lishni talab qiladi. Bu yoshda semizlikka asosan nosog‘lom oziq-ovqatlar va kamharakatlik sabab bo‘ladi. Asosiy maqsadingiz semizlik yuzaga kelmasidan oldin uning oldini olish bo‘lishi kerak. Chaqalog‘ingizning bo‘yiga mos vaznini bilgan holda uning kun tartibi va ovqatlanishini shunga muvofiq tashkil qilishingiz kerak.') WHERE id = '0c5e42c2-ff51-4921-be51-98211c1fde6d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu davrda hamma narsani o‘rganishga intilgani uchun qo‘llari doimo iflos bo‘lishi mumkin. Bu uning rivojlanish jarayonining bir qismi, shuning uchun bunga to‘sqinlik qilmasligingiz kerak. Uyda gigiyenaga rioya qilish oson bo‘lsa-da, tashqarida ko‘pincha antibakterial gellarga ehtiyoj tug‘ilishi mumkin. Bunday gellar suv va sovun bo‘lmagan joylarda yaxshi muqobil hisoblanadi. Ammo bu mahsulotlar tarkibida ko‘p miqdorda spirt va zaharli moddalar borligini unutmang. Shu sababli gelni hech qachon bolaning qo‘liga tutqazmang. Zarur bo‘lganda uning kaftiga 1 tomchi siqib, qo‘llarini bir-biriga ishqalashiga yordam berishingiz mumkin. Gelni qo‘llagandan keyin bolaning qo‘llarini hidlashiga yo‘l qo‘ymang, chunki bu nafas yo‘llarini ta’sirlantirishi mumkin. Antibakterial gellar ko‘zni ham achishtiradi, shuning uchun bolaning ko‘zlarini ishqalashiga yo‘l qo‘ymang. Gel tasodifan ko‘ziga tegsa, darhol ko‘p miqdordagi suv bilan yuving.') WHERE id = '611311a5-f1da-4044-901d-5e129a858e3b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning bu davrda boshqa tengdoshlari kabi vazn yo‘qotishi mutlaqo tabiiy. Biroq uning rivojlanishi sekinlashmasligi va organizmi uchun zarur oziq moddalarni yetarli miqdorda olishi uchun ovqatlanish tartibini qayta ko‘rib chiqishingiz kerak. Tayyorlaydigan menyuingizda kletchatkasi va oqsili ko‘p mahsulotlar bo‘lishi muhim. Bir muddat o‘ta yog‘li taomlardan saqlanishingiz mumkin, ammo bu ratsion butunlay "yog‘siz" bo‘lishi kerak degani emas. Chunki yog‘lar chaqalog‘ingizning ham jismoniy, ham aqliy rivojlanishi uchun juda muhim makroelementdir. Eng asosiysi, bu yog‘lar foydali manbalardan olinishi kerak. Masalan, avokado va baliq foydali yog‘larning ajoyib manbalaridir. Baliq tarkibidagi ko‘plab minerallar va Omega-3 tufayli chaqalog‘ingizning sog‘lom o‘sishida katta rol o‘ynaydi.') WHERE id = '5c08add0-1273-45c1-b0fd-3449a7f6de9c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz endi o‘yinchoqlari bilan mustaqil o‘ynay olishini va tanasini yaxshiroq boshqarayotganini sezayotgan bo‘lsangiz kerak. Shu tufayli u turli buyumlardan foydalana oladi va murakkabroq o‘yinlarga qiziqish bildira boshlaydi. Bu ajoyib rivojlanishni kuzatish bilan birga, jarayonda ishtirok etish ham sizga katta zavq bag‘ishlaydi. Qo‘l ostingizdagi oddiy buyumlardan foydalanib, chaqalog‘ingizning jismoniy va aqliy rivojlanishiga foyda beradigan ko‘plab mashg‘ulotlarni tashkil qilishingiz mumkin. Masalan, birga ko‘chaga chiqqaningizda "ranglar ovi"ni o‘ynashingiz mumkin. Oldindan belgilangan rangdagi o‘simlik yoki buyumlarni topish bo‘yicha musobaqalashib, juda maroqli vaqt o‘tkazasiz. Eski oilaviy suratlarni tomosha qilib, qarindoshlarning bolalikdagi ko‘rinishini topishni so‘rashingiz mumkin. Hatto uydagi stullar va choyshablardan o‘yin qal’asi yoki stol tagida yashirin chodir qurish ham ajoyib fikr.') WHERE id = '08464b0f-495b-4181-afc5-ae0e47bd6f76';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingizning odamlar haqidagi fikri juda keskin bo‘lishi mumkin. Masalan, uning nazarida inson yo butunlay yaxshi, yo butunlay yomon bo‘ladi. U yaxshi odamlarning salbiy jihatlari bo‘lishi mumkinligini o‘ylamaganidek, yomon deb hisoblagan odamlarning ijobiy tomonlarini ham tan olmaydi. Shu sababli ayrim odamlarga nisbatan juda sovuq va uzoq munosabatda bo‘lishi mumkin. Aksincha, yaxshi ko‘rgan insonlariga juda samimiy munosabat ko‘rsatadi. Bu davr barcha tengdoshlari uchun xos ekanini unutmang va uni majburlamang. Agar chaqalog‘ingiz biror sababga ko‘ra kimnidir yoqtirmasa, u bilan yaqinlashishga majburlash vaziyatni yanada qiyinlashtirishi mumkin. Biroq farzandingiz umuman hammaga nisbatan haddan tashqari sovuq munosabatda bo‘layotganini sezsangiz, mutaxassis bilan maslahatlashish foydali bo‘ladi.') WHERE id = '4eec5008-4918-434b-9083-b409f329d305';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu bosqichda ancha qaysar va "aytganim aytgan" bo‘lishi mumkin. Bu holat ba’zan sizni qiyin vaziyatga solsa-da, bolada qaysarlik boshlanganida qo‘llanadigan eng muhim qoida — uning diqqatini boshqa tomonga yo‘naltirishdir. "Buni qilma!" deyish o‘rniga, "Kel, birga o‘yin o‘ynaymiz!" desangiz, ko‘pincha bu mo‘jizadek samara beradi. Albatta, har safar uni boshqa mashg‘ulotga yo‘naltirish uchun vaqtingiz yoki sabringiz yetmasligi mumkin. Ammo yangi mashg‘ulot bilan birga soatlab shug‘ullanishingiz kerak deb o‘ylamang. Atigi 5-10 daqiqa u bilan shug‘ullanishingiz qaysarligi bosilishi va o‘yinga berilib ketishi uchun yetarli bo‘ladi. Qisqasi, imkoni bor har qanday vaziyatda birinchi usul sifatida uning diqqatini chalg‘itishga harakat qiling.') WHERE id = '406f94ca-8e7c-4eb0-ba29-320528d7f38a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingizda ishtaha keskin pasayganini sezishingiz mumkin. Ko‘plab shifokorlarning fikricha, bolalarda uchraydigan ishtahasizlik odatda noto‘g‘ri ovqatlanish odatlaridan kelib chiqadi va kasallik hisoblanmaydi. Shuning uchun xavotir olmang. Biroq ishtahasizlik surunkali tus olsa va 3 haftadan ortiq davom etsa, shifokorga murojaat qilishingiz tavsiya etiladi. Chunki uzoq davom etadigan ishtahasizlik ortida ayrim infeksiyalar yoki boshqa sog‘liq muammolari bo‘lishi mumkin. Agar muammo noto‘g‘ri odatlar bilan bog‘liq bo‘lsa, ayrim jihatlarga e’tibor qarating. Masalan, chaqalog‘ingiz ba’zi mahsulotlarni yoqtirmasligi mumkin. Bunday vaziyatda uni majburlash o‘rniga muqobil mahsulotlarni taklif qiling. Agar ismaloqni yoqtirmasa, unga go‘sht, sut, tuxum yoki baliq berib, ismaloqdan ololmaydigan temir va vitaminlarni boshqa mahsulotlardan olishiga yordam berishingiz mumkin.') WHERE id = 'c34bd107-e494-44f0-ad8f-0d26c2cab8c1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz shu oylardan boshlab jinslar o‘rtasidagi farqlarni anglay boshlaydi. Aytish mumkinki, u ayollar va erkaklar o‘rtasida muayyan farqlar borligini tushunadigan darajaga yetdi. Shu sababli ayrim bolalarda bu farqlarni anglash bilan bog‘liq turli munosabatlar kuzatilishi mumkin. Masalan, u bir jins vakillariga boshqasiga qaraganda tezroq jahli chiqishi yoki o‘rinli-o‘rinsiz tajanglik qilishi mumkin. Shuningdek, bir jins vakillaridan uyalishi, tortinishi yoki aksincha, ularga yaqinroq munosabatda bo‘lishi mumkin. Biroq rivojlanishning bu bosqichida bunday holat mutlaqo tabiiy hisoblanadi. Xavotirlanish o‘rniga, farzandingizning xatti-harakatlarini kuzatib, bunday holatlarni qanday kamaytirish va muammo yuzaga kelsa, uni qanday qilib tezda hal etish mumkinligini turmush o‘rtog‘ingiz bilan muhokama qilishingiz kerak. Chunki chaqalog‘ingizni hammadan ko‘ra siz yaxshiroq bilasiz va eng to‘g‘ri yechimni ham aynan siz topa olasiz.') WHERE id = 'a2a1f8bf-e46d-4735-b6ff-cfa1846c3118';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz uchun barcha ovqatlanish vaqtlari va nimalar yeyishi juda muhim, ammo ular orasida nonushtaning o‘rni alohida. Sog‘lom hayot kechirish uchun nonushta har bir inson uchun muhim, chunki kechki ovqatdan keyin tana ko‘p energiya sarflaydi. Tonggacha uyqu paytida hech qanday oziq-ovqat iste’mol qilinmasligi tanada energiya hosil bo‘lishini sekinlashtirishi mumkin. Shu sababli nonushta tunda sarflangan energiyani tiklash uchun eng yaxshi imkoniyatdir. Shunday qilib, kichkintoyingiz kunni tetik boshlaydi va kun davomidagi harakatlari uchun zarur bo‘lgan "yoqilg‘i"ni to‘playdi. Nonushtada nimalar yeyilishi esa alohida ahamiyatga ega. Farzandingiz tuxum va sut mahsulotlarini iste’mol qilishi uning kundalik ehtiyojlarini katta darajada qoplaydi. Ayniqsa, tuxum ona sutidan keyin eng qimmatli oziq moddalarni o‘zida jamlagan mo‘jizaviy mahsulotdir.') WHERE id = 'f7cb97a9-2f7f-4a20-87e3-acdb8e3339f0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizda hali ham 2 yosh inqirozining belgilari kuchli namoyon bo‘lishi mumkin. Ayrim bolalar bu davrdan ko‘proq ta’sirlanadi va ularda tishlash kabi nomaqbul xatti-harakatlar kuzatilishi mumkin. Agar kichkintoyingiz tishlasa, ursa yoki to‘satdan jahli chiqsa, avvalo sabrli va vazmin bo‘lishingiz muhim. Unutmang, bolangizning bunday xatti-harakati aslida bir vositadir; u istagan narsasiga erishish uchun shunday yo‘l tutadi. Tishlaydigan yoki uradigan bolaga nisbatan aniq va qat’iy munosabatda bo‘lish uning sog‘lom hissiy rivojlanishi uchun juda muhim. Agar farzandingiz his-tuyg‘ularini so‘z bilan ifodalay olmasa, buni uning o‘rniga siz yoki otasi aytishingiz mumkin. Bunday vaziyatlarda Sen juda jahldorsan, shundaymi? kabi gaplarni aytib, unga o‘zini tushunishayotganini his qildira olasiz.') WHERE id = '067c1fbe-4e1e-4749-96ff-19097dcc209e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning aqliy rivojlanishi yangi tug‘ilgan davriga qaraganda ancha ilgarilagan. Biroq u hali ham jonli va jonsiz narsalarni to‘liq farqlay olmaydi. Masalan, Quyosh va Oy haqida ham xuddi inson haqida o‘ylagandek fikrlashi mumkin. Qisqacha aytganda, jonsiz narsalarni jonli deb tasavvur qilish bu davrga xos xususiyatdir. Agar u o‘yinchoq yoki vazani sindirib qo‘ysa, vaza o‘zi sinishni xohlagan deb o‘ylashi mumkin. Buning sabablaridan biri — unda voqelik hissi hali to‘liq shakllanmaganidir. Aqliy rivojlanishi davom etgani sari u atrofidagi dunyoni yanada to‘g‘ri anglay boshlaydi. Siz esa uning tuganmas nima, qanday, nega degan savollariga katta qiziqish, sabr va e’tibor bilan javob berib, bu rivojlanishga eng katta hissa qo‘sha olasiz.') WHERE id = '77742548-5dac-44f3-becd-3cd309b83f2b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning hozirgi rivojlanish bosqichiga xos asosiy xususiyatlardan biri — juda ko‘p savol berishidir. U deyarli har bir mavzu bo‘yicha xayolingizga ham kelmaydigan tafsilotlarni o‘ylab, savollar berishi sizni hayratda qoldirishi mumkin. Ba’zan chaqalog‘ingiz buni shunchaki e’tiborni jalb qilish uchun ham qilishi mumkin. E’tiborni jalb qilish maqsadida berilgan savollar ko‘pincha mantiqsizroq bo‘ladi. Biroq savollarning soni, ma’nosizligi yoki ularni qayta-qayta so‘rashidan qat’i nazar, farzandingizni ko‘p savol bergani uchun hech qachon koyimang. Uning aqliy rivojlanishi uchun savollariga imkon qadar mantiqli va sodda tarzda javob berishga harakat qiling. Savollar ko‘paygan sari javob berishdan qochgingiz kelishi mumkin, ammo bu rivojlanish nuqtayi nazaridan katta xato ekanini unutmang. Imkon qadar sabrli bo‘ling; hali yo‘lning boshidasiz. :)') WHERE id = '272f9de9-ae5a-4eb4-b4f0-09f249a69a3c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar juda serharakat bo‘lgani uchun kattalarga qaraganda ko‘proq energiyaga ehtiyoj sezadi. Ular jadal rivojlanish davrida bo‘lgani sababli tanasi uchun zarur vitamin va minerallarni yetarli miqdorda olishi kerak. Farzandingizning 5 yoshgacha bo‘lgan davri uning kognitiv, harakat va ko‘rish qobiliyatlari eng faol shakllanadigan paytdir. Barcha oziq-ovqat guruhlaridan yetarli miqdorda iste’mol qilishi miya va asab hujayralarining sog‘lom ishlashini ta’minlab, diqqat yetishmovchiligi va giperfaollik kabi muammolarning oldini olishga yordam beradi. Muvozanatli ovqatlanish aqliy rivojlanish va o‘rganish qobiliyatini oshiradi. Ayniqsa, foydali yog‘larni muntazam iste’mol qilish miya hujayralarining yaxlitligini saqlaydi va neyronlar o‘rtasidagi aloqani osonlashtiradi. Bu chaqalog‘ingizning ruhiy holatiga ham ijobiy ta’sir ko‘rsatib, injiqlik va tajovuzkorlik xurujlarining oldini oladi.') WHERE id = '957a986d-ee56-489a-b467-9bed2d7b4892';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bola bor uyda yashaganda ko‘pincha e’tibordan chetda qoladigan masalalardan biri — yashash joyini bolaga moslab tashkil qilmaslikdir. Uy sharoitini bolaga moslashtirish farzand tarbiyasi va intizom jarayoni bilan chambarchas bog‘liq. Chunki kundalik hayotda bolaga taqiqlanadigan va “yo‘q” deyiladigan ko‘p narsalar aslida u o‘rganishni istaydigan, ammo o‘zi uchun xavfli yoki ota-onalar uchun alohida ahamiyatga ega buyumlar bilan bog‘liq. Ota-onalar qanchalik ko‘p “yo‘q” demasin, bolalar baribir ayrim ishlarni qilishni xohlashadi. Masalan, televizor pultini titkilash, vazani o‘yinchoq mashina bilan urish yoki elektr rozetkasiga sanchqi tiqish shular jumlasidandir. Albatta, bunga ruxsat berib bo‘lmaydi. Biroq doimiy taqiqlar qo‘yib, tarang va bezovta muhitda yashash o‘rniga, bir nechta kichik usul yordamida hayotni osonlashtirish mumkin. Pultni baland joyda saqlashingiz mumkin. Vazani bola ulg‘ayguncha qulflanadigan shkafga qo‘yish mumkin. Elektr rozetkalariga esa xavfsizlik qopqoqlarini o‘rnatish mumkin. Qisqasi, hamma narsaga “yo‘q” deb, bolani cheklashdan ko‘ra, sizni “yo‘q” deyishga majbur qiladigan vaziyatlarni bartaraf etish oqilona yo‘l bo‘ladi.') WHERE id = '24d78195-52d6-418b-9a44-151ac076ad3c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tadqiqotlar shuni ko‘rsatadiki, 26 oylik bolalar hamdardlikning dastlabki yaqqol ko‘nikmalarini namoyon qila oladilar. Bu davrda ular boshqa odamlar o‘zlarini qanday his qilishi haqida, hatto o‘zlari ayni tuyg‘uni his qilmasa ham, tushunchaga ega bo‘la boshlaydilar. Hatto yaqin insoni og‘riq his qilsa, ular buni shunchaki tushunibgina qolmay, og‘riqni yengillashtirishga ham harakat qiladilar. Biroq bu chaqalog‘ingiz har doim hamdardlik bildira oladi degani emas. Shu sababli farzandingiz bir kuni sizning his-tuyg‘ularingizga juda qiziqib, boshqa kuni esa butunlay xudbinlarcha tutishini kuzatishingiz mumkin. Hatto kattalarda ham ba’zan hamdardlik qobiliyati sust bo‘lishini hisobga olsak, bu ko‘nikma farzandingizda bir kunda to‘liq shakllanishini kutmasligingiz kerak. Uning hamdardlik qobiliyatini rivojlantirish uchun u bilan to‘g‘ri muloqot qilish juda muhimligini unutmang.') WHERE id = '66b861ee-daf9-4bb4-99ec-98a5a4c85861';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ayniqsa, chaqalog‘ingizning hozirgi yoshida uning injiq va sho‘x xatti-harakatlarini qo‘zg‘atadigan muayyan sabablar bo‘ladi. Masalan, butun kunini tashqarida o‘tkazgan va tashqi ta’sirlarga (shovqin, ranglar, odamlar) haddan tashqari ko‘p duch kelgan bola uyga kelgach, juda serharakat va sho‘x bo‘lishi mumkin. Shu bilan birga, kun bo‘yi uyda qolgan bola kechqurun uxlashga qarshilik qilishi mumkin. Bunday vaziyatlarda uning nega gapga kirmayotganini topishmoqdek qabul qilish o‘rniga, chaqalog‘ingizning fe’l-atvori va ehtiyojlarini tushunishingiz kerak. Bolalar och yoki uyqusiz bo‘lganda yoxud kun davomida ularga yetarlicha e’tibor berilmaganda juda qaysar bo‘lib qolishi mumkin. Shuning uchun farzandingiz tajovuzkorona tuta boshlaganida, avvalo uning asosiy ehtiyojlarini qondirishga harakat qiling. Shunda bu serharakatlik va injiqlikning asl sababini aniqroq bilib olishingiz mumkin.') WHERE id = 'a6f116b1-a2fd-4df4-9d02-8024e8406686';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz diqqatini bir joyga jamlay olish muddati ancha uzaydi. Endi uning biror mashg‘ulotga avvalgidan ko‘ra uzoqroq vaqt davomida va chuqurroq qiziqayotganini yaqqol ko‘rishingiz mumkin. Masalan, barcha bolalar kabi sizning kichkintoyingiz ham bu davrda rasm chizishga juda qiziqadi. Rasm chizayotganda butun diqqatini qog‘oz va ranglarga qaratishi buning eng yaxshi isbotidir. Farzandingizning bu diqqatini ijobiy tomonga yo‘naltirib, unga ko‘proq rasmli kitoblarni tomosha qilish imkonini yaratishingiz mumkin. Bolangiz bu diqqatini televizor yoki planshet qarshisida sarflamasligiga harakat qiling. Chunki u yerda nazoratsiz ko‘radigan tasvirlar uning tasavvuriga salbiy ta’sir qilishi mumkin. Buning o‘rniga, siz unga tasavvur olamini imkon qadar samarali rivojlantirishga yordam berishingiz kerak.') WHERE id = '3dd2e755-52bb-485f-aae6-0adf656f3d85';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2 yosh inqirozi deb ataladigan 1.5-2.5 yosh oralig‘idagi davr ota-onalar uchun bola tarbiyasining eng murakkab bosqichlaridan biridir. Bu davrda chaqalog‘ingiz bilan murosa qilish haqiqatan ham sabr talab qilishi mumkin. Bu qiyinchilikda yolg‘iz emasligingizni unutmang, Anacan oilasi sifatida yoningizdamiz. Ko‘plab ota-onalar bu vaziyatni yengish uchun turli usullardan foydalanadilar, ammo ularning ayrimlari bolaning rivojlanishiga zarar yetkazishi mumkin. Masalan, bola injiqlik qilmasligi uchun telefonni qo‘liga berib, undan soatlab foydalanishiga ruxsat berish ana shunday xatolardan biridir. Bu masalada bir marta yon berish keyinchalik voz kechish qiyin bo‘lgan odatlarga olib kelishi mumkin. Agar farzandingizda shunday qaramlik paydo bo‘lgan bo‘lsa va uni bartaraf eta olmayotgan bo‘lsangiz, mutaxassisdan yordam olishingiz mumkin. Shuningdek, bu borada aytayotgan gaplaringiz qilayotgan ishlaringizga mos kelishi kerak. Qisqasi, farzandingiz so‘raganida unga telefon bermasangiz, o‘sha vaqt davomida o‘zingiz ham telefondan uzoq turishingiz kerak.') WHERE id = 'f1c6bc8b-26e9-4fdb-a3cc-6f2e7f573fdd';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar tug‘ilganidan 3 yoshigacha ularning miyasi jadal rivojlanadi. Kichkintoyning aqliy rivojlanishiga ta’sir qiladigan eng muhim oziqa ona sutidir. Shu sababli bolalarning dastlabki 2 yil davomida ona suti bilan oziqlanishi ularning aqliy rivojlanishiga katta hissa qo‘shadi. Chunki miyaning 60%ini yog‘ tashkil etadi va uning yarmini Omega-3 yog‘ kislotasi bo‘lgan DHA tashkil qiladi. Qisqasi, bu davrda chaqaloq miyasining rivojlanishini qo‘llab-quvvatlaydigan eng zarur modda aynan DHA hisoblanadi. Farzandingizni har bir davrda miya rivojlanishini qo‘llab-quvvatlaydigan mahsulotlar bilan oziqlantirish muhim, ammo hozirgi oylar bu rivojlanish eng tez kechadigan davrlardan biridir. Shu sababli farzandingiz DHA miqdori yuqori bo‘lgan baliqlarni iste’mol qilishi, agar baliq yemasa, shifokoringiz tavsiyasi bilan baliq yog‘ini qabul qilishi yaxshi tanlov bo‘lishi mumkin.') WHERE id = '43411138-1170-4057-8905-a104a8761813';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Kundalik hayotdagi shoshilish va bosim tufayli ko‘plab ota-onalar tajovuzkor xatti-harakat qiladigan farzandlari hayotidagi muhim bosqichlarni e’tibordan chetda qoldiradilar. Ko‘pincha farzandining jahlini tezda bosishni istagan ota-onalar uning barcha istaklarini bajarib, o‘zlaridan foydalanishiga yo‘l qo‘yadilar. Agar farzandingiz shunday xatti-harakatlarni namoyon qilsa, uning istagini o‘sha zahoti bajarmasligingiz kerak. Chunki bu katta xatodir. Farzandingiz shu yo‘l bilan istagan narsasiga erishayotganini ko‘rsa, tajovuzkor munosabatni odatga aylantiradi. Uning tajovuzkorligiga yon bermasligingiz kerak. Unga vaqt ajratib, u bilan qiziqayotganingizni va hech bo‘lmaganda harakat qilayotganingizni his qildirish juda muhim. Uning diqqatini boshqa tomonga yo‘naltirishingiz va o‘zini yaxshiroq ifoda etishi uchun yo‘llar topishingiz kerak. Zo‘ravonlik qiladigan va boshqalarni uradigan bolalar tarbiyasidagi eng to‘g‘ri usul shu.') WHERE id = 'f625e959-60b5-495d-a840-b56855c25995';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bilan birga 27 oyni ham ortda qoldirdingiz. Tabriklaymiz! Bu davrda farzandingizning jismoniy rivojlanishi bilan birga idrok etish qobiliyati ham sezilarli darajada oshganini kuzatishingiz mumkin. Uning uchun o‘rganishning asosiy usullaridan biri taqlid qilishdir, shu sababli u sizning har bir harakatingizni takrorlaydi. Uning yonida o‘z xatti-harakatlaringizga yanada ko‘proq e’tibor berishingiz kerak. Endi unga ayrim vazifalarni topshirishingiz mumkin. Masalan, sochib tashlagan o‘yinchoqlarini yig‘ish, oyoq kiyimini yechish yoki uy shippagingizni olib kelish shunday vazifalardan bo‘lishi mumkin. Bu ishlarni unga ko‘rsatib tushuntiring va bajarganida minnatdorligingizni his qildiring. Shaxsiy parvarish masalasida ham uni ruhlantiring; endi u tishlarini tozalash, qo‘llarini yuvish kabi ishlarni o‘zi bajara oladi. Biroq undan qo‘lidan kelmaydigan darajada katta ishlarni kutmang, chunki muvaffaqiyatsizlik hissi uning ishtiyoqini so‘ndirishi mumkin.') WHERE id = 'b44114a4-c08d-4b3e-a2d0-1cd68b02620c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Persentil jadvaliga ko‘ra, 27 oylik o‘g‘il bolalarning vazni o‘rtacha 13.100 gramm, 27 oylik qiz bolalarning vazni esa o‘rtacha 12.500 grammni tashkil qiladi. 27 oylik o‘g‘il bolalar uchun xavfsiz vazn oralig‘i 10.700 gramm bilan 16.200 gramm, qiz bolalar uchun esa 10.400 gramm bilan 15.700 gramm orasidadir. Bu davrda o‘g‘il bolalarning bo‘yi o‘rtacha 90 sm, qiz bolalarniki esa 88,5 sm bo‘ladi. O‘g‘il bolalar uchun xavfsiz bo‘y oralig‘i 83 sm–97 sm, qiz bolalar uchun esa 81,5 sm–95 sm hisoblanadi. 27 oylik o‘g‘il bolalarning bosh aylanasi o‘rtacha 49 sm, qiz bolalarniki esa 47,8 sm bo‘ladi. Agar chaqalog‘ingizning vazni, bo‘yi yoki bosh aylanasi ushbu oraliqlardan tashqarida bo‘lsa, bu haqda shifokoringiz bilan maslahatlashishingiz mumkin.') WHERE id = '70fc133b-03bd-43e1-aada-df82f087d242';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqlik va bolalik davrida ovqat hazm qilish tizimi allergenlarga juda sezgir bo‘ladi. Ayniqsa, bir yoshgacha paydo bo‘ladigan ko‘plab allergiyalar keyingi yillarda o‘tib ketadi. Chaqalog‘ingiz bu davrda allergenlarga 6 oylik chaqaloqqa qaraganda chidamliroq bo‘ladi. Biroq so‘nggi yillarda glyutenga allergiya holatlari keskin ko‘paygan. Glyutenga allergiya — ingichka ichakning irsiy kelib chiqishga ega sezgirligidir. Bu allergiya bug‘doy, arpa, suli va boshqa donlarda mavjud bo‘lgan glyuten moddasiga qarshi yuzaga keladi. Glyuten ingichka ichakdagi vorsinkalarni (villus) zararlagani sababli bola organizm uchun zarur oziq moddalarni o‘zlashtira olmaydi. Bu esa immunitet tizimida muammolar paydo bo‘lishiga olib keladi. Agar chaqalog‘ingiz tarkibida glyuten bo‘lgan mahsulotlarni iste’mol qilganidan keyin qusish, ich ketishi, qorin dam bo‘lishi, ishtahasizlik va rivojlanishning kechikishi kabi belgilarni namoyon qilsa, glyutenga allergiyadan shubhalanish mumkin.') WHERE id = 'eb1b2068-46a0-49bb-b797-caac49ade7df';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ishlaydigan onalar uchun ishga qaytish va bolaning bog‘chaga tayyor yoki tayyor emasligini aniqlash charchatadigan jarayon bo‘lishi mumkin. So‘nggi yillarda ham pedagogik, ham iqtisodiy sabablarga ko‘ra maktabgacha ta’lim muassasalariga ehtiyoj oshdi. Biroq favqulodda vaziyat bo‘lmasa, mutaxassislar bolalarni 2.5 - 3 yoshdan oldin oila muhitidan ajratmaslikni tavsiya qiladilar. Chunki bu yoshda bolaga birinchi navbatda bog‘cha emas, aynan oilaviy mehr va iliqlik kerak. Yetarli darajada jismoniy, aqliy va hissiy yetuklikka erishmasdan bog‘chaga yuborilgan bola ruhiy zarar ko‘rishi va bu qarorning salbiy izlari yillar davomida saqlanib qolishi mumkin. Shu sababli chaqalog‘ingiz bog‘chaga tayyor ekaniga ishonch hosil qiling va bu qarorni shoshilib qabul qilmang.') WHERE id = 'a4e9b2f0-988c-4121-83d2-5b078dc54a4e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizga muntazam ovqatlanish odati va sog‘lom ovqatlanish madaniyatini singdirishingiz mumkin, biroq buni bosim bilan amalga oshirish to‘g‘ri emas. Majburan o‘rnatilgan tartib uzoq muddatda samara bermaydi. Sog‘lom ovqatlanish odatini shakllantirish uchun, avvalo, siz — ota-onalar o‘z ovqatlanishingizga e’tibor berishingiz kerak. Chunki bola ota-onasiga taqlid qilib ulg‘ayadi. Uyda sog‘lom ovqatlanish an’anasi bo‘lmasa, bolaning boshqacha bo‘lishi qiyin. Muvozanatli ovqatlanish muntazam ovqatlanishdan boshlanadi. Chaqalog‘ingiz ba’zan ovqatlanishni vaqtni behuda sarflash deb hisoblab, qarshilik ko‘rsatishi mumkin. Uyda belgilangan ovqatlanish vaqtlarining bo‘lishi chaqalog‘ingizga ham tartib-intizomni, ham ovqatlanish tushunchasini anglashga yordam beradi.') WHERE id = '6d888f31-72fe-4046-b79d-3d045211080a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bitlash har qanday yoshda uchrashi mumkin bo‘lgan muammo bo‘lsa-da, u ko‘proq bolalarda kuzatiladi. Bunga bolalar immun tizimining hali to‘liq rivojlanmagani va gigiyena qoidalariga to‘liq amal qila olmasligi sabab bo‘lishi mumkin. Ayniqsa, o‘yin guruhlari va bolalar bog‘chasi kabi gavjum joylarda bit yuqish xavfi juda yuqori. Bolalarda eng ko‘p uchraydigan turi — bosh biti. Bu jarayon tuxum qo‘yish va lichinka bosqichlari bilan davom etadi, shuning uchun chaqalog‘ingizning soch parvarishiga befarq bo‘lmasligingiz kerak. Agar bolangizda bitlash muammosi yuzaga kelsa, maxsus shampunlardan foydalanishingiz mumkin. Cho‘miltirish vaqtida sochlarini mayda tishli taroq bilan tarash ham bitlarni yo‘qotishning samarali usulidir.') WHERE id = 'f0808361-bf65-40fb-aa73-6be6cd94a7ac';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Baliq tarkibidagi yog‘ chaqalog‘ingiz salomatligini asrashda juda foydalidir. Baliq yog‘i yallig‘lanishga qarshi, antioksidant va o‘smalarga qarshi ta’siri bilan tanilgan, shuningdek, qon tomirlarining qattiqlashishi va tiqilib qolishining oldini olishga yordam beradi. Aksariyat mutaxassislarning ta’kidlashicha, bolalar bu yog‘ni qo‘shimcha ozuqa sifatida emas, balki bevosita baliq iste’mol qilish orqali olgani foydaliroq. Biroq ko‘p bolalar yog‘li baliq yeyishni yoqtirmaydi. Haftasiga ikki marta baliq iste’mol qiladigan bolalarga qo‘shimcha baliq yog‘i berish shart emas, degan fikrlar mavjud. Ayrim mutaxassislar esa mintaqamizdagi baliqlar asosan iliq dengizlarda yashaydigan turlar bo‘lgani sababli ularda Omega-3 yog‘ kislotalari (DHA va EPA) juda kamligini aytib, baliq yog‘i qo‘shimchasining muhimligini ta’kidlashadi. Shu bois shifokoringiz bilan maslahatlashgach, chaqalog‘ingizga har kuni baliq yog‘i berish yaxshi fikr bo‘lishi mumkin.') WHERE id = 'fbb69386-c7e5-4fbb-97e9-982d14f4b94e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz kun sayin ulg‘ayib, qisqa vaqt ichida rivojlanishning katta bosqichini bosib o‘tdi. Endi sizning vazifangiz unga ulg‘ayib qolganini his qildirishdir. Farzandingiz oilaning bir a’zosi ekanini ko‘rsatish uchun uning shaxsiy buyumlaridan tashqari, ovqatlanish vaqtida ishlatadigan alohida likopchasi va sanchqisini ham olib berishingiz mumkin. Ayniqsa, u yaxshi ko‘radigan qahramonlar tasviri tushirilgan bunday kichik buyumlar uni ovqatlanishga qiziqtirishning yoqimli usuli bo‘ladi. Shuningdek, chaqalog‘ingizdan yechgan kiyimlarini kir savatiga tashlashini so‘rashingiz mumkin. Bunday odatlarni shakllantirish bir qarashda unchalik muhim tuyulmasligi mumkin, ammo mas’uliyat hissi aynan shu yoshda shakllanadi. Bu kichik vazifalar kelajakda uning yanada tartibli va mas’uliyatli inson bo‘lib ulg‘ayishiga yordam beradi.') WHERE id = '3101c4cb-3b48-4335-a262-39fa7a1322ad';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz endi siz bajarayotgan ishlarga qiziqish bildirishi mumkin. Bu davrda u ortingizdan yurib, biror narsani artish kabi harakatlar bilan sizga taqlid qilishga urinadi. Ko‘plab ota-onalar bolaning ishga aralashishini istamay, unga to‘sqinlik qilishadi. Biroq ishingizni qiyinlashtiradi deb o‘ylab, unga xalal berish o‘rniga, bunday ishlarni bajarishiga ruxsat berishingiz va unga biroz erkinlik yaratishingiz kerak. Qolaversa, bu lahzalarni imkoniyatga aylantirib, kundalik muloqot jarayonida unga kichik-kichik ma’lumotlarni o‘rgatishingiz mumkin. Masalan, ranglar va raqamlarni o‘yin shaklida o‘rganish osonroq kechadi. U o‘ynashni yoqtiradigan uy buyumlarini rangiga qarab guruhlash yoki polni artayotganda undagi plitkalarni sanash kabi mashg‘ulotlar chaqalog‘ingiz rivojiga katta hissa qo‘shadi. Shu tariqa siz ham zavqlanishingiz, ham farzandingiz bilan mazmunli vaqt o‘tkazib, uning ta’lim olishiga ko‘maklashishingiz mumkin.') WHERE id = '62a7c96c-d9da-4a1b-918e-e957e6e835d1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '27-oyda chaqalog‘ingizning savollar yomg‘iri jadal davom etadi. Siz doimo mavzuga aloqador yoki aloqasiz ko‘plab savollarga duch kelishingiz mumkin va u albatta sizdan izoh kutadi. Unga fikrlarini qadrlashingizni his qildirgan holda, eng sodda va tushunarli tarzda javob berishingiz juda muhim. Bu jarayonda bola ba’zan jahli chiqishi yoki bezovtaligini namoyon qilishi mumkin, ammo siz sabr bilan tushuntirishga harakat qilsangiz, bu uning rivojiga albatta ijobiy ta’sir ko‘rsatadi. Yana bir muhim jihat — chaqalog‘ingizni uddalay olgan ishlari uchun qadrlash, uddalay olmaganlari uchun esa uni ayblamaslikdir. Chunki bunday munosabat bolada ruhiy zo‘riqish paydo qilishi mumkin. Unga nisbatan sabrli bo‘ling, chunki u bergan har bir savoli va qilgan har bir sho‘xligi orqali dunyoni yanada yaqindan anglab boradi.') WHERE id = '8617b177-02ab-46b0-bf53-616ceb20767c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalik davridagi ovqatlanish odatlari juda katta ahamiyatga ega. Chunki bolalarni kasalliklardan himoya qilish, ularning aqliy va jismoniy qobiliyatlarini rivojlantirish bevosita sog‘lom ovqatlanish bilan bog‘liq. Aslida, to‘g‘ri ovqatlanish har qanday yoshda muhim, ammo rivojlanish davridagi bolalar uchun bu hayotiy ahamiyatga ega. Yetarli va muvozanatli ovqatlanmaslik ko‘plab kasalliklarning asosiy sababidir. Zararli oziq-ovqatlarni tanlash rivojlanish buzilishlari va ayrim salomatlik muammolariga olib kelishi mumkin. 2 yoshdan keyingi davr ko‘pincha noto‘g‘ri ovqatlanish odatlari boshlanadigan bosqichdir, chunki bu vaqtda bolalar tayyor qadoqlangan mahsulotlar va ozuqaviy qiymatga ega bo‘lmagan shirinliklar bilan tanishadilar. Bu esa sog‘lom o‘sish yo‘lidagi eng katta to‘siqlardan biridir. Mutaxassislar bolalarni hech bo‘lmaganda maktab yoshigacha bunday zararli oziq-ovqatlardan uzoq tutishni tavsiya qilishadi.') WHERE id = 'b67098ba-523c-4deb-8d75-c6e4c04c833c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bir necha oydan beri o‘z mustaqilligini namoyon qila boshlaganini sezgan bo‘lsangiz kerak. Talablaringizga qarshilik bildirib, «Nega?», «Nima uchun?» deb so‘rashda davom etayotgan kichkintoyingiz ba’zan sizni qiyin vaziyatga soladigan savollarni ham berishi mumkin. Masalan, bu yoshdagi bolalar odatda o‘zlari qanday paydo bo‘lgani bilan qiziqadi. Qisqasi, farzandingiz yoningizga kelib: «Men qanday paydo bo‘lganman, dunyoga qanday kelganman?» kabi savollarni berishi mumkin. Ko‘plab ota-onalar bu savol bevosita jinsiy hayot bilan bog‘liq deb o‘ylab, javob berishdan qochadi va mavzuni boshqa tomonga buradi. Ammo bunday yondashuv bolaning qiziqishini yanada oshiradi va savollarning keti uzilmaydi. Bunday hollarda bolaga barcha tafsilotlarni aytib berish shart emas. Buning o‘rniga, u tushunadigan tilda: «Sen mening qornimda ulg‘aygansan», deb javob berish ma’qulroq.') WHERE id = '63361e0d-5fd3-4108-803f-7f7fd698945d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'D vitamini farzandingiz salomatligi uchun eng muhim moddalardan biridir. Ayniqsa, suyaklarning rivojlanishi va tishlar salomatligiga katta ta’sir ko‘rsatadigan D vitamini yetishmasa, bolalarda raxit deb ataladigan va suyaklar shaklining buzilishiga olib keladigan kasallik paydo bo‘lishi mumkin. Farzandingizdagi holsizlik, bezovtalik, tez-tez kasallanish va ishtahasizlik kabi muammolarga aynan D vitamini yetishmasligi sabab bo‘lishi ehtimoli bor. Shu sababli bolaning D vitaminini muntazam ravishda qabul qilishi foydalidir. D vitamini boshqa vitaminlardan farqli ravishda organizmga oziq-ovqat bilan birga quyosh nuri orqali ham tushadi. Tabiiy ravishda D vitaminini o‘z ichiga oladigan mahsulotlar kam bo‘lib, ular orasida baliq yetakchi o‘rinda turadi. Ayniqsa, sardina, losos va skumbriya kabi yog‘li baliqlar D vitaminiga boy. Tuxum, qo‘ziqorin, sut va pishloq kabi mahsulotlarda ham u oz miqdorda mavjud. Unutmang, faqat quyoshda bo‘lish yoki faqat oziq-ovqat iste’mol qilish D vitamini sintezi uchun yetarli bo‘lmasligi mumkin. Ikkalasini birga uyg‘unlashtirish samaraliroqdir.') WHERE id = '54b7999d-3552-4ccb-ad57-5e50a6a6a619';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingizning bo‘yi yetarlicha tez o‘smayotgani yoki rivojlanish jadvali (persentil) bo‘yicha ortda qolayotganini o‘ylasangiz, xavotirlanishingiz tabiiy. Mutaxassislarning ta’kidlashicha, bolalarda o‘sishning eng muhim ko‘rsatkichlari bo‘y va vazn ortishidir. Bo‘y suyaklar uchidagi o‘sish zonalari deb ataladigan tog‘ay to‘qimasining rivojlanishi hisobiga uzayadi. O‘smirlik davri oxirida bu zonalar yopilgach, bo‘y o‘sishi to‘xtaydi. O‘sishga ta’sir qiladigan ikkita asosiy omil mavjud: birinchisi — genetik omillar. Har bir bolaning bo‘yiga ota-onasidan o‘tgan genlar ta’sir qiladi. Ikkinchi omil esa ovqatlanishdir. Genetik bo‘y salohiyatidan imkon qadar to‘liq foydalanish uchun bola yoshiga mos miqdorda kaloriya olishi va muvozanatli ovqatlanishi juda muhim. Ayniqsa, rivojlanish tez kechadigan dastlabki ikki yildagi ovqatlanish buzilishlari, surunkali qusish, surunkali ich ketishi yoki noto‘g‘ri ovqatlantirish rivojlanishning sekinlashishiga olib keladigan asosiy omillar qatoriga kiradi.') WHERE id = 'e4cccfa5-92e6-4cfb-b6af-32b8c84e3a41';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar ko‘chaga chiqqanda farzandingizga taglik kiydirib, uyga kelgach esa uni faqat ichki kiyimda qoldirsangiz, bu uning boshini chalg‘itadi. Shuning uchun uyda ham, ko‘chada ham, agar borsa, bog‘chada ham bir xil qoidaga amal qilishingiz va bola undan nima kutilayotganini tushunishini ta’minlashingiz kerak. Hojatxonaga borish odati shakllanayotgan davrda vaqti-vaqti bilan ko‘ngilsiz holatlar yuz berishi mutlaqo tabiiy. Bunday vaziyatlarda sizning yoki bolaga qarayotgan kishining munosabati juda muhim. Aslo qattiqqo‘l va ayblovchi gaplarni ishlatmang, bolada xavotir uyg‘otishi mumkin bo‘lgan «Senga aytgan edim», «Endi katta bo‘lgansan, chaqaloqdek taggingni ho‘l qilyapsan» kabi so‘zlarni aytmang. Buning o‘rniga: «Hechqisi yo‘q, bunday holatlar bo‘lib turadi» yoki «Bugun shunday bo‘ldi, ammo ertaga yanada e’tiborli bo‘lamiz, shundaymi?» kabi ruhlantiruvchi jumlalarni tanlang. Hojatxonaga o‘rgatish jarayonida farzandingizni qo‘llab-quvvatlash juda muhim. Xato qilish tabiiy va har kim xato qilishi mumkin. Unutmang, xatolarsiz o‘rganishning iloji yo‘q.') WHERE id = '74cbe601-3405-4913-b913-ad225051c0de';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning ovqatlanishi uning sog‘lom rivojlanishi va kun davomida zarur bo‘ladigan energiyani olishi uchun juda muhim. Ko‘plab ota-onalar bu davrda bolalarning injiqlik qilishi va foydali mahsulotlarni yemasligidan shikoyat qiladi. Masalan, tuxum shunday mahsulotlardan biri bo‘lishi mumkin. Ba’zan taomni boshqacha ko‘rinishda tortish yoki yangi ziravor qo‘shish farzandingizning tuxum yeyishiga yordam beradi. Buning uchun sizga ajoyib retseptimiz bor! :) Retseptimizning nomi: Tuxumli kartoshka. Kerakli masalliqlar: 1 dona kartoshka, ta’bga ko‘ra oq pishloq, 1 dona tuxum, 2-3 choy qoshiq butun donli bug‘doy uni, biroz petrushka, bir chimdim tuz, yalpiz, tog‘rayhon va qovurish uchun 2 osh qoshiq zaytun moyi. Tayyorlanishi juda oson: Kartoshkani qirg‘ichdan o‘tkazing, ustiga tuxum, un, petrushka, pishloq va ziravorlarni qo‘shing. Yaxshilab aralashtirgach, aralashmadan qoshiqda olib, zaytun moyida har ikki tomonini qovuring. Yoqimli ishtaha! 😊') WHERE id = 'a528e9be-0130-4c5b-8b4a-8c91b4559506';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Genetik omillar va ovqatlanishdan keyin farzandingizning o‘sishiga ta’sir qiladigan eng muhim omil gormonlardir. Inson organizmidagi bezlar o‘sish, rivojlanish va boshqa hayotiy faoliyatlarni boshqaradigan gormonlarni ishlab chiqaradi. Ularning eng asosiysi miyadagi gipofiz bezi tomonidan ishlab chiqariladigan o‘sish gormoni (Growth hormone) hisoblanadi. O‘sish gormoni va organizmda ishlab chiqariladigan ayrim omillar suyak uchlaridagi tog‘ay hujayralarining bo‘linishini ta’minlab, bo‘y o‘sishiga yordam beradi. Shuningdek, qalqonsimon bez gormonlari ham moddalar almashinuvini tartibga solib, o‘sishni qo‘llab-quvvatlaydi. Qizlarda estrogen, o‘g‘il bolalarda esa testosteron gormoni bo‘y o‘sishi va rivojlanishda muhim rol o‘ynaydi. Bu gormonlarning yetishmasligi o‘sishning sekinlashishi yoki bo‘y pastligiga olib kelishi mumkin. Agar bu borada shubhangiz bo‘lsa, albatta shifokoringiz bilan maslahatlashing.') WHERE id = '9f60c03d-388c-4852-aae7-a31ffa00fa8f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '27 oylik chaqalog‘ingiz rivojlanish jarayonida o‘z shaxsiyatini faol ravishda anglashga urinayotganini aytish mumkin. Bu davrda uning yonida xatti-harakatlaringiz va so‘zlaringizga e’tibor berishingiz juda muhim. Ko‘plab ota-onalar uchun yoqimsiz holat bo‘lsa-da, bolalar bu davrda eshitgan har bir so‘zini ishlata boshlashi mumkin. Shu sababli, chaqalog‘ingiz bo‘lgan muhitda yoqimsiz yoki odobsiz iboralarni ishlatadigan odamlarni ogohlantirish maqsadga muvofiq. Shuningdek, siz ham chaqalog‘ingiz yonida bahslashmaslikka, yomon so‘zlarni ishlatmaslikka va ovoz ohangingizni nazorat qilishga e’tibor berishingiz kerak. Chunki chaqalog‘ingiz sizdan ko‘rgan deyarli barcha narsani takrorlay boshlaydi. Shuning uchun unga yaxshi namuna bo‘lishga harakat qiling. Bu davrda farzandingizning harakat ko‘nikmalarini rivojlantirishga yordam berish bilan birga, unga o‘ziga g‘amxo‘rlik qilish odatlarini ham o‘rgatishingiz kerak. Masalan, chaqalog‘ingiz endi sizning yordamingizsiz tishlarini tozalashi va qo‘llarini yuvishi kerak.') WHERE id = '5abe92b5-f52e-400b-a5f6-cabd63afd859';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ftor chaqalog‘ingiz salomatligi uchun juda muhim minerallardan biridir. Shunga qaramay, uning miqdoriga e’tibor berish lozim. Ftor, ayniqsa, tishlarda kariyes paydo bo‘lishining oldini oladi va bu mineral organizmga ichimlik suvi orqali kirishi mumkin. Agar ichayotgan suvingiz tarkibidagi ftor miqdori yetarli bo‘lsa, qo‘shimcha qabul qilishga ehtiyoj yo‘q. Ammo ftor miqdori kam bo‘lsa va chaqalog‘ingizda kariyes xavfi mavjud bo‘lsa, shifokoringizning roziligi bilan ftor qo‘shimchasidan foydalanishingiz mumkin. Mamlakatimizning ayrim hududlarida suv ftor moddasiga juda boy.  Ftorning ortiqcha miqdori tishlarda dog‘lar, ya’ni flyuoroz kabi muammolarga olib kelishi mumkin. Ftor tish pastalari tarkibida ham bo‘ladi. Biroq bunday mahsulotlarga sun’iy ftor qo‘shilgani sababli, ulardan foydalanishda juda ehtiyot bo‘lish kerak. Shu sababli, chaqalog‘ingiz tish pastasidan foydalana boshlagan dastlabki davrda qo‘shimcha ftor qabul qilishiga ehtiyoj yo‘q.') WHERE id = '6748d69e-868b-4bd5-8a5b-784f97c40a36';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu davrda kamida 50 dan ortiq so‘zni anglab ayta olishi mumkin. Bu so‘zlardan foydalanib gaplar ham tuzishi mumkin, ammo undan hozircha juda murakkab va mazmunli gaplarni kutmasligingiz kerak. U «to‘pni ot», «ona kel», «dada qara», «qo‘g‘irchoqni ber», «oshxonaga boraylik» kabi gaplar bilan istagini ifodalashi mumkin. Bundan tashqari, ayrim bolalar bu davrda o‘zlari haqida uchinchi shaxsda gapirishlari mumkin. Boshqalar unga ismi bilan murojaat qilgani uchun, u ham o‘zi haqida gapirganda «men» deyish o‘rniga o‘z ismini aytishi mumkin. Mushuk, it va qush kabi hayvonlarning ovozini eshitganda, agar siz uni bu hayvonlar bilan avval tanishtirgan bo‘lsangiz, ovoz qaysi hayvonga tegishli ekanini tushunishi mumkin. Chaqalog‘ingiz bu moslashtirishlarni barchasini bexato bajarishini kutmasligingiz va uning rivojlanishiga yordam berishda davom etishingiz kerak. Hayvonlarning ovozlariga oid dasturlar yoki hayvonlar tasvirlangan kartochkalar bilan o‘ynaladigan o‘yinlar bu maqsadda juda foydali bo‘ladi.') WHERE id = '0b2efb81-ea8f-4a69-a8e4-bfa0406f23c0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizni ovqatlantirish masalasida ancha qiynalayotganingizni bilamiz. Xavotir olmang, chunki siz bilan bir xil hislarni boshdan kechirayotgan son-sanoqsiz onalar bor! :) Bu jarayonda chaqalog‘ingiz yoqtiradigan va yoqtirmaydigan taomlar borligini hamda ularni yeyishga majburlamaslik kerakligini unutmang. Kutgan natijalaringiz haqiqatga mos bo‘lishi hamda o‘zingizni va chaqalog‘ingizni qiynamasligingiz sizga ancha yengillik beradi. Ota-onalar chorasiz qolganda eng ko‘p murojaat qiladigan vositalar telefon va televizordir. Biroq bu qurilmalar yordamida bolaning e’tiborini chalg‘itib, unga biror narsa yedirish o‘rganish va idrok etish qobiliyatining rivojlanishiga salbiy ta’sir ko‘rsatadi. Eng to‘g‘ri yo‘l — chaqalog‘ingizni shu yoshdan boshlab dasturxon atrofida, ovqatlanish stolida o‘tirishga odatlantirishdir. Bu yoshda shakllangan odat kelajakda uning tezroq moslashishiga va muntazam ovqatlanish odati paydo bo‘lishiga yordam beradi.') WHERE id = '28fd7c5d-9fca-4359-bc66-b636a21a6247';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tadqiqotlarga ko‘ra, odatda qiz bolalar 23 oyligida, o‘g‘il bolalar esa taxminan 25 oyligida hojatxonadan foydalanishni o‘rganishga qiziqish bildira boshlashi aniqlangan. Qiziqish bilan bir qatorda, bolalarning fiziologik jihatdan ham tayyor bo‘lishi muhim. Qiz bolalar odatda 33 oyligida, o‘g‘il bolalar esa 37 oyligida hojatxonadan foydalanish odatini to‘liq o‘zlashtirgan bo‘lishi mumkin. Bolalar bu yoshgacha ushbu odatni o‘zlashtirishi kutiladi, ammo har bir bolaning rivojlanish sur’ati turlicha ekanini unutmasligingiz kerak. Hozirgi 27-oyda chaqalog‘ingiz hojatxonadan foydalanishni to‘liq o‘rgangan yoki hali o‘rganish bosqichida bo‘lishi mumkin. Jarayonni to‘liq yakunlagan bo‘lsangiz ham, yana bir muddat kichik "ko‘ngilsiz holatlar" yuz berishi mumkin. Mutlaqo tabiiy bo‘lgan bunday vaziyatda keskin munosabat bildirmaslik va unga tushunish bilan yondashish eng to‘g‘ri yo‘ldir.') WHERE id = 'a2e641a4-c0c5-4079-b4c0-664fe147cd24';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Donli mahsulotlar tolaga boy tuzilishi tufayli farzandingizning hazm qilishini yengillashtiradi va qorin og‘rig‘i kabi shikoyatlarning oldini oladi. Donli mahsulotlar, shuningdek, B guruhi vitaminlariga boy oziq-ovqat guruhidir. B vitaminlari asab tizimining rivojlanishida muhim rol o‘ynaydi, shuningdek, organizmda energiya hosil bo‘lishiga ta’sir qiladi. Bundan tashqari, donli mahsulotlar suyaklar va mushaklar uchun foydali bo‘lgan temir, selen va magniy kabi minerallarga boy. Farzandingiz donli mahsulotlardan to‘liq foyda olishini istasangiz, masalan, makaron pishirilgan suvni to‘kib yubormasligingiz kerak. Chunki uning tarkibidagi oziq moddalar pishirish vaqtida suvga o‘tadi. Shu sababli, farzandingizga makaron tayyorlayotganda uni oz miqdordagi suvda, suvini shimdirib pishirganingiz ma’qul. Guruchni esa pishirishdan oldin suvda juda uzoq saqlash yoki yog‘da uzoq vaqt qovurish uning oziqaviy qiymatini kamaytiradi. Bulochka kabi xamirli mahsulotlarni tayyorlayotganda, agar farzandingiz ham undan yeydigan bo‘lsa, qabartma kukuni o‘rniga xamirturushdan foydalanishni afzal ko‘ring.') WHERE id = 'e7b4691f-ceeb-4bdc-b7b7-f707d0e7fa17';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingiz ayrim shaxsiy ehtiyojlarini mustaqil ravishda bajara oladigan darajaga yetadi. Oyoq kiyimi va paypog‘ini yordamsiz yecha olishi buning eng yaqqol belgisidir. Bu ishlarni mustaqil bajarishi uning o‘ziga bo‘lgan ishonchini oshiradi. Shu bilan birga, tishlarini tozalash va qo‘llarini yuvish kabi shaxsiy gigiyena ko‘nikmalari ham rivojlanadi. Uni bu borada rag‘batlantirishingiz ozodalikka tezroq odatlanishiga yordam beradi. Kichik yoshda shakllangan bu odatlar kelajakda jamiyat tomonidan maqbul deb hisoblangan xulq-atvorni osonroq o‘zlashtirishiga xizmat qiladi. Aslida, kelajakdagi fe’l-atvorning poydevori aynan shu bosqichda qo‘yiladi. Shuning uchun bu davrda unga yaxshi va yomon xulq-atvorni to‘g‘ri tushuntirishga alohida e’tibor qaratishingiz kerak.') WHERE id = '1cf45b6a-65d5-41da-a06e-3f002349179b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz ayrim kunlari siz kutganingizdan ko‘proq ovqat yeyishi mumkin. Uni to‘yib bo‘ldi, deb o‘ylab, ovqatdan mahrum qilmang. Serharakat va o‘sib-rivojlanayotgan bolalar ba’zi kunlari kattalardek ko‘p ovqat iste’mol qilishi mumkin, ammo shunga qaramay, odatda ortiqcha vazn yig‘maydi. Biroq zararli mahsulotlar vazn ortishi va holsizlikka sabab bo‘lishi mumkin. Chaqalog‘ingizning rivojlanishi uchun asosiy ovqatlar kabi tamaddilar ham muhimdir. Ba’zi onalar bolaning ishtahasi pasayib qolmasin deb, ovqatlar orasida meva berishdan tiyiladilar. Ammo asosiy ovqatlanishlar orasidagi vaqt uzoq bo‘lgani uchun bolalar och qolishi va energiyaga ehtiyoj sezishi mumkin. Tamaddilar bu ehtiyojni qondirish bilan birga, bolaning keyingi ovqatlanish paytida haddan tashqari och qolib, oshqozoniga zo‘riqish tushishining oldini oladi. Bu chaqalog‘ingizning ovqat hazm qilish tizimi uchun juda foydalidir.') WHERE id = '576b4ad4-9092-4186-be86-eba5187c22f3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning o‘z fikrini ifoda etish qobiliyati avvalgiga qaraganda ancha rivojlangan. Ammo bu uning nutq qobiliyati to‘liq shakllanganini anglatmaydi. Bu davrda bolalar o‘zlarini hamma narsaning markazida deb bilishadi. «Egotsentrik» (men-markazli) deb ataladigan bu bosqichda bolalar hali boshqalarning ehtiyojlariga e’tibor bermaydilar. Farzandingiz istak va his-tuyg‘ularini yetkazish uchun turli yo‘llardan foydalanishi mumkin. Ba’zan bu usullar, masalan, birovni urish yoki tishlash kabi nomaqbul xatti-harakatlar bo‘lishi mumkin. Bunday vaziyatlarda xotirjamlikni saqlab, uni ayblamasdan, bu xatti-harakat nima uchun noto‘g‘ri ekanini u tushunadigan tilda izohlashingiz kerak.') WHERE id = '1916c84e-aa52-46dc-a413-ae73bae1219c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingiz ovqatlanish paytida dasturxon atrofida ovqatdan boshqa hamma narsaga qiziqayotganini sezishingiz mumkin. Buning uchun uni ayblamasligingiz, ayrim nozik jihatlarga e’tibor berib, ovqatlanish vaqtining azobga aylanishiga yo‘l qo‘ymasligingiz kerak. Avvalo, ovqatlanish juda uzoq davom etmasligiga e’tibor bering. Chunki bolalar tez zerikadi va uzoq davom etadigan ovqatlanishni umuman yoqtirmaydi. Shu bilan birga, farzandingiz har bir taomni yoqtiravermasligi mumkin. Masalan, unga selderey yedirish uchun bosim o‘tkazmasligingiz kerak. Ammo bu holat uning nosog‘lom oziq-ovqatlarni tanlashiga ham olib kelmasligi lozim. Buning uchun uyda foydali yeguliklar tayyorlab qo‘ying, aks holda u tashqarida ko‘rgan narsalarini so‘rashi mumkin. Oilaning barcha a’zolari birgalikda ovqatlanishini ta’minlash orqali farzandingizning chalg‘ishiga yo‘l qo‘ymasligingiz mumkin. Boshqalarning ham ovqatlanayotganini ko‘rish bu jarayonni uning uchun ham osonlashtiradi.') WHERE id = '4f28c186-22d8-43cc-bc2e-3b3c3bfa0f2b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Hojatxonadan mustaqil foydalanishni to‘liq o‘rganish chaqalog‘ingiz uchun juda katta qadam va murakkab vazifadir. Agar siz hali ham ushbu jarayonda bo‘lsangiz, e’tibor berishingiz kerak bo‘lgan jihatlar bor. Masalan, bog‘chaga borishni boshlash, emizishdan chiqarish yoki ko‘chib o‘tish kabi katta o‘zgarishlar arafasida hojatxonaga o‘rgatishni boshlash ma’qul emas. Buning uchun chaqalog‘ingiz ham tayyor bo‘lishi, davr ham mos kelishi kerak. Shu bilan birga, bunga siz ham chaqalog‘ingiz kabi tayyor bo‘lishingiz lozim. Chunki ayrim bolalar uchun bu ko‘nikmani egallash qiyinroq kechishi mumkin. Bu davrda izchil va sabrli bo‘lishingiz muhim. Farzandingizni ayblamaslik, jarayonni tabiiy qabul qilish va unga mehringizni ko‘proq namoyon etish vazifangizni ancha yengillashtiradi.') WHERE id = '2add9cbb-bed9-4a33-8609-e9090d87a0b2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bilan yana bir oyni ortda qoldirdingiz. 28-oyga xush kelibsiz! :) Bolajoningizning shaxsiyati endi to‘liq shakllana boshlaydi. Ammo uning fe’l-atvori siznikidan farq qilishi mumkinligini unutmang. U o‘zining tabiiy xususiyatlarini namoyon qilar ekan, uni qoralash emas, qanday bo‘lsa, shundayligicha qabul qilish kerak. Qisqasi, uni albatta siz istagandek inson bo‘lishga majburlamang. Dunyoni o‘ziga xos tarzda idrok etishini qo‘llab-quvvatlash uning sog‘lom shaxs bo‘lib ulg‘ayishiga yordam beradi. Bu davrda chaqalog‘ingiz o‘z tanasini, ayniqsa jinsiy a’zolarini o‘rganishi va ularga qiziqa boshlashi mumkin. Bu aslo unga jahlingiz chiqishi kerak bo‘lgan holat emas. Zarurat tug‘ilsa, mutaxassis bilan maslahatlashib, bu mavzuda chaqalog‘ingizga qanday munosabatda bo‘lish kerakligini bilib olishingiz mumkin.') WHERE id = '6e1b9324-94a1-40b9-be8a-0189cd97ec29';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu oylarda chaqalog‘ingizda egotsentrik, ya’ni hamma narsani o‘z nuqtayi nazaridan qabul qilishga moyillik hali ham yuqori darajada saqlanib qoladi. Shu sababli u ba’zan xudbinlarcha xatti-harakat qilishi mumkin. Ammo bu holat vaqtinchalik ekanini va vaqt o‘tishi bilan yo‘qolib ketishini unutmang. Bunday xatti-harakatlarning sababi — chaqaloqning mantiqiy tafakkuri hali yetarlicha rivojlanmagani, boshqalar haqidagi tushunchani to‘liq anglamagani, bo‘lishish hissi shakllanmagani va mavhum ma’nolarni tushuna olmasligidir. Shu bilan birga, u voqealarni tasniflash, tartiblash yoki guruhlash qobiliyatini ham hali to‘liq egallamagan. Bularning natijasida chaqalog‘ingiz ko‘pincha boshqa insonlarning, jumladan sizning ham fikr va qarashlaringizni hisobga olmaydi. Chunki u hali bunday idrokiy yetuklik darajasiga erishmagan. Shuning uchun xavotirlanishingizga asos yo‘q. Ammo bu holat sizni juda tashvishga solayotgan bo‘lsa, mutaxassis bilan maslahatlashish foydali bo‘lishi mumkin.') WHERE id = 'e03558fa-2b62-46f8-8b8d-62974309090d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Sut oqsilning ajoyib manbai bo‘lsa-da, ayrim bolalar uni ichishni istamasligi mumkin. Agar chaqalog‘ingiz ham sutni yoqtirmasa, bunday holat faqat sizda emasligini bilib qo‘ying. :) Biroq chaqalog‘ingizni ushbu muhim oziq-ovqatdan mahrum qilmaslik uchun sutni boshqa taomlarga qo‘shib, kichik hiylalardan foydalanishingiz mumkin. Masalan, chaqalog‘ingiz tuxumli nonni yoqtirsa, to‘yimli nonushta tayyorlash uchun tuxum bilan sutni birga ko‘pirtiring. Butun donli nonni ushbu aralashmaga botirib, ozroq sariyog‘da qovuring. Agar chaqalog‘ingiz ichimliklarni yaxshi ko‘rsa, mazali smuzi (smoothie) tayyorlashingiz mumkin. Buning uchun sut bilan bananni blenderdan o‘tkazing, istakka ko‘ra uyda bor boshqa mevalarni ham qo‘shing. Shuningdek, uy sharoitida tayyorlangan puding deyarli barcha bolalar rad eta olmaydigan mazali taomdir! Bundan tashqari, bu sutni yoqtirishga o‘rgatishning eng yaxshi usullaridan biridir. :) Shakarsiz kakao kukunini sut bilan pishirib, ta’m berish orqali turli mazalar yaratishingiz mumkin.') WHERE id = 'd764e4e1-1fd6-421c-bf7e-324e9264d8bd';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu oy chaqalog‘ingiz sinab ko‘rish va xato qilish orqali faol o‘rgana boshlaydigan davrdir. U endi Nega? va Nima uchun? savollarini yanada ongli va maqsadli tarzda bera boshlaydi. Masalan, kichik buyumlarning o‘ramini ochishga urinib, ular nima uchun kerakligini sizdan so‘rashi mumkin. Bu davrda chaqalog‘ingiz yangi ko‘nikmalarni ham egallaydi: balandroq minoralar qurish shulardan biridir. Sizga taqlid qilib, qog‘ozni osongina ikkiga buklashi, fermuarini yopishi yoki kiyimlarini mustaqil kiyishga urinishi mumkin. Jadal rivojlanish davom etayotgan ushbu oylarda chaqalog‘ingiz bilan uyda yoki tashqarida turli mashg‘ulotlar o‘tkazib, vaqtingizni maroqli o‘tkazishingiz mumkin. Masalan, birgalikda bir oyoqda turish o‘yinini o‘ynash ham qiziqarli bo‘ladi, ham uning jismoniy rivojlanishiga yordam beradi! :)') WHERE id = '1c1e64d8-d06f-466f-9b34-33f9ed75a828';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Baliq chaqaloq ovqatlanishidagi eng muhim oqsil manbalaridan biri bo‘lishi mumkin. Yangi baliq topish, uni pishirish va suyaklarini tozalash qiyin bo‘lgani uchun ko‘plab ota-onalar konservalarni afzal ko‘rishadi. Biroq konservalangan baliqlarga nisbatan ehtiyotkor bo‘lishingiz kerak. Konservalangan tunets turli baliq turlaridan tayyorlanadi va ayrim turlarida hatto kichik dozalarda ham zaharli ta’sir ko‘rsatishi mumkin bo‘lgan simob mavjud bo‘lishi mumkin. Oq tunetsdagi simob miqdori light tunetsga qaraganda yuqoriroq. Kattalar uchun oq tunets miqdori haftasiga ko‘pi bilan 170 gramm bilan cheklansa-da, bu miqdor chaqaloq uchun xavfli bo‘lishi mumkin. Chunki bu yoshdagi bolaga oyiga jami 85 gramm baliq yetarli. Shu sababli, ko‘proq mehnat talab qilsa ham, konserva o‘rniga yangi dengiz mahsulotlarini tanlashingiz chaqaloq salomatligi uchun ancha foydaliroqdir.') WHERE id = '42d066ad-b938-4b87-8fff-39d96cc2a17e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz endi mustaqilligining eng yuqori bosqichida. Bu uning ayrim sabzavotlarni iste’mol qilishdan bosh tortishiga sabab bo‘lishi mumkin. Ba’zi ota-onalarning aytishicha, bolalar yashil rangdagi barcha narsani sabzavot deb o‘ylab, uning ta’mi yoqimsiz bo‘ladi, deb hisoblashadi. Agar siz ham shunday holatga duch kelsangiz, bir muddat uni bu fikrdan chalg‘itishga harakat qiling. Buning uchun rang-barang sabzavotlardan foydalanishingiz mumkin! Masalan; qizil va sariq bulg‘or qalampiri, sabzi, pomidor, lavlagi, qovoq kabi rangli sabzavotlardan tayyorlangan taomlar farzandingizda ko‘proq qiziqish uyg‘otadi. Bu sabzavotlar A va C vitaminlariga ham boy. Shuningdek, u yoqtiradigan mahsulotlarni yoqtirmaydiganlari bilan birga berishingiz mumkin. Masalan; farzandingiz go‘shtli dumaloq kotletlarni yoqtirsa, yoniga bir necha bo‘lak gulkaram yoki brokkoli qo‘yishingiz mumkin. Tovuq bo‘laklarini yashil no‘xat bilan aralashtirib, taom bezagining bir qismi sifatida taqdim eting.') WHERE id = 'e19f528f-be1a-4590-a1ad-08cb799868f7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz eng faol bo‘ladigan bu oylarda u bilan qanday mashg‘ulotlar o‘tkazish foydaliroq ekanini o‘ylashingiz mumkin. Aslida uyda ham, tashqarida ham tanlovlar juda ko‘p. Mushaklarni rivojlantirish va sport bilan shug‘ullanish odatini shakllantirish uchun bolalar sport markazlari yaxshi tanlovdir. Shuningdek, hissiy va harakat ko‘nikmalarini rivojlantiradigan o‘yin guruhlari hamda ijodiy mashg‘ulotlar ham foydali bo‘ladi. Uy ishlarini birgalikda bajarish esa ham birga vaqt o‘tkazish, ham unga tartib-intizomni o‘rgatish uchun juda mos. Masalan; siz polni artayotganingizda, farzandingiz ham o‘yinchoq tozalash to‘plami bilan sizga qo‘shilishi mumkin. Kir kiyimlarni kir yuvish mashinasiga solayotganda undan yordam so‘rashingiz mumkin. Qisqasi, kundalik hayotda bajaradigan har bir ishingizga farzandingizni ham jalb qilishingiz mumkin.') WHERE id = 'c3a4f4bb-ac8b-4cd2-b729-634f2ef8e015';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalarda eng ko‘p uchraydigan shikoyatlardan biri ich ketishidir. Agar farzandingizda vaqti-vaqti bilan ich ketishi kuzatilsa, ovqatlantirish bo‘yicha ayrim ma’lumotlarni bilishingiz kerak bo‘ladi. Shuni bilingki, qabziyatdan farqli ravishda, ich ketganda kletchatkasiz oziq-ovqatlar berish lozim. Ich ketganda eng foydali mahsulotlardan biri qatiqdir, chunki u kuchli probiotik hisoblanadi. Ich ketishi paytida organizm yo‘qotadigan eng muhim minerallardan biri ruxdir. Ruxga boy bug‘doy murtagi bu davrda berish mumkin bo‘lgan eng yaxshi mahsulotlardan biridir. Shuningdek, taomlarga oz-ozdan qo‘shilgan sumaq ham ich ketishiga ijobiy ta’sir ko‘rsatadi. Agar farzandingiz holsizlik tufayli ovqat yeyishni istamasa, unga banan va shaftoli berishingiz mumkin. Shaftoli kattalarda ichni yumshatuvchi ta’sir ko‘rsatsa-da, bolalarda ich ketishining oldini olish xususiyatiga ega.') WHERE id = 'a3da791d-47b3-44f0-b6db-2186758922d6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning bu oylarda birga o‘ynaydigan va ovqatlanadigan xayoliy do‘sti paydo bo‘lishi mumkin. Ko‘plab ota-onalar farzandida bunday xatti-harakatlarni ko‘rganda xavotirlanib, aralashishga harakat qilishadi. Aslida xavotirlanishga hech qanday asos yo‘q. Chunki maktabgacha bo‘lgan davrda xayol bilan haqiqat hali bir-biridan keskin ajratilmaydi. Bu yoshdagi bolalar jonsiz narsalarni jonli deb qabul qilishlari mumkin. Ba’zan chaqalog‘ingizga uning eng sevimli ayiqchasi yoki qo‘g‘irchog‘i ham hamroh bo‘lishi mumkin. Ayrim hollarda esa atrofda hech kim yoki hech qanday buyum bo‘lmasa ham, chaqalog‘ingiz kim bilandir gaplashayotganini ko‘rishingiz mumkin... Bunday do‘stliklarning barchasi chaqalog‘ingiz rivojlanishining me’yoriy jarayoni hisoblanadi. Biroq bu holat juda uzoq davom etsa va sizni jiddiy tashvishga sola boshlasa, shifokoringiz bilan maslahatlashishingiz mumkin.') WHERE id = '43ebcc3b-a67c-42aa-91cf-6698742da655';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Yoz-u qish chaqalog‘ingiz doimo xohlashi mumkin bo‘lgan mahsulotlardan biri muzqaymoqdir. Muzqaymoqni to‘g‘ridan-to‘g‘ri fastfud yoki foydasiz oziq-ovqatlar qatoriga kiritish biroz adolatsizlik bo‘ladi. Chunki muzqaymoq tarkibida B12, B6, D, C va E vitaminlari mavjud. Shuningdek, u yog‘, oqsil va uglevodlarga ham boy. Muzqaymoq ajoyib energiya manbai hisoblanadi va me’yorida iste’mol qilinganda ortiqcha vaznga sabab bo‘lmaydi. Biroq ayrim muzqaymoqlar tarkibida sun’iy ta’m beruvchilar bo‘lishi mumkin. Shu sababli, agar vaqtingiz bo‘lsa, farzandingiz uchun uyda foydali muzqaymoq tayyorlashingiz mumkin. Kerakli mahsulotlar: 100 gramm shokolad, 100 ml sut va 1 paket quyuq qaymoq. Tayyorlash juda oson: shokoladni suv hammomi usulida eriting, ustiga sut qo‘shib, yaxshilab aralashtiring. Qaymoqni alohida idishda mikser yordamida ko‘pik hosil bo‘lguncha ko‘pirtiring. So‘ng barcha masalliqlarni aralashtirib, muzlatkichda 2 soat saqlang. Muzqaymog‘ingiz tayyor! :)') WHERE id = 'd4f84a64-6da8-4928-8a62-9c2d85080c7a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz endi yoshini ko‘rsatish uchun barmoqlaridan foydalana boshlashi mumkin. Uning nutqi ham jadal rivojlanishda davom etadi. Masalan, tana a’zolarining nomlarini ayta oladi, 1-2 ta rangni taniydi va so‘ralganda qiz yoki o‘g‘il ekanini bemalol ayta oladi. Shu paytgacha so‘zlarni faqat birlik shaklida ishlatgan kichkintoyingiz endi ko‘plik qo‘shimchalaridan ham foydalanishi mumkin. Ya’ni endi bir nechta kitobni ko‘rganda shunchaki kitob emas, kitoblar deb ayta oladi. Bundan tashqari, o‘tgan zamon qo‘shimchalarini ham to‘g‘ri ishlata boshlaydi (masalan, ketdi, keldi). Bu nima?, U nima? kabi savollarni hali ham tez-tez berishda davom etadi. Har safar uning savollariga sabr bilan va u tushunadigan tilda javob berishingiz juda muhim. Savollardan qochish to‘g‘ri emas, chunki chaqalog‘ingiz aynan savollar berish orqali dunyo va hayotni anglaydi.') WHERE id = '623efdbe-b7f0-42be-97e8-fdfbef54b271';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqning mayda va yirik motorika ko‘nikmalari bu bosqichda ancha rivojlangan. Endi u bemalol yuguradi, istagan paytda to‘xtaydi va to‘siqlardan osonlik bilan o‘tadi. Yerdan biror buyumni olish uchun bemalol cho‘kkalaydi va qo‘llari bilan tayanmasdan o‘rnidan tura oladi. Mebel ustiga chiqishi va ko‘pincha yordamsiz pastga tushishi mumkin. Hatto uning oyoq uchida turganini ham ko‘rishingiz mumkin. Panjaradan ushlab, zinadan mustaqil ravishda tushib-chiqa oladi, ammo muvozanatini saqlash uchun hali ham har bir pog‘onaga ikkala oyog‘ini qo‘yadi. Bu oylarda bolalar oldidagi to‘pni tepishga urinsalar-da, ko‘pincha mo‘ljalga tekkiza olmaydilar. Chaqaloqning qalamni butun kafti bilan ushlashi va qoralamalar chizishi mutlaqo normal. U kitob sahifalarini varaqlashni ham juda yaxshi ko‘radi. Bu endi chaqalog‘ingiz uchun rasm chizish vaqti kelganini anglatadi! Shunga qaramay, devorlarga chizmasligi uchun uni nazorat qilib turganingiz ma’qul! :)') WHERE id = 'b039724d-e5f7-45e9-8fc4-95a761a5df3b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz ham jismoniy, ham aqliy jihatdan katta yutuqlarga erishdi. Biroq bu davrda unga tunda hali ham 11-12 soat uyqu kerak. Shu sababli, kechki uyqu vaqtini chaqaloqning ertalab uyg‘onish vaqtiga qarab belgilashingiz lozim. Masalan, chaqalog‘ingiz ertalab soat 07:00 da uyg‘onsa, 11 soatlik uyqu ehtiyojini qondirish uchun uni soat 20:00 lar atrofida yotqizishingiz kerak. Sog‘lom uyqu tartibi shakllanishi uchun u kechki soat 21:00 dan kechikmay uxlashiga e’tibor bering. Agar chaqalog‘ingiz kunduzgi uyqudan allaqachon voz kechgan bo‘lsa, uyqu vaqtini biroz oldinga surish orqali uning haddan tashqari charchagan holda uxlab qolishining oldini olishingiz va tunda uyg‘onishlarini kamaytirishingiz mumkin. Uyqu oldi odatlari orqali chaqalog‘ingizga uxlash vaqti kelganini his qildira olasiz. Tish yuvish, kitob o‘qish, kun davomida eng ko‘p yoqqan voqeani aytib berish, chiroqlarni o‘chirish va xayrli tun bo‘sasini berish bu yosh davriga mos mashg‘ulotlardir.') WHERE id = 'aa2b7696-4c81-4ab5-b66f-36eb3f265c8f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Persentil jadvaliga ko‘ra, 28 oylik o‘g‘il bolalarning vazni o‘rtacha 13.200 gramm, qiz bolalarning vazni esa 12.700 grammni tashkil etadi. Chaqaloqning vazni bu ko‘rsatkichlardan biroz past yoki yuqori bo‘lishi mumkin. Chunki har bir bolaning sog‘lom tana o‘lchamlari ko‘plab turli omillarga bog‘liq holda o‘zgaradi. Bu omillarning eng asosiylari chaqaloqning genetikasi va o‘ziga xos gormonal muvozanatidir. Bundan tashqari, ovqatlanish tartibi, kun davomida qanchalik faol bo‘lishi va yashash muhiti ham vaznga bevosita ta’sir qiladi. Chaqaloqning rivojlanish ko‘rsatkichlari bir-biri bilan bog‘liqligini unutmaslik kerak. Masalan, bo‘yi o‘rtachadan balandroq bolaning sog‘lom vazni ham o‘rtachadan yuqori bo‘ladi. Shu sababli, eng aniq bahoni chaqaloqni muntazam kuzatib boradigan shifokoringiz beradi.') WHERE id = '5a3ba4d7-afcf-4bb0-aad2-6d8e229cd0e1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Nutq bilan bog‘liq muammolar bu davrda ota-onalarni eng ko‘p tashvishga soladigan masalalardan biridir. Ko‘pincha bolalarda til rivojlanishi va nutqning kechikishi bir xil tushuncha deb qabul qilinadi, ammo ular boshqa-boshqa holatlardir. Agar chaqalog‘ingiz aytilganlarni tushunishda va o‘z fikrini ifodalashda qiynalsa, bu til rivojlanishining buzilishi bo‘lishi mumkin. Bunday holatda chaqaloq tengdoshlariga nisbatan qisqaroq gaplar tuzadi, qo‘shimchalarni noto‘g‘ri yoki to‘liq ishlatmaydi, so‘z boyligi esa cheklangan bo‘ladi. Agar chaqalog‘ingiz tovushlarni to‘g‘ri va ravon talaffuz qila olmasa, bu nutq buzilishidir. Nutq buzilishi tovushlarni talaffuz qila olmaslik (artikulyatsiya buzilishi), duduqlanish yoki til rivojlanishining kechikishi ko‘rinishida namoyon bo‘lishi mumkin. Biroq bu tashxisni faqat shifokor qo‘yishi mumkin. Ayniqsa, chaqaloq so‘zlar va qo‘shimchalarni endigina o‘rganayotganini inobatga olib, vaziyatga yanada xolis yondashishingiz muhim.') WHERE id = 'adac34a3-0b40-4281-8ff2-1c451c990897';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqning sog‘lom o‘sishi va rivojlanishi uchun sog‘lom va muvozanatli ovqatlanish juda muhim. Bu jarayonda oqsillarning (proteinlarning) o‘rni katta. Tananing asosiy qurilish materiali bo‘lgan oqsillar mushak va hujayralarning tiklanishi uchun zarur. Ona suti 1 yoshgacha bu ehtiyojni qondiradi. 1 yoshdan keyin esa kunlik iste’mol qilinadigan oqsilning 20% hayvon, 80% esa o‘simlik manbalaridan olinishi kerak. Bu davrda chaqaloq tana vaznining har bir kilogrammi uchun kuniga 2 gramm oqsil olishi yetarli. Bu o‘rtacha hisobda kuniga 16 gramm oqsil degani. Masalan, 2 kosa qatiq yoki bir likopcha pishloqli makaron chaqaloqning kunlik oqsil ehtiyojini to‘liq qondirishi mumkin. Sut, tuxum, go‘sht, tovuq go‘shti va baliq kabi mahsulotlar to‘liq oqsil manbalari bo‘lib, tana uchun zarur barcha aminokislotalarni o‘z ichiga oladi. Bundan tashqari, oqsilga bo‘lgan ehtiyojni to‘liq qondirish uchun donli mahsulotlar, dukkaklilar va sabzavotlarni birga berish foydali.') WHERE id = '5d36b2bf-f065-4e27-b7dc-33f78f228aae';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz hojatxonaga o‘rgatish borasida hali yetarlicha natijaga erishmagan deb o‘ylasangiz, ayrim muhim jihatlarni bilish foydali bo‘ladi. Chaqaloqni hali to‘liq yetuk inson sifatida ko‘rmasangiz-da, uning idroki kattalarniki kabi ancha rivojlangan. Shu sababli, hojatxonaga o‘rgatish jarayonida yuz ifodangizdagi ayblash yoki bezovtalikni osongina anglaydi va o‘z munosabatini shunga qarab o‘zgartiradi. Chaqalog‘ingizga hojatga borgisi kelganida bu haqda aytishi kerakligini muntazam eslatib turishingiz lozim. Biroq buni qilayotganda har doimgidan ham sabrli va mehribon bo‘lishga harakat qiling. Shu bilan birga, chaqalog‘ingiz o‘zi aytmasa ham, uni ma’lum vaqt oralig‘ida hojatxonaga o‘tqazib, rag‘batlantirishingiz mumkin. Taxminan 1-2 kun davomida uni har soatda hojatxonaga olib borish, keyinchalik esa bu oraliqni asta-sekin uzaytirish mumkin. Shu tariqa, chaqalog‘ingiz qisqa vaqt ichida hojati kelganini o‘zi ayta boshlaydi.') WHERE id = '115cbd6b-06db-4566-8c7c-e6c251edd677';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning ovqatlanish ko‘nikmalari ancha rivojlangan. U qoshiqni faol ushlashi, stakandan bir qo‘li bilan suv ichishi va qo‘li bilan ushlab yeyish mumkin bo‘lgan ko‘plab mahsulotlarni iste’mol qilishi mumkin. U muntazam ovqatlana boshlagan bo‘lsa-da, hali ham chaynash va yutishni o‘rganishda davom etmoqda; ba’zan o‘ynashga shoshilgani uchun ovqatni to‘liq chaynamay yutib yuborishi mumkin. Shu sababli bo‘g‘ilib qolish xavfi hali ham mavjud. Nafas yo‘llarini to‘sib qo‘yishi mumkin bo‘lgan mahsulotlardan saqlanishingiz kerak. Masalan, bir qoshiq yeryong‘oq pastasi, yong‘oq va boshqa mag‘izlar, lokum, uzum, xom sabzi, xom selderey, danakli gilos va olcha bunga sabab bo‘lishi mumkin. Farzandingiz bu mahsulotlarni iste’mol qilayotganda juda ehtiyotkor bo‘lishingiz muhim. Agar farzandingiz ularni yeyayotgan bo‘lsa, uni yolg‘iz qoldirmaslikka harakat qiling. Biror qiyinchilik yuzaga kelsa, sarosimaga tushmang, bolani kuzating va nafas ololmayotganini sezsangiz, nafas yo‘li to‘liq to‘silgan holatda darhol tez yordam chaqirib, birinchi yordam qoidalarini qo‘llang.') WHERE id = '43766e9c-9331-414f-9fe4-c87c7161371c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bu davrda uchta asosiy ovqatdan tashqari, 1-2 marta tamaddi ham qilishi kerak. Endi u oilaning boshqa a’zolari bilan bir xil taomlarni yeyishi mumkin. Boshqacha aytganda, unga alohida ovqat tayyorlashingiz shart emas. Farzandingizning nutqiy va ijtimoiy ko‘nikmalari rivojlanib borar ekan, hamma bilan bir dasturxon atrofida o‘tirish unga ovqatlanish jarayonida faol qatnashish imkonini beradi. Bunda bolaning qancha yeganiga haddan tashqari e’tibor qaratmasdan va ovqatlanish vaqtini kurashga aylantirmasdan, birga maroqli vaqt o‘tkazish muhim. Uning ovqat tanlashi haqida qancha ko‘p bahslashsangiz, u o‘z aytganini qilishga shuncha qat’iy intiladi. Biroq oila bo‘lib sog‘lom ovqatlanish odatlariga rioya qilishga va birgalikda foydali tanlovlar qilishga harakat qilishingiz kerak. Ovqatlanish vaqtida butun oila bilan dasturxon atrofida o‘tirish yaxshi odatning boshlanishidir.') WHERE id = '690fc0a4-31a8-41bb-8387-afbb9a513803';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz ulg‘aygani sayin ko‘ylagini kiyib-yechishdan tortib, likopchasiga ovqat solishgacha bo‘lgan ko‘plab ishlarni mustaqil bajarishni o‘rganadi. Chaqalog‘ingizning mustaqilligi rivojlanishini kuzatish ham hayajonli, ham faxrli. Bu uning shaxsiy va ijtimoiy rivojlanishining muhim qismidir. U keng kiyimlarini anchadan beri o‘zi kiya olayotgan bo‘lsa-da, futbolka kabi torroq kiyimlarni mustaqil kiyishi uchun hali bir necha oy kerak bo‘lishi mumkin. Butunlay mustaqil kiyinishni o‘rganishi esa bir-ikki yil vaqt oladi. Shuning uchun kutgan natijalaringiz hayotiy bo‘lsin va xavotir olmang. Shuningdek, unga haddan tashqari ko‘p aralashmang. Masalan, farzandingiz endi yordamsiz oyoq kiyimini yecha olishi va kiyinayotganda biror rangni o‘zi tanlashi kerak.') WHERE id = 'd7f6ffc6-8357-4c5b-94b8-550d90fdcbed';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Hatto ovqat masalasida ham o‘z qarorlarini qabul qila boshlagan va mustaqillashayotgan farzandingiz uchun ovqatlanish vaqti biroz qiyin kechishi mumkin. Farzandingiz sog‘lom ovqatlanish odati va tartibini egallashida ota-ona sifatida sizning rolingiz katta. Ovqatlanishga majburlash, mukofot yoki jazo kabi usullardan foydalanish bolaning ovqatlanish odatlariga salbiy ta’sir qiladi. Siz qilishingiz kerak bo‘lgan narsa — farzandingizning ishtahasini hurmat qilish. Asosiy ovqatlar va tamaddilarni o‘tkazib yubormaslik, uni zararli yeguliklarga o‘rgatmaslik sog‘lom ovqatlanishning asosiy shartidir. Bu davrda, ayniqsa, sut va sut mahsulotlari, tuxum, pishloq, yangi mavsumiy sabzavot va mevalar, donli mahsulotlar, qizil go‘sht, parranda go‘shti, baliq hamda dukkaklilar muhim oziq-ovqatlardir. Ularni farzandingizning ovqatlanish ratsioniga muvozanatli tarzda kiritishingiz kerak. Unutmang, farzandingiz bugun iste’mol qilgan har bir foydali mahsulot uning kelajagiga kiritilgan eng katta sarmoyadir.') WHERE id = '7ace9092-3ee2-47b6-b891-840cce162d3e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz hozir kognitiv (bilish) rivojlanish bosqichlarining ikkinchisi — "operatsiyagacha bo‘lgan davr"da. Bu davr tafakkurning boshlanishi ham hisoblanadi. Qisqacha aytganda, farzandingiz endi miyasidan o‘z maqsadlari yo‘lida foydalana boshlaydi. Dastlabki sinab ko‘rish va xato qilish tajribalaridan xulosa chiqarishi uning o‘rganish jarayonidagi eng katta yordamchisidir. Chaqalog‘ingiz bu davrda xotirasidan faol foydalana boshlaydi, buyumlarning doimiyligi va o‘ziga xosligi haqidagi tushunchalarni egallaydi. Endi u ichki reaksiyalardan tashqi reaksiyalarga o‘tadi. Taqlid qilish qobiliyati yanada rivojlanadi, shu sababli atrofidagi odamlar unga yaxshi namuna (rol modeli) bo‘lishi juda muhim.') WHERE id = '694eaa85-119e-4aa0-b132-331a3944017a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu bosqichda iste’mol qilgan har bir foydali mahsulotni uning kelajagiga kiritilgan sarmoya deb hisoblashingiz mumkin. Masalan, farzandingizning ovqatlanish ro‘yxatiga mavsumiy sabzavot va mevalardan tashqari, immunitet tizimini mustahkamlaydigan suyak sho‘rvasini qo‘shish foydali. Suyak sho‘rvasi ko‘plab vitaminlar, minerallar va katta miqdordagi oqsilni o‘z ichiga oladi. Shu sababli u chaqalog‘ingizning ovqatlanishida muhim o‘rin tutadi. Suyak sho‘rvasidagi kollagen, xondroitin va glyukozamin tog‘ay to‘qimasini mustahkamlab, chaqalog‘ingiz suyaklarining sog‘lom rivojlanishiga yordam beradi. Bundan tashqari, suyak sho‘rvasi tanani tinchlantiruvchi glitsin aminokislotasiga boy bo‘lib, bu chaqalog‘ingizning yanada tinch uxlashiga yordam beradi. Chaqalog‘ingizning ovqat hazm qilish tizimi hali rivojlanish bosqichida, shuning uchun siz iste’mol qiladigan ayrim og‘ir ovqatlarni hazm qilishga qiynalishi tabiiy. Suyak sho‘rvasi esa oson so‘rilishi tufayli chaqalog‘ingiz uchun yengil hazm bo‘ladigan oziqdir.') WHERE id = 'a406b692-65b5-470a-8764-73b3f8d9ec30';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz hojatxonadan foydalanishni to‘g‘ri o‘rganganiga qaramay, ma’lum vaqtdan keyin yana tagiga qilib qo‘ya boshlashi mumkin. Bu holat ayrim bolalarda kuzatiladi va vahimaga tushish o‘rniga nima qilish kerakligini bilish juda muhim. Agar farzandingiz hojatxonadan foydalanishni o‘rganganidan keyin to‘satdan tagiga qilib qo‘ya boshlasa, bunga nima sabab bo‘lganini aniqlashga harakat qilishingiz va uyda yuz berayotgan voqealarni tahlil qilishingiz kerak. Hojatxonadan foydalanish 2–3 yoshli bolalar egallaydigan so‘nggi rivojlanish ko‘nikmasidir va biror muammo yuzaga kelganda ortga qaytish eng avvalo shu ko‘nikmada namoyon bo‘ladi. Ortga qaytish deganda ancha oldin ko‘krakdan ajratilgan bolaning yana ona sutini so‘rashi, so‘rg‘ichdan voz kechgan bolaning yana u bilan uxlashni istashi yoki hojatxonadan foydalanishni o‘rgangan bolaning tagiga qilib qo‘yishi tushuniladi. Farzandingizning kundalik hayotini izdan chiqarishi va uni avvalgi davrdagi xavfsizlik hissiga qaytishga undashi mumkin bo‘lgan sabablarni kuzatishingiz kerak. Masalan, bog‘chada tengdoshlari tomonidan ko‘rsatiladigan bosim, oila a’zolarining salbiy munosabati yoki yangi uka yoxud singil tug‘ilishi kabi holatlar bunday reaksiyalarga sabab bo‘lishi mumkin.') WHERE id = '618a4bda-826f-4f95-b833-9fc6f643980b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz kundalik hayotda, ayniqsa stressli vaziyatlarda tikka o‘xshash ayrim xatti-harakatlarni namoyon qilishi mumkin. Sochini tortish, oyog‘ini tebratish, boshini biror joyga urish yoki barmog‘ini so‘rish shular jumlasidandir. Avvalo, farzandingizni bunday harakatlarni qilishga undayotgan sabablarni aniqlashingiz kerak. Masalan, bola xavotirlangan va taranglashgan paytlarida barmog‘ini so‘rishini sezsangiz, uni bu zo‘riqishdan himoya qilishingiz lozim. Bolani stressga solishi mumkin bo‘lgan o‘zgarishlardan oldin uni ruhiy jihatdan tayyorlashga harakat qiling. Shuningdek, bolangizga yoshiga mos bo‘lmagan tasvirlar va kontentlarni ko‘rishga ruxsat bermang. Agar bu vaziyatni yolg‘iz yenga olmasligingizni his qilsangiz, bolaga bosim o‘tkazish o‘rniga mutaxassisdan yordam olish eng to‘g‘ri yo‘l bo‘ladi.') WHERE id = '45fb1590-a84e-4747-9499-1dc671d7ac73';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingiz xayolida o‘zi umuman tanimaydigan kimnidir xayoliy do‘st sifatida gavdalantirishi mumkin. Taxminan 2,5 yoshda paydo bo‘ladigan bu holat bolangizning mavhum tafakkuri rivojlanishining bir qismi bo‘lib, mutlaqo tabiiydir. Ba’zan u o‘z fikrlarini shu xayoliy do‘stiga tasdiqlatishi yoki qilgan xatosini uning zimmasiga yuklashini ko‘rishingiz mumkin. Masalan, biror narsani sindirgan bo‘lsa, buni o‘zi qilmaganini aytishi mumkin. Aslida bu to‘liq ma’noda yolg‘on emas, chunki uning maqsadi o‘sha narsani sindirish bo‘lmagan. Shu sababli undan jahlingiz chiqishi o‘rniga, yuz bergan voqeani aytib berishga undashingiz kerak. Xayoliy do‘stlar odatda 6 yoshgacha yo‘qoladi. Buning sababi — bola hali haqiqat bilan xayol o‘rtasidagi farqni to‘liq anglamasligidir. Bu jarayonga aralashishingiz bolaning shaxsiyati rivojlanishiga salbiy ta’sir ko‘rsatishi mumkin.') WHERE id = 'f133f827-1aea-4a05-8919-15682019fac0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalikdan o‘rganilgan GMOli oziq-ovqatlar, aromatizatorlar va fast-fud mahsulotlariga qo‘shiladigan ta’m kuchaytirgichlarga qaramlikdan kelajakda xalos bo‘lish juda qiyin. Noto‘g‘ri ovqatlanish oqibatida orttirilgan vazndan xalos bo‘lish va buzilgan gormonal salomatlikni tiklash ba’zan imkonsiz bo‘ladi. Aynan shu sababli farzandingizni qadoqlangan oziq-ovqatlar va fast-fudga o‘rgatmasligingiz kerak. Farzandingiz sog‘lom ovqatlanish odatini egallashi uchun uyda tayyorlangan taomlarni butun oila bilan birga muntazam vaqtda tanovul qilish juda muhim. Masalan, makkajo‘xori bodrog‘i (popkorn) juda foydali ko‘rinishi mumkin, ammo makkajo‘xori GMO eng ko‘p qo‘llaniladigan o‘simliklardan biridir. Bunga mikroto‘lqinli pechda tayyorlash kabi omillar ham qo‘shilsa, u chaqalog‘ingiz uchun yanada zararli bo‘ladi. Naggetlar, kartoshka fri, gamburgerlar, chipslar hamda tarkibida nitrat miqdori yuqori bo‘lgan kolbasa va sosiska kabi qayta ishlangan go‘sht mahsulotlari ham bolangizdan uzoq tutishingiz kerak bo‘lgan oziq-ovqatlar qatoriga kiradi.') WHERE id = 'f814e388-56b0-4495-929d-571e82ff8364';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingizning uyqu tartibi har qachongidan ham muammoliroq bo‘lishi mumkin. Avval ham uyqu muammolariga duch kelgan oilalar bu muammolar 2 yoshdan keyin ham davom etayotganini ko‘rib, biroz hafsalasi pir bo‘lishi mumkin. Odamlar orasida bolalar ulg‘aygani sayin uyqu muammolari o‘z-o‘zidan yo‘qoladi degan fikr keng tarqalgan bo‘lsa-da, amalda har doim ham bunday bo‘lavermaydi. Agar siz ham chaqalog‘ingizning uyqu muammolaridan shikoyat qilsangiz, ayrim jihatlarga e’tibor qaratishingiz kerak. Masalan, tadqiqotlarga ko‘ra, bola bo‘lgan muhitda televizor va internetning mavjudligi uning uxlashga to‘g‘ridan-to‘g‘ri qarshilik ko‘rsatishiga sabab bo‘ladi. Buning asosiy sababi — haddan tashqari ko‘p qo‘zg‘atuvchi ta’sirlardir. Qisqacha aytganda, shakar va shokolad tanaga qanday qo‘zg‘atuvchi ta’sir ko‘rsatsa, televizor kabi qurilmalar ham xuddi shunday ta’sir qiladi. Shu nuqtayi nazardan, chaqalog‘ingizning uyqu vaqtidan kamida 2 soat oldin televizor, planshet va telefon kabi qurilmalarni o‘chirib qo‘yish bu zo‘riqishni sezilarli darajada kamaytiradi.') WHERE id = '27bc15ff-de70-4213-99e8-421c8ec7be89';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Asalarilar o‘z bolalarini oziqlantirish uchun tanasidan ajratib chiqaradigan qimmatli mahsulot — ari suti chaqalog‘ingizning salomatligi va ovqatlanishida muhim o‘rin tutadi. Oziqlantiruvchi xususiyati juda yuqori bo‘lgan ari suti 1 haftalik asalarilar ajratib chiqaradigan gelsimon moddadan iborat. Immunitet tizimini mustahkamlashi ma’lum bo‘lgan ari sutini har tong 1 choy qoshiq asal bilan birga iste’mol qilish uning ta’sirini yanada oshiradi. 100 grammida taxminan 15 gramm oqsil bo‘lgan ari suti, shuningdek, B guruhi vitaminlari, foliy kislotasi, magniy, rux va temir minerallariga boy. Ari suti tarkibida boshqa hech qanday oziq-ovqatda uchramaydigan royalaktin nomli maxsus oqsil va 10-HDA nomli qimmatli yog‘ kislotasi mavjud. Barcha shu xususiyatlari tufayli ari suti chaqalog‘ingizning o‘sishi va rivojlanishini qo‘llab-quvvatlash maqsadida ishlatilishi mumkin bo‘lgan tabiiy mahsulotdir. Uni muntazam qo‘llaganda chaqalog‘ingizda immunitetni kuchaytirish, jismoniy va aqliy rivojlanishni qo‘llab-quvvatlash hamda ishtahani tartibga solish kabi ta’sirlarini ko‘rasiz.') WHERE id = 'a10c3d04-e569-47ea-bad2-70a751db07a2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning hozirgi yosh davrida chegaralar juda muhim. Ota-onalar chegara belgilashni, bolalar esa bu chegaralarni sinab ko‘rishni yaxshi ko‘radilar. Bunda eng muhim jihat — izchil bo‘lishdir. Chunki chegaralar ba’zan qo‘llanib, ba’zan esa qo‘llanmasa, chaqalog‘ingiz yanada chalkashib qoladi. Uxlashdan oldin "yana bir stakan suv", "dadamni yana bir marta o‘pay", "oxirgi marta hojatxonaga boray" kabi istaklarga chegara qo‘yishingiz kerak. Masalan, chaqalog‘ingiz uxlamaslik uchun turli bahonalar o‘ylab topsa, chegaralarni belgilashingiz va ularga qat’iy rioya qilishingiz lozim. Qaysarlik yuzaga kelganda, ikkingiz orasida kattaroq va yetukroq tomon siz ekaningizni unutmang. Boshqa tomondan, u bilan qaysarlashishdan ham ma’no yo‘q, chunki bu kurashda g‘alaba qozona olmaysiz. :) Bu shunchaki siz istamagan xatti-harakatning davom etishiga sabab bo‘ladi. Buning o‘rniga bo‘shashing, o‘tiring va xotirjamligingiz bilan chaqalog‘ingizga namuna bo‘lishga harakat qiling.') WHERE id = 'bc1477cb-0848-495f-b85f-1500cde5812a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Hojatxonaga o‘rgatishni tugatgan yoki hali davom ettirayotgan shu kunlarda chaqalog‘ingiz ba’zan siydik chiqarishda qiynalayotganini sezishingiz mumkin. Ayniqsa, siyayotganda yig‘lash yoki sababsiz yig‘i xurujlari kabi belgilar kuzatilishi mumkin. Bu holat 2 yosh sindromining belgisi bo‘lishi bilan birga, infeksiyadan ham darak berishi mumkin. Ayniqsa, qiz bolalarda ko‘p uchraydigan siydik yo‘llari infeksiyasi siydik yo‘llarining yallig‘lanishi natijasida yuzaga keladi. Qizlarda ko‘proq uchrashining sababi — ularning tana tuzilishi tufayli bakteriyalarning siydik yo‘llariga osonroq kirishidir. Agar chaqalog‘ingizda qorin og‘rig‘i, siydikda yoqimsiz hid, qusish, ko‘ngil aynishi, ishtahasizlik, siydik tutolmaslik, tez-tez, ammo oz miqdorda siyish kabi belgilar bo‘lsa, shifokoringiz bilan maslahatlashishingiz kerak. Tahlil natijasida yallig‘lanish aniqlansa, shifokor tegishli antibiotik bilan davolashni buyuradi.') WHERE id = 'da48700f-d847-4b96-8c98-118ee88f992c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalardagi semizlik so‘nggi yillarda butun dunyoda bo‘lgani kabi mamlakatimizda ham ko‘p uchraydigan muammoga aylandi. Bolalarning, ayniqsa, shakar, turli shirinliklar hamda ozuqaviy qiymati past, ammo kaloriyasi yuqori mahsulotlarni iste’mol qilishi semizlikning asosiy sabablaridan biridir. Oq shakar qondagi qand miqdorining tez ko‘tarilib, keyin keskin tushishiga sabab bo‘ladi. Bu esa bolalarda shirinlikka bo‘lgan tinimsiz ehtiyojni yuzaga keltiradi. Nonushta o‘rniga beriladigan bulochkalar va shunga o‘xshash xamirli taomlarni ham cheklash muhim. Chunki glikemik indeksi yuqori bo‘lgan bu mahsulotlar ham xuddi shakar kabi doimiy ochlik hissini keltirib chiqaradi. Rangli qadoqlarda sotiladigan yumshoq jelatinli shirinliklar (jele konfetlar) esa har bir bolaning e’tiborini tortadi. Bunday mahsulotlar odatda yirik shoxli hayvonlarning suyakli qismlarini qaynatish orqali olinadi. Qisqasi, tarkibida aynan nimalar borligi noma’lum bo‘lgan bunday mahsulotlardan chaqalog‘ingizni albatta uzoq tutishingiz kerak.') WHERE id = 'd02c7a47-3078-410b-a75a-b2f0b0e780c9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'So‘nggi paytlarda tarqalish darajasi ancha oshgan autizm ko‘plab ota-onalar kabi sizni ham xavotirga solishi mumkin. Autizmda erta tashxis eng muhim jihatdir, shu sababli uning belgilarini bilishingiz katta ahamiyatga ega. Autizm — ilk bolalik davridan namoyon bo‘ladigan hamda miya va asab tizimining o‘ziga xos tuzilishi yoki faoliyati bilan bog‘liq deb hisoblanadigan neyrobiologik buzilishdir. Boshqalar bilan muloqot qilishga xalaqit beradigan va bolaning o‘z ichki dunyosiga berilib ketishiga olib keladigan autizm odatda 3 yoshgacha namoyon bo‘ladi. Bu holat chaqaloqning ijtimoiy muloqoti, o‘zaro munosabatlari va xatti-harakatlariga salbiy ta’sir ko‘rsatadi. Autizm va autistik spektrdagi boshqa buzilishlarga tashxis qo‘yish qiyin bo‘lishi mumkin, chunki belgilarning og‘irlik darajasi har bir bolada turlicha bo‘ladi. Muloqot ko‘nikmalarining sustligi, ko‘z bilan aloqa qilishdan qochish, qo‘llarni silkitish, boshini urish yoki biror buyumni qayta-qayta aylantirish kabi takroriy xatti-harakatlar, shuningdek, o‘zgarishlarga moslashishda qiynalish eng ko‘p uchraydigan belgilardir. Bundan tashqari, qiziqish doirasining cheklanganligi, quchoqlash yoki teginishlarini istamaslik ham autizm belgisi bo‘lishi mumkin.') WHERE id = '47c104cd-1ceb-4881-829f-8f78f639b9f1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz hali ona qornidaligidayoq barmog‘ini so‘ra boshlashi mumkin. 18-24 oy atrofida og‘iz sohasi asosiy qoniqish manbai bo‘lgani uchun barmoq so‘rish odat tusiga kirishi mumkin. Shu bilan birga, u kundalik hayotida barmog‘ini so‘rib, o‘zini tinchlantiradi va yengil his qiladi. Odatda 2 yoshdan keyin nutq rivojlanishi bilan bola o‘zini ifodalash uchun yangi ko‘nikmalarni egallaydi va barmoq so‘rish kamayadi. Biroq ayrim bolalar yoshi ulg‘aysa ham bu odatni davom ettiradilar; ular qo‘rqqanda, charchaganda, zerikkanda yoki uxlab qolish uchun barmog‘ini so‘rishi mumkin. Agar chaqalog‘ingiz ham bu xatti-harakatni davom ettirayotgan bo‘lsa, uni to‘g‘ri usullar bilan va o‘z vaqtida bu odatdan chiqarish muhim. Noto‘g‘ri yondashuvlar bolaning o‘zini jazolangan va aybdor his qilishiga sabab bo‘lishi mumkin. Masalan, bolaning barmog‘ini so‘rmayotgan paytlariga e’tibor qaratishingiz mumkin. Bunday paytlarda uni maqtash ijobiy rag‘bat bo‘lib, bu odatdan voz kechishga undaydi.') WHERE id = '0ce7f0c6-55c7-478c-bbc2-e2aef384f568';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ikkinchi sut oziq tishlari to‘liq chiqib bo‘lgan bo‘lishi mumkin. Agar hali chiqmagan bo‘lsa, kelgusi 2 oy ichida chiqib bo‘lishini eslatib o‘tmoqchimiz! :) Sut tishlarining to‘liq chiqishi 2 yarim, hatto 3 yoshgacha davom etishi mumkin, 6 oylik farqlar esa me’yoriy hisoblanadi. Oziq tishlar eng qiyin chiqadigan tishlardir, shu sababli birinchi tishlarga qaraganda ancha murakkab jarayonni boshdan kechirishingiz mumkin. Bu davrda tish chiqayotgan joyda binafsharang shish paydo bo‘lishi mumkin, tibbiyotda bu tish chiqish kistasi deb ataladi. Bu muammo uchun tibbiy jihatdan ko‘p narsa qilish talab etilmaydi; shunchaki o‘sha joyni massaj qilish yoki tish qashlagichni muzlatkichda sovitib, chaqaloqqa berish yordam berishi mumkin. Kamdan-kam hollarda tish ushbu kista ichidan chiqa olmaydi; bunday vaziyatda shifokor kichik kesma orqali tishning chiqishiga yordam berishi mumkin.') WHERE id = '5201e9e6-1a37-48d8-b089-cbbfefcfd807';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz hali yangi tug‘ilgan davridayoq boshqa chaqaloqning yig‘isini eshitib, yig‘lay boshlasa, bu empatiya qobiliyatining poydevori shakllanayotganini ko‘rsatadi. Bunga uning boshqa chaqaloqning bezovtaligini his qilishi sabab bo‘ladi. Biroq bu yoshda hali to‘liq ongli empatiya haqida gapirishga erta. Agar chaqalog‘ingiz 12-18 oylik bo‘lsa, u turli yuz ifodalari turli his-tuyg‘ularni aks ettirishini tushuna oladi. Ya’ni u sizning g‘azabingiz, mehringiz yoki qayg‘uingizni sezadi. O‘z his-tuyg‘ulari va fikrlari boshqalarnikidan farq qilishi mumkinligini anglash ham taxminan shu oylarga to‘g‘ri keladi. Bu o‘zini boshqa birovning o‘rniga qo‘ya olish — empatiya qobiliyati rivojlana boshlaganini ko‘rsatadi. Albatta, hozircha undan qarshisidagi insonning his-tuyg‘ularini o‘zinikidan ustun qo‘yib, shunga muvofiq harakat qilishini kutib bo‘lmaydi.') WHERE id = '213fc964-930a-472e-84f6-21113ae224d3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar yura boshlaydigan 1 yoshdan 3 yoshgacha bo‘lgan davr mustaqillik davridir. Chaqalog‘ingiz hali ham shu bosqichda ekanini unutmang. U endi o‘zini alohida shaxs sifatida his qilishni va ko‘p narsalarni mustaqil bajarishni o‘rganmoqda. Har bir yangilik va tajriba unga quvonch bag‘ishlasa-da, ba’zan noma’lumlik uni xavotirga solishi mumkin. Notanish vaziyatlarni yengib o‘tish oson emas, shuning uchun u hali ham o‘zi ishonadigan insonning ko‘magi va ma’qullashiga muhtoj. Faqat sizning ma’qullashingiz bilan u atrofni o‘rganishda davom eta oladi. Bu jarayonda ba’zan taqiqlangan ishlarni qilishi muqarrar. Shu sababli cheklov va qoidalarga duch kelganda ko‘pincha norozilik bildirishi mumkin. Bunday to‘siqlar ba’zan uning jahlini chiqarishi mumkin. Biroq bu qarama-qarshiliklar bolaning "yo‘q" deyish qobiliyatini rivojlantiradi. Bu esa o‘z tanlovlari va his-tuyg‘ularini anglash yo‘lidagi muhim qadamdir.') WHERE id = 'd9130ed0-2f5f-4d02-851c-ceed9e0bc359';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ayrim ota-onalar farzandi kam ovqat yeyishidan shikoyat qilsa, boshqalari uning haddan tashqari ko‘p yeyishidan xavotirlanadi. Agar sizda ham shunday muammo bo‘lsa, avvalo "ko‘p" degan tushunchani nimaga asoslanib belgilayotganingiz haqida o‘ylab ko‘rishingiz kerak. Har bir bola turlicha ekanini va har birining o‘ziga xos to‘yish chegarasi borligini unutmang. Eng to‘g‘ri yondashuv — chaqaloq nega ko‘p ovqat yeyotganini aniqlashdir. Sabab fiziologik bo‘lsa, pediatr bilan, psixologik bo‘lsa, pedagog yoki psixolog bilan maslahatlashish juda muhim. Ba’zan bolalar shunchaki e’tiborni jalb qilish uchun ham ko‘p ovqat yeyishi mumkin. Har qanday holatda ham shifokor tavsiyasisiz chaqaloqning ovqatlanishiga aralashmasligingiz va uni parhezga o‘tqazmasligingiz kerak. Bu o‘sish va rivojlanish davridagi bola uchun xavfli oqibatlarga olib kelishi mumkin.') WHERE id = 'b0d1338b-df42-42bb-9eec-8ea39482f47d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu bosqichda chaqaloqning miya hujayralari yangi ma’lumotlarni nihoyatda tez sur’atda to‘plashda davom etadi! U hayotidagi barcha tajribalarni kelajakda foydalanish uchun xotirasiga joylaydi. Endi u o‘zini ko‘zguda taniydi, hatto qiziqish bilan o‘zini tez-tez kuzatishni xohlaydi. Ayniqsa, siz bajaradigan oddiy uy ishlariga taqlid qilib, atrofidagi insonlar kabi bo‘lishni mashq qiladi. Otasi uyda biror narsani tuzatganda, go‘yo dunyodagi eng qiziqarli voqeani tomosha qilayotgandek munosabat bildirishi mumkin. Keyin esa xuddi shu harakatlarni o‘yinchoqlarida takrorlashga urinadi. Farzandingizning bu kuzatuvlari, taqlidlari va xotirasida saqlayotgan tajribalari unda empatiya hissining poydevorini ham yaratadi.') WHERE id = 'af02d5b9-9b5a-44a3-8a27-d35bbbd65550';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizni ovqatlantirishda e’tibor berishingiz kerak bo‘lgan muhim jihatlardan biri — taomlarni tayyorlash usulidir. Bug‘da va dimlab pishirish kabi usullar oziq-ovqat tuzilishiga zarar yetkazmaydi, natijada uning ozuqaviy qiymati saqlanib qoladi. Shu jihatdan, sabzavotlarni chaqalog‘ingiz uchun foydali tarzda tayyorlashning eng yaxshi usuli — ularni bug‘da pishirishdir. Baliqni esa duxovkada, grilda yoki dimlab tayyorlashingiz mumkin. Sabzavotlar va baliqni qovurib tayyorlash juda zararli. Imkon qadar qovurilgan taomlardan butunlay voz kechish farzandingizning kelajakdagi salomatligi uchun eng katta sarmoya bo‘ladi.') WHERE id = 'b026868b-14a9-4e91-9d7c-64f2335b71be';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz taxminan 36 oylik bo‘lguniga qadar kechasi 11 soat, kunduzi esa 1,5-2 soat uxlashi kerak. Bu yoshdagi bolalarning aksariyati kechqurun 19.00-21.00 oralig‘ida uxlaydi va ertalab 06.30-08.00 oralig‘ida uyg‘onadi. Bu vaqtlar ularning uyqu tartibi endi kattalarnikiga yaqinlashganini ko‘rsatadi. Farzandingizning uyqusi siznikidan yengilroq bo‘lishi taxminan 4 yoshgacha davom etishi mumkin. Agar u ertalab sizdan oldin uyg‘onsa, unga yana uxlab qolishni o‘rgatish foydali bo‘ladi. Bu davrda bolaning uxlashga qarshilik ko‘rsatishi juda ko‘p uchraydi. Yotoqqa borishni istamasligi qorong‘ilikdan yoki xayoliy narsalardan qo‘rqishi bilan bog‘liq bo‘lishi mumkin. Qo‘rquv bolaning tabiiy rivojlanishining bir qismidir, shuning uchun unga tushunish va mehr bilan munosabatda bo‘lishingiz kerak.') WHERE id = 'd4569b71-1c50-4817-b555-f4e1a27ff451';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2-6 yosh oralig‘i bolalarda yetarli va muvozanatli ovqatlanish tushunchasi shakllanadigan davrdir. Biroq kun davomidagi ijtimoiy mashg‘ulotlar va bolaning juda serharakat bo‘lishi bu jarayonni qiyinlashtirishi mumkin. Yana bir qiyinchilik — bu yoshdagi bolalarning o‘jarlik qilishidir. Bunda asosiy maqsadingiz farzandingizda maktab yoshigacha to‘g‘ri ovqatlanish odatlarini shakllantirish bo‘lishi kerak. Chunki bu yoshda shakllangan ta’m tanlovi va odatlar bolaning butun kelgusi hayotiga ta’sir qiladi. Ota-onalarning eng katta xatosi — bola och qolishidan qo‘rqib, unga bosim o‘tkazishidir. Aksincha, bola ovqatlanishni azob sifatida emas, balki yoqimli mashg‘ulot sifatida qabul qilishi kerak.') WHERE id = 'cca7e654-d2f4-435d-ac1b-7bc12c892a08';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Xavfsizlik va muhim axloqiy qoidalar bilan bog‘liq holatlardan tashqari, chaqalog‘ingizga nisbatan “yo‘q” va “qilma” kabi taqiqlovchi so‘zlarni ko‘p ishlatmasligingiz kerak. Bu iboralar uning o‘rganishga ochiq ongida yengib bo‘lmas to‘siqlarga aylanishi mumkin. Istagan narsalarini qila olmaslik uning tasavvur olamiga putur yetkazib, o‘ziga bo‘lgan ishonchini kamaytirishi mumkin. Shu sababli salbiy emas, ijobiy iboralar asosida muloqot qilishga harakat qiling. “Yo‘q” deyish o‘rniga, har ikkingiz uchun ham qiziqarliroq va foydaliroq muqobillarni taklif qilishingiz mumkin. Bola xato qilganida, shundoq ham o‘zini aybdor va yomon his qilishi mumkin. U eng ko‘p ishonadigan insonlar sifatida siz va juftingiz uni hukm qilmasdan yonida bo‘lishingiz kerak. Bir tomondan uni to‘g‘ri xatti-harakatlarga yo‘naltirsangiz, boshqa tomondan xatolari tufayli chuqur aybdorlik hissini tuyishdan asrashingiz lozim.') WHERE id = 'adaca540-c013-4a03-bbd7-74d6af6f0d5a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bilan birga mazmunli o‘tkazadigan yangi davr boshlanmoqda. Bu bosqichda bolaning mushaklari kuchayishi bilan harakatlaridagi uyg‘unlik va muvozanat yanada yaxshilanadi. Juda serg‘ayrat bo‘lgan chaqalog‘ingiz doimo harakatda bo‘ladi va ko‘plab ota-onalar uning energiyasiga yetishishga qiynalishi mumkin. Jismoniy rivojlanish bilan bir qatorda, uning aqliy rivojlanishi ham jadal davom etadi. Shu bois bu davrda chaqalog‘ingizni mushak kuchi, ijodkorligi va jismoniy chidamliligini oshiradigan mashg‘ulotlarga yo‘naltirishingiz muhim. 29 oylik bola uchun to‘p tepish, yugurish, velosiped haydash va turli joylarga tirmashib chiqish kabi faoliyatlar bunga ajoyib misol bo‘ladi. U bajaradigan bu jismoniy harakatlarning barchasi ayni paytda uning aqliy rivojlanishiga ham katta hissa qo‘shadi.') WHERE id = '1aab8015-59a1-447d-9108-ce75d06b5eba';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar 1 yoshdan boshlab har yili o‘rtacha 5-7 santimetrga o‘sadi va taxminan 2-3 kilogramm vazn qo‘shadi. Biroq jismoniy rivojlanishdagi bu o‘sish ko‘plab turli omillarga qarab o‘zgarishi mumkin. Bu davrda irsiy xususiyatlar o‘z ta’sirini ko‘proq namoyon qila boshlaydi. Shu sababli chaqalog‘ingizning ovqatlanish odatlari o‘zgarmasa ham, bo‘yi va vaznining rivojlanishida tengdoshlaridan farqli o‘sish yoki ortda qolishni kuzatishingiz mumkin. Masalan, ozg‘in va kichik gavdali ota-onalarning bolalari qanchalik muvozanatli ovqatlanmasin, tengdoshlariga qaraganda kichikroq ko‘rinishi mumkin. Shu bois jismoniy rivojlanishni baholashda yagona mezoningiz shifokoringizning fikri bo‘lishi kerak. Persentil (rivojlanish) jadvali ham bu borada sizga yo‘l-yo‘riq ko‘rsatishi mumkin. Jadvalga ko‘ra, 29 oylik qiz bolalarda vaznning quyi chegarasi 10.000 gramm, yuqori chegarasi esa 16.000 grammni tashkil etadi. 29 oylik o‘g‘il bolalarda esa vaznning quyi chegarasi 10.500 gramm, yuqori chegarasi 16.400 grammdir. Bo‘yiga kelsak, 29 oylik qiz bolalarda quyi chegara 83,4 sm, yuqori chegara 96,4 sm; o‘g‘il bolalarda esa quyi chegara 84,9 sm, yuqori chegara 97,5 sm-dir.') WHERE id = 'db8346fb-9273-49d5-bf2c-a86e6c17b290';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz kun davomida ehtiyoj sezadigan energiyaning katta qismi, kattalardagi kabi, uglevodlardan olinadi. Avvalo non va boshqa uglevod manbalari shu maqsadga xizmat qiladi. Biroq foydali uglevodlarni tanlash sizning mas’uliyatingizdir. Nafaqat siz, balki chaqalog‘ingiz ham oq non o‘rniga butun bug‘doydan tayyorlangan (butun donli) nonni tanlagani ma’qul. Butun bug‘doy uni kamroq qayta ishlangani uchun ozuqaviy qiymati yuqoriroq bo‘ladi. Guruch o‘rniga bulg‘ur ishlatish ham yaxshi muqobildir. Agar bolangiz vazn yig‘ishga moyil bo‘lsa, bu mahsulotlarni butunlay chiqarib tashlash o‘rniga porsiyalarni kichraytirishingiz mumkin. Shuningdek, foydali uglevodlar guruhiga kiradigan loviya, no‘xat va yasmiq kabi dukkakli mahsulotlarni haftasiga 2-3 marta chaqalog‘ingiz menyusiga kiritishingiz mumkin.') WHERE id = '1c27be1f-dfab-44ba-8a0e-90b8852c1426';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu yoshda quvlashmachoq va bekinmachoq kabi o‘yinlardan juda zavqlanadi. Bu o‘yinlarni siz bilan o‘ynashi u uchun juda muhim, chunki shu tariqa u o‘zini istalgan va izlanadigan inson sifatida his qiladi. Bekinmachoq o‘ynaganda uni topish lahzasi chaqalog‘ingizda buyumlar ko‘zdan yo‘qolsa ham mavjud bo‘lib qolishi haqidagi tushunchani mustahkamlaydi. Bu davrda egalik hissi hali to‘liq shakllanmagani sababli, u buyumlarini qisman baham ko‘rsa-da, boshqa bolalar bilan bevosita birgalikda o‘ynamayotganini ko‘rishingiz mumkin. Odatda boshqa bolaning yonida o‘ynayotganda uni kuzatsa ham, go‘yo u yo‘qdek tutishi mumkin. Shunga qaramay, chaqalog‘ingiz boshqa bolaning kulgisiga kulib javob berishi yoki uning yig‘isidan qo‘rqib ketishi mumkin. Hatto boshqa bolaning yig‘lashiga o‘zi sababchi bo‘lsa, uning bezovtalanganini ham kuzatishingiz mumkin.') WHERE id = '48eeead7-4aaf-4261-980b-2417b364eaf1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz 2.5 yoshga yaqinlashayotgan shu kunlarda porsiyalarini kichraytirishni xohlashi va tez-tez "to‘ydim" deyishi mutlaqo normal holat. Bu chaqalog‘ingizning ishtahasi yo‘qolganini anglatmaydi, shuning uchun xavotir olmang. Buning asosiy sababi o‘sish sur’ati ancha sekinlashganidir. Chaqalog‘ingiz kamroq ovqatlana boshlaganda, eng yaxshi yo‘l unga ovqatni kichik porsiyalarda, ammo ozuqaviy qiymati yuqori holda taqdim etishdir. Bu davrda bola katta odam iste’mol qiladigan ovqat miqdorining ko‘pi bilan yarmini yeyishi mumkin. Shu bois uni ko‘proq ovqatlanishga majburlamasligingiz juda muhim. Oz miqdorda iste’mol qilayotgan taomlari foydali bo‘lishiga e’tibor bering. Chaqalog‘ingiz istagan paytda foydali yeguliklarni oson olishi, zararli mahsulotlar esa uning qo‘li yetmaydigan joyda saqlanishi kerak.') WHERE id = '3870e199-6a66-48e6-9897-cabfbe66081e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz endi shunday bosqichdaki, uydagi har qanday buyum uning uchun o‘yinchoqqa aylanishi mumkin. Bunga sizning shaxsiy buyumlaringiz ham kiradi. U o‘yinchoq deb bilgan buyumlarini uyning turli joylariga olib borishi, atrofga sochib tashlashi yoki joyini o‘zgartirishi mumkin. Bu holat uyda katta tartibsizlikka sabab bo‘lsa-da, unga to‘sqinlik qilishga urinish to‘g‘ri yondashuv emas. Chunki chaqalog‘ingiz dunyoni o‘yin orqali kashf etadi, taniydi va o‘rganadi. Uni doimo cheklash o‘rganishga bo‘lgan ishtiyoqini so‘ndirishi mumkin. Eng yaxshisi — aniq chegaralarni belgilash. Masalan, oshxonada kesuvchi va sanchuvchi asboblar bilan o‘ynashni taqiqlab, qozonlar bilan o‘ynashiga ruxsat berishingiz mumkin. O‘yin tugagach esa buyumlarni birgalikda yig‘ishtirib, unga mas’uliyat hissini o‘rgatishingiz mumkin.') WHERE id = '368b3b11-1e1f-4a83-bc4e-453fba29a7a6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz hojatxonaga borishni to‘liq o‘rgangan bo‘lsa ham, tunda hali ham tagini ho‘llab qo‘yishi mumkin. Tibbiyotda bu holat "enurez" deb ataladi. Odatda bolalarning aksariyati hojatxonaga borishni o‘rganishi va siydik pufagi rivojlanishi natijasida taxminan 2 yoshida siydigini kechasi ham, kunduzi ham ushlab turishni o‘rganadi. Tunda tagini ho‘llash muammosi ko‘pincha siydik pufagi rivojlanishining kechikishi bilan bog‘liq bo‘lib, bola ulg‘aygani sari o‘tib ketadi. Agar bunday holatni kuzatsangiz, avvalo siydik yo‘llari infeksiyasi kabi muammo bor-yo‘qligini aniqlash uchun shifokor bilan maslahatlashing. Agar sabab kasallik bo‘lmasa, ayrim jihatlarga e’tibor berishingiz mumkin: uxlashdan 2 soat oldin suyuqlik iste’molini kamaytiring va tarkibida kofein bo‘lgan ichimliklardan saqlaning. Eng muhimi, tozalikni saqlash maqsadida bolaga kechasi taglik taqmang; bu uning tunda uyg‘onishga bo‘lgan rag‘batini pasaytiradi.') WHERE id = '8d79c984-59c4-461b-b19e-f63da9c3b917';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingiz haqiqatga mos kelmaydigan gaplarni aytayotganini ko‘rishingiz mumkin. Biroq bu tom ma’noda "yolg‘on" emas. Bolalar 5-7 yoshgacha xayoliy dunyo bilan haqiqatni to‘liq ajrata olmaydi. Ayniqsa, 2.5-3 yoshli bolalar e’tiborni jalb qilish uchun ayrim voqealarni o‘ylab topishi mumkin. Masalan, o‘yinchoq ayig‘i qochib, yashirinib olganini aytishi yolg‘on emas, balki uning xayol mahsulidir. Farzandingizning xayolot olami juda keng, shuning uchun bunday xatti-harakatlarni "yolg‘on gapirish" deb baholamasligingiz va uni ayblamasligingiz kerak. Bu xatti-harakatlar asta-sekin kamayadi va odatda 7 yoshgacha butunlay yo‘qoladi.') WHERE id = '312018ab-f646-4975-9148-a5d080d99b50';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Siz farzandingiz uchun hamon eng katta o‘rnaksiz. Bu uning siz yegan va ichgan har bir narsani tatib ko‘rishni istashini anglatadi. Choy, qahva va gazli ichimliklar bolalarda katta qiziqish uyg‘otadi. Ota-onalar ba’zan bolaning talabiga chiday olmay, bu zararli ichimliklardan ozgina tatib ko‘rishiga ruxsat beradi. Biroq choy tarkibidagi tein va qahvadagi kofein kabi moddalar qo‘zg‘atuvchi ta’sirga ega bo‘lib, qaramlikni keltirib chiqarishi mumkin. Shuningdek, choy va shunga o‘xshash ichimliklar qondagi temir miqdorini kamaytiradi. Gazli va rangli ichimliklar esa bolalarda asabiylikni keltirib chiqarishi bilan birga sog‘liq uchun ham zararlidir. Eng yaxshisi, bola bunday ichimliklarning ta’mini umuman bilmasligidir.') WHERE id = 'd3f39e2d-95d5-4448-a3ee-5735bd480f16';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Qanchalik himoya qilishga urinmang, chaqalog‘ingiz vaqti-vaqti bilan kasal bo‘lib qolishi mumkin. Kasalliklarning og‘irligini kamaytirish uchun uning immun tizimini mustahkamlash muhim. Buning eng tabiiy yo‘li — bolaning "foydali" bakteriyalar bilan aloqada bo‘lishidir. Bolalar tabiat qo‘ynida tuproq bilan o‘ynagan sari ularning immuniteti yaxshiroq rivojlanadi. Hozirgi davrda ko‘chadagi o‘yinlar kamaygani sababli farzandingiz bilan tabiat qo‘ynida ko‘proq vaqt o‘tkazishga harakat qiling. Shuningdek, kasal bo‘lib qolishidan qo‘rqib, uni boshqa bolalardan uzoq tutmang. Tadqiqotlar tengdoshlari bilan tez-tez muloqot qiladigan va o‘yin guruhlarida qatnashadigan bolalarning immun tizimi chidamliroq bo‘lishini ko‘rsatadi.') WHERE id = 'f9d7a8b1-31bd-4aa3-ada9-e3738e8a0231';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu davrda oziq-ovqat nafaqat ovqatlanish uchun kerakligini, balki boshqa maqsadlarda ham qo‘llanishini tushuna boshlaydi. Masalan, u ovqatning pora, mukofot yoki sovg‘a sifatida berilishi, shuningdek, uni rad etish orqali ta’sir ko‘rsatish mumkinligi bilan shu davrda tanishadi. Endi ovqatlanish vaqtida farzandingiz kichikroq porsiya bilan ham to‘yganini aytishi mumkin. Buning sabablaridan biri — uning o‘sish sur’ati chaqaloqlik davriga nisbatan ancha sekinlashgani va shunga mos ravishda kaloriyaga bo‘lgan ehtiyoji kamayganidir. Eng muhimi, bu kaloriya ehtiyojini foydali oziq-ovqatlar bilan qondirishini ta’minlashdir. Kechki ovqatdan oldin qornini meva sharbati va kreker bilan to‘ldirgan bolaning kechki ovqatda sabzavotli taomni ishtaha bilan yeyishini kutmasligingiz kerak. Tamaddilar miqdorini kamaytirish va shirinligi kamroq mahsulotlarni tanlashdan boshlashingiz mumkin. Asosiy ovqat paytida esa taomlarni avval sabzavotlar, keyin oqsillar, so‘ng uglevodlar guruhi tartibida bersangiz, bola eng och bo‘lgan paytida sabzavotlarni ishtaha bilan yeyishga moyilroq ekanini ko‘rasiz.') WHERE id = '644f27a1-772e-4290-a4c7-b64545b7ca56';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2,5 yoshli farzandingizning rivojlanish xususiyatlari orasida ranglarni tanish, so‘zlarni to‘g‘ri qo‘llash va sanashni boshlash kabi ko‘nikmalar mavjud. Bu ko‘nikmalar siz ota-ona sifatida unga qanday yo‘l-yo‘riq ko‘rsatishingizga qarab o‘zgarishi mumkin. Bu davrda farzandingizda mustaqillik hissi bilan birga, atrofidagi muhitni nazorat qilish istagi ham shakllanadi. 2,5 yosh bola rivojlanishidagi eng katta inqirozli davrlardan biri hisoblanadi. Qaysarlik bosqichi deb ham ataladigan bu davrda farzandingiz juda salbiy, isyonkor va qat’iyatsiz xatti-harakatlarni namoyon qilishi mumkin. Uning o‘z muhitida hukmronlik qilish istagi atrofdagilar va ota-onalar belgilagan taqiqlar bilan to‘qnasha boshlaydi. Bu davrda bolaning jahldor va o‘ylamay harakat qilishi mutlaqo tabiiy bo‘lib, rivojlanish jarayonining bir qismidir. Shu sababli, hissiy va ijtimoiy rivojlanishi uchun bu davrda farzandingizni ijtimoiy muhitlarga ko‘proq jalb qilish foydali bo‘lishi mumkin.') WHERE id = 'fd9715f6-ed39-43d1-a0a5-6696d68a16b2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingiz rasm chizishni juda yaxshi ko‘rishini va chizgan rasmlariga nom qo‘yishini kuzatishingiz mumkin. Farzandingiz endi o‘z ismini to‘liq anglagani uchun boshqalarga ismini ayta boshlashi mumkin. Aqliy rivojlanishi jadallashgani sari o‘rgangan asosiy tushunchalarini yanada takomillashtiradi. Masalan, u biladigan ranglar soni ko‘payganini, bir nechta qo‘shiqni o‘rganib kuylayotganini, xato qilsa ham raqamlarni sanay boshlaganini ko‘rishingiz mumkin. Farzandingiz bu davrda kamida 200 dan ortiq turli so‘zni ishlata oladi. Shuningdek, "men, meni, menga" kabi kishilik olmoshlarini aniq ayta oladi. Biroq nutq qobiliyatidagi bu katta o‘zgarishlar zamon qo‘shimchalarida hali namoyon bo‘lmayotgani sizni tashvishga solmasligi kerak. Chunki farzandingizga "keldi, kelyapti, keladi" kabi zamon tushunchalarini anglash va ishlatish uchun hali vaqt kerak.') WHERE id = '0ce06f10-94aa-437c-be3f-bceab8e03d9c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bu davrda turli buyum va hodisalarga nisbatan ayrim odatlar yoki takrorlanuvchi qiziqishlarni shakllantirishi mumkin. Bir xil multfilmni qayta-qayta ko‘rish, bir xil ertakni tinglash, sevimli o‘yinchog‘i yoki ko‘rpachasini hamma joyga olib borish 2-5 yoshli bolalarda tez-tez uchraydi. Bu yoshdagi bolalarda takrorlanuvchi xatti-harakatlar va odatlarning kuzatilishi normal rivojlanish jarayonining bir qismidir. Bolaning doimo aynan bir xil stakandan suv ichishni istashi undagi sevimli multfilm qahramoni tasviri yoki u yoqtiradigan rang bilan bog‘liq bo‘lishi mumkin. Bunday holat takrorlanganda ota-onalar ba’zan xavotirlanadilar, ammo rivojlanishga xos bu xatti-harakatlar odatda 5 yoshdan keyin kamaya boshlaydi.') WHERE id = '2a252a94-6183-4f26-b967-1e55f04f7793';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ishtahasizlik va ovqat tanlash eng yuqori darajaga yetadigan bu davrda ayrim ota-onalar farzandining ortiqcha vazni haqida tashvishlanishi mumkin. Mutaxassislar, agar vazn haqiqatan ham xavfli darajada bo‘lmasa, bu davrda bolalarga ozish uchun qat’iy parhez va dasturlarni tavsiya etmaydi. Chunki haddan tashqari cheklovchi parhezlar sinchkovlik bilan nazorat qilinmasa, o‘sayotgan bolalarning rivojlanishini sekinlashtirishi va boshqa sog‘liq muammolariga olib kelishi mumkin. Mutaxassislar ortiqcha vaznli bolalar uchun odatda ovqatlanish odatlarini yaxshilash va jismoniy faollikni oshirishni tavsiya etadilar. Bunda maqsad bo‘y o‘sishi, suyak va mushaklar rivojlanishi davom etayotgan paytda yog‘ to‘qimasining kamayishiga erishishdir. Bu jarayon albatta mutaxassis nazorati ostida olib borilishi kerak. Ota-onalar o‘z parhezini bolaga tatbiq etish xatosiga yo‘l qo‘ymasliklari lozim. Maqsadlar bolaning yoshi va rivojlanishiga mos ravishda shifokor tomonidan belgilanishi kerak.') WHERE id = '12d89f35-8555-4479-a974-3feb5d64d6dc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'O‘yin o‘ynash har bir bola uchun muhim rivojlanish vositasidir. O‘yinlar va o‘yinchoqlar kuch-g‘ayratini sarflashga ehtiyoj sezadigan farzandingizning ham jismoniy, ham aqliy rivojlanishi uchun katta ahamiyatga ega. O‘g‘il yoki qiz bo‘lishidan qat’i nazar, har bir bola yaxshi ko‘radigan uycha o‘yini farzandingiz hozirgi yoshida uyda o‘ynashi mumkin bo‘lgan eng foydali mashg‘ulotlardan biridir. Uycha o‘yinida turli rollarga kirish va shu rol talabiga muvofiq harakat qilish farzandingizning aqliy rivojlanishini qo‘llab-quvvatlash bilan birga, ruhiy jihatdan yengillashishiga ham yordam beradi. Bu o‘yin farzandingizga o‘zini tanish imkonini beradi va uni kelajakdagi muhim rollarga tayyorlaydi. O‘yin davomida farzandingiz kundalik hayotda orttirgan tajribalaridan foydalanadi, shuningdek, xayolot olami va his-tuyg‘ularini o‘yinga ko‘chiradi. Shu tariqa u o‘zini boshqa birovning o‘rniga qo‘yishni, mas’uliyatni o‘z zimmasiga olishni, his-tuyg‘ularini ifodalashni va oiladagi tashvishlarini bo‘lishib, yengillashishni o‘rganadi. Rollarni ijro etish jarayonida uning o‘zini ifodalash va ravon gapirish qobiliyati rivojlanib, so‘z boyligi ortadi. Shu sababli, uycha o‘ynash farzandingiz bilan birga bajarishingiz mumkin bo‘lgan eng yaxshi mashg‘ulotlardan biridir.') WHERE id = '7052912b-8ae5-42fd-9ebb-4b3f1ca4c1a8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingiz atrofidagi boshqa bolalarni urish, tishlash yoki o‘yinchoqlarni sindirish kabi xatti-harakatlarni namoyon qilayotganini ko‘rsangiz, bu masalada qat’iy turishingiz kerak. Qisqacha aytganda, "Boshqalarga va o‘zingga zarar yetkazish mumkin emas!" deb ayta olish va bu qoidadan chekinmaslik juda muhim. Farzandingizga umumiy qoidalarda erkinlik bersangiz ham, zo‘ravonlikka oid taqiqlarni belgilashdan tortinmasligingiz kerak. Chunki faqat shu yo‘l bilan farzandingiz boshqalarni hurmat qilishni, ijtimoiy qoidalar mavjudligini va ularga rioya etish muhimligini anglaydi. E’tibor berishingiz kerak bo‘lgan eng muhim jihat shuki, farzandingizning xatti-harakati qanchalik noto‘g‘ri bo‘lmasin, uni hech qachon xatosi uchun jazolamasligingiz kerak. Masalan, u tishlaganda qanchalik og‘riq his qilganingizni ko‘rsatish uchun siz ham uni tishlashingiz to‘g‘ri yechim emas. Aksincha, bunday noto‘g‘ri yondashuv farzandingizning xatti-harakatini yanada yomonlashtirishi mumkin. Eng yaxshisi, unga urish yoki tishlash juda og‘riqli ekanini so‘z bilan tushuntirish va o‘z xatosini anglab yetishi uchun imkon yaratishdir.') WHERE id = '1d14becf-2063-41bf-9be0-72a1734a9d5c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz baliqni yoqtirmasa, buning asosiy sababi, boshqa bolalarda bo‘lgani kabi, uning hididan bezovta bo‘lishidir. Chunki bolalar ta’mni qabul qilishda maza, hid va ko‘rinishni birgalikda baholaydilar. Bundan tashqari, baliq iste’mol qilgandan keyin yuzaga keladigan ayrim noqulayliklar ham chaqalog‘ingizning baliqdan voz kechishiga sabab bo‘lishi mumkin. Baliq allergiyasi o‘rtacha har 200 kishidan birida uchrasa-da, bolalarda bu ko‘rsatkich ancha yuqori. Baliq allergiyasining belgilariga ko‘ngil aynishi, qusish, ich ketishi, oshqozon spazmlari, xirillab nafas olish, burun oqishi, terining qizarishi va shishishi kiradi. Allergiya keltirib chiqarishi mumkin bo‘lgan dengiz mahsulotlariga skumbriya, tunets balig‘i, langust, sardina, krevetka, krab, shilliqqurt va midiya kiradi. Shuningdek, baliq pishirilayotganda mayda oqsil zarrachalari bug‘lanishi sababli, hatto bu bug‘ ham allergiyasi bor bolalarda reaksiyani qo‘zg‘atishi mumkin.') WHERE id = 'ac158c46-bbd5-4329-8d4c-0e71f3f20b42';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Raqs chaqalog‘ingizning hozirgi rivojlanish davri uchun ajoyib mashg‘ulotdir. Raqsga tushish nafaqat sport, balki san’at hamdir. U bolada uyg‘unlik, ritm va muvozanat hissini shakllantiradi. Bundan tashqari, raqs chaqalog‘ingizga his-tuyg‘ularini qanday ifodalashni o‘rgatadi, zo‘riqishni kamaytirishga yordam beradi va stressga qarshi kurashish qobiliyatini oshiradi. Raqsning eng muhim foydalaridan biri uning jismoniy rivojlanishga ijobiy ta’siridir. Raqsga tushadigan chaqalog‘ingizning tanasi yanada egiluvchan, kuchli va nafis bo‘ladi. Raqs harakatlari mushaklarni cho‘zgan holda bajarilgani uchun suyak-mushak tizimi va tana tuzilishining yanada to‘g‘ri, chiroyli shakllanishini ta’minlaydi. Kelajakda yuzaga kelishi mumkin bo‘lgan qomat buzilishlarining oldini olishda raqsning o‘rni katta. Shuningdek, yassi oyoqlik, yurayotganda oyoqlarning ichkariga qiyshayishi va umurtqa pog‘onasi egriliklarining oldini olish uchun raqs juda foydali. Bularning barchasini hisobga olib, kun davomida chaqalog‘ingizni mos musiqa sadolari ostida raqsga tushishga undashingiz mumkin.') WHERE id = '068ebdad-194f-4a1d-9270-77ef045bd6c5';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz hozir sog‘lom ovqatlarga ishtahasi yo‘q, ammo shirin va tayyor qadoqlangan mahsulotlarga juda qiziqadigan davrda. Deyarli barcha bolalar bunday mahsulotlarni juda yaxshi ko‘radi va siz cheklov qo‘ymasangiz, ularni me’yoridan ortiq iste’mol qilishi mumkin. Maktabgacha yoshdagi bolalarda ovqat tanlash juda keng tarqalgan va tabiiy holat ekanini unutmang. Ya’ni, bu borada siz yolg‘iz emassiz, siz bilan bir xil hislarni boshdan kechirayotgan ota-onalar juda ko‘p. Shu sababli, bu davrda chaqalog‘ingizni sog‘lom va muvozanatli oziqlantirish sizdan biroz sabr va mehnat talab qiladi. Agar chaqalog‘ingizning bu yoshdagi ovqat borasidagi injiqligiga yon bersangiz, u bu muammoni yenga olmaydi va voyaga yetgan davridagi ovqatlanish muammolariga zamin yaratiladi. Bu davrda unga imkon qadar turli xil oziq-ovqatlarni taklif qilishingiz va yangi ta’mlarni tatib ko‘rishga undashingiz kerak.') WHERE id = '57a840ed-dc9e-4918-86ea-a8434bde9387';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Muntazam harakat qilish nafaqat kattalar, balki bolalar uchun ham juda muhim. Tadqiqotlar shuni ko‘rsatadiki, kun davomida faol bo‘lgan va sport bilan shug‘ullanadigan bolalarning kasallanish xavfi 57% ga kamayadi. Shu bilan birga, muntazam harakat qiladigan bolalar yuqori nafas yo‘llari infeksiyalariga kamroq chalinadi va shamollaganda tezroq sog‘ayadi. Shu sababli, chaqalog‘ingiz bilan birgalikda bajarishingiz mumkin bo‘lgan mashg‘ulotlar katta ahamiyatga ega. Jismoniy faollik farzandingizning uyqu sifatini ham yaxshilaydi. Masalan, fasldan qat’i nazar, ob-havoga mos kiyimda parkda o‘ynash ham maroqli, ham foydali jismoniy mashg‘ulotdir. Oilaviy sayrlar, quvlashmachoq o‘yini, voleybol, futbol va suzish chaqalog‘ingiz uchun juda foydali.') WHERE id = 'b3c41e3b-28a4-4d9f-a7f2-3d2269ca1f16';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Mutaxassislar 2-3 yoshli bolalarning ovqatlanish dasturini rejalashtirishda Amerika Diyetologlar Assotsiatsiyasining oziq-ovqat piramidasidan foydalanadilar. Ushbu piramidaga ko‘ra, bolalar iste’mol qilishi kerak bo‘lgan 5 ta asosiy guruh mavjud. 1-guruh: don mahsulotlari va non; 2-guruh: sabzavot va mevalar; 3-guruh: sut va yogurt; 4-guruh: go‘sht, tuxum va dukkaklilar; 5-guruh esa shakar va yog‘lardir. Farzandingizning kunlik me’yori quyidagicha bo‘lishi kerak: 1-guruhdan 6 porsiya (yarim bo‘lak non, bir kichik kosa palov yoki makaron); 2-guruhdan 5 porsiya (sabzavot sharbati, yangi meva); 3-guruhdan 3 porsiya (yarim kosa yogurt yoki sut, gugurt qutisi kattaligidagi pishloq); 4-guruhdan 2 porsiya (1 osh qoshiq tovuq go‘shti, baliq yoki go‘sht, 1 dona tuxum); 5-guruhdan esa 3-4 porsiya (kun davomida 1 choy qoshiq o‘simlik yog‘i yoki sariyog‘).') WHERE id = '962b4a12-0b09-4183-b941-3cfed8499be2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '“Farzandingiz juda odobli ekan!” degan gapni eshitish har bir ota-ona uchun yoqimli. Hurmatni biladigan bolani tarbiyalash sabr-toqat, namuna bo‘lish va maqtovni talab qiladigan jarayondir. Agar farzandingiz hurmatli bo‘lishini istasangiz, avvalo o‘zingiz unga namuna bo‘lishingiz kerak. Chaqalog‘ingiz odobni go‘dakligidanoq atrofdagilardan o‘rganadi. Masalan, qo‘lingizdagi narsani tortib olgan chaqalog‘ingizga “Iltimos” deb murojaat qilishingiz yoki sochingizni tortganida “Og‘riyapti” deb, qo‘lini muloyimlik bilan bo‘shatishingiz unga mehribonlikni o‘rgatadi. Chaqalog‘ingiz o‘ziga hurmat bilan munosabatda bo‘linayotganini his qilishi kerak. Uning gapini bo‘lmay, ko‘zlariga qarab tinglash, xonasiga eshikni taqillatib kirish va qaror qabul qilishda uning ham fikrini so‘rash bunga eng yaxshi misollardir. Xatti-harakatlaringizda izchil bo‘ling; bir vaziyatga goh qattiqqo‘l, goh yumshoq munosabat bildirish farzandingizning sizga bo‘lgan ishonchi va hurmatiga putur yetkazishi mumkin.') WHERE id = 'faf2efdc-0dd3-4966-8ab3-9c85e83a2de6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingiz tez-tez qo‘rqinchli tushlar ko‘rayotganini, hatto qichqirib uyg‘onayotganini sezishingiz mumkin. Bunday vaziyatda darhol uning yoniga borib, tinchlantirishingiz va qo‘rquvlari haqida suhbatlashishingiz kerak. Agar bu holatlar tez-tez takrorlanmasa, jiddiy xavotirga o‘rin yo‘q. Ammo ular muntazam davom etsa, kun davomida bunga sabab bo‘lishi mumkin bo‘lgan omillarni (masalan, zo‘ravonlik bilan bog‘liq hodisaga guvoh bo‘lishi, yiqilish oqibatidagi jarohat yoki televizorda ko‘rgan qo‘rqinchli qahramonlar) aniqlashingiz va zarurat tug‘ilsa, mutaxassisga murojaat qilishingiz lozim. Farzandingiz kun davomida kimlar bilan muloqot qilayotgani va nimalarni tomosha qilayotganini diqqat bilan kuzatish muammoni hal qilishda sizga yordam beradi. Sababini aniqlaganingizdan so‘ng, qo‘rqinchli tushlar asta-sekin yo‘qolayotganini ko‘rasiz.') WHERE id = 'b61f296a-4531-4652-8575-c61cd39dfd62';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bilan birga 2.5 yilni ortda qoldirdingiz, tabriklaymiz! Biroq 2.5 yosh yangi bir bosqich — “3 yosh sindromi”ning boshlanishi ham bo‘lishi mumkin. Endi uning har bir masala bo‘yicha o‘z fikri bor va u o‘zini namoyon etishni, maqtovga sazovor bo‘lishni istaydi. Bu rivojlanishning tabiiy bosqichidir, shuning uchun u bilan o‘jarlashmang. Buni g‘olib chiqish kerak bo‘lgan kurash deb bilish befoyda. Qiyin paytlarda farzandingizning e’tiborini boshqa tomonga yo‘naltirishga harakat qiling va jahli bosilishini sabr bilan kuting. Qattiq jazolardan saqlaning, chunki bu yoshda his-tuyg‘ular juda o‘zgaruvchan bo‘ladi: bola bir zumda yig‘lab, keyingi zumda tinchlanishi mumkin. Uni tinchlantirish uchun e’tiborini boshqa qiziqarli mashg‘ulotga jalb qilish endi avvalgidan osonroq.') WHERE id = '639bc96b-c7fc-4373-a80d-f5910cdd0c67';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning bu davrdagi rivojlanish xususiyatlari va o‘zgarishlari boshqa bolalarnikidan farq qilsa-da, umuman olganda, oldindan taxmin qilish mumkin bo‘lgan yo‘nalishda kechadi. Kattalar sifatida bu o‘zgarishlardan xabardor bo‘lishingiz xavotiringizni kamaytirish bilan birga, farzandingizni qo‘llab-quvvatlashingiz uchun ham juda muhimdir. 2.5 yoshda farzandingizda begona odamlardan qo‘rqish va tashlab ketilish qo‘rquvi kuchli namoyon bo‘lishi mumkin. Siz uni tashlab ketishingizdan qo‘rqib yoningizdan uzoqlashishni istamasa-da, ayni paytda tengdoshlari bilan vaqt o‘tkazishni ham xohlashi mumkin. Chunki endi u o‘zi yoqtiradigan va yaqin bo‘lishni istaydigan tengdoshlarini ajrata oladi. Biroq bunday ikkilanish holatida u har qachongidan ham o‘jarroq xatti-harakatlarni namoyon qilishi mumkin. Bunday vaziyatlarda imkon qadar vazmin bo‘lishingiz, bu davr o‘tkinchi ekanini bilishingiz va doimo uning yonida ekaningizni his qildirishingiz juda muhim.') WHERE id = '68cb6aa4-e74d-46fc-9a61-c95e7e0181e6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bola organizmini kattalar organizmidan ajratib turadigan eng asosiy xususiyat — uning doimo o‘sish va rivojlanish jarayonida bo‘lishidir. Biroq bu rivojlanish har bir bolada turlicha kechadi. Masalan, 1-2 yosh oralig‘ida o‘sish sur’ati biroz sekinlashadi, 2-10 yosh oralig‘ida esa barqaror davom etadi. O‘smirlik davrida yana jadal o‘sish bosqichi boshlanadi. Qisqacha aytganda, farzandingizning hozirgi davri bo‘y o‘sishi va vazn ortishi biroz barqarorlashadigan bosqichdir. Barcha ekologik va irsiy omillar ta’sirida bu yoshdagi bolalarning vazni va bo‘yi bir-biridan ancha farq qilishi mumkin. Masalan, 2.5 yoshli bolaning vazni 9.900 gramm ham, 16.500 gramm ham bo‘lishi mumkin. Farzandingiz uchun eng muhimi — uning vazni xavfsiz diapazon deb ataladigan ushbu me’yorlar doirasida bo‘lishidir.') WHERE id = '02cec2db-f46a-42b8-bf27-568e1890c0f7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bu oyda A gepatitiga qarshi vaksinaning takroriy dozasini olishi kerak bo‘lishi mumkin. A gepatiti shu nomdagi virus yuqishi natijasida yuzaga keladigan jigar infeksiyasidir. Ushbu kasallikning tarqalishi ijtimoiy-iqtisodiy sharoit va yashash hududiga qarab farq qilsa-da, u butun dunyoda keng tarqalgan. Kasallik kuzda va qishning dastlabki oylarida ko‘proq uchraydi. A gepatitiga qarshi vaksina ushbu kasallikning oldini olishning eng samarali usulidir. Tibbiy tadqiqotlar ommaviy emlash tufayli yillik kasallanish holatlari keskin kamayganini ko‘rsatadi. Shu jihatdan, vaksina farzandingizni A gepatitidan himoya qilishda juda muhim ahamiyatga ega.') WHERE id = 'df299f90-e498-4bad-8aac-c9ce133896e2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizni ovqatlantirishdagi asosiy maqsadingiz organizmning vitaminlar, minerallar, oqsillar, uglevodlar va yog‘larga bo‘lgan ehtiyojini qondirishdan iborat bo‘lishi kerak. 2-6 yosh — bolada yetarli va muvozanatli ovqatlanish tushunchasi shakllanadigan davrdir. Shunga qaramay, ijtimoiy faoliyat va bolaning haddan tashqari serharakatligi ovqatlanish jarayonini biroz qiyinlashtirishi mumkin. Bu yoshda farzandingizning o‘jarlik qilishi ham duch kelishingiz mumkin bo‘lgan qiyinchiliklardan biridir. Bu yerda e’tibor berish kerak bo‘lgan jihat — bolada maktab yoshigacha to‘g‘ri ovqatlanish odatlarini shakllantirishdir. Chunki bu yoshda shakllangan ta’mga oid tanlovlar va odatlar uning butun kelgusi hayotiga ta’sir qiladi. Keyinchalik bu odatlarni o‘zgartirish juda qiyin. Unutmang, katta yoshda vazn va salomatlik bilan bog‘liq muammolarga duch keladigan ko‘plab insonlarda buning ildizi bolalikda shakllangan noto‘g‘ri ovqatlanish odatlariga borib taqaladi.') WHERE id = 'fe0a2002-9184-44fe-a34f-37af62aa35fd';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz o‘yin orqali tabiiy ravishda, mustaqil va zavqlanib yangi ma’lumotlarni o‘rganadi. 2.5 yoshli chaqalog‘ingiz endi maqsadga yo‘naltirilgan xatti-harakatlarni namoyon eta boshlaydi va uning diqqatini jamlash davomiyligi avvalgi yillarga qaraganda uzoqroq bo‘ladi. U bilan faol muloqot qilishingiz birga o‘tkazadigan vaqtingizni yanada sifatli qiladi. Masalan, chaqalog‘ingiz bu davrda bir mashg‘ulotga taxminan 10 daqiqa davomida diqqat qarata oladi. 2.5 yoshli bolalar atrofdagi insonlar bilan birga faoliyat olib borishni yaxshi ko‘radilar. Biroq bu davr parallel o‘yin bosqichi ekanini unutmasligingiz kerak. Parallel o‘yin davri — bola tengdoshlari yoki kattalar bilan bir muhitda, bir xil o‘yinchoqlar bilan vaqt o‘tkazishdan zavqlanadigan, ammo hali ular bilan o‘zaro hamkorlikdagi o‘yinni tashkil qilmaydigan bosqichdir. Shu sababli, ayniqsa, tengdoshlari bilan o‘yinchoqlarini bo‘lishishda qiyinchiliklar yuzaga kelishi mumkin.') WHERE id = 'ba0dbae3-755a-40e2-a8cd-2a1d2c900c58';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingizga miqdor va oziq-ovqat xilma-xilligi jihatidan nimalar taklif qilish borasida savollaringiz bo‘lishi mumkin. Masalan, nonushtaga farzandingizga ustiga oq pishloq surtilgan non va qaynatilgan tuxum yoki pekmez va tahin surtilgan 1 bo‘lak butun donli bug‘doy noni hamda oq pishloq berishingiz mumkin. Nonushtadan taxminan 1-1.5 soat o‘tgach, unga yangi siqilgan, shakarsiz meva sharbati yoki 1 stakan sut ichirishingiz mumkin. Tushlikdan taxminan 1 soat oldin va 1 soat keyin unga meva yoki qatiqdan birini berishingiz rivojlanishi uchun juda muhimdir. Tushlikda 1 kosa sabzavotli taom yoniga yarim kosa palov yoki butun donli bug‘doy unidan tayyorlangan makaron yaxshi tanlov bo‘lishi mumkin. Kechki ovqatda o‘zingiz uchun pishirgan deyarli barcha go‘shtli-sabzavotli taomlarni farzandingizga ham berishingiz mumkin. Agar tushlik yoki kechki ovqatda go‘sht, tovuq, baliq kabi oqsil manbalari iste’mol qilinmagan bo‘lsa, kechki ovqatdagi sabzavotli taom o‘simlik oqsiliga boy bo‘lishi juda muhimdir.') WHERE id = 'a05e1296-3724-4f4f-b2bb-e078e101f1c5';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz 2.5 yoshda bo‘lgan bu davrda uning muloqot qilish qobiliyati yana jadal rivojlana boshlaydi. Bu davrda til rivojlanishi uchun farzandingiz muloqot qilish, boshqalarning e’tiborini jalb etish, istaklari, his-tuyg‘ulari va fikrlarini bo‘lishishga ehtiyoj sezadi. Hozirgi davrda bolangiz taxminan 200-250 ta so‘zni ayta olishi va so‘zlarni birlashtira boshlashi kutiladi. Ayniqsa, 3 yoshga yaqinlashadigan keyingi 1-2 oy davomida uning so‘z boyligi ancha kengayishi va 3-4 so‘zdan iborat gaplar tuza boshlashi kerak. U tushunadigan so‘zlar soni esa ayta oladigan so‘zlari sonidan ancha ko‘p bo‘ladi. Bu yoshdagi bolalar telegrafik nutq deb ataladigan, ya’ni «Dada to‘p o‘yna» kabi faqat asosiy ma’noni ifodalovchi qisqa gaplardan iborat nutq uslubidan foydalanishlari mumkin. Shu sababli, farzandingizning nutqini rivojlantiruvchi mashqlarni davom ettirar ekansiz, hozircha undan kognitiv jihatdan qila oladiganidan ortig‘ini kutmaslik tavsiya etiladi.') WHERE id = 'e211eecc-39db-4566-ab98-8e17bb940902';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar bu davrda ko‘pincha zararli oziq-ovqatlar va fastfud bilan tanishadilar. Ishtahasi yo‘q bolalarda bu holat rivojlanishning kechikishiga, ishtahasi yaxshi bolalarda esa semirishga sabab bo‘lishi mumkin. Agar farzandingiz qadoqlangan tayyor mahsulotlarga qiziqsa va ularni doimiy ravishda so‘rasa, sog‘lomroq va mazali muqobillarini topishingiz juda muhimdir. Masalan, chipsni yaxshi ko‘radigan bola uchun kartoshkani yupqa to‘g‘rab, ziravorlar bilan ta’mlantirib, duxovkada pishirishingiz mumkin. Bundan tashqari, bola yetarli miqdorda don mahsulotlari va mevalar iste’mol qilsa, bunday zararli oziq-ovqatlarga bo‘lgan istagi kamayadi. Masalan, don mahsulotlarini sho‘rvalarga qo‘shish, sut yoki qatiq bilan birga berish mumkin. Taom yoniga oz miqdorda butun donli bug‘doydan tayyorlangan palov yoki makaron ham tortish mumkin. Bu mahsulotlar farzandingizning zararli oziq-ovqatlarga bo‘lgan qiziqishini kamaytirish bilan birga, uning sog‘lom o‘sishi va kasalliklardan himoyalanishi uchun ham muhimdir.') WHERE id = 'dea526e3-269a-402d-8089-37a01ca0586f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Kattalar va bolalar dunyosi o‘rtasidagi eng asosiy farqlardan biri his-tuyg‘ularni anglash va baholash usulidir. Maktabgacha yoshdagi farzandingiz siz va atrofidagi insonlarning yuz ifodalari hamda noverbal ishoralari orqali his-tuyg‘ularni juda yaxshi tushuna oladi. Farzandingizning turli his-tuyg‘ular haqidagi tushunchalarni yaxshiroq o‘rganishini qo‘llab-quvvatlash uchun uyda bajarishingiz mumkin bo‘lgan ajoyib Montessori mashg‘uloti bor. Buning uchun kerakli jihozlar: karton, qaychi va rangli flomasterlar. :) Tuxum, kvadrat yoki uchburchak shaklida kesilgan, taxminan 10 sm o‘lchamdagi kartonlarga rangli flomasterlar yordamida og‘iz va shu og‘iz ifodasiga mos qoshlarni chizishingiz kerak. Masalan, tishlarini qisib turgan jahldor og‘izni chimirilgan qoshlar bilan, hayratlangan og‘izni esa yuqoriga ko‘tarilgan qoshlar bilan to‘ldirishingiz kerak. Keyin kartonni og‘iz va qoshlar o‘rtasidan to‘liq ajraladigan qilib qaychi bilan kesishingiz kerak. Shundan so‘ng barcha kartonlarni aralashtirib, farzandingizning mos qosh va og‘izlarni birlashtirishini zavq bilan kuzatishingiz mumkin! :)') WHERE id = 'a9c58f85-ffb9-43bd-bd02-2e1899f70507';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz qaysi intellekt yo‘nalishlariga moyilligini aniqlash va ularni rivojlantirish uchun ayrim tavsiyalar mavjud. Ulardan eng ko‘p afzal ko‘riladigani intellekt yo‘nalishlarini rivojlantirishga qaratilgan o‘yinlar va o‘yinchoqlardir. Farzandingiz 2.5 yoshda bo‘lgan davrda u bilan turli mashg‘ulotlarni bajarib, qaysi sohaga ko‘proq qiziqishi va qaysi sohada muvaffaqiyatliroq ekanini aniqlashingiz mumkin. Masalan, yirik bo‘lakli pazllar, bir-birining ichiga joylanadigan qutilar bilan o‘ynash, ko‘chada yugurish va yo‘lda uchragan kichik to‘siqlar ustidan sakrash juda maroqli bo‘ladi. To‘p otish va tutish, qumdan shakllar yasash yoki qumga yashirilgan buyumlarni topish kabi qumli o‘yinlar ham farzandingizning intellektini rivojlantiruvchi mashg‘ulotlardir. Shubhasiz, qum bilan o‘ynash deyarli har bir bolaga yoqadigan mashg‘ulotdir. Qolaversa, qum bilan o‘ynash uchun yoz oylarini kutish shart emas. Farzandingizning bo‘yiga mos stol ustiga chetlari baland idishda toza qum qo‘yib, uning uyda ham o‘ynashi va barmoq mushaklarini mustahkamlashiga sharoit yaratishingiz mumkin.') WHERE id = '27c1de50-2c42-464a-b6bf-b96b6763bf44';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz hozir o‘sish va rivojlanish nisbatan sekinlashadigan davrda. Shu sababli u ayrim kunlari kamroq, ayrim kunlari esa ko‘proq ovqat yeyishi mumkin. Uni har kuni muayyan miqdorda ovqat yeyishga majburlamaslik juda muhim. Har doimgidek, bu yoshda ham chaqalog‘ingizning ishtahasini hurmat qilishingiz kerak. Ovqatni muayyan vaqtlarda berish va zararli yeguliklarga qiziqtirmaslik bolada yaxshi odatlar shakllanishi uchun muhimdir. Sog‘lom ovqatlanish odatlarini shakllantirishda ota-ona sifatida izchil bo‘lishingiz va yaxshi namuna ko‘rsatishingiz eng asosiy shartdir. Qisqasi, o‘zingiz shokolad yeb, bolangizni nonushtada tuxum yeyishga majburlasangiz, bundan hech qanday foyda bo‘lmaydi. Shuningdek, ovqat yeyishni doimiy talab qilish, mukofot yoki jazo kabi qoidalarni qo‘llash chaqalog‘ingizning kelajakdagi ovqatlanish xulqiga salbiy ta’sir qiladi.') WHERE id = '0ff6de72-1685-4d41-9fb9-6bad83bfb59a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ijodkorlik — insonning o‘zini ifoda etishidagi eng erkin shakldir. Chaqalog‘ingiz uchun ham o‘zini erkin va ochiq ifoda etishdan ko‘ra yoqimliroq narsa yo‘q. Farzandingiz tug‘ilgan paytidan boshlab atrofini doimiy ravishda kuzatishi, tinglashi va turli tajribalar qilib ko‘rishini payqagansiz. Bu davrda esa har bir yangi tajriba va kashfiyot uni yanada hayajonlantiradi. Bu tug‘ma qobiliyatni to‘g‘ri yondashuv bilan qo‘llab-quvvatlash bolangizning butun umri davomida ijodiy fikrlashida hal qiluvchi omil bo‘ladi. Buning uchun uning barcha urinishlarini qo‘llab-quvvatlashingiz kerak. Chaqalog‘ingiz mukammal natijaga erishishi uchun vaqt kerak bo‘lishi mumkin, ammo eng muhimi — uning mehnatini qadrlashingiz va maqtashingizdir. Bu bolaning o‘ziga bo‘lgan ishonchini mustahkamlaydi va iste’dodlarini yuzaga chiqaradi.') WHERE id = '4508e3d7-7e76-4f2d-8b22-fd23d4a47309';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tadqiqotlar har bir bolaning o‘ziga xos o‘rganish usuli va salohiyati borligini ko‘rsatadi. Chaqalog‘ingiz ulg‘aygani sari sizning yordamingiz bilan yangi ma’lumotlarni tezroq o‘zlashtirishi mumkin. Biroq bunda eng muhim jihat — bolada o‘rganishga ishtiyoq va qiziqish uyg‘otishdir. Masalan, unga taklif qilgan variantlaringiz orasidan mustaqil qaror qabul qilishiga imkon berishingiz mumkin. Uning yutuqlarini emas, balki qilgan sa’y-harakatlarini maqtashingiz kerak. Bergan savollariga zerikmasdan va «hali kichkinasan» demasdan javob berish eng ko‘p e’tibor qaratishingiz lozim bo‘lgan jihatlardan biridir. Bu jarayonda bolangizning yiqilishiga, kiyimlari kir bo‘lishiga yoki o‘yinchoqlarini qismlarga ajratib, qayta yig‘ishiga ruxsat berishingiz kerak. Uning xatti-harakatlari haqidagi suhbatlarni har ikki tomon ham xotirjam bo‘lgan paytda o‘tkazishingiz lozim. Eng muhimi esa, chaqalog‘ingizni hech qachon tengdoshlari bilan taqqoslamang.') WHERE id = 'cb11e36c-39a0-4aef-be34-9d54b22af192';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar siz ham ko‘plab onalar kabi chaqalog‘ingizning ishtahasi yo‘qligidan shikoyat qilsangiz, xavotir olmang, siz yolg‘iz emassiz! :) Ko‘plab ota-onalar bolasining ishtahasi yo‘q deb o‘ylashsa-da, aslida ularning kutganlari haqiqatdan yiroq bo‘ladi va boladan yeyishi mumkin bo‘lganidan ko‘proq ovqat talab qilishadi. Ammo chaqalog‘ingizning ishtahasi chindan ham yo‘q deb hisoblasangiz, ayrim nozik jihatlarga e’tibor berishingiz kerak. Unutmang, bolalar uchun ovqatning ta’midan ko‘ra ko‘rinishi muhimroq. Shuningdek, hid ham bolaning ishtahasiga ta’sir qiluvchi omildir. U bir-biriga aralashib ketgan ta’mlar va ko‘rinishi qorishiq ovqatlarni rad etishi mumkin. Shu sababli taom tortishda ijodkor bo‘lishga harakat qiling. Masalan, nonushtada yeyishi uchun sabzi bo‘laklarini shunchaki likopchaga terish o‘rniga, ulardan qiziqarli shakllar yasasangiz, kichkintoyingizning e’tiborini jalb qilishingizga ishonamiz! 😊') WHERE id = 'fac64036-a219-4703-b872-665eb449d5b6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz hali ham hojatxonadan foydalanish odatini to‘liq o‘zlashtirmagan bo‘lsa, sabrli bo‘lishingiz, uni boshqalar bilan taqqoslamasligingiz va jazolamasligingiz juda muhim. Mutaxassislar hojatxonaga o‘rgatish uchun eng qulay vaqt yoz oylari va 1.5 - 3 yosh oralig‘i ekanini ta’kidlashadi. Qisqasi, agar bolangizda bu odatni hali ham shakllantira olmagan bo‘lsangiz, kechikkan hisoblanmaysiz. Agar bunga erisha olmayotgan bo‘lsangiz, sabab sizga ham, bolaga ham bog‘liq bo‘lishi mumkin. Ayrim bolalar bir necha kunda o‘rgansa, boshqalari bunga qattiq qarshilik ko‘rsatishi mumkin. Ota-ona sifatidagi noto‘g‘ri yondashuvingiz kelajakda bolada jiddiy muammolarga olib kelishi mumkin. Unutmang, har bir sog‘lom bola kabi sizning kichkintoyingiz ham ertami-kechmi hojatxonadan foydalanishni o‘rganadi. Biroq noto‘g‘ri o‘rgatish usullari bolada o‘ziga ishonch, shaxsiyat va bog‘lanish bilan bog‘liq muammolarni keltirib chiqarishi mumkin.') WHERE id = 'feaefa5c-467b-473d-8593-ed69b32fa642';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'So‘nggi paytlarda sovuq muzli choylar bolalarning eng sevimli ichimliklari qatoridan joy oldi. Agar chaqalog‘ingiz ham sovuq choylarni yoqtirsa va ularni doimo ichishni istasa, bunday holat faqat sizda emasligini biling. 😊 Biroq chaqalog‘ingizning suyuqlikka bo‘lgan ehtiyojini imkon qadar suv bilan qondirish muhim. Sovuq choylarni berishda ularning tarkibidagi kofein va shakar miqdoriga e’tiborli bo‘lishingiz kerak. Chunki bunday ichimliklar bolaning asab tizimini haddan tashqari qo‘zg‘atishi va oson vazn orttirishiga sabab bo‘lishi mumkin. Kofein hatto kattalarda ham muayyan miqdordan keyin haddan tashqari sergaklikni keltirib chiqaradi. Bolalarda esa bu asabiy xurujlar, haddan tashqari harakatchanlik va uxlashga qarshilik ko‘rsatish kabi holatlarga olib kelishi mumkin.') WHERE id = '0d16f898-6bee-46b7-810a-0ae08cd779d7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizga ijtimoiy-emotsional rivojlanishning muhim qismi bo‘lgan his-tuyg‘ularni aniqlash ko‘nikmasini o‘rgatish juda muhim. Chunki his-tuyg‘ularini ijtimoiy muhitga mos tarzda ifodalay oladigan bolalarda xulq-atvor bilan bog‘liq muammolar kamroq uchraydi. Farzandingiz biror narsadan jahli chiqqanida «Juda jahlim chiqdi» deb ayta olsa, unda g‘azab portlashlari va yig‘i xurujlari yuz berish ehtimoli kamayadi. Unga his-tuyg‘ularini anglash va ifodalashga yordam berish orqali salbiy hissiyotlarni sog‘lom tarzda yengishni ham o‘rgatasiz. Bundan tashqari, emotsional rivojlanish bilan birga bolada empatiya ko‘nikmasi ham shakllanadi. Shu tariqa u yoshligidanoq atrofidagi odamlar turli vaziyatlarda turlicha his-tuyg‘ularni boshdan kechirishi mumkinligini anglaydi. Masalan, chaqalog‘ingiz o‘rtog‘ining qo‘lidan o‘yinchog‘ini olsa, uning xafa bo‘lishini bilsa, bunday qilish ehtimoli kamayadi.') WHERE id = '6f6fea86-044b-4ad1-8721-a20a4d184e96';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Har bir bola o‘ziga taalluqli qaror qabul qilinayotganda fikrini erkin bildirish huquqiga ega. Ya’ni chaqaloqning qarorlar qabul qilishda ishtirok etishi ham uning huquqi, ham rivojlanishining muhim qismidir. Qarorlar qabul qilishda qatnashadigan bolaning aqliy va ijtimoiy rivojlanishi, mas’uliyatni o‘z zimmasiga olish hamda muammolarni hal qilish ko‘nikmalari qo‘llab-quvvatlanadi. Alohida shaxs sifatida qabul qilinadigan, fikri so‘raladigan va o‘zini qadrlangan deb his qiladigan bola o‘zini yaxshiroq himoya qila oladi, e’tiborsizlik va zo‘ravonlikka duchor bo‘lish ehtimoli kamayadi. Agar buni hali boshlamagan bo‘lsangiz, chaqalog‘ingizga qarorlar qabul qilishda ishtirok etish mas’uliyatini singdirishingiz muhim. Avvalo, uni o‘z tanasi bilan bog‘liq qarorlarni mustaqil qabul qilishga undashingiz mumkin. Masalan, qarindoshlar yoki tanishlar uni o‘pishi va quchoqlashiga ruxsat berish-bermaslikni uning o‘zi hal qilishidan boshlashingiz mumkin.') WHERE id = '20007018-c312-42f8-9d7c-bba3d4a8dc28';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqning avvalgiga qaraganda kamroq ovqat iste’mol qilishi rivojlanishning tabiiy qismidir. Sizning vazifangiz esa u iste’mol qiladigan mahsulotlarni sifatli variantlar orasidan tanlashdir. Masalan, chaqalog‘ingizga beradigan oqsil va uglevodlar yuqori sifatli bo‘lishi kerak. Yuqori sifatli oqsil manbalariga tuxum, sut, qatiq, go‘shtli kotletlar va dukkakli mahsulotlar kiradi. Chaqalog‘ingiz bu mahsulotlardan kuniga 2–3 porsiya iste’mol qilishi kerak. E’tibor berishingiz lozim bo‘lgan jihat esa sut miqdoridir. U sutni juda yaxshi ko‘rgani uchun haddan tashqari ko‘p berish foydadan ko‘ra ko‘proq zarar keltirishi mumkin. Sut yoki qatiq miqdori kuniga 500 ml dan oshmasligi kerak; bunday mahsulotlarni ortiqcha iste’mol qilish qabziyatga, shuningdek, temirning so‘rilishini buzib, kamqonlikka (anemiyaga) olib kelishi mumkin.') WHERE id = 'a35dfbb5-f5f6-479e-a555-e5d0082e7b04';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Har bir bola o‘ziga xosdir. Hatto aka-uka, opa-singil yoki egizak bolalar bir uyda ulg‘aysa ham, bir-biriga to‘liq o‘xshamasligi mumkin. Buning asosiy sabablaridan biri temperament (fe’l-atvor) tushunchasidir. Temperament — chaqaloq tug‘ma ravishda ega bo‘lgan va kelajakda shakllanadigan shaxsiyatiga asos soluvchi xususiyatlardir. Masalan, ayrim bolalar sokinroq, boshqalari esa harakatchanroq va ta’sirchanroq bo‘ladi. Ayniqsa, chaqaloqlar haqida gapirganda ishlatiladigan «oson» yoki «qiyin» so‘zlari aslida bolaning temperamentini ifodalaydi. Umuman olganda, temperamentning to‘qqizta asosiy xususiyati aniqlangan bo‘lib, ular orasida faollik, kirishimlilik va moslashuvchanlik darajalari alohida ajralib turadi. Masalan, moslashuvchanlik darajasi bolaning yangi vaziyatlar va o‘zgarishlarga moslasha olish qobiliyatini ko‘rsatadi. Chaqaloq xonasi, uyi yoki maktabi o‘zgarganda bunga tez ko‘nikishi yoki ko‘nikmasligi aynan shu xususiyat bilan bog‘liq.') WHERE id = 'd7b7b77e-5570-44db-89ff-93dc046edc75';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu davrda hojatxonadan foydalanish odatini egallagan bo‘lishi yoki siz hali ham uni o‘rgatish bosqichida bo‘lishingiz mumkin. Ammo bu jarayonda deyarli barcha bolalarda uchraydigan umumiy muammo bor: qabziyat! Hojatxonaga o‘rgatish davrida bolalar tez-tez qabziyatga duch keladi. Tagligi yaqinda yechilgan chaqalog‘ingiz hojatga chiqish ehtiyojini ataylab kechiktirishi mumkin, bu esa najasning qotishiga va og‘riqli ich kelishiga sabab bo‘ladi. Og‘riq va qo‘rquv doirasi boshlanganidan keyin vaziyatni me’yorga keltirish uchun farzandingizni qattiq majburlamasligingiz kerak. Shuningdek, bu davrda bolaning najasi haqida salbiy fikr bildirish to‘g‘ri emas. Chunki bu yoshdagi bola uchun uning najasi juda qadrli bo‘lib, uni o‘z tanasining bir qismi deb qabul qiladi. Hojatga chiqayotganida go‘yo tanasining bir qismi uzilib ketayotgandek his qilishi mumkin.') WHERE id = '8cd65094-234a-43ba-9216-79ad31e952d9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ovqatlanish vaqtlarining muntazam bo‘lishi chaqalog‘ingizga singdirishingiz mumkin bo‘lgan eng muhim odatlardan biridir. Biroq tartib bilan birga porsiyalar miqdori ham muhim. Bu davrda farzandingizga yeya oladigan miqdorda kichik porsiyalar berishingiz va tugata olmaydigan darajada ko‘p ovqat solmasligingiz kerak. Agar chaqalog‘ingizning ishtahasi juda past bo‘lsa, o‘sishi va rivojlanishi me’yorda davom etayotgan ekan, qancha yeyishni uning o‘zi hal qilishiga imkon bering. Taomlarni sog‘lom usullarda tayyorlash juda muhim. Achchiq va ziravorli mahsulotlardan, shuningdek, ovqatni haddan tashqari issiq yoki sovuq holda berishdan saqlanishingiz kerak. Ijtimoiy muhiti kengayib borayotgan chaqalog‘ingiz ba’zan nosog‘lom mahsulotlar bilan tanishishi mumkin. Bunda asosiy maqsadingiz bunday mahsulotlardan imkon qadar uzoq turish va sog‘lom ovqatlanish tartibini saqlash bo‘lishi kerak.') WHERE id = '16c8ff33-deb6-4f40-89a3-c531e7b4cb9c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Uyqu chaqalog‘ingizning sog‘lom rivojlanishi uchun har qanday yoshda hayotiy ahamiyatga ega. Chunki o‘sish gormoni chaqalog‘ingiz uxlayotganida ajralib chiqadi. 2 yoshdan keyin kunduzgi uyqu kamaygan bo‘lsa-da, tungi uyquga ehtiyoj ortadi. Bu bosqichda kechasi uzluksiz 11 soat, kunduzi esa 1-1,5 soat uxlash yetarli. 2 yosh inqirozi tugadi deganingizda boshlanadigan 3 yosh inqirozi sababli farzandingiz biroz qaysar bo‘lib, uxlashni istamay qarshilik ko‘rsatishi mumkin. U uxlash vaqtini kechiktirishga uringanida, qat’iy ekaningizni bildiring, ammo haddan tashqari qattiqqo‘l bo‘lmay, biroz yon berishingiz ham mumkin.') WHERE id = '4051aaec-c1ae-4638-bc35-ce5ea1cf068b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Nutq ko‘nikmalari rivojlanayotgan chaqalog‘ingizni tinglash va o‘z fikrlarini ifodalashiga ko‘maklashish kerak. Nima uchun u yoki bu ishni qilayotganini tushunmaydigan bolalar qarorlar qabul qilishda ishtirok eta olmaydi. Hatto eng kichik qarorlar bo‘yicha ham unga tushuntirish berishingiz, sabablarini izohlashingiz va his-tuyg‘ulari haqida samimiy so‘rashingiz juda muhim. Uni tinglashingiz farzandingizga o‘zini qadrlangan deb his qilishiga yordam beradi va o‘ziga bo‘lgan ishonchini oshiradi. U istagan hamma narsaning imkoni bo‘lmasa ham, buning sababini unga tushuntiring. Unutmang, farzandingizni tinglaganingiz va qarorlarda ishtirok etishini qo‘llab-quvvatlaganingiz sari u mustaqil hayot kechira oladigan shaxs bo‘lib ulg‘ayadi.') WHERE id = '0ce591a9-3ab7-4fd5-aaf6-d14c88201ae3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '24 oylikdan boshlab bolalar tobora mustaqil bo‘la boshlaydi. 2,5 yosh davrida chaqalog‘ingiz oilada o‘zini ko‘proq mustaqil shaxs sifatida ko‘rsatishni istaydi. Bu mustaqillik hissi uning ovqatlanish odatlariga ham ta’sir qiladi. Bu davrda farzandingiz ta’mi yoqmagan taomlarni yemaslikka qaysarlik qilishi yoki muayyan bir mahsulotga haddan tashqari qiziqib qolishi mumkin. Agar farzandingiz talab qilayotgan mahsulot zararli bo‘lsa, unga tanlash imkonini bering. Masalan: Sabzavotli taomni yeb bo‘lganingdan keyin kartoshka fri yeyishing mumkin, kabi jumlalar bilan uning istagini ham inobatga olishingiz, ham foydali ovqatlanishini ta’minlashingiz mumkin.') WHERE id = '158b48bc-de87-4a18-8590-049c1345f651';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingizga baxt, qayg‘u, g‘azab va qo‘rquv kabi asosiy his-tuyg‘ularni nomlashni o‘rgatishingiz kerak. Keyin Baxtli bo‘lganingda nimalarni his qilasan? yoki Jahling chiqqanida nimalarni his qilasan? kabi savollar berib, bu iboralar uning xayolida nimalarni uyg‘otishini tushunish uchun rasm chizishini yoki gapirib berishini so‘rashingiz mumkin. Farzandingizdan har kuni Bugun o‘zingni qanday his qilyapsan? yoki Bugun o‘zingni qanday his qilding? deb so‘rashingiz mumkin. U ifodalagan his-tuyg‘u haqida suhbatlashishingiz ham juda muhim. Masalan: Seni nima xursand qildi?, Seni nima xafa qildi? yoki Nima boshqacha bo‘lganida, o‘zingni yaxshiroq his qilarding? kabi savollar bu borada yordam berishi mumkin. Shu o‘rinda har bir his-tuyg‘uga o‘z hayotingizdan misol keltirib, unga yordam berishingiz mumkin. Ammo unutmang, noxush vaziyatlarni yengish usullaringiz va odatlaringiz farzandingiz uchun namuna bo‘ladi. Agar siz jahlingiz chiqqanida baland ovozda baqirsangiz, his-tuyg‘ularingizni ifodalamay qo‘ysangiz yoki biror buyumni yerga otib munosabat bildirsangiz, farzandingizdan his-tuyg‘ularini so‘z bilan ifodalashi va salbiy hissiyotlarni to‘g‘ri yengishini kutish o‘rinli bo‘lmaydi.') WHERE id = '0daa42c4-6bd6-49b7-8345-003a12087e4e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Texnologiyalar davrida bolangizni texnologiyadan butunlay uzoq tutish mumkin emas. Biroq ma’lum vaqtlarda texnologik qurilmalardan, zarur bo‘lsa, butun oila bilan birga tanaffus qilishni o‘rganishingiz kerak. Televizor, mobil telefonlar, kompyuterlar – bularning barchasi juda qiziqarli, ammo bolangizning ijodkorligi uchun juda kam imkon qoldiradi. Farzandingiz ijodkorlik qilishi va xayol surishiga vaqt ajratishi uchun bu qurilmalarni ma’lum muddatga o‘chirishingiz kerak. Masalan, bolangizga "Osmondagi bulut yoki devordagi soya nimaga o‘xshaydi?" kabi tasavvurni ishga solishni talab qiladigan savollar berishingiz mumkin. O‘yin vaqtida uni o‘yinchoqlar yoki buyumlardan odatdagi vazifasidan boshqacha tarzda foydalanishga undashingiz mumkin. Biroz ijodkorlik bilan bir o‘yinchoq butunlay boshqa narsaga aylanishi mumkin. Hikoya aytib berish ham bolangizning ijodkorligini qo‘llab-quvvatlash uchun juda foydali. Siz unga tanish hikoyani o‘zgartirib aytib berishingiz, keyin esa uni ham hikoyalarni o‘zgartirib aytib berishga undashingiz mumkin.') WHERE id = '8115dfc9-eb92-4e72-a543-4ea919c775ac';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Gap farzandingiz haqida ketganda, u iste’mol qilayotgan oziq-ovqatlar borasida xayolingizda doimo savollar bo‘lishi tabiiy. Bu savollardan biri hatto shifokorlar ham bir to‘xtamga kelmagan non va un mahsulotlari masalasidir. Bu oziq-ovqat guruhiga, avvalo, non va boshqa uglevod manbalari kiradi. Non mahsulotlari guruhida nafaqat kattalar, balki bolalar ham oq non o‘rniga butun bug‘doydan (to‘liq donli) tayyorlangan non iste’mol qilishi kerak. To‘liq donli un kamroq qayta ishlangani sababli ozuqaviy moddalarga boyroq. Guruch o‘rniga bulg‘ur ishlatish ham sog‘lomroq va yaxshi muqobil bo‘lishi mumkin. Agar farzandingiz vazn orttirishga moyil bo‘lsa, bu mahsulotlarni ratsiondan butunlay chiqarib tashlash o‘rniga, kichikroq porsiyalarda berish ma’qulroq.') WHERE id = 'bb018208-0884-4d7b-917a-81edc759ffd2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalik davrida shakllangan gigiyena, kundalik tartib va ovqatlanish odatlari uzoq vaqt saqlanib qoladi. Shu sababli to‘g‘ri ovqatlanish, shaxsiy gigiyenaga mustaqil rioya qilish va ayrim asosiy kundalik ishlarni odatga aylantirish farzandingizni uzoq muddatli istiqbolda kasalliklardan himoya qilishi mumkin. Bunday odatlar nafaqat kasalliklardan saqlanish, balki bolangizning rivojlanishi uchun ham juda muhimdir. Unutmang, farzandingiz uchun qilayotgan mehnatingiz uning kelajagiga kiritayotgan eng katta sarmoyangizdir. Shu nuqtai nazardan, bolangizning ovqatlanishdan oldin va keyin qo‘llarini yuvishi, kechqurun uxlashdan oldin tishlarini tozalashni odatga aylantirishi hamda ko‘chadan kelgach kiyimlarini almashtirishi muhimdir. Farzandingiz har qanday odatni oson o‘zlashtiradigan bu davrda noto‘g‘ri odatlardan ham ehtiyot bo‘lishingiz kerak. Masalan, yaqinlaridan ko‘rib baqirib gaplashish, jahli chiqqanda atrofdagi narsalarga zarar yetkazish yoki yomon so‘zlarni eshitish uning ham bunday odatlarni oson o‘zlashtirishiga sabab bo‘lishi mumkin.') WHERE id = 'fa462e53-99cc-4df3-9374-bf4b0433f122';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '31-oyiga kirgan farzandingizning bu davrda jismoniy va nozik motorika ko‘nikmalari ancha rivojlangan bo‘ladi. U sizga taqlid qilib, qalam ushlash va rasm chizishni oson o‘rganishi mumkin. Hali to‘laqonli rasm chiza olmasa-da, ranglardan tartibsiz foydalanishi mumkin. Bolangizga barmoq bo‘yoqlarini olib berib, uni rasm chizishga qiziqtirishingiz, hatto birgalikda chizib, maroqli vaqt o‘tkazishingiz mumkin. Rasm chizayotganda uning ijodkorligini rivojlantirish uchun barcha ranglardan foydalanishiga ruxsat berishingiz kerak. Odatda qora rang ustun va ko‘zga yaqqol tashlanadigan rang bo‘lgani uchun uni boshqa ranglardan ko‘proq yoqtirishi mumkin, ammo bolangizning qaysi ranglarni tanlashiga aralashmasligingiz kerak. Barmoq bo‘yoqlari mo‘yqalamdan ko‘ra foydaliroq bo‘lishi mumkin, chunki bola barmoqlari bilan chiziqlarni osonroq chizadi. Qanchalik to‘sqinlik qilishga urinmang, bolangiz rasm chizishni nafaqat qog‘ozda, balki uy devorlarida ham sinab ko‘rishi mumkin. Tozalashga hozirdanoq tayyor turing! Uyingiz devorlarini oson artiladigan bo‘yoqlar bilan bo‘yasangiz, ularni tozalash osonroq bo‘ladi. ‐ Anacan oilasi.') WHERE id = 'f361492b-3d92-4ce0-97da-c8386dbad563';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu davrda o‘rtacha 11-13 soat uxlashi kerak. Bu umumiy uyqu vaqti tun va kunduz o‘rtasida quyidagicha taqsimlanishi lozim: tunda 10-11 soat, kunduzi esa bir marta 1-2 soat uxlash. Ayrim ota-onalar bu davrda farzandlarini kunduzi uxlatmaydilar. Biroq bolalarning rivojlanishi uchun o‘rtacha 4 yoshgacha kunduzgi uyqu hali ham muhimdir. Yangi narsalarni o‘rganishi, kunning qolgan qismi uchun zarur energiyani to‘plashi va haddan tashqari charchab, tungi uyqudan bosh tortmasligi uchun chaqalog‘ingizning kunduzgi uyqusiga hamon ahamiyat berishingiz kerak. Chaqalog‘ingiz endi hamma narsani tushunadigan yoshda. Shu sababli uning uyqusiga kun davomida yuz bergan har qanday salbiy voqea ta’sir qilishi mumkin. Bolajoningiz ulg‘ayib, ancha harakatchan bo‘lib qolgani uchun uni panjarali karavotda saqlash endi qiyin bo‘lishi mumkin. Chaqaloqlar karavotidan bolalar karavotiga o‘tkazish uchun ayni davr, odatda, eng maqbul vaqt hisoblanadi. Bu o‘tish jarayonini qiziqarli qilishingiz foydali bo‘ladi. Shunda bolajoningiz yangi karavotini yaxshi ko‘rib qoladi. Aks holda uyqu bilan bog‘liq muammolarga duch kelishingiz muqarrar.') WHERE id = 'a72583c0-5214-45e6-a7f3-7cad2b42e3ee';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz o‘zingiz uchun tayyorlagan barcha taomlarni yeyishni boshlagach, ovqatga qo‘shayotgan tuz miqdori haqida savollar tug‘ilishi mutlaqo tabiiy. Ota-onalar odatda taomga ko‘p tuz qo‘shmaslikka harakat qilsalar-da, dasturxondagi tuzdon ko‘pincha bolalarda ham unga qiziqish uyg‘otadi. Chaqalog‘ingizning hozirgi yoshida uning organizmiga ko‘p tuz kerak emas. Mahsulotlar tarkibida tabiiy tuz mavjud bo‘lgani uchun taomga oz miqdorda tuz qo‘shish kifoya. E’tibor berishingiz kerak bo‘lgan asosiy jihat — ishlatiladigan tuz yodlangan bo‘lishidir. Agar chaqalog‘ingiz juda sho‘r taomlarga o‘rganib qolsa, kelajakda yuqori qon bosimi xavfiga duch kelishi mumkin. Shu sababli, agar bolajoningiz sho‘r taomlarni yoqtirsa, bir muddat butun oilangiz bilan taomlarga qo‘shadigan ortiqcha tuzni ratsioningizdan chiqarishingizga to‘g‘ri kelishi mumkin.') WHERE id = '190574b9-2d94-41ec-8775-1a8e11808369';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Har bir bolaning ijtimoiylashuv darajasi turlicha. Ijtimoiylashuv darajasi past yoki yuqori bo‘lishidan qat’i nazar, bunda ota-ona sifatida sizning zimmangizga ko‘plab vazifalar tushadi. Ijtimoiylashuv darajasi bolaning ijtimoiy muhitga va ilk bor ko‘rayotgan odamlarga munosabatini, ya’ni ularga yaqinlashish yoki ulardan uzoq turishga moyilligini anglatadi. Ayrim bolalar yangi muhitda o‘zlarini juda erkin his qilib, atrofdagilar bilan tez til topishadilar, boshqalari esa uyalib, hech kimga yaqinlashishni istamaydilar. Agar chaqalog‘ingizning ijtimoiylashuv darajasi past bo‘lsa, uni yangi muhitda odamlar bilan darhol muloqot qilishga majburlamasligingiz kerak. Bunday vaziyatda avval chaqalog‘ingizning atrofga ko‘nikishini kutish eng to‘g‘ri yo‘l bo‘ladi. Ijtimoiylashuv darajasi yuqori bo‘lsa, bolangizni yanada diqqat bilan kuzatib, nazorat qilishingiz kerak. Agar bunday ijtimoiylashuv holati sizni juda tashvishga solsa, mutaxassis shifokor bilan maslahatlashishingiz mumkin.') WHERE id = '3818caec-41c6-4171-b3ce-2ce4abd11b1e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Shu oydan boshlab chaqalog‘ingizning vazni o‘rtacha 13.250 grammni tashkil qiladi. Qiz bolalar uchun bu ko‘rsatkich o‘rtacha 12.900 gramm, o‘g‘il bolalar uchun esa 13.600 gramm atrofida. 31 oylik bolalarning bo‘yi esa o‘rtacha 92 sm. Qiz bolalarda bu ko‘rsatkich o‘rtacha 91,4 sm, o‘g‘il bolalarda esa 92,7 smni tashkil qiladi. Biroq unutmang, bu raqamlar shunchaki o‘rtacha ko‘rsatkichlardir. Chaqalog‘ingizning bo‘yi va vazni o‘rtacha qiymatlarga mos kelmasa ham, xavfsiz oraliqda bo‘lsa, muammo yo‘q. Persentil jadvaliga ko‘ra, 31 oylik bolalarning bo‘y-vazn oralig‘i quyidagicha: 31 oylik qizlarda vaznning quyi chegarasi 10.300 gramm, yuqori chegarasi 16.500 gramm; 31 oylik o‘g‘il bolalarda vaznning quyi chegarasi 10.800 gramm, yuqori chegarasi 16.900 gramm. Bo‘y ko‘rsatkichi esa 31 oylik qizlarda quyi chegara 84,7 sm, yuqori chegara 98,2 sm; o‘g‘il bolalarda esa quyi chegara 86,2 sm, yuqori chegara 99,2 sm.') WHERE id = '3842dedf-9bba-4a59-b233-533a1cd51008';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda ota-onalarni eng ko‘p tashvishga soladigan mavzulardan biri — farzandining xayoliy do‘stlar orttirishidir. Agar siz ham shunday holatni kuzatayotgan bo‘lsangiz, avvalo xotirjam bo‘ling va bu rivojlanishning tabiiy bir qismi ekanini biling. Xayoliy do‘sti bor chaqalog‘ingiz o‘zi buyruqlar beradigan va jonlantiradigan hayvon yoki o‘yinchoq bilan ham muloqot qilishi mumkin. Uni tartibga chaqirishi, hatto jahli chiqib, baqirishi ham mumkin. Bunday holatga duch kelsangiz, hayron bo‘lmang. Bu uning sizga taqlid qilishi va o‘zini kattalardek his etishi bilan bog‘liq. Bu davrda chaqaloqning jismoniy va aqliy rivojlanishini qo‘llab-quvvatlaydigan, yoshiga mos hamda rolli o‘yinlar o‘ynash imkonini beradigan yumshoq o‘yinchoqlar xarid qilishingiz mumkin. Tanlaydigan o‘yinchoqlaringiz chaqaloqni ham aqliy, ham jismoniy faollikka undashi va rivojlanayotgan tasavvurini ishga solishiga e’tibor bering. O‘sib borayotgan chaqaloq o‘z energiyasini sog‘lom tarzda yo‘naltirishi uchun o‘yinchoq tanlash ustuvor vazifalaringizdan biri bo‘lishi kerak.') WHERE id = 'f8ae4ada-7f41-4498-b68a-fecd1f544ae2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Mavjud statistik ma’lumotlarga ko‘ra, afsuski, bugungi kunda har 5 boladan biri semizlikdan aziyat chekadi. Ortiqcha vaznli bolalarga e’tibor qaratsak, ular kam harakatlanishi, televizor yoki kompyuter qarshisida uzoq vaqt o‘tirishi, hatto ovqatlanayotganda ham shunday mashg‘ulotlar bilan band bo‘lishini ko‘rish mumkin. Bundan tashqari, sport bilan shug‘ullanmaslik va eng muhimi, bolani doimo boshqalar ovqatlantirishi semizlikni keltirib chiqaradigan muhim omillardandir. Chunki mustaqil ovqatlanish odatiga ega bo‘lmagan bolalarda noto‘g‘ri ovqatlanish odatlari shakllanadi. Yana bir sabab — bolalarning tarkibida qo‘shimchalar bo‘lgan oziq-ovqatlarga o‘rganib qolishidir. Mutaxassislar bolalarni fastfud, tayyor oziq-ovqatlar, chips, kola va gazlangan ichimliklardan, shuningdek, sun’iy qo‘shimchali mahsulotlardan uzoq tutishni tavsiya qiladilar. 2.5 yoshli chaqalog‘ingiz yaqin kelajakda maktabga borishini va tez-tez kasal bo‘lishi mumkinligini hisobga olsak, uning immuniteti mustahkam bo‘lishi uchun sog‘lom ovqatlanish naqadar muhim ekanini unutmasligingiz kerak.') WHERE id = '58502d60-f8e0-4b8e-a1fb-c17d973d4ff1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu bosqichda chaqalog‘ingiz ancha ijtimoiylashadi, atrofdagilar bilan doimiy muloqot qiladi va odamlarga nisbatan turli hislarni tuyadi. Maktabgacha yoshdagi farzandingiz birdan paydo bo‘lgan sevgi yoki nafrat hislarini tez-tez tilga olayotganini ko‘rishingiz mumkin. Chunki bolalik davrida his-tuyg‘ular ayni paytda xohlagan narsasi amalga oshishi yoki oshmasligiga qarab tez o‘zgarishi mumkin. Shu sababli chaqalog‘ingizga kimnidir sevish yoki sevmaslikni aytishdan ma’no yo‘q. U qarshisidagi inson bilan o‘rnatgan munosabatiga qarab muayyan hislarni tuyadi. Ya’ni bu munosabat uning uchun qanchalik qiziqarli ekani va u boshqa inson bilan nimalarni baham ko‘rishiga qarab hislari ham shakllanadi. Shuning uchun «Qara, qanday yaxshi do‘st, kel, uni yaxshi ko‘r» yoki «Buvingni yaxshi ko‘rishing kerak» kabi iboralar chaqalog‘ingiz uchun unchalik mazmunli emas. Qisqacha aytganda, munosabat qanday rivojlansa, bolaning hislari ham shunday bo‘ladi. Uni majburlashingiz o‘sha insonga nisbatan yanada ko‘proq salbiy hislar paydo bo‘lishiga sabab bo‘lishi mumkin.') WHERE id = '24346579-f274-43ec-b861-363147af3e6c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '31 oylik chaqalog‘ingizning so‘nggi paytlarda atrofdagi voqelikni anglash qobiliyati oshganini kuzatishingiz mumkin. Buning eng yaqqol namunasi vaqt tushunchasi bilan bog‘liq. Bu davrda chaqalog‘ingizda vaqt tushunchasi asta-sekin shakllana boshlaydi. Masalan, «3 soatdan keyin» deganingizda, u «keyin» so‘zi gapda qanday ma’noni anglatishini endi tushunadi. Biroq vaqtning qisqa yoki uzoqligi uning uchun hali to‘liq tushunarli emas. Buni anglashiga yordam berish uchun, masalan, 2 kundan keyin boradigan joyingiz haqida «uxlaymiz, uyg‘onamiz, yana uxlaymiz, uyg‘onamiz» deb tushuntirishingiz mumkin. Bunday misollar chaqalog‘ingizga vaqtni yaxshiroq anglashga yordam beradi va yuzaga kelishi mumkin bo‘lgan tushunmovchiliklarning oldini oladi.') WHERE id = '12b0c10e-3144-4c46-a3b6-1700a0248288';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz hali ham uxlashga qarshilik qilayotgan bo‘lsa, bu borada yolg‘iz emasligingizni va ko‘plab onalar xuddi shu muammoga duch kelishini biling! Uxlash o‘rniga o‘ynashni, savollar berishni va siz bilan ko‘proq vaqt o‘tkazishni afzal ko‘rishi bu yoshda mutlaqo tabiiy. Shuningdek, uxlaganidan bir muddat o‘tib uyg‘onishi va o‘ynashni xohlashi ham tabiiy holat hisoblanadi. Bu bosqichda uyqu tartibini va uxlashga tayyorgarlik jarayonini yo‘lga qo‘yish juda foydali bo‘ladi. Masalan, chaqalog‘ingiz hali ham siz bilan uxlashni istasa, bu masalada yon bermasligingiz kerak. Imkon bo‘lsa, uning alohida xonasi, buning iloji bo‘lmasa, albatta, o‘z yotog‘i bo‘lishi ishingizni osonlashtiradi. Uxlash vaqti kelganda xonadagi pardalarni yopib, chiroqni o‘chirish orqali qorong‘i va sokin muhit yaratishingiz kerak. Pijamasini kiydirib, uni uyquga tayyorlaganingizda, u uxlash vaqti kelganini tushunadi.') WHERE id = 'fcf11140-2354-4af3-8445-6e3473639648';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz uchun tayyorlaydigan nonushta, tushlik va kechki ovqat kabi 3 ta asosiy ovqatlanish orasida kamida 4 soat tanaffus bo‘lishiga e’tibor bering. Chunki ovqatlanish tez-tezligi chaqalog‘ingizning ishtahasi va odatlari uchun katta ahamiyatga ega. Nonushta bilan tushlik, shuningdek, tushlik bilan kechki ovqat orasida yengil tamaddilar berishingiz mumkin. Biroq bundan tashqari, chaqaloqqa suvdan boshqa hech qanday yegulik yoki ichimlik berilmasligi kerak. Arzimagandek tuyulgan kichkina biskvit yoki kreker chaqaloqning keyingi ovqatga bo‘lgan ishtahasini bo‘g‘ishi mumkin. Shuningdek, bunday tamaddilar bola iste’mol qilishi kerak bo‘lgan asosiy oziq-ovqatlarning o‘rnini egallaydi. Shu sababli chaqalog‘ingiz asosiy ovqatlanish paytida kam yegan bo‘lsa ham, unga albatta biror narsa yedirish uchun keyingi tamaddi yoki ovqatlanish vaqtini kutish tavsiya etiladi.') WHERE id = '03e2d49c-fc1b-4405-8b1e-dc104530e959';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Shu kunlarda farzandingizda aybdorlik hissi rivojlana boshlaganini sezishingiz mumkin. Endi u tengdoshlari bilan o‘ynaganda hamkorlik qila oladi, yaqinlariga mehr ko‘rsatadi va o‘yinchoqlarini bo‘lishishni boshlaydi. Aybdorlik hissi tufayli, agar tasodifan do‘stiga ozor yetkazsa, bundan tashvishlanishi mumkin. Muloqot ko‘nikmalari mustahkamlangani sari farzandingizning xatti-harakatlari tartibliroq bo‘lib, tajovuzkor munosabati vaqt o‘tishi bilan yumshay boshlaydi. Biroq 3 yosh inqirozining ta’sirini ham unutmasligingiz kerak. Bu davrda chaqalog‘ingiz bir payt juda murosali va gapga quloq soladigan bo‘lsa-da, ko‘p o‘tmay yana qaysar va tajovuzkor bo‘lib qolishi mumkin. U bilan muloqotingizni imkon qadar mustahkam saqlashingiz ushbu noaniq davrda sizga katta yordam beradi.') WHERE id = 'a43e3be1-81c8-45fd-98c2-ea9d64a44b8b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Endi deyarli barcha mahsulotlarni iste’mol qila oladigan farzandingizda oziq-ovqat allergiyasi xavfi avvalgi yillarga qaraganda kamroq. Biroq jigar, baqlajon, dengiz tubida yashovchi baliqlar va ot loviyasi kabi mahsulotlarni ratsionga kiritishdan oldin baribir shifokor bilan maslahatlashganingiz ma’qul. 3 yoshgacha bo‘lgan davrda bolangizga berishingiz mumkin bo‘lgan oziq-ovqatlar 4 ta asosiy guruhga bo‘linadi: 1-guruh: B vitaminlari, oqsil, qon hosil qiluvchi minerallar va energiya manbai bo‘lgan tuxum, qizil go‘sht, baliq, tovuq go‘shti, loviya, yasmiq, no‘xat hamda ulardan tayyorlangan taomlar. 2-guruh: Kalsiy, A va B vitaminlariga boy sut, pishloq va qatiq kabi mahsulotlar. 3-guruh: Energiya beruvchi don mahsulotlari va ulardan tayyorlangan barcha taomlar. 4-guruh: C vitamini manbai bo‘lgan meva va sabzavotlar. Ayniqsa, A, B va C vitaminlariga boy yashil bargli sabzavotlar juda muhim. Farzandingiz kunlik 3 ta asosiy ovqatlanishning har birida ushbu guruhlardan yetarli va muvozanatli miqdorda iste’mol qilishini ta’minlashingiz kerak.') WHERE id = 'f972da56-9345-45fd-af4a-8733021b3193';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingizning qo‘rquvlari ancha kuchayishi mumkin. Ayniqsa, qorong‘ilikdan qo‘rqish davom etishi mumkin. U sizga ishonsa va sizni yaxshi ko‘rsa-da, o‘zi uchun yangi bo‘lgan qo‘rquvlar uni xavotirga soladi. Hatto shu paytgacha alohida yotgan bo‘lsangiz ham, chaqalog‘ingiz kechalari tez-tez uyg‘onib, siz bilan uxlashni xohlashi mumkin. Uning ehtiyojlariga mehr bilan javob berishingiz va xavfsiz muhit yaratishingiz o‘ziga ishongan va nekbin bolani voyaga yetkazishingizga yordam beradi. Kechasi uxlash vaqtida tinchlantiruvchi musiqa qo‘yish yoki unga «uyqudagi hamroh» (yumshoq o‘yinchoq) olib berish foydali bo‘lishi mumkin. Bundan tashqari, uxlashdan kamida ikki soat oldin televizor va telefon kabi qurilmalarni o‘chirib qo‘yish kerak. Chunki ekranda ko‘rgan qisqa tasvirlar uning ong ostidagi qo‘rquvni qo‘zg‘atib, uyqu sifatini pasaytirishi mumkin.') WHERE id = 'd586b6dd-dba7-499f-a5f6-07d3a6c2087c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingizning kunlik energiya va oziq moddalarga ehtiyoji yuqori bo‘ladi. Bu nafaqat o‘sishi, balki kun bo‘yi juda faol bo‘lishi bilan ham bog‘liq. Biroq bolalar bir martada katta porsiyadagi ovqatni yeya olmaydi. Bu yoshda bolalarning ayrim taomlarni rad etishi, ovqatni haddan tashqari tanlashi va faqat bir necha turdagi mahsulotlarni iste’mol qilishni xohlashi ko‘p uchraydigan, vaqtinchalik muammodir. Farzandingizning ishtahasi past bo‘lsa ham, odatda ovqatlanishlarning birida yaxshi yeydi va kerakli energiyani oraliq yeguliklar bilan to‘ldiradi. Shunga qaramay, bolaga asosiy ovqatlanishlardan tashqari pechenye, kreker, shirinlik, gazli ichimliklar va shokolad kabi kaloriyali mahsulotlarni bermasligingiz kerak. Bu uning foydali oziq-ovqatlarga ishtahasi pasayishiga, ortiqcha vazn to‘plashiga va ozuqaviy qiymati bo‘lmagan kaloriyalarni qabul qilishiga sabab bo‘lishi mumkin.') WHERE id = 'df828bef-6a35-4e81-bf54-f27cccf0eaf6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ikki yoshdan keyin bolalar odatda kunduzgi uyquni xohlamay qoladi. Agar siz ham bu muammoga duch kelayotgan bo‘lsangiz, avvalo bolangizga tushunish bilan yondashishingiz kerak. Chunki bu 2-3 yoshli bolalarda uchraydigan «uyqu regressiyasi» deb ataluvchi holat bo‘lib, rivojlanishning bir qismidir. Bunday vaziyatda bola bilan qaysarlashish hech qanday natija bermaydi, aksincha, uni yanada qaysar qiladi. Chaqalog‘ingiz uyqudan oldin haddan tashqari charchab qolmasligiga harakat qiling. Odamlar orasida bola charchasa, tezroq uxlaydi degan tushuncha bor, ammo aslida haddan tashqari charchoq bolalarda zo‘riqish va yig‘lashga sabab bo‘lib, uxlab qolishni qiyinlashtiradi. Unutmang, haddan tashqari charchoq uyqu keltirmaydi, aksincha, uyqusizlik va bezovtalikka olib keladi.') WHERE id = '8f507486-74e1-4930-a39d-bd0f1f3a9dd1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu oylarda tushuncha va buyumlarni ongida mavhum tarzda tasavvur qila boshlaydi. Vaqt tushunchasi shakllanishi bilan birga, ayrim narsalarni eslab qolish qobiliyati yaxshilanib, diqqatini jamlash darajasi oshadi. U o‘zi uchun qiziqarli bo‘lgan voqea yoki buyum haqida kunlar, hatto haftalar o‘tgach sizga gapirib berishini yoxud shunga o‘xshash voqea yuz berganda uni eslatishini kuzatishingiz mumkin. Bu davrda farzandingizga uch g‘ildirakli velosiped, bolalar uchun mos bo‘yoqlar, baraban, nog‘ora, nay kabi musiqa asboblari va koptoklar olib berishingiz mumkin. Shuningdek, uy ishlariga taqlid qilishi uchun o‘yinchoq oshxona to‘plamlari, o‘yinchoq ta’mirlash asboblari, yutib yubora olmaydigan o‘lchamdagi yig‘ma rasmlar (pazllar) va legolar, avtomobillar, harakatlanuvchi va rangli kitoblar hamda geometrik shakllar ham bolangiz uchun juda mos keladi. Bular jismoniy rivojlanish bilan birga aqliy rivojlanishni ham tezlashtiradi. Sotib olgan o‘yinchoqlaringiz va ijodiy mashg‘ulot materiallari chaqalog‘ingiz uchun xavfsiz ekanini albatta tekshirishingiz kerak.') WHERE id = '64a38c2b-47fb-49f6-b66e-e941b4f59ce1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning yig‘i xurujlari va begona odamlarga nisbatan sovuqqonligi kamayganini sezishingiz mumkin. Bu davrda sizning ko‘zoynagingiz yoki sumkangiz uning nazarida katta bo‘lish ramzi bo‘lib, unga juda yoqadi. Bunday o‘yinlar unga hayotni tushunishga yordam beradi. U o‘yinchoqlari bilan sizga va uy yumushlaringizga taqlid qiladi, rolli o‘yinlarni yaxshi ko‘radi. Buning uchun unga buyumlaringizni vaqtincha berishingiz mumkin. Uy ishlariga taqlid qilish uning eng sevimli rollaridan biri bo‘lgani uchun u kattalardek ovqat pishirishni va tozalashni xohlaydi. Farzandingizning kattalarga taqlid qilib, o‘zini boshqa birovning o‘rniga qo‘yishi eng muhim o‘yinlardan biridir. U kuzatgan deyarli har bir kishining roliga kirishga harakat qiladi. Biroq hozircha askar yoki styuardessa kabi muayyan kasblarga qiziqmaydi. Buning o‘rniga unga eski sumkangiz, ko‘zoynagingiz yoki oyoq kiyimingizni berishingiz mumkin. Bunday rollar unga dunyoni kashf etish va tasavvurining to‘g‘ri yo‘nalishda rivojlanishi uchun imkon yaratadi.') WHERE id = 'df956a39-da9f-4532-82ec-209edcca5b25';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu haftalarda ko‘plik qo‘shimchalari va so‘zlarni to‘g‘ri qo‘llay boshlashi mumkin. U o‘rtacha 300 ga yaqin turli so‘zni biladi, o‘z jinsini, yoshini va ismini ayta oladi hamda voqealarni ketma-ket bayon qila oladi. Biroq bu ko‘rsatkichlar farzandingizning nutq rivojiga qanchalik e’tibor berishingizga qarab o‘zgarishi mumkin. Chunki vaqtining ko‘p qismini televizor yoki planshet qarshisida o‘tkazadigan bolaning til ko‘nikmalari bu borada tez-tez turli mashg‘ulotlar bilan shug‘ullanadigan bolaning ko‘nikmalaridan farq qiladi. Farzandingizning nutq qobiliyatini rivojlantirish uchun u bilan birga raqsga tushishingiz, qo‘shiqlar kuylashingiz va musiqa tinglashingiz mumkin. U ritmni qanday his qilishini kuzating, chunki ritm hissi tug‘ma bo‘ladi. Qo‘shiq so‘zlarini aytish va mustaqil ravishda musiqa yaratishni esa vaqt o‘tishi bilan o‘rganadi.') WHERE id = '4c057f5d-1f83-4813-a64a-8ad2927711c6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Go‘sht, tovuq go‘shti, baliq, tuxum va dukkaklilar kabi mahsulotlar oqsilga (protein) boy. Ular mushaklarning mustahkamlanishi, qon hosil bo‘lishi, organizmning sog‘lom o‘sishi va sog‘lom hayot kechirish uchun zarur. Oqsillarning ovqatlanishdagi ahamiyati juda katta. Biroq ayrim ota-onalar farzandi go‘sht yemasligidan shikoyat qiladi. Agar chaqalog‘ingiz bo‘lak go‘sht yeyishni istamasa, unga kotlet, tovuq go‘shti, baliq yoki qiymali dukkakli taomlarni taklif qilishingiz mumkin. Biror mahsulotni yoqtirmasligi uni boshqacha taqdim etish yoki pishirish usulida ham yemasligini anglatmaydi. Masalan, chaqalog‘ingiz xom pomidor yemasa, uni taomlar tarkibida pishirib berish orqali oziq moddalarga bo‘lgan ehtiyojini qondirishingiz mumkin. Shuningdek, sut, qatiq va pishloq kabi mahsulotlar suyaklar hamda tishlarning rivojlanishi, asab va mushaklarning me’yorda ishlashi uchun zarur bo‘lgan kalsiy, A vitamini va yuqori sifatli oqsil manbaidir.') WHERE id = '00d733e5-f424-4abb-bd54-db1b13f18fb2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalarda funksional qabziyat tez-tez uchraydi. Bu jiddiy tibbiy sababga bog‘liq bo‘lmagan va turli psixologik-ijtimoiy omillar tufayli yuzaga keladigan holatdir. Qabziyatga olib keladigan 5 ta asosiy omil mavjud: psixologik-ijtimoiy sabablar, ovqatlanishdagi xatolar, ovqat hazm qilish tizimidagi tuzilish muammolari, dori vositalarining ta’siri va endokrin muammolar. Psixologik-ijtimoiy sabablarga bolalarning ich kelishi vaqtida og‘riq sezgani uchun najasni ataylab ushlab turishi va buning odatga aylanishi kiradi. Ovqatlanishdagi xatolarga esa kam ovqatlanish, kuniga yarim litrdan ortiq sigir suti ichish, tolali mahsulotlar (sabzavot va mevalar) kam bo‘lgan ratsion hamda qo‘shimcha ovqatga o‘tishda yo‘l qo‘yilgan xatolar kiradi. Ovqat hazm qilish tizimidagi tuzilish muammolari deganda anal yoriq, abssess yoki anusning tug‘ma ravishda noodatiy joylashuvi tushuniladi. Dori vositalarining ta’siri esa ayrim antidepressantlar yoki antixolinergik preparatlar tufayli yuzaga kelishi mumkin. Endokrin muammolar orasida eng ko‘p uchraydigani gipotireozdir. Shu sababli chaqalog‘ingizda qabziyat tez-tez kuzatilsa, shifokor bilan maslahatlashishingiz muhim.') WHERE id = 'a1fca9a1-a5b5-4cd3-9585-094e87558f67';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ko‘rish xotirasi shu qadar kuchayganki, siz biror buyumni qayergadir qo‘ysangiz, u sizni kuzatadi. Hatto o‘sha buyumni topa olmasangiz, u joyini ko‘rsatib, sizga yordam berishi mumkin. Bu uning rivojlanishi uchun juda yaxshi ko‘rsatkichdir. U ko‘rgan rasmini yoki tashqaridagi biror manzarani qog‘ozga chizishga urinishi mumkin. Ba’zan buni to‘liq uddalay olmasa-da, bu mashg‘ulot unga qalamni ushlash va ranglarni farqlashni o‘rganishga yordam beradi. Shu bilan birga, e’tiborini tortgan narsani darhol siz bilan baham ko‘rishni istaydi. Masalan, kapalakni ko‘rganda his qilgan hayajonini siz ham ko‘rishingizni xohlaydi va uni sizga qayta-qayta ko‘rsatadi. Tafsilotlar, mayda buyumlar va ayniqsa siz tegishga ruxsat bermagan narsalar unda katta qiziqish uyg‘otadi. Ularni darhol xotirasiga muhrlab oladi va birinchi imkoniyatdayoq maqsadiga erishishga harakat qiladi.') WHERE id = 'f14124df-63d7-46de-a1b0-fb1bc90ef99c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning til va nutq ko‘nikmalari bu davrda yangi bosqichga qadam qo‘yadi. Farzandingiz bir muddatdan beri shaxs qo‘shimchalarini farqlab gapirayotganini kuzatishingiz mumkin. U "xola", "tog‘a", "amaki" kabi qarindoshlikni bildiruvchi so‘zlardan foydalanib, bu insonlar oilasining bir qismi ekanini anglaydi. Bundan tashqari, "ona" va "ota" so‘zlarini yanada kulgili tarzda talaffuz qilib, ham e’tiboringizni jalb qilishga, ham siz bilan muloqotini kuchaytirishga urinishi mumkin. U so‘zlarning inkor shaklini tushunadi va biror buyum o‘ziga tegishli ekanini bildirish uchun "meniki" yoki "otamniki" kabi iboralarni ishlatadi. Biroq bu oylarda "sizningcha", "menimcha" kabi so‘zlarni hali ham chalkashtirishi mumkin. Bu yangiliklarning barchasi uning nutq rivojlanishida ancha katta yo‘l bosib o‘tganini ko‘rsatadi.') WHERE id = 'c55bb7ad-082f-45d6-afd3-b0c6f31390a4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning sog‘lom ovqatlanishi qabziyat, ich ketishi kabi ovqat hazm qilish muammolari va temir tanqisligi bilan bog‘liq kamqonlikning oldini olish uchun juda muhim. Bu davrda qabziyatning oldini olish maqsadida sabzavot va mevalarga boy, tolali mahsulotlar berish kerak. Shu bilan birga, uning oqsil, vitamin va minerallarga bo‘lgan ehtiyojini sinchiklab qondirishingiz lozim. Agar chaqalog‘ingiz go‘sht yeyishni yoqtirmasa, mos go‘sht turlaridan kotlet tayyorlab, qaynatib yoki sabzavotli taomlar va sho‘rvalarga qo‘shib berishingiz mumkin. Haftalik menyuingizda esa kamida bir marta baliq bo‘lishi kerak. Chaqalog‘ingiz ushbu guruhdagi mahsulotlardan kuniga 2-3 porsiya iste’mol qilishi lozim. Umuman olganda, kun davomida 2 stakan sut (400-500 gramm) va gugurt qutisidek pishloq uning ehtiyojini qondiradi. Bundan ortiq kalsiy iste’mol qilish boshqa minerallarning organizmda so‘rilishiga salbiy ta’sir ko‘rsatishi mumkin.') WHERE id = 'e18a2773-f5ca-428b-953b-bdd7310cbd6f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Hozir boshdan kechirayotgan davringiz farzandingiz uchun go‘yo bir inqilobga o‘xshaydi. Chunki 2 yosh inqirozining alomatlari hali to‘liq tugamay turib, 3 yosh inqirozining belgilari boshlanishi mumkin. Bu yangi davrda ayrim kichik yangiliklar orqali uni tushunishingizni ko‘rsatishingiz yoki kundalik tartibni biroz o‘zgartirishingiz mumkin. Masalan, shu paytgacha uxlash uchun hamroh o‘yinchoq olib bermagan bo‘lsangiz, ayni vaqti! Uxlash uchun hamroh sifatida yumshoq, tuklari og‘iz yoki burunga kirmaydigan, tugma va zanjirsiz o‘yinchoq tanlashingiz mumkin. O‘yinchoqni yuvish mumkinligiga, shuningdek, qo‘l, quloq yoki dum kabi ushlashga qulay qismlari borligiga e’tibor bering. Bu o‘yinchoqni boshqa o‘yinchoqlar yoniga qo‘ymaslik juda muhim. Chunki chaqalog‘ingiz uning oddiy o‘yinchoq emas, balki faqat uxlayotganda yonida bo‘ladigan alohida do‘st ekanini his qilishi kerak.') WHERE id = 'dad27d76-9b3f-4d94-805e-e4b144d944ca';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz sog‘lom bo‘lishi uchun faqat bir turdagi ovqatlanish yetarli emas. Unga har kuni to‘rtta asosiy oziq-ovqat guruhiga mansub turli mahsulotlarni taklif qilsangiz, avvaliga xohlamasa ham, vaqt o‘tishi bilan ularga o‘rganib, muvozanatli ovqatlanishni boshlaydi. Ovqatlanish vaqtlari muntazam bo‘lishiga e’tibor berishingiz va ozuqaviy qiymati yuqori mahsulotlarni tanlashingiz kerak. Oz-ozdan va tez-tez ovqatlanishi lozim bo‘lgan farzandingiz uchun kichik likopchalarda oz miqdorda taom tayyorlash ma’qul. U bilan birga dasturxon atrofida o‘tirish, oshxona ishlarini birgalikda bajarish va dasturxonni birga tayyorlash ham alohida ahamiyatga ega. Agar farzandingiz ayrim muhim mahsulotlarni iste’mol qilishdan bosh tortsa, ularning o‘rnini bosadigan boshqa mahsulotni berishingiz mumkin. Masalan, kalsiy suyaklar va tishlar salomatligi uchun juda muhim. Agar farzandingiz sut ichishni yoqtirmasa, uning o‘rniga ayron, pishloq, qatiq yoki sutli donli bo‘tqalarni taklif qilishingiz mumkin.') WHERE id = 'f14350f9-b48d-4bfb-88a6-d4e850319819';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ijtimoiy hayotga moslashishida sizning rolingiz katta. Uning ishtiyoq bilan bajarayotgan mashg‘ulotlarini qo‘llab-quvvatlang, unga «sen buni uddalay olmaysan» kabi ruhini tushiradigan so‘zlarni aytmang. Bu kelajakda o‘ziga bo‘lgan ishonchning yetishmasligiga olib kelishi mumkin. Farzandingizni tengdoshlari ko‘proq bo‘lgan muhitga olib boring, unda baham ko‘rish, yordamlashish va hamjihatlik tushunchalarini mustahkamlang. U sizni tinglab, buni xatti-harakatlarida namoyon etganida, unga minnatdorlik bildiring va bu yaxshi xulq ekanini ayting. O‘yinchoqlari qanchalik ko‘p bo‘lmasin, u doimo siz bilan o‘ynaydigan o‘yinlarni afzal ko‘radi. Hatto uyda sizning xatti-harakatlaringizga taqlid qilishi ham o‘zini allaqachon katta deb his qilayotganining belgisidir. Shu sababli biror ish qilishdan oldin yana bir bor o‘ylab ko‘ring, chunki endi u sizning ko‘zgungizdir.') WHERE id = 'e8b1c2b9-b8f2-4e27-b070-1a99713d7661';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Televizor hech qachon farzandingiz uchun sizchalik yaxshi enaga, o‘qituvchi yoki o‘yin sherigi bo‘la olmaydi. Agar televizor ko‘rsa, yolg‘iz o‘zi soatlab emas, sizning yoningizda qisqa vaqt tomosha qilishi kerak. Kunlik tomosha vaqti yarim soatdan oshmasligi muhim. U tomosha qiladigan dasturlar yoshiga mos, ta’limiy va qiziqarli ekaniga ishonch hosil qiling. Televizorni haddan tashqari ko‘p tomosha qilish bolaning ijtimoiy faolligi va qobiliyatlarini cheklaydi. Ko‘plab ota-onalar bolaning energiyasi ortib ketganida uni chalg‘itish uchun televizor ko‘rishga ruxsat berishadi. Biroq bunday vaziyatda o‘yinchoqlar foydaliroqdir. O‘yinchoq tanlashda chaqaloqni jismoniy va aqliy faollikka undaydigan, uning rivojlanayotgan tafakkurini ishga soladigan turlarga ustunlik berish foydali.') WHERE id = 'f2588707-ed76-4381-a46a-51f910d91358';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bilan birga 32-oyga xush kelibsiz! 😊 32-oyga kirgan chaqalog‘ingiz endi ko‘plab yangi ko‘nikmalarga ega. Masalan, qalam bilan doira chiza oladi, ammo kvadrat yoki uchburchak chizish uchun unga hali vaqt kerak. Ko‘ylagini ko‘pincha teskari kiysa-da, uni mustaqil ravishda kiyib-yecha oladi. Tugmali kiyimlarni kiyishda esa yordamga muhtoj bo‘lishi mumkin. Bir oyog‘ida biroz vaqt tura oladi va oldinga bemalol sakraydi. O‘lchami mos keladigan to‘plarni ham ota, ham ushlay oladi. Farzandingiz qanchalik faol bo‘lsa, jismoniy rivojlanishi uchun yangi narsalarni sinab ko‘rishda shunchalik muvaffaqiyatli bo‘ladi. 32 oylik chaqalog‘ingiz uyqu vaqtidan tashqari 60 daqiqadan ortiq harakatsiz qolmasligi kerak. Uni bolalar aravachasi yoki avtomobil o‘rindig‘ida uzoq vaqt o‘tqazib qo‘ymang. Agar quchoqqa chiqish yoki aravachaga o‘tirishdan bosh tortsa, xavfsiz sharoitda mustaqil yurishiga ruxsat bering.') WHERE id = '70fac899-c576-4661-823a-c8e6d7ab1f20';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu yoshdagi bolalari bor oilalar ko‘pincha farzandi tinmay savol berishi va gapirishidan shikoyat qilsa, ayrim ota-onalar farzandi hali ham gapirmayotganidan xavotirlanadi. Agar chaqalog‘ingizda shunday holatni kuzatsangiz, shifokorga murojaat qilishdan oldin ayrim jihatlarga e’tibor berishingiz kerak. Ulardan eng muhimi — oilaviy nutq rivojlanishining kechikishidir. Siz yoki turmush o‘rtog‘ingiz kech gapira boshlagan bo‘lsangiz, chaqalog‘ingiz ham kech gapirishi mumkin va ko‘pincha buning ortida jiddiy muammo bo‘lmaydi. Muddatidan oldin tug‘ilgan yoki rivojlanishdan ortda qolayotgan bolalarda ham nutq ko‘nikmalari kechikishi mumkin. Uyda ikki tilda gaplashish, o‘ng yoki chap qo‘ldan foydalanish borasidagi noaniqliklar, eshitish qobiliyatining pasayishi, til yuganchasining kaltaligi, tanglay yoki lab yorig‘i kabi muammolar ham chaqaloqning tengdoshlaridan ortda qolishiga sabab bo‘lishi mumkin. Bundan tashqari, bola yashaydigan muhitda muloqotning kamligi yoki aksincha, bolani haddan tashqari avaylab, uning o‘rniga hamma ishni bajarish ham gapirishiga to‘sqinlik qilishi mumkin. Ko‘pincha bolaga gapirish imkoniyati berilmagani sababli bu muammo yuzaga keladi; zarur sharoit yaratilganda esa qisqa vaqt ichida rivojlanish seziladi.') WHERE id = '142a2085-8e97-430d-aa1a-76d048b9f3e3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ritmni his qilish qobiliyati har bir bolada bo‘lgani kabi, chaqalog‘ingizda ham tug‘ma ravishda mavjud. Shu sababli chaqalog‘ingiz bilan bolalar qo‘shiqlaridan tashqari, o‘zingiz yoqtirgan istalgan turdagi musiqani tinglashingiz mumkin. Uning energiyasini to‘g‘ri sarflashi uchun birga raqsga tushishingiz, qo‘shiq kuylashingiz va ritmga mos ravishda qarsak chalishingiz mumkin. Chaqaloqqa ohangning ko‘tarilib-pasayishini his etish va buni tana harakatlari orqali ifodalashga yordam berish uning musiqiy qobiliyatini rivojlantiradi. U tanish qo‘shiqni xirgoyi qila boshlaganda, boshqa musiqa asboblari bilan tanishishga tayyor ekanini tushunishingiz mumkin. Uydagi ikkita qozon qopqog‘i yoki oddiy nog‘oracha ham musiqa asbobi vazifasini bajarishi mumkin. Biroq chaqaloqqa haqiqiy ohanglarni eshittiradigan asbob ham kerak bo‘lishi mumkin. Shu jihatdan bolalar uchun mo‘ljallangan o‘rgatuvchi pianino tugmalarini yoki gitara torlarini chertib, chiqqan tovushga taqlid qilish har ikkingiz uchun ham juda maroqli bo‘ladi.') WHERE id = '72d5321b-8667-4786-a0a9-55391cfc58eb';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar siz ham "bolamga hech narsa yedira olmayapman", "soatlab och qolsa ham, parvo qilmaydi" kabi gaplarni tez-tez aytsangiz, xafa bo‘lmang. Chunki bu yosh davrida ko‘plab onalarning muammosi bir xil: ishtahasiz bolalar! Chaqaloqning ovqatlanish istagi o‘sish sur’ati va individual holatiga qarab o‘zgarsa-da, ayniqsa 1-3 yosh oralig‘i ishtaha eng past bo‘ladigan davrdir. Chaqaloqning ayrim kunlari kam, boshqa kunlari esa ko‘p ovqatlanishi bu yoshning tabiiy xususiyatidir. Shu sababli ortiqcha xavotirlanishga hojat yo‘q. Shuningdek, bola oz-ozdan va tez-tez ovqatlanishga odatlangan bo‘lsa, shu yo‘l bilan oladigan ozuqaviy qiymat asosiy ovqatnikidek foydali bo‘lishi mumkin. Ammo ishtahasizlik uzoq vaqt davom etsa va chaqaloq yetarlicha vazn olmasa, bunga ichak parazitlari, qabziyat, kamqonlik yoki siydik yo‘llari infeksiyasi sabab bo‘lishi mumkin. Bunday hollarda albatta shifokor bilan maslahatlashish kerak.') WHERE id = '8eb704da-d3e4-4f40-a1ec-24b231c52cba';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizni tengdoshlari orasida kuzatsangiz, ayrim bolalar yolg‘iz, boshqalari esa guruh bo‘lib o‘ynayotganini ko‘rishingiz mumkin. Bu davrda bolalarning birgalikda o‘ynashi ko‘proq uchrasa-da, ayrim bolalar yolg‘iz o‘ynaganda o‘zlarini baxtliroq his qilishadi. Agar chaqalog‘ingiz vaqtini yolg‘iz o‘tkazishni yoqtirsa, uni majburlamang va xavotirlanmang. Tez orada u ham boshqa bolalar kabi o‘ziga o‘yin sherigi topib, do‘stlik poydevorini quradi. Ijtimoiy rivojlanishning bir qismi sifatida ayrim bolalar boshqalarga hukmronlik qilishga va bosim o‘tkazishga moyil bo‘lishi mumkin. Buyruqbozlik bu yosh davrida tez-tez uchraydigan xatti-harakatdir. Agar chaqalog‘ingizda tengdoshlariga nisbatan shunday xatti-harakatlarni ko‘rsangiz, unda empatiya (o‘zini boshqa birovning o‘rniga qo‘yish) tuyg‘usini rivojlantirish juda muhim.') WHERE id = '13173885-9e0a-4abe-ab99-a5202cd0d97c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz atrofidagi odamlarni, jumladan sizni ham qanday harakatga keltirishni juda yaxshi biladi. Uning boshqa odamlarning kayfiyatiga qiziqayotganini, qo‘shni nega jahldor yoki otasi nega xafa ekanini bilishni istayotganini kuzatishingiz mumkin. U tushunadigan tilda izoh berishingiz chaqalog‘ingizga his-tuyg‘ular tabiiy ekanini va ular haqida gapirish to‘g‘ri ekanini anglashga yordam beradi. Bu davrda kichkintoyingiz mehr va ishonch kabi asosiy hissiy andozalarni shakllantira boshlaydi. U siz va oilaning boshqa a’zolari uni himoya qilishingizni va uning yonida ekaningizni tushunadi. Bu muhim tushunchalarni ham aynan shu anglash asosida, hayotining dastlabki ikki yilida unga bo‘lgan munosabatingiz orqali o‘rgangan. Unga mehr ko‘rsatishingiz, ehtiyojlariga o‘z vaqtida javob berishingiz va xavfsiz muhit yaratishingiz uning his-tuyg‘ularni to‘g‘ri anglashiga yordam beradigan eng muhim omillardan biridir.') WHERE id = 'e0588130-112a-43d1-a91a-610ac0b19398';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz endi o‘zini yanada ijtimoiyroq tuta boshlaydi, notanish odamlarga nisbatan tortinchoqligi va qo‘rquvi kamayadi. U o‘yinchoqlarini do‘stlari bilan bo‘lishib, ular bilan birga o‘ynashi mumkin. Hatto divan yostiqlaridan o‘ziga kichkina uycha qurib, shaxsiy hududini yaratishga harakat qiladi va u yerga faqat o‘z do‘stlarini taklif qilishni xohlaydi. Sizni bu jarayonga qo‘shishni istamasligi tabiiy, chunki bu hududda boshliq uning o‘zi. Shuningdek, bu davrda bolaning rangli qalamlarga va rasm chizishga qiziqishi ortadi. Unga bo‘sh qog‘ozlar va bo‘yoqlar berib, tasavvuridagi narsalarni qog‘ozga tushirishi uchun sharoit yarating. Bu uning dunyoqarashini kengaytiradi. Ammo ehtiyot bo‘ling, chunki bu yoshdagi bolalarning devorlar va mebellarni bezab qo‘yishi ota-onalarning eng katta tashvishlaridan biridir. 😊') WHERE id = 'b23ce050-0379-4aa6-b489-85355e97ec2f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz “bu nima?”, “to‘p qayerda?”, “men kimman?” kabi savollarni tushunishi va mazmunli javoblar berishi kutiladi. Sog‘lig‘ida hech qanday muammo bo‘lmagan har bir bola ko‘pi bilan 36 oyligiga qadar 2 yoki 3 so‘zdan iborat gaplar tuza olishi kerak. Ammo chaqalog‘ingizda bu ko‘nikmalarni kuzatmasangiz, bu har doim ham jiddiy muammo borligini anglatmaydi. Nutq kechikishi bolaning tengdoshlariga o‘xshash nutq ko‘nikmalariga ega emasligi sifatida ta’riflanadi. Agar bola yoshiga mos ravishda gapirmasa, bu “nutq nuqsoni” yoki “rivojlanish kechikishi” bo‘lishi mumkin. Nutq kechikishining eng muhim sabablaridan biri eshitish qobiliyatining pasayishidir. Bu tug‘ma yoki keyinchalik orttirilgan bo‘lishi mumkin. Shu sababli, agar sizda xavotir bo‘lsa, mutaxassis shifokorga murojaat qilishingiz tavsiya etiladi.') WHERE id = '8b57d158-736c-4f31-9161-27c88480c843';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning jami 20 ta sut tishi hozirga kelib to‘liq chiqib bo‘lgan bo‘lishi mumkin. Agar hali to‘liq chiqmagan bo‘lsa, yaqin 1–2 oy ichida ikkinchi oziq tishlari ham chiqadi. Shundan so‘ng ilk doimiy tishlar 6 yoshdan boshlab chiqadigan birinchi katta oziq tishlari bo‘ladi. Tish chiqish jarayonida chaqalog‘ingizda isitma, ko‘ngil aynishi va ich ketishi kabi alomatlarni kuzatishingiz mumkin. Shuningdek, bu davrda bolaning bezovtaroq bo‘lishi va ishtahasi pasayishi odatiy hol. Ikkinchi oziq tishi chiqayotganida milklarning qizarishi va so‘lak oqishining ko‘payishi ham kutiladi. Shu sababli farzandingizning bir muddat ovqat yeyishni istamasligi va ishtahasi yo‘qligiga tushunish bilan munosabatda bo‘lishingiz kerak.') WHERE id = '4caba1ee-fe4e-4f39-9676-eeb0deb3ad9f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqning jismoniy imkoniyatlari ortishi uning ko‘nikmalari yanada rivojlanishiga sharoit yaratdi. Endi u zinadan yordamingizsiz tushib-chiqa oladigan darajada kuchli. Qo‘l harakatlari ancha muvozanatli bo‘lib, qo‘llaridan foydalanishda yanada mohir bo‘ldi. Biroq chaqalog‘ingiz zinadan mustaqil chiqib-tusha olsa ham, siz baribir ehtiyotkor bo‘lishingiz kerak. Uning xavfsizligi uchun zarurat bo‘lmasa, uni nazoratsiz qoldirmang. Chunki chaqalog‘ingiz, boshqa barcha bolalar kabi, o‘z imkoniyatlari chegarasini anglash uchun ba’zan kuchi yetmaydigan ishlarni ham qilishga urinishi mumkin. Masalan, zinapoyalarni ikkita-ikkitadan bosib chiqish yoki sakrab tushish shunday harakatlardan ayrimlaridir.') WHERE id = '84c09dfd-750f-4d20-9c62-31f373486223';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Dunyoda va mamlakatimizda eng ko‘p uchraydigan maishiy baxtsiz hodisalarning taxminan 44%iga yiqilish sabab bo‘ladi. Agar ko‘p qavatli uyda yashasangiz, zinapoyaning boshi va oxiriga mos to‘siqlar yoki xavfsizlik darvozachalarini o‘rnatishni unutmang. Derazadan yiqilish ham bolalar orasida tez-tez uchraydigan baxtsiz hodisalardan biridir. Hasharotlardan himoya qiluvchi to‘rlar chaqalog‘ingizni asrash uchun yetarli emas. Ayniqsa, shu davrda energiyasi toshib turgan chaqalog‘ingiz uchun to‘liq xavfsizlikni ta’minlamoqchi bo‘lsangiz, derazalarga maxsus himoya moslamalarini o‘rnatishingiz mumkin. Shuningdek, chaqalog‘ingiz ustiga chiqishi mumkin bo‘lgan mebellarni derazalardan uzoqroq tutishga harakat qiling. Yiqilishning yana bir sababi — polning sirpanchiq bo‘lishi. Uydagi gilamlar tagiga sirpanishga qarshi tagliklar qo‘yib, xavfni kamaytirishingiz mumkin. Stol va tokchalarning burchaklariga himoya qoplamalarini o‘rnatish orqali yuzaga kelishi mumkin bo‘lgan jarohatlarning ham oldini olishingiz mumkin.') WHERE id = '8d8068ce-d413-4155-9f05-19664d00e5b9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizda muntazam ovqatlanish odatini shakllantirish uchun ayrim jihatlarga e’tibor berishingiz kerak. Ulardan eng muhimi — farzandingiz haddan tashqari charchagan va uyqusi kelgan paytlarni hisobga olishdir. Chunki bunday holatda ishtahasi bo‘lmagani uchun ovqatlanishdan bosh tortishi mumkin. Dasturxon atrofida o‘tirishdan oldin chaqalog‘ingiz bilan o‘ynashingiz uning kayfiyatini ko‘tarib, ovqatlanishga qarshiligini kamaytirishi mumkin. Ovqatlanish oralig‘ida farzandingizga shakar, shokolad, tort, gazlangan va boshqa o‘ta shirin ichimliklarni aslo bermang. Chunki hatto yarim stakan tayyor meva sharbati ham uning ishtahasini bo‘g‘ishi mumkin. Ovqatlanish vaqtida esa uni yedirishga majburlamang. Uni mukofotlash yoki jazolash, aksariyat o‘ylaganidek ijobiy emas, aksincha, ovqatlanish odatlariga salbiy ta’sir qiladi. Bundan tashqari, katta opa-akalari va oila kattalarining dasturxonga o‘tirmasligi yoki ovqat tanlashi farzandingizning odatlariga yomon namuna bo‘lishi mumkin. Shu sababli ovqatlanish vaqtida imkon qadar barcha oila a’zolari dasturxon atrofida bo‘lishi kerak.') WHERE id = 'b0de3f60-3586-4525-93f5-131c4993a7dc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu davrda hojatini chiqarganidan keyin chuqur qayg‘u va xavotirni his qilishi mumkin. Aslida bu mutlaqo tabiiy reaksiya. Chunki farzandingiz hali yetarlicha katta bo‘lmagani sababli hojatga chiqqanida tanasining bir qismi uzilib ketgan deb o‘ylaydi. Natijada tanasining boshqa qismlari, masalan, qo‘li yoki oyog‘i ham yo‘qolib qolishidan xavotirlanadi. Bunday vaziyatlarda farzandingizga aslo keskin munosabat bildirmang va qat’iy ohangda Yo‘q!, Qo‘rqma! kabi gaplarni takrorlamang. Buning o‘rniga, bu jarayonning fiziologiyasini unga tushunarli tilda izohlashga harakat qiling. Bu yegan ovqatlarining chiqindisi ekanini aytib, unitazni chiqindi qutisiga o‘xshatib tushuntirishingiz mumkin. Hatto tagligidagi najasini ko‘rishiga ham ruxsat berishingiz mumkin. Uni birgalikda chiqindi joyiga yoki unitazga tashlashingiz mumkin.') WHERE id = '8c882e96-3609-47c5-bc42-d3ee39abdda4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz rivojlanishining bu davrida jinsidan qat’i nazar, uy ishlarida sizga yordam berishga urinayotganini kuzatishingiz mumkin. Chunki bu davrda farzandingizning sizga va atrofidagi insonlarga taqlid qilishi rivojlanishning tabiiy bir qismidir. Shu tariqa farzandingiz o‘zi sezmagan holda qayerda qanday tutish kerakligini o‘rganadi. Bunda siz va atrofdagi boshqa insonlar zimmasiga muhim mas’uliyat tushadi. Xatti-harakatlaringizga e’tiborli bo‘lishingiz kerak; agar bola kimdandir yoshiga mos bo‘lmagan yomon so‘zni eshitsa, darhol uni takrorlay boshlaydi. Shu sababli har qachongidan ham ehtiyotkorroq bo‘lishingiz zarur. Chaqalog‘ingiz uy ishlarida sizga yordam bermoqchi bo‘lsa, unga to‘sqinlik qilish o‘rniga o‘ziga shikast yetkazmasligiga ishonch hosil qiling. Qisqasi, "O‘zingga zarar yetkazasan, qilma!" deyish o‘rniga, "Ehtiyotkor bo‘lsang, uddalaysan!" deb uni ruhlantirishingiz mumkin.') WHERE id = 'a8b1ba6a-e9b7-4b18-8bee-81c98164dc1d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tadqiqotlar shuni ko‘rsatadiki, shakar ta’mini o‘rganmagan bolalarni maktab yoshigacha tarkibida sun’iy shakar bo‘lgan pechenye, shokolad va tort kabi mahsulotlardan uzoq tutish mumkin. Shakar farzandingizning rivojlanishi va kun davomida zarur energiyani olishi uchun muhimdir. Biroq bu ehtiyojni hech qanday ozuqaviy qiymatga ega bo‘lmagan oddiy shakar bilan qondirish o‘rniga, uyda shinni yoki asal qo‘shib tayyorlangan keks va pechenye kabi mahsulotlar orqali farzandingizning uglevodlarga bo‘lgan ehtiyojini ta’minlashingiz mumkin. Baribir maktab yillarida boshqa bolalar orasida bo‘lganida, istamasa ham bunday mahsulotlarga duch keladi. Ammo o‘sha yoshga yetguniga qadar unda to‘g‘ri ovqatlanish tarzini shakllantirgan bo‘lishingiz muhim. Farzandingizning shirin mahsulotlarga moyilligi qancha kuchli bo‘lsa, kelajakda yuzaga kelishi mumkin bo‘lgan sog‘liq muammolari ham shuncha ko‘payadi. Shu bois odatlar shakllanadigan bu davrda yon bermasligingiz juda muhim.') WHERE id = '35e2d7ef-3499-43c9-ac1b-a5604e2b87d4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ilgari miya rivojlanishi faqat genetik omillarga bog‘liq deb hisoblangan. Biroq so‘nggi vaqtlarda olimlar atrof-muhit omillari miya rivojlanishida muhim rol o‘ynaydi, degan xulosaga kelishmoqda. Har bir bola taxminan 100 milliard asab hujayrasi bilan tug‘iladi. Hayotning keyingi davrlarida yangi asab hujayralari hosil bo‘lmaydi. Shu sababli chaqalog‘ingiz bilan mazmunli o‘tkazgan har bir daqiqangiz uning kelajakdagi muvaffaqiyati uchun ekilgan urug‘dir. Tadqiqotlar bolalar qabul qiladigan og‘zaki, vizual va tovushli stimullarning miya hamda aqliy rivojlanishga ijobiy ta’sir qilishini isbotlaydi. Bu stimullar qanchalik xilma-xil bo‘lsa, foydasi ham shunchalik ko‘p bo‘ladi. Shuning uchun farzandingizni imkon qadar tabiat qo‘ynida sayr qilishga olib chiqing, rangli va suratli kitoblarni tomosha qilishi uchun sharoit yarating hamda u bilan rivojlantiruvchi mashg‘ulotlar o‘tkazishga harakat qiling.') WHERE id = 'ea041f70-a712-4618-a072-ebd4e18f986e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqaloqning kunlik tuzga bo‘lgan ehtiyoji taxminan 1500 milligrammdir. Bu miqdor kuniga 1.5 gramm tuzga teng. JSST belgilagan me’yorlarga ko‘ra, yodlangan tuz iste’mol qilish qalqonsimon bez gormonlari hosil bo‘lishi uchun muhimdir. Tuzni butunlay cheklash farzandingizda, avvalo, gipotireoz va boshqa gormonal buzilishlarga olib kelishi mumkin. Shu bilan birga, me’yordan ortiq tuz iste’mol qilish ham xavfli asoratlarni keltirib chiqarishi mumkin. Ovqatiga qo‘shimcha tuz solmasangiz ham, chaqalog‘ingiz tayyor qadoqlangan mahsulotlarni iste’mol qilsa, kerakli tuz miqdoridan ancha ortig‘ini oladi. Tuzni haddan tashqari ko‘p iste’mol qilish organizmdagi suv miqdorining kamayishiga va natijada suvsizlanishga (degidratatsiyaga) sabab bo‘ladi. Shu bois chaqalog‘ingizni qadoqlangan mahsulotlardan uzoq tutishingiz va imkon qadar uyda tayyorlangan taomlarni tanlashingiz juda muhim.') WHERE id = 'f91b2ae4-510c-4199-8db1-8954345d3297';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingizning tengdoshlariga nisbatan xatti-harakatlari o‘zgarganini sezishingiz mumkin. Endi u tengdoshlari bilan guruh bo‘lib o‘ynay boshlashi mumkin. Biroq u hali ham o‘yinchoqlari va buyumlarini boshqalar bilan to‘liq bo‘lishishni istamasligi mumkin. Buni xasislik deb emas, balki shu yosh davriga xos xususiyat sifatida qabul qilishingiz kerak. Vaqt o‘tishi bilan u bo‘lishishni yaxshiroq o‘rganadi. Unga biroz vaqt bering va majburlamang, chunki farzandingiz hali bir muddat o‘zini dunyoning markazi deb bilishda davom etadi. Shuningdek, shu davrda uning his-tuyg‘ulari tez-tez o‘zgarib turishi mumkin. U juda xursand bo‘lib turgan paytda, o‘zi istamagan biror ishni qilishi kerak bo‘lsa, birdan jahli chiqishi mumkin. Hatto kuchli jahl xurujlari davri ortda qolgan bo‘lsa ham, bu ular butunlay tugaganini anglatmaydi va ba’zan bunday holatlarga duch kelishingiz mumkin.') WHERE id = 'a6115683-f3cb-4edb-9c84-9bf3b5c64952';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar o‘g‘lingizning moyaklari yoki qizingizning ko‘krak bezlari kattalashayotganini sezsangiz, e’tibor berishingiz kerak bo‘lgan jihatlar bor. Balog‘at davri — bolalikdan yetuklikka o‘tish jarayonida yuz beradigan gormonal va jismoniy o‘zgarishlarni qamrab oluvchi biologik bosqichdir. Odatda balog‘at davri qizlarda 9-11, o‘g‘il bolalarda esa 10-12 yoshda boshlanadi. Qizlarda 8, o‘g‘il bolalarda esa 9 yoshdan oldin boshlangan rivojlanish erta balog‘atga yetish hisoblanadi. Buning dastlabki belgisi qizlarda ko‘krak bezlarining bo‘rtishi, o‘g‘il bolalarda esa moyaklarning kattalashishidir. So‘nggi yillarda oziq-ovqatlarda GMO miqdorining ko‘payishi va gormonal o‘zgarishlar sababli bolalarda erta balog‘atga yetish holatlari ortgan. Bunga irsiy omillar, geografik sharoit, ovqatlanish va umumiy salomatlik holati ta’sir qiladi. Davolash mumkin bo‘lgan bu muammoga beparvo qaralsa, jiddiy asoratlar yuzaga kelishi mumkin. Shu sababli farzandingizni diqqat bilan kuzatishingiz juda muhim.') WHERE id = '96217fde-5713-4fe7-acb8-719f4d28185d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingiz ba’zan tajovuzkor xatti-harakatlar qilayotganini ko‘rishingiz mumkin. Biroq bu yoshda kuzatiladigan tajovuzkorlik odatda keyinchalik o‘rganilgan xatti-harakatdir. Agar avval bunday holatlar bo‘lmagan bo‘lsa, uning sababini aniqlashga harakat qilishingiz mumkin. Masalan, oilada tajovuzkor xatti-harakatlar qiladigan kishi bo‘lsa, bu farzandingizga ta’sir qilishi ehtimoli juda yuqori. O‘rganishga juda moyil bo‘lgan farzandingiz hatto bog‘da yoki do‘konda ko‘rgan tajovuzkor harakatni ham xotirasiga muhrlab olishi mumkin. Bu davrda uni bunday noodatiy va salbiy xatti-harakatlardan uzoq tutish juda muhim. Shuning uchun farzandingizda tajovuzkorlikka sabab bo‘layotgan omillarni kuzatishingiz va zarur bo‘lsa, mutaxassisdan yordam olishingiz kerak.') WHERE id = 'f6c4c1fb-2085-4620-b3dd-958a42acbbb4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bu davrda juda faol bo‘lishini bilamiz. Buni imkoniyatga aylantirishingiz mumkin! Masalan, unga uddalay oladigan kichik vazifalarni berib, mas’uliyat hissining rivojlanishiga yordam berishingiz mumkin. Chunki bu davrda farzandingiz sizning va boshqa odamlarning his-tuyg‘ularini, ularga yordam kerak yoki kerak emasligini tushuna boshlaydi. Bundan tashqari, o‘ziga xos fobiya va qo‘rquvlari paydo bo‘layotgan farzandingiz uchun yangi va noodatiy narsalarni sinab ko‘rish qo‘rqinchli tuyulishi mumkin. Siz bu o‘zgarishga tayyor bo‘lishingiz va uning xavotirlarini kamaytirishingiz kerak. Bu davrda farzandingizni eng ko‘p tashvishga soladigan omillardan biri — sizdan ayrilib qolish qo‘rquvidir. Shu sababli biror joyga ketayotganingizda unga qachon qaytishingizni albatta ayting. Qaytib kelishingizga ishonch hosil qilsa, u sizdan uzoqroq vaqt davomida alohida qola oladi.') WHERE id = '333574d8-98a5-4257-9524-278228cb207c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu bosqichda farzandingiz endi sizning yordamingizsiz qo‘llari va yuzini bemalol yuvib, arta oladi. Oyoq mushaklari avvalgiga qaraganda yanada kuchaygan, bu esa unga bemalol sakrash imkonini beradi. Albatta, bu davrda barcha bolalarning jismoniy rivojlanish imkoniyatlari bir xil bo‘lmasligi mumkin. Farzandingizni boshqa bolalar bilan taqqoslash sizga hech qanday foyda bermaydi. Har bir bolaning o‘ziga xos xulq-atvori va alohida shaxsiyati borligini unutmasligingiz kerak. Ayniqsa, 2 yoshdan keyin bu farqlar yanada yaqqol namoyon bo‘la boshlaydi. Hozir kirib kelgan 3 yosh davri esa ushbu farqlar to‘liq namoyon bo‘ladigan bosqichdir. Shu sababli farzandingizni uddalay olmaydigan ishlari uchun emas, balki qila oladigan ishlari uchun qo‘llab-quvvatlashingiz kerak. Uni ruhlantirishingiz o‘ziga ishonchi va o‘zini qadrlash hissi shakllanishiga yordam beradi.') WHERE id = '2736628c-47d5-4efe-8544-30f307dcafe3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz maktabga boradigan 6 yoshgacha bo‘lgan davr — uning ovqatlanish odatlari deyarli to‘liq shakllanadigan vaqt. Bu yoshda egallangan to‘g‘ri ovqatlanish odatlari kelajakda uning sog‘lom inson bo‘lib voyaga yetishiga zamin yaratadi. Tartibsiz ovqatlanish vaqtlari, shirinliklar va nosog‘lom taomlar (fast food) farzandingiz kelajakda semizlikdan aziyat chekishi mumkinligining belgisi hisoblanadi. So‘nggi 20 yil davomida olib borilgan tadqiqotlar ortiqcha vaznli ota-onalarning farzandlari orasida ham bolalik, ham katta yoshda shu muammoga duch keluvchilar ko‘p ekanini ko‘rsatmoqda. Bu oiladagi ovqatlanish odatlari bola tomonidan bevosita o‘zlashtirilishini tasdiqlaydi. Maktab yoshigacha zararli oziq-ovqatlardan uzoq bo‘lgan bolalar hayoti davomida bunday mahsulotlarni ratsionining asosiy qismiga aylantirmaydi. Shuning uchun farzandingiz sog‘lom vaznga ega bo‘lishini istasangiz, avvalo o‘zingiz sog‘lom ovqatlanishingiz kerak.') WHERE id = '70039ed8-6ea5-4eb9-9e14-4db990b7a7b1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Endi 3 yoshga to‘lib borayotgan farzandingiz atrofdagi olamni yanada yaxshiroq anglaydi. U kundalik tartibni to‘liq o‘zlashtirgan va hayot haqida ko‘proq savollar bera boshlagan. Bu davrda farzandingizning o‘ynashga bo‘lgan ehtiyoji ortganini sezishingiz mumkin. Agar u bilan qanday mashg‘ulotlar qilishni bilmasangiz, sizga bir nechta tavsiyalarimiz bor: 😊 Musiqa sadolari ostida raqsga tushishingiz, musiqa to‘xtaganda esa birdan qotib qolish yoki yo‘nalishni o‘zgartirish o‘yinlarini o‘ynashingiz mumkin. 3 yoshli bolalar uchun tafakkurni rivojlantiruvchi o‘yinlar ham bu davrda kundalik hayotingizdan albatta o‘rin olishi kerak. Turli buyumlarni birgalikda kattadan kichikka, uzundan qisqaga qarab terishingiz mumkin. Bu yoshda farzandingiz uzun-qisqa, katta-kichik kabi qarama-qarshi tushunchalarni o‘rganishga tayyor bo‘ladi. Shuningdek, birgalikda hikoya aytish o‘yinini o‘ynashingiz mumkin. Navbatma-navbat bir-biringizga o‘zingiz to‘qigan qisqa hikoyalarni aytib berish juda qiziqarli bo‘lishi mumkin! 😊') WHERE id = 'f3002e6d-b300-436f-b377-ff336ed0acaa';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '33 oylik chaqalog‘ingiz endi bir-biriga ulanadigan o‘yinchoqlarni qismlarga ajratib, yana qayta yig‘a oladi. Vintli o‘yinchoqlarning vintlarini ham burab yecha oladi. Ma’lum darajada mustaqil kiyina boshlaydi. Uch g‘ildirakli velosipedga minib, pedallarini aylantirish orqali uni boshqara oladi. Kattalar kabi har bir zinaga navbatma-navbat boshqa oyog‘ini qo‘yib ko‘tarila oladi va bir oyoqda tura oladi. Bundan tashqari, farzandingizning diqqatini jamlash muddati ham uzaya boshlaydi. U uzoqroq vaqt davomida mustaqil o‘ynay oladi. Shunga qaramay, o‘yin paytida sizning yonida bo‘lishingizni afzal ko‘rishi mumkin. Chaqalog‘ingiz sizni kuzatish orqali kundalik hayotni o‘rganishda davom etadi. Ayniqsa, taqlid va rolli o‘yinlar ko‘payadigan bu davrda uning o‘yinchoqlarini harakatlantirib, ularga topshiriqlar berayotganini ko‘rishingiz mumkin. Bunday o‘yinlar uning tasavvur olami boyib borayotganini ko‘rsatadi va hayotni anglashida muhim rol o‘ynaydi. Vaqti-vaqti bilan uning o‘yinchoqlar orqali yetkazayotgan ishoralariga e’tibor bersangiz, qo‘rquvlari, xavotirlari va istaklarini osonroq tushunishingiz mumkin.') WHERE id = '312c2aaa-2210-4dfd-80d6-b0c1928bed26';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning tishlarini parvarish qilish juda muhim va alohida e’tibor talab qiladigan masaladir. «Baribir sut tishlari, tushib ketadi!» deb tish parvarishiga beparvo qarash milk yallig‘lanishi va tish kariyesi kabi asoratlarga olib kelishi mumkin. Buning oldini olish uchun chaqalog‘ingizda tishlarini muntazam tozalash odatini shakllantirish — unga o‘rgatishingiz mumkin bo‘lgan eng yaxshi odatlardan biridir. Tish tozalash deganda birinchi bo‘lib xayolga keladigan vosita — tish pastasi bolalarga dastlabki davrda tavsiya etilmaydi. Bu davrda farzandingiz tishlarini pastasiz yuvishi mumkin. Ayrim mutaxassislar o‘rtacha 3 yoshgacha tish pastasidan foydalanishni tavsiya etmaydi. Bu yoshdan keyin esa no‘xatdek miqdordagi tish pastasidan foydalanish mumkin. Sizning vazifangiz — ovqatdan keyin va kechasi uxlashdan oldin tishlaringizni yuvib, unga namuna bo‘lishdir. Unutmang, chaqalog‘ingiz bu odatni sizga taqlid qilish orqali o‘zlashtiradi.') WHERE id = '8d37727a-164c-4cf0-b23a-460dee8cf99d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bilan birgalikda 33 oyni ortda qoldirdingiz, tabriklaymiz! 😊 Shu oydan boshlab so‘z boyligi oshib, u o‘z fikrini yanada erkin ifodalay oladi. Nutqi kundan-kunga rivojlanib boradi. Bu davrda kichkintoyingiz olmosh va bog‘lovchilardan to‘g‘ri foydalanadi, kim, nima, nega, qayerda kabi savollarni tez-tez bera boshlaydi. Nega va nima uchun degan savollarga mos javoblar beradi. Rasmlardagi odamlarni tanib, ko‘rsata oladi va ularning ismlarini aytadi. Gapirayotganda ovoz ohangini o‘zgartira oladi, so‘ralganda ismini, necha yoshdaligini va jinsini ayta oladi. Agar o‘rgatgan bo‘lsangiz, 10 gacha bo‘lgan sonlarni yoddan sanay oladi. Sevimli hikoyalarini qayta-qayta tinglashdan zerikmaydi. Boshqalar bilan sodda suhbatlar qura olsa-da, ayrim talaffuz xatolariga yo‘l qo‘yishi mutlaqo tabiiy.') WHERE id = '0ad387e8-b68f-42e3-a771-8b717ee81176';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning o‘sishi va rivojlanishi eng jadal kechadigan davr ortda qoldi. Endi uning rivojlanishi o‘smirlik davrigacha nisbatan sekin sur’atda davom etadi. Biroq bu uning har kuni iste’mol qilishi kerak bo‘lgan oqsil miqdorini o‘zgartirmaydi. Chaqaloq kun davomida o‘rtacha 100 qram go‘sht iste’mol qilishi kerak. Bu miqdor uning yoshi va vazniga qarab o‘zgarishi mumkin. Menyuda tovuq go‘shti, baliq va qizil go‘shtni navbatma-navbat berishingiz mumkin. Vitaminlar yo‘qolmasligi va chaqaloq oqsildan maksimal foyda olishi uchun go‘shtni imkon qadar qovurmaslikka harakat qiling. Bu mahsulotlar to‘g‘ri tayyorlanib iste’mol qilinganda, chaqaloqning temir va oqsilga bo‘lgan ehtiyojini to‘liq qondiradi. Baliq mavsumida esa unga imkon qadar ko‘proq baliq yedirishga harakat qiling. Baliq chaqaloqning aqliy va jismoniy rivojlanishi uchun zarur bo‘lgan barcha foydali moddalarga boy.') WHERE id = '31476911-a7ea-4f5e-a49b-77486ebc31c9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '33 oylik chaqalog‘ingizning harakat ko‘nikmalari ancha rivojlangan. U qo‘l va barmoqlaridan foydalanishni yaxshi o‘zlashtirgan. Boshqacha aytganda, endi qo‘llari bilan murakkabroq harakatlarni bajara oladi. 5-6 ta kubikni bemalol ustma-ust qo‘ya oladi, 6-12 bo‘lakli pazllarni yig‘adi va to‘pni havoga ota oladi. Muvozanatni saqlash qobiliyati ham yaxshi rivojlangani sababli bir oyog‘ida bemalol turib, to‘p o‘ynay oladi. U deyarli har qanday buyumni o‘rganib, ular bilan o‘ynay oladi. Qo‘llar chaqalog‘ingiz miyasining harakat va sezgi markazlarida funksional jihatdan eng katta o‘rinni egallaydigan tana qismidir. Chaqalog‘ingizning qo‘llaridan mohirona foydalana olishi uning asab tizimi qay darajada rivojlanganiga bevosita bog‘liq. Shu sababli chaqalog‘ingiz bilan birga mayda motorika ko‘nikmalarini rivojlantiradigan mashg‘ulotlarni tez-tez bajarishingiz juda muhim.') WHERE id = '3bca3dac-612d-48d3-8788-6c23c8d4b4e8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizga nisbatan, ayniqsa boshqalar oldida “uyatchan”, “sho‘x” yoki “injiq” kabi so‘zlarni ishlatmaslikka e’tibor bering. Chaqalog‘ingiz sizni eshitmayapti yoki gaplaringizga ahamiyat bermayapti deb o‘ylasangiz ham, u bu so‘zlarni aytayotganingizda tana tilingiz orqali hammasini anglaydi. Uning shaxsiyatiga bunday munosabatda bo‘lish o‘zlik hissining rivojlanishiga salbiy ta’sir ko‘rsatadi. Agar farzandingizda shunday fe’l-atvor xususiyatlari bo‘lsa, uning ehtiyojlarini hisobga olgan holda yo‘l tutishingiz kerak. Masalan, uyatchan bolani 10 nafar bolaning orasiga qo‘shib, undan yetakchilik qilishini kutish to‘g‘ri emas. Uni ijtimoiy hayotga asta-sekin, kichik qadamlar bilan tayyorlashingiz mumkin. Unutmang, biz muayyan fe’l-atvor bilan tug‘ilamiz, ammo atrof-muhit ta’siri bu fe’l-atvorni shakllantirishi va o‘zgartirishi mumkin.') WHERE id = '35e3ed0f-aad4-4c45-9de0-b5a3eebc1289';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Endi 3 yoshga yaqinlashayotgan bolangizga gul changi (polen) kabi asalarichilik mahsulotlarini bemalol berishingiz mumkin. Gul changi 22 turdagi aminokislota, uglevodlar, kalsiy, rux va ko‘plab vitaminlarni o‘zida jamlagan tabiiy oziqdir. Shuningdek, uning tarkibidagi flavonoidlar kuchli antioksidant xususiyatga ega. Antioksidant ta’siri tufayli u immunitetni mustahkamlaydi, kasalliklardan himoya qiladi va organizmning tiklanishiga yordam beradi. Tarkibidagi aminokislotalar, uglevodlar va vitaminlar bolaning jismoniy hamda miya rivojlanishini qo‘llab-quvvatlaydi. Bu davrda bolaning kuniga taxminan 10-15 gramm gul changi iste’mol qilishi yetarli. Biroq farzandingizda asal yoki asalarichilik mahsulotlariga allergiya bo‘lsa, bunday mahsulotlardan voz kechishingiz kerak. Shuningdek, gul changini ishonchli, tabiiy va organik manbalardan xarid qilish juda muhim.') WHERE id = 'e2dc9a31-e473-4137-a35c-bba202f969bf';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '33 oylik chaqalog‘ingiz bu davrda chips, shokolad va pechenye kabi mahsulotlarga juda katta qiziqish bildirishi mumkin. Ayniqsa, tengdoshlari orasida bunday mahsulotlarni iste’mol qiladiganlar bo‘lsa, u ham tatib ko‘rishni xohlaydi. Bunday vaziyatda chaqalog‘ingiz uchun shunga o‘xshash ta’mga ega yeguliklarni tabiiyroq usulda tayyorlashingiz mumkin. Masalan, chips xohlagan chaqalog‘ingizga pechda kam yog‘ bilan pishirilgan kartoshka bo‘laklarini tayyorlab berishingiz mumkin. Shuningdek, tabiiy va foydali usulda tayyorlangan pechenyelar bilan ham chaqalog‘ingizning bu istagini qondirishingiz mumkin. Bunda asosiy maqsad — chaqalog‘ingizning do‘konlarda sotiladigan tayyor mahsulotlarni iste’mol qilishiga yo‘l qo‘ymaslik. Muzlatilgan yarim tayyor mahsulotlar, haddan tashqari shirin ichimliklar, yog‘li va sho‘r chipslar kelajakda semizlikka sabab bo‘lishi mumkin. Chaqalog‘ingizning hozirgi ovqatlanish odatlari uning kelajakdagi hayotiga ta’sir qiladi. Shu sababli, bu davrda qilayotgan sa’y-harakatlaringizni chaqalog‘ingiz kelajagiga kiritilgan sarmoya deb hisoblashingiz mumkin.') WHERE id = 'e6a1b900-7219-4ca0-ae6e-83f3e11c466a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz endi rivojlanishning yangi bosqichiga qadam qo‘ydi. Shu davrdan 7 yoshgacha u hayot uchun zarur bo‘lgan asosiy ko‘nikmalarni egallay boshlaydi. Bularga faol va yordamsiz yugurish, sakrash, irg‘ish, bir oyoqda sakrash, ushlash, uloqtirish va to‘pni tepish kabi harakatlar kiradi. Bu xususiyatlar deyarli barcha bolalarda bir xil bo‘lgani va hayotiy ahamiyatga ega ekani uchun asosiy ko‘nikmalar deb ataladi. Ushbu oylarda mazkur harakatlar hali ancha qo‘pol ko‘rinishda namoyon bo‘ladi. Chunki chaqalog‘ingiz avval o‘z tanasining harakat imkoniyatlarini tushunishga va ularni sinab ko‘rishga harakat qiladi. Keyinchalik tanasini boshqarish qobiliyati ortgani sari harakatlari yanada uyg‘un va boshqariladigan bo‘lib boradi. Bu bosqichning oxiriga kelib esa chaqalog‘ingiz ushbu harakatlarni mexanik jihatdan yanada samarali bajara oladi. 5-6 yoshga kelib asosiy ko‘nikmalar to‘liq shakllanadi.') WHERE id = '35b98740-6814-45cf-ad4b-cc3187b7b7a4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingiz bilan o‘jarlik tufayli jiddiy kelishmovchiliklarga duch kelishingiz mumkin. Masalan, ob-havo yaxshi va siz tashqariga chiqmoqchisiz, ammo chaqalog‘ingiz ob-havoga mos kelmaydigan kiyimni kiyaman deb turib oladi. Bunday vaziyatda har qanday ota-ona kabi e’tiroz bildirsangiz, bu bir necha daqiqa davom etadigan yig‘i xurujiga aylanishi mumkin. Mutaxassislar bu ayanchli doira haqida shunday deydilar: “O‘jar bola bo‘lmaydi, o‘jar ota-ona bo‘ladi”. Albatta, bu bolaning har bir istagini bajarish kerak degani emas. Agar uning barcha istaklari bajarilaversa, boshqarib bo‘lmaydigan kuch va tartibsizlikka duch kelishingiz mumkin. Bunday paytlarda chaqalog‘ingizga “Cheklangan erkinlik” tamoyili asosida yondashishingiz kerak. Qisqacha aytganda, yuqoridagi misolga qaytsak, kiyimini o‘zi tanlamoqchi bo‘lgan chaqalog‘ingizga ob-havoga mos bir nechta variantni taklif qilib, ular orasidan tanlashiga ruxsat berishingiz mumkin. Bunday yondashuv muammoni kattalashmasidan hal qilishga yordam beradi.') WHERE id = '89f175d2-1f56-4a45-a902-ade3acc28e69';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingizning o‘ziga bo‘lgan ishonchini, muvaffaqiyatga erishish tuyg‘usini, mayda motorikasini, ranglar haqidagi bilimini hamda qism va butun o‘rtasidagi bog‘liqlikni rivojlantirmoqchi bo‘lsangiz, sizga ajoyib taklifimiz bor: munchoq tizish mashg‘uloti! Bu mashg‘ulot uchun sizga rangli jun iplar, teshigi katta munchoqlar va yerga yoyish uchun mos to‘shama kerak bo‘ladi. Chaqalog‘ingizni diqqat bilan kuzatgan holda, unga munchoqlarni ipga tizishda yordam berishingiz mumkin. Ushbu mashg‘ulot davomida chaqalog‘ingiz alohida munchoqlar birlashtirilganda qanday buyum hosil bo‘lishini ko‘radi va qism hamda butun o‘rtasidagi bog‘liqlikni anglaydi. Shu bilan birga, bu qiziqarli mashg‘ulot chaqalog‘ingizning diqqati va diqqatni jamlash qobiliyatini mustahkamlash uchun juda foydali. Qo‘l-ko‘z muvofiqligini rivojlantirish va boshlagan ishini oxiriga yetkazishni o‘rgatish jihatidan ham foydali bo‘lgan bu mashg‘ulot chaqalog‘ingizga zavqlanib o‘rganish imkonini beradi. Munchoqlarni yutib yuborish xavfi borligi sababli, mashg‘ulot davomida chaqalog‘ingizni yolg‘iz qoldirmasligingiz juda muhim.') WHERE id = 'e89e203c-f03d-42bd-adfb-e246026e0afe';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'O‘tkazilgan tadqiqotlar shuni ko‘rsatadiki, onalarning katta qismi uyquning ahamiyati haqida yetarlicha ma’lumotga ega emas. To‘laqonli tungi uyqu chaqalog‘ingizga kun davomida o‘rganganlarini tizimlashtirish, energiya zaxirasini tiklash hamda yangi kunni xursand, tetik va eng muhimi, o‘rganishga tayyor holda boshlash imkonini berib, uning aqliy rivojlanishini tezlashtiradi. Chaqalog‘ingizda uyqu bilan bog‘liq muammolar uzoq davom etsa, bu miya rivojlanishining kechikishiga sabab bo‘lishi va sog‘lom o‘sishiga to‘sqinlik qilishi mumkin. Chunki hozirgi yosh davri aqliy rivojlanish va sog‘lom o‘sish uchun juda muhim. Bu davrda chaqalog‘ingizning miyasi ma’lumotlarni gubka kabi shimib oladi. Miya rivojlanishining taxminan 75-80%-i shu davrda yakunlanadi va miya hajmi deyarli voyaga yetgandagi hajmiga yetadi. Bu davrda yo‘l qo‘yilgan xatolar va beparvolik oqibatlarini kelajakda bartaraf etish imkonsiz bo‘lishi mumkin. Shu sababli uzluksiz tungi uyqu, ayniqsa REM uyqusi, chaqalog‘ingiz miyasining mavjud rivojlanish salohiyatini to‘liq ro‘yobga chiqarishda hayotiy ahamiyatga ega.') WHERE id = '295fa9e3-3754-4afa-a728-c53e7964be12';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz hozir haqiqiy his-tuyg‘ular kashfiyotchisidir. U aql-zakovati, atrof-muhiti, tili va madaniyatini har tomonlama o‘rganish orqali shakllanmoqda. Bu davrda farzandingiz kattalarnikidan farq qiladigan o‘ziga xos ong tuzilishiga ega. U kattalarning fikrlash yo‘lidan bormaydi. Ilm-fanda bu bosqich "ongsiz ong bosqichi", Montessori metodida esa "singdiruvchi ong" deb ataladi. Buning eng yorqin namunasi — farzandingizning til o‘rganish usulidir. Boshqacha aytganda, atrofidagilar u bilmaydigan tilda gaplashayotganida, u ikki yil davomida indamay kuzatib, so‘ng birdan bu tilda mukammal grammatika va talaffuz bilan gapira boshlashi "singdiruvchi ong"ning namoyon bo‘lishidir. Shu sababli, farzandingizning ushbu "qabul qiluvchi" davrida uning rivojlanishiga mos mashg‘ulotlarni tashkil etishingiz juda muhim. Farzandingiz rivoji uchun ajratgan har bir mazmunli daqiqangiz uning kelajakdagi muvaffaqiyatlariga poydevor yaratadi.') WHERE id = 'd731faa5-02e6-48b2-9d1d-d0e589f45abc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz bu bosqichda hali ham so‘rg‘ich ishlatsa va “Nima qilsam ham, undan voz kechira olmadim”, desangiz, siz uchun mutaxassis tavsiyasi bor! 😊 Mutaxassislardan biri bunday vaziyatlarda “buzilish” tushunchasidan foydalanishni tavsiya qiladi. Uning fikricha, dunyoda so‘rg‘ichlar ham buzilishi va “nafaqaga chiqishi” mumkin. Shu nuqtayi nazardan, chaqalog‘ingiz bilan suhbatlashayotganda har qanday buyum buzilishi mumkinligini aytishingiz mumkin. Masalan, endi ishlamaydigan o‘yinchoq yoki qalamni topganingizda: “Bu buzilibdi, uni tuzata olmaymiz. Shuning uchun uni tashlashimiz kerak”, deyishingiz mumkin. Kun davomida buzilgan buyumlar haqida gapirishda davom eting. Tayyor bo‘lganingizda esa so‘rg‘ich bilan xayrlashishingiz mumkin. Chaqalog‘ingizga so‘rg‘ichni ko‘rsatib: “Qara, bu buzilibdi”, deb uni birgalikda tashlashingiz mumkin.') WHERE id = '77122e18-58c2-4599-aad9-dbc48d22e09c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ishtahasizligi bilan kurashayotganingizni bilamiz. Bu davrda onalar farzandining ishtahasini ochish uchun turli usullardan foydalanadilar. Karob shinnisi esa eng ko‘p qo‘llanadigan qo‘shimcha oziq-ovqatlardan biridir. Karob shinnisi ishtahani oshirishini tasdiqlovchi ilmiy tadqiqotlar yetarli bo‘lmasa-da, u salomatlik uchun juda foydali. Masalan, u temir, kalsiy, kaliy, magniy, fosfor, rux va ko‘plab vitaminlarga boy. Tarkibidagi gall kislotasi tufayli astma, allergiya va bronxitda ijobiy ta’sir ko‘rsatadi, immunitet hamda ovqat hazm qilish tizimini qo‘llab-quvvatlaydi. Chaqalog‘ingizning aqliy rivojlanishiga yordam beradi va antioksidant tarkibi tufayli yuqori nafas yo‘llari infeksiyalarida balg‘am ko‘chiruvchi ta’sir ko‘rsatadi. Tarkibidagi beta-karotin erkin radikallarni zararsizlantiradi. Ovqat hazm qilish tizimini tartibga soladi va ayniqsa ich ketishida foydali ta’sir ko‘rsatishi taxmin qilinadi.') WHERE id = '0f76d1dc-d8f6-44ec-b73b-3a61bf8f4885';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '3 yosh sindromi davrini yengilroq va sog‘lomroq o‘tkazishni istasangiz, avvalo o‘zingizdan boshlashingiz kerak. Masalan, hech bir jumlani “Yo‘q”, “Ammo” yoki “Mumkin emas” kabi so‘zlar bilan boshlamang. Buning o‘rniga chaqalog‘ingiz bilan chegaralari aniq belgilangan mehrli tilda muloqot qiling. Masalan: “Buni ovqatingni yeb bo‘lgach yeyishing mumkin”, “O‘yinchoq olinadigan kun kelganda, o‘sha o‘yinchoqni olib berishim mumkin”, “Bu kiyimni juda yaxshi ko‘rishingni tushunaman. Havo isiganda uni yana kiyishing mumkin”, kabi izohlar asqatadi. Agar jumlalarni “Yo‘q” deb boshlasangiz, muloqot qiyinlashadi, chunki siz undan biror narsa so‘raganingizda u ham darhol “yo‘q” deydi. Chaqalog‘ingiz xohlayotgan, ammo amalga oshirib bo‘lmaydigan narsaning sababini tushuntirib, muqobil variantlarni taklif qiling. Siz xotirjam gapirishingizga qaramay, u jahli chiqishda davom etsa, o‘zingizni bosib: “Yaxshi, tinchlanishingni kutaman. Variantlardan birini tanlasang, o‘yinimizni to‘xtagan joyimizdan davom ettirishimiz mumkin”, deb kutish samarali bo‘ladi. Sizning xotirjam va vazmin bo‘lishingiz chaqalog‘ingizni ham tinchlantiradi.') WHERE id = '72c2f63f-5be1-4b2b-b6e5-eaccc64d9c5d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tuxum ona sutidan keyin barcha makro va mikro oziq moddalarni o‘zida mujassam etgan ikkinchi eng muhim oziq-ovqatdir. Chaqalog‘ingizning ovqatlanishida tuxumga katta ahamiyat berishingizni bilamiz. Biroq tabiiy tuxum, qishloq tuxumi va organik tuxum kabi tushunchalar ba’zan chalkashlik tug‘diradi. Odatda, “erkin yuradigan tovuq tuxumi” deyilganda, hammaning ko‘z oldiga qishloqda erkin yuradigan tovuqlar keladi, ammo bu har doim ham shunday emas. Bu shunchaki tovuqlar tor qafas o‘rniga belgilangan ochiq hududda harakatlana oladigan ishlab chiqarish usulidir va bunday tuxumning oziqaviy qiymati oddiy tuxumlardan katta farq qilmasligi mumkin. Organik tuxum ishlab chiqarishda esa yemlarning GMOsiz bo‘lishi va tuproqda kamida uch yil davomida kimyoviy o‘g‘itlardan foydalanilmagan bo‘lishi shart. Shu nuqtayi nazardan, mustaqil tashkilotlar ko‘proq organik tuxum iste’mol qilishni tavsiya qiladi.') WHERE id = '0d3c6f23-838a-4186-987c-62162e29d087';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingizning tagini ho‘llab qo‘yayotganini kuzatishingiz mumkin. Chunki bu bolalar salomatligi va kasalliklari sohasida eng ko‘p uchraydigan shikoyatlardan biridir. Odatda bolalarning tunda tagini ho‘llab qo‘yishiga 3 ta asosiy sabab bo‘lishi mumkin: siydik pufagi mushaklari faoliyatidagi nomutanosiblik (siydik chiqishini ushlab turuvchi mushakning zaifligi), siydik pufagining kichikligi yoki organizmning me’yordan ortiq siydik ishlab chiqarishi. Shu sababli farzandingizga uxlashdan 2 soat oldin haddan tashqari ko‘p suv ichirmaslikka harakat qiling. Shuningdek, unda siydik yo‘llari infeksiyasi yo‘qligiga ishonch hosil qilishingiz kerak. Gormonal buzilish bor-yo‘qligini aniqlash uchun esa bolalar shifokori (pediatr) qabuliga yozilish juda muhim.') WHERE id = '706d264f-8089-480e-811b-db2ce4f82fa7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'O‘zini yerga tashlash, yugurib borib boshini devorga urish, jahli chiqib baqirish, yig‘i xurujlari (odatda ko‘z yoshisiz) va nima istayotganini bilmaslik... Bu xatti-harakatlar sizga ham tanishmi? 😊 Agar farzandingizda bunday holatlarni yana kuzata boshlagan bo‘lsangiz, yolg‘iz emasligingizni biling. Hozir minglab oilalar siz bilan bir vaqtda tugamaydigandek tuyuladigan sindromlardan biri bilan kurashmoqda. 3 yosh sindromining belgilari bu davrda yanada yaqqol namoyon bo‘lishi mumkin. Farzandingiz bilan muloqotingiz qanchalik mustahkam bo‘lsa, bu davrni shunchalik yengil o‘tkazasiz. O‘zini ifodalashda qiynaladigan bolalar bilan bu jarayon biroz murakkabroq kechishi mumkin, ammo bu shunchaki o‘tkinchi bosqich ekanini unutmang. Sabrli bo‘lishingiz va bu holat vaqtinchalik ekanini anglab yetishingiz juda muhim.') WHERE id = 'aad09a79-e81c-43b7-ab90-cbeb4244addf';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Shu kunlarda farzandingiz siz bilan ko‘proq vaqt o‘tkazishni va sizni tez-tez quchoqlashni istayotganini sezishingiz mumkin. Hatto siz ish bilan band bo‘lganingizda ham, u to‘satdan yoningizga kelib sizni quchoqlashi yoki quchog‘ingizga sakrashni xohlashi mumkin. Ayniqsa, tashqariga chiqqaningizda uning tez charchab, quchog‘ingizda ko‘tarib yurishingizni so‘rashi odatiy hol. Bunday paytlarda imkon qadar uni rad etmaslikka harakat qiling. Chunki u tashqaridan kelishi mumkin bo‘lgan xavflardan qo‘rqadi va faqat sizning quchog‘ingizda o‘zini xavfsiz his qiladi. Uni quchog‘ingizga olishdan oldin u bilan kichik bir kelishuv qilishingiz mumkin: uzoq vaqt ko‘tarib yursangiz, belingiz og‘rishi mumkinligini va dam olishingiz kerak bo‘lganda uning o‘zi yurishi lozimligini tushuntiring. Qo‘rquv hissining paydo bo‘lishi rivojlanishning tabiiy qismidir, ammo ba’zida bu sizni charchatishi mumkin. Kun davomida farzandingizga uni juda yaxshi ko‘rishingizni ayting va bunga ehtiyoji borligini sezganingizda uni quchoqlashni unutmang.') WHERE id = '158d8d1e-7cf7-43eb-ab2b-077ae8698a3a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Jamiyatda odatda tinch bolalar ko‘proq "tarbiyali" deb hisoblansa-da, aslida farzandingiz bu davrda faol va harakatchan bo‘lishi kerak. Uning chaqqonligi yangi ko‘nikmalarni egallashi va bu ko‘nikmalar miyada to‘g‘ri shakllanishi uchun juda muhim. Farzandingiz energiyasini to‘g‘ri sarflashi uchun rejalashtirilgan mashg‘ulotlarga ustunlik berishingiz kerak. Harakat ko‘nikmalarining rivojlanishida muhit, o‘yinchoqlar va vaqt omili katta rol o‘ynaydi. Bu davrda mashg‘ulotlar qanchalik maqsadli va xilma-xil bo‘lsa, bolaning harakat qobiliyati shunchalik yaxshilanadi. Sport bilan shug‘ullanishni puxta tayyorgarlik bilan boshlashi uchun mashg‘ulot muhiti muhim. Hozirgi maqsad — asosiy harakatlarni to‘liq o‘zlashtirish. Ushbu ma’lumotlardan kelib chiqib, farzandingizni suzish kabi oddiy va foydali sport turlariga yo‘naltirishingiz mumkin.') WHERE id = 'dfcc6d4e-9df3-4f70-83ad-b2044dc2b08d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda bolangizning nonushtasiga asalni bemalol qo‘shishingiz mumkin. Agar yutishga qiynalsa, uni non ustiga surtib berish ham yaxshi variant. Asal tarkibidagi vitaminlar, minerallar, probiotiklar va prebiotiklar tufayli bolalar uchun haqiqiy shifo manbai hisoblanadi. Asal organizmdagi kurashuvchi hujayralar — leykotsitlar va limfotsitlar sonini oshirib, immunitetni mustahkamlashi va kasalliklardan himoya qilishi ma’lum. Shuningdek, qizil qon hujayralari sonini oshirib, temir tanqisligi bilan bog‘liq kamqonlikning oldini oladi, bu esa jismoniy va nevrologik rivojlanishga, hatto IQ darajasiga ham ijobiy ta’sir ko‘rsatadi. Biroq bozorda soxta mahsulotlar ko‘p bo‘lgani sababli, asal organik va sifatli brendga tegishli ekaniga e’tibor bering. Agar bolangiz asalni birinchi marta tatib ko‘rsa, allergiya xavfini hisobga olib, 3 kun qoidasiga amal qilishni unutmang.') WHERE id = '56e68160-3db6-4a51-9004-f5ed90328cb8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolangizning ovqatlanishiga katta ahamiyat berishingizni bilamiz. Ammo sog‘lom rivojlanish uchun uzluksiz tungi uyqu ham ovqatlanish kabi muhim ekanini unutmang. Chunki bolalar haqiqatan ham uyquda o‘sadi. Uyqu paytida, ayniqsa qorong‘ida melatonin gormoni ajralib chiqadi. Bu gormon immunitetni mustahkamlaydi va gipofiz bezining ko‘proq o‘sish gormoni ishlab chiqarishiga yordam beradi. Chaqalog‘ingiz kun davomida o‘rgangan ma’lumotlarini uyqu paytida miyasida mustahkamlaydi, bu esa miya hujayralari o‘rtasidagi aloqalarni kuchaytiradi. Yaxshi uxlab, dam olgan bola yangi kunni yanada tetik boshlaydi, o‘rganishga ishtiyoqi baland bo‘ladi va o‘yinlardan ko‘proq zavq oladi.') WHERE id = 'd38c5b0c-a2eb-49b2-9b6a-81efef827283';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda bolangiz uchun duradgor, shifokor yoki oshpaz to‘plamlari kabi kasblarga oid o‘yinchoqlar xarid qilishingiz mumkin. Bunday o‘yinchoqlar bolalar rivoji bo‘yicha mutaxassislar tomonidan tavsiya etiladi va bolaning rivojlanishiga katta hissa qo‘shadi. Bu o‘yinchoqlarni ham qizlar, ham o‘g‘il bolalar uchun tanlashingiz mumkin. Mutaxassislarning ta’kidlashicha, sog‘lom gender o‘zligi shakllanishi uchun bolalarning o‘yinchoqlarni ajratmasdan, har xil turdagi o‘yinlar bilan tanishishi foydalidir. Albatta, bolangiz o‘z tabiatiga ko‘ra ayrim o‘yinchoqlarni afzal ko‘rishi mumkin (masalan, qizlarning qo‘g‘irchoqlarga, o‘g‘il bolalarning mashinalarga moyilligi). Biroq kasblarning jinsi bo‘lmasligini unutmasligingiz va bolangizni bu borada cheklamasligingiz kerak.') WHERE id = 'b8d6b288-c63d-469e-a5b5-b302aabd5be2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingizning his-tuyg‘ulari yanada noziklashganini kuzatishingiz mumkin. Masalan, kimdir yig‘lasa, u nega yig‘layotganiga qiziqadi, uning qayg‘usiga sherik bo‘lib, o‘zi ham qattiq xafa bo‘lishi mumkin. Mehr-shafqat tuyg‘usi kuchaygani uchun u yig‘layotgan odamni tinchlantirishga harakat qiladi, yuzini silaydi va tasalli beruvchi harakatlar qiladi. Albatta, u bularning barchasini sizdan o‘rgangani uchun qiladi. Uning asosiy ustozi sifatida farzandingiz uchun har tomonlama namuna ekaningizni unutmasligingiz kerak. Bu oylarda u sizning his-tuyg‘ularingizni ham anglay boshlaydi, ya’ni siz xursand, asabiy yoki qayg‘uli bo‘lganingizda yoningizda bo‘lishga harakat qiladi. U qaysi xatti-harakatdan so‘ng sizda bu hislar paydo bo‘lishini tushunadi va kelajakda o‘zi ham xuddi shunday vaziyatga duch kelganda siz kabi yo‘l tutadi. Shu bilan birga, siz ham farzandingizni tushunishga harakat qilishingiz kerak. Chunki uni yetuk shaxs qilib tarbiyalaydigan asosiy inson sizsiz. U odamlar bilan to‘g‘ri muloqot qila olishi uchun unga hamdardlik bildirishni va yordamga muhtojlarga ko‘maklashish qanchalik yaxshi ekanini o‘rgatishingiz lozim. Bundan tashqari, minnatdorlik bildirishni, xushmuomala bo‘lishni va shirin so‘z har qanday eshikni ochishini ko‘rsatishingiz kerak. Shuningdek, chaqalog‘ingizni ruhlantirib, bu yoshda paydo bo‘lishi mumkin bo‘lgan uyatchanlik hissini kamaytirishingiz va uning o‘ziga ishongan shaxs bo‘lib ulg‘ayishiga ko‘maklashishingiz lozim.') WHERE id = '0ce0c599-580b-4527-aa93-807483cb4649';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu davrda qanday ovqatlanishi kerakligi haqida sizda ayrim savollar bo‘lishi mumkin. Shu bois 33 oylik bolangiz bir kunda nimalar iste’mol qilishi kerakligini ko‘rsatadigan namunaviy ro‘yxatni taqdim etamiz! Nonushtaga: ko‘kat va pishloq solib, sariyog‘da tayyorlangan omlet + 2-3 dona zaytun + 1 bo‘lak butun donli bug‘doy noni bolangizning barcha oziq-ovqat guruhlaridan foyda olishiga yordam beradi. Tamaddi uchun: 1 dona kichik meva + 2-3 dona quritilgan anjir + 1 dona butun yong‘oq mag‘zi uning energiyaga bo‘lgan ehtiyojini to‘liq qondiradi. Tushlikka: pechda pishirilgan qizilbaliq (losos) + 1 bo‘lak butun donli bug‘doy noni; agar baliq bo‘lmasa, muqobil ravishda tovuq go‘shti yoki mol go‘shti qo‘shilgan dukkakli taom berishingiz mumkin. Keyingi tamaddi uchun: 2 dona uyda tayyorlangan shakarsiz suli pechenyesi + yarim stakan meva sharbati yetarli. Kechki ovqatga esa: sabzavotli palov + yarim kosa qatiq berishingiz mumkin. Istakka ko‘ra, kechasi uxlashdan oldin 1 stakan sut ham mos tanlovdir.') WHERE id = '549b2994-2980-4e78-85f4-a5477bf37526';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu bosqichda chaqalog‘ingizning aqliy rivojlanishi jadal kechadi, shuning uchun rivojlanishni rag‘batlantiradigan va miyani faollashtiradigan o‘yinchoqlarni tanlashingiz muhim. Harakatlanish qobiliyati ancha yaxshilangani uchun unga 3 g‘ildirakli velosiped olib berishingiz mumkin. Xavfsiz sharoitda velosiped haydashiga imkon yaratib, uning ham ijtimoiylashishiga, ham energiyasini samarali sarflashiga yordam berasiz. Uyda bo‘lgan kunlaringizda qo‘l ko‘nikmalarini rivojlantirish uchun yirik qismlardan iborat boshqotirmalar yoki pazllarni tanlashingiz mumkin. Shuningdek, uy yumushlarida sizga taqlid qilgani uchun unga o‘yinchoq oshxona to‘plamlari yoki kichik maishiy buyumlar olib berishingiz mumkin. Bu davrda sakrash, irg‘ish va urishga qiziqishi kuchli bo‘lgani sababli, baraban yoki ritm tayoqchalari kabi o‘yinchoqlar ham juda asqatadi. Bularning barchasi chaqalog‘ingizning ham nozik, ham yirik motorika ko‘nikmalarini rivojlantirish uchun ajoyib vositalardir.') WHERE id = '369cc37b-2f9a-4abf-a1f2-8c6ddb44235b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning hozirgi faol o‘yin davrida ovqatlanishi kattalarnikiga yaqin darajaga yetdi. Bu bosqichda kattalar ratsionidagi kabi yog‘lardan ortiqcha qo‘rqishingiz shart emas. Chunki oshqozon hajmi kichik bo‘lgan farzandingizga kamroq miqdorda ko‘proq energiya beradigan yog‘lar kerak. Yog‘ning 1 grammi 9 kaloriya beradi, bu esa bolaning kun davomida zarur bo‘lgan energiyasining katta qismini ta’minlaydi. Biroq uning miqdorini haddan tashqari oshirmaslik kerak; yog‘ni ortiqcha iste’mol qilish kelajakda yurak-qon tomir salomatligi uchun xavf tug‘dirishi mumkin. Shuning uchun siz ham, farzandingiz ham sog‘lom ovqatlanish odatlarini shakllantirishingiz uchun foydali yog‘larga ustunlik bering. Masalan, taomlarda zaytun moyidan foydalanish, avokado, bodom, funduq va yong‘oq kabi yog‘li urug‘ va mag‘izlarni berish eng yaxshi tanlovdir.') WHERE id = '6a9442ee-d5d9-453f-a3b4-67e47e360e31';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'So‘nggi yillarda butun dunyoda keng tarqalgan sahnalashtirish mashg‘ulotlari, ayniqsa, maktabgacha yoshdagi bolalarning rivojlanishi uchun beqiyos ahamiyatga ega. Bunday mashg‘ulotlarda o‘yin, rollarni ijro etish, hikoya tuzish kabi usullardan foydalaniladi. O‘yin — bolaning ta’lim olishidagi eng muhim vositadir. Farzandingiz hamma narsani taqlid qilish orqali o‘rganadi. Keling, u bilan birgalikda bajarishingiz mumkin bo‘lgan qiziqarli sahnalashtirish namunasini ko‘rib chiqamiz: 1. Men chaqaloqman (Chaqaloq kabi g‘ujanak bo‘lib olish). 2. Avval emakladim (Emaklash harakati). 3. Keyin yurdim (Yurish harakati). 4. So‘ng gapirdim (Gapirish harakati). 5. O‘sdim, o‘sdim, o‘sdim (O‘rindan turib bo‘yini ko‘rsatish). 6. Maktabga bordim, hozir 3 yoshdaman (3 ta barmoqni ko‘rsatish). Bunday mashg‘ulotlar qiziqarli bo‘lish bilan birga, farzandingizning ijodkorligini rivojlantiradi va yangi tushunchalarni oson o‘rganishiga yordam beradi.') WHERE id = 'b977ef12-87df-48c3-93a8-39c832b155c7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar siz ishlaydigan ona bo‘lsangiz va farzandingiz bilan yetarlicha vaqt o‘tkaza olmayapman deb o‘ylasangiz, aslo xafa bo‘lmang. Mutaxassislar bola bilan o‘tkaziladigan vaqtning davomiyligidan ko‘ra, uning sifati muhimroq ekanini ta’kidlaydilar. Ishdan uyga qaytgach, farzandingiz bilan mazmunli o‘tkazgan yarim soat yoki bir soat ba’zan kun bo‘yi birga o‘tkazilgan samarasiz vaqtdan ancha foydaliroqdir. Qolaversa, dam olish kunlari ham sizniki! Dam olish kunlari butun oilangiz bilan uzoq sayrga chiqishingiz, velosiped minishingiz yoki turli to‘p o‘yinlarini o‘ynashingiz mumkin. Bolalar ko‘ngilochar markazlariga borib, birgalikda maroqli vaqt o‘tkazish ham ajoyib tanlovdir. Unutmang, chaqalog‘ingiz uchun sizning o‘rningiz har qanday sharoitda ham boshqalarnikidan o‘zgacha va doimo shunday bo‘lib qoladi. Shuning uchun o‘zingizni qiynamang; ulgurmagan ishlaringizga emas, birga baham ko‘rgan go‘zal onlaringizga e’tibor qarating.') WHERE id = 'd9001d20-5e18-461f-a3d5-cec998022416';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bilan yana bir oyni ortda qoldirdingiz. 34-oyga xush kelibsiz! 😊 34 oylik farzandingizning bu davrdagi rivojlanishi avvalgi oydagidan deyarli farq qilmaydi. Bu oyning eng muhim yangiligi shundaki, farzandingiz endi maktabgacha ta’limga to‘liq tayyor. Shuni ham ta’kidlash kerakki, 3 yosh sindromiga qadam qo‘ygan chaqalog‘ingiz bilan sizni biroz murakkab, ammo qiziqarli jarayon kutmoqda. 3 yosh inqirozi deb ham ataladigan bu bosqichda farzandingiz o‘z egosini kashf etadi. Ego shaxsiyat tuzilishining eng muhim qismlaridan biridir. Shaxsiyat deb ataladigan tuzilma o‘zaro bog‘liq uchta asosiy qismdan — impulslar, istaklar va ehtiyojlar; ego; qadriyatlar, e’tiqodlar va vijdondan iborat. Ego bu tuzilmada muvozanatni saqlovchi vazifani bajaradi. Shu nuqtai nazardan qaraganda, egoning ruhiy salomatligimizda juda muhim o‘rin tutishi ayon bo‘ladi. Anacan oilasi sifatida biz doimo yoningizdamiz!') WHERE id = 'a8ffabb9-3040-4b25-bec5-5f9659629255';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingizni 2 yoshida batafsil ko‘z tekshiruvidan o‘tkazmagan bo‘lsangiz, buni u 3 yoshga to‘lmasidan oldin amalga oshirishingiz juda muhim. Chunki g‘ilaylik, ko‘z dangasaligi va turli ko‘rish nuqsonlarini aniqlash uchun ko‘z tekshiruvi albatta 3 yoshdan oldin o‘tkazilishi kerak. Bolalarda ko‘rish tizimi dastlabki 9 yil davomida to‘liq rivojlanadi va undan keyin jiddiy o‘zgarish yuz bermaydi. Barcha bolalar singari, kichkintoyingizda hech qanday muammo bo‘lmasa ham, u 3 yoshga to‘lguniga qadar albatta ko‘z shifokori ko‘rigidan o‘tishi lozim. 9-10 yoshgacha davolanmagan ko‘rish buzilishlari oqibatida yuzaga kelgan ko‘z dangasaligini katta yoshda davolashning imkoni bo‘lmaydi. Bundan tashqari, ko‘rishida nuqsoni bo‘lgan bolalarning maktabda o‘qish va o‘zlashtirishda qiyinchiliklarga duch kelish ehtimoli yuqori. Shu sababli muammo qanchalik erta aniqlansa, davolashning muvaffaqiyatli yakunlanish ehtimoli shunchalik yuqori bo‘ladi.') WHERE id = 'e386827d-ad41-4c20-bd38-219ad4b81467';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingiz tun bo‘yi uyg‘onmasdan uxlashini istasangiz, unga mustaqil ravishda uxlab qolish odatini o‘rgatishingiz kerak. Aks holda, u har safar uyg‘onganida uni qayta uxlatish uchun siz ham uyg‘onishingizga to‘g‘ri keladi. Ehtimol, farzandingiz endi chaqaloqlar karavotiga sig‘mayotgandir. Bunday holat uning uyqu sifatiga salbiy ta’sir qilishi mumkin. Sog‘lom uyqu uchun farzandingizga mos karavot sotib olishingiz mumkin. Har qanday yoshdagi bolalarda eng ko‘p uchraydigan ikkita asosiy uyqu muammosi — uxlab qolishdagi qiyinchilik va tez-tez uyg‘onishdir. Farzandingiz sizni chaqirmasdan tun bo‘yi uxlashini istasangiz, eng muhimi, u biror o‘yinchoq yoki buyumni quchoqlab, o‘zini tinchlantirishni va qayta uxlab qolishni o‘rganishi kerak. Farzandingizning uxlab qolish uchun musiqa, yorug‘lik yoki ovqatga odatlanishi to‘g‘ri emas. Chunki bunday noto‘g‘ri odat uning tunda uyg‘onganida qayta uxlab qolish uchun yana shu narsalarni talab qilishiga sabab bo‘ladi.') WHERE id = '4ab036c3-4a94-40eb-b15f-cc5e03491b45';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz suyaklarining rivojlanishi uchun bu davrda kalsiyga boy oziq-ovqatlarni iste’mol qilishi juda muhim. Shu sababli u har kuni 2 stakan sut yoki shunga teng miqdorda sut mahsulotlarini iste’mol qilishi kerak. Sut mahsulotlarini farzandingizning ham asosiy taomlari, ham tamaddi menyusiga kiritishingiz mumkin. Sut tanlashda e’tibor berishingiz kerak bo‘lgan eng muhim jihat — sut yangi va pasterizatsiyalangan bo‘lishidir. Qatiqni ham imkon qadar pasterizatsiyalangan sutdan uyda o‘zingiz tayyorlashga harakat qiling. Agar farzandingiz sutning ta’mini yoqtirmasa va uni ichishni istamasa, sutga shakar yoki boshqa moddalar qo‘shib, ta’mini o‘zgartirishdan saqlaning. Buning o‘rniga unga qatiq, tvorog va pishloq kabi muqobil sut mahsulotlarini taklif qilishingiz mumkin.') WHERE id = 'eeb8003d-add3-422d-9fd8-3b5b9e6003eb';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning qiziquvchanligi shu darajaga yetadiki, ba’zan u sizni charchatadigan darajada ko‘p savol bera boshlaydi. Nutq qobiliyati rivojlangani sayin Nega?, Nega kechalari uxlaymiz?, Nega olmalar daraxtda o‘sadi?, Nega yomg‘ir yog‘adi? kabi savollarni tez-tez eshitishingiz mumkin. Albatta, bu tuganmas savollar har qanday ota-ona singari sizni ham charchatishi mumkin. Ammo unutmang, savol berish farzandingizning aqliy rivojlanayotgani va dunyoni kashf etayotganidan dalolat beradi. U savollar orqali o‘rganadi. Charchagan paytingizda uni jerkib bermasdan, Savolingga birozdan keyin javob bersam maylimi? kabi muloyim munosabat bildiring. Chunki bolaning xayolini chalkashtiradigan yoki uni bezovta qiladigan vaziyatlarda faqat siz beradigan javoblar uni tinchlantirishi mumkin.') WHERE id = '2fa7ea2e-a30f-47c2-aef5-ed3fe5788bde';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz sabzavot yemasa va bu sizni tashvishga solsa, bilingki, bunday muammoga duch kelgan yagona inson siz emassiz. Odatda bolalar eng kam yoqtiradigan, ammo ular uchun juda muhim bo‘lgan oziq-ovqatlar sabzavotlardir. Deyarli barcha vitaminlar turli sabzavot va mevalarda mavjud. Shu sababli farzandingiz ratsionini imkon qadar xilma-xil qilishingiz kerak. Agar u pishirilgan sabzavotlarni yoqtirmasa, xomligicha iste’mol qilish mumkin bo‘lgan sabzavotlardan salat tayyorlashingiz mumkin. Tamaddi uchun esa eng yaxshi tanlov mevalardir. Shu tariqa bolangizni ortiqcha shakar va shokolad iste’molidan ham uzoq tutasiz. Farzandingiz barcha sabzavot yoki mevalarni yoqtirishi shart emas. Kattalar kabi uning ham o‘z ta’bi bor. Har bir oziq-ovqat guruhidan 2-3 turini iste’mol qilishi kifoya. Uni majburlash ovqatdan yanada bezishiga sabab bo‘lishi mumkin.') WHERE id = '93e9401a-1194-4460-ab5a-1ff01deaad41';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Mutaxassislarning umumiy fikriga ko‘ra, ikki yoshdan uch yoshgacha bo‘lgan bolalar tunda 11 soat, kunduzi esa taxminan bir yarim yoki ikki soat uxlashi kerak. Bu yoshdagi bolalarning aksariyati kechqurun soat 19:00 dan 21:00 gacha uxlaydi, ertalab esa 06:30 dan 08:00 gacha uyg‘onadi. Chaqalog‘ingizning uyqu tartibi asta-sekin siznikiga o‘xshab borsa-da, 4 yoshgacha u sizga qaraganda yengil REM uyqu bosqichida ko‘proq vaqt qoladi. Natijada uyqu bosqichlari o‘rtasidagi o‘tishlar tez-tez yuz bergani uchun chaqalog‘ingiz tunda sizdan ko‘ra ko‘proq uyg‘onadi. Aynan shu sababli, u sizni uyg‘otmasdan tun bo‘yi uzluksiz uxlashini istasangiz, unga mustaqil ravishda qayta uxlab qolish odatini o‘rgatishingiz muhim. Ayniqsa, uxlashdan oldin ong ostiga ta’sir qiladigan televizor, planshet va telefon kabi texnologik qurilmalardan uzoq turishingiz kerak. Bunday qurilmalar chaqalog‘ingiz uyqusining odatdagidan ko‘ra tez-tez bo‘linishiga sabab bo‘lishi mumkin.') WHERE id = '2c2d7b4a-f9e9-4546-9aa6-71036a012509';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingizga nozik motorika ko‘nikmalarini rivojlantirishga yordam beradigan rangli qalamlar, bo‘yash va faoliyat kitoblarini olib berishingiz mumkin. Ayniqsa, yoshiga mos faoliyat kitoblari bilan birgalikda shug‘ullanish vaqtingizni mazmunli o‘tkazishingizga hamda chaqalog‘ingizning o‘ynab-o‘rganishiga yordam beradi. Kun davomida kamida 1-2 soat birgalikda rivojlantiruvchi o‘yinlar o‘ynashingiz chaqalog‘ingiz kelajagi uchun kiritadigan eng katta sarmoyangizdir. Masalan, kichik qismlardan yaxlit shakl yasash bu davrdagi eng qiziqarli o‘yinlardan biridir. Shu sababli pazllar, bir-biriga ulanadigan o‘yinchoqlar va lego to‘plamlari energiyasi tugamaydigan chaqalog‘ingiz uchun haqiqiy najot bo‘lishi mumkin. Bola ulg‘aygani sari bunday o‘yinchoqlar ham murakkablashib boradi va o‘ynash uchun yanada rivojlangan motorika ko‘nikmalari talab qilinadi. Bu esa chaqalog‘ingizga yangi qobiliyatlarni egallash va muvaffaqiyat hissini tuyish imkonini beradi.') WHERE id = 'b66a0d11-0af2-4535-8154-1f619d2a0bfa';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingizning ovqatlanish tartibi va porsiya miqdori haqida savollaringiz bo‘lishi mumkin. Siz uchun bir kunlik namunaviy ovqatlanish menyusini tayyorladik! 😊 Nonushtani 1 bo‘lak butun donli bug‘doy nonidan tayyorlangan tost, 1 choy qoshiq yeryong‘oq pastasi va yarim stakan sut bilan boshlash juda yaxshi. Tamaddi uchun yarim stakan qulupnay, yarim stakan yogurt yoki foydali makkajo‘xori yormalaridan (myusli) birini tanlashingiz mumkin. Tushlikda 1 bo‘lak kepakli non, biroz baliq, kichik qaynatilgan kartoshka va 1 dona kichik apelsindan iborat to‘yimli menyu tayyorlashingiz mumkin. Keyingi tamaddi uchun uyda tayyorlagan 5 dona donli kreker, 5 dona xom bodom yoki ustiga shinni/asal surtilgan 1 bo‘lak butun donli bug‘doy nonini berishingiz mumkin. Kechki ovqatga esa yarimta sabzi, 30 gramm sabzavot, shuningdek, 30 gramm mol yoki tovuq go‘shti hamda yarim kosa bulg‘ur palovi to‘yimli va foydali tanlov bo‘ladi.') WHERE id = '443f9eda-baee-4eb9-a55b-b12c4d58ecb1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingizning jismoniy rivojlanishi sekinlashsa-da, aqliy rivojlanishi jadal davom etadi. Endi chaqalog‘ingiz harakat va faoliyatni ifodalovchi rasmlarni bemalol nomlay oladi. Agar avval o‘rgatgan bo‘lsangiz, geometrik shakllarni ularning rasmlari bilan moslashtira oladi. Tayoqchaga kattadan kichikka yoki kichikdan kattaga qarab 5 ta halqani ketma-ket joylashtira oladi. Biror buyumning yengil yoki og‘irligini farqlay oladi. Hatto u bilan birga vazni necha kilo ekanini kuzatib borishingiz mumkin, bu unga juda yoqadi. Chaqalog‘ingiz, shuningdek, yaxlit tasvir hosil qilish uchun rasmning ikki qismini birlashtira oladi. So‘raganingizda uzun va kalta buyumlarni ko‘rsatadi. Tish pastasi bilan tish cho‘tkasi, qo‘g‘irchoq bilan bolalar butilkasi kabi o‘zaro bog‘liq buyumlarni topa oladi. Bularning barchasini qisqa vaqt ichida o‘rganishi chaqalog‘ingiz miyasi bilim olishga qanchalik tayyor ekanining isbotidir.') WHERE id = '7f5ccfc6-4475-4f0c-8f31-12479dd8da41';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davr chaqalog‘ingizning karavotini almashtirish uchun qulay vaqt. Chunki agar hali ham bolalar beshigidan foydalanayotgan bo‘lsangiz, unga sig‘ishi tobora qiyinlashadi. Oilaga yangi a’zoning kelishi ham bu qarorni tezlashtirishi mumkin. Agar homilador bo‘lsangiz yoki homiladorlikni rejalashtirayotgan bo‘lsangiz, katta farzandingizni chaqaloq tug‘ilishidan kamida 6-8 hafta oldin yangi karavotiga o‘tkazishingiz kerak. Chunki katta farzandingiz yangi tug‘ilgan chaqaloq uning beshigini "tortib olishidan" oldin yangi karavotiga ko‘nikishi psixologik jihatdan ma’qulroq. Agar bu o‘zgarishga ko‘nikishi juda qiyin kechsa, uni yangi chaqaloq 3-4 oylik bo‘lguniga qadar kechiktirishingiz mumkin. Yangi chaqaloq bu oylarni istalgan joyda uxlab o‘tkazar ekan, katta farzandingiz ham oilaning yangi a’zosiga ko‘nikadi va yangi karavotga o‘tish osonlashadi. Karavotni almashtirishning yana bir sababi hojatxonaga borish odatidir. Chaqalog‘ingiz endi tunda sizni bezovta qilmasdan hojatxonaga borishni o‘rganishi kerak. Bu borada uni ruhlantirishingiz uning ushbu odatni egallashi va sizning uyqu sifatingiz yaxshilanishi uchun juda muhim.') WHERE id = 'b162f1d9-6368-4367-b8db-fde84325b9ed';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizni kasalliklardan himoya qilish, immun tizimini mustahkamlash yoki shunchaki unga quvvat berish uchun ziravorlardan foydalanishingiz mumkin. Ziravorlar kuchli antioksidant xususiyatga ega bo‘lishi bilan birga, yallig‘lanishga qarshi ko‘plab foydali ta’sirlarga ham ega. Ular tarkibidagi beta-karotin, selen, A, C va E vitaminlari kabi antioksidantlar farzandingizni yurak kasalliklaridan tortib saratongacha bo‘lgan ko‘plab muammolardan himoya qilishga yordam beradi. Masalan, tadqiqotlar kurkuma miya salomatligi va yoshga bog‘liq kognitiv rivojlanishga ijobiy ta’sir ko‘rsatishini tasdiqlaydi. Boshqa bir tadqiqotga ko‘ra esa, bir choy qoshiq zanjabilning antioksidant darajasi bir stakan ismaloqniki bilan teng. Shu sababli, miqdorini oshirib yubormasdan va albatta shifokoringiz bilan maslahatlashgan holda farzandingiz ovqatlanishida foydali ziravorlardan bemalol foydalanishingiz mumkin.') WHERE id = 'c72aa2b5-e59d-4e6f-ad3f-c7a037c197ef';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bergan savollarga javob berayotganda, uni ham mavzuni o‘rganishga va fikrlashga undash muhim. Masalan: «Seningcha, nega bunday bo‘lishi mumkin?», «Sen nima deb o‘ylaysan?», «Taxmining bormi?» kabi savollar bilan bolangizni fikrlashga rag‘batlantirishingiz mumkin. Uyda savollariga javob oladigan bola maktabda ham tushunmagan mavzulari haqida bemalol so‘ray oladi. O‘qituvchisiga ko‘proq savol beradigan bolalar darslarda muvaffaqiyatliroq bo‘lishi kuzatilgan. Aksincha, savollari javobsiz qolgan yoki e’tiborsiz qoldirilgan bolalar o‘zlarini qadrsiz his qiladi va maktabda savol berishdan tortinadi. Ko‘proq fikrlaydigan, savol beradigan va izlanadigan farzandingiz kelajakda ham muvaffaqiyatliroq bo‘ladi. Shu sababli bolangizning savollariga imkon qadar sabr bilan javob berishingiz juda muhim.') WHERE id = '5b153890-626c-4f66-9895-e87a3626f96f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Do‘konlarda sotiladigan qadoqlangan sutmi yoki sigirdan sog‘ilgan xom sutmi? Bu savol yillar davomida onalarni o‘ylantirib kelayotgan eng muhim masalalardan biridir. Ba’zilar xom sutni uy sharoitida qaynatib ichishni foydaliroq deb hisoblasa, boshqalar pasterizatsiya qilingan yoki UHT sut deb ataladigan mahsulotlarni afzal ko‘radi. Agar sutning manbasi va tashish sharoiti to‘liq ma’lum bo‘lmasa, xom sut ancha xavfli bo‘lishi mumkin. Uning tarkibidagi zararli bakteriyalar farzandingiz organizmida turli reaksiyalarni keltirib chiqarishi mumkin. Bundan tashqari, sigirga antibiotik berilgani yoki sut gigiyena talablariga javob bermaydigan sharoitda saqlangani ham xavf tug‘diradi. Shu nuqtai nazardan, ishonchsiz joylardan olingan ochiq sut o‘rniga kundalik pasterizatsiya qilingan sutni tanlashingiz sog‘lomroq qaror bo‘ladi.') WHERE id = 'e3a23f3e-4fd8-4dbb-ac95-29d46ad09622';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz ilk bolalik davrining deyarli oxiriga yetdi. Endi u chinakam o‘yin yoshidagi bola. U butun kunini o‘yin bilan o‘tkazishi, bundan hech qachon zerikmasligi va sizni ham doimo o‘yinlariga qo‘shishni istashi mumkin. O‘yinlar bolangiz uchun dunyoni anglash va yangi narsalarni o‘rganishning eng samarali vositasidir. Unga zo‘ravonlikni targ‘ib qiluvchi qurol, to‘pponcha kabi o‘yinchoqlar o‘rniga, bunyodkorlik va ijodkorlikni rivojlantiradigan o‘yinchoqlarni tanlashingiz tavsiya etiladi. U asta-sekin maktabgacha yosh davriga qadam qo‘yayotgani uchun harflar va raqamlarni o‘rganishiga yordam berishingiz mumkin. Biroq bu borada shoshilmang. Agar uning raqamlar va harflarga qiziqish bildirayotganini ko‘rsangiz, bosim o‘tkazmasdan o‘rgatishingiz mumkin. Qisqasi, agar o‘zi o‘rganishga intilayotgan bo‘lsa, uni albatta qo‘llab-quvvatlashingiz kerak.') WHERE id = 'e878f726-41d1-4bee-844c-9a7d1fa53eaa';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Hozirgi kunda deyarli barcha meva va sabzavotlarni yilning istalgan faslida topish mumkin. Biroq gap farzandingizning ovqatlanishi haqida ketganda, o‘z mavsumida yetishtirilgan mahsulotlar ham mazaliroq, ham foydaliroq bo‘ladi. Ular tabiiy yo‘l bilan yetishtirilgani sababli vitamin va minerallarga boy bo‘ladi. Masalan, qishda terilgan ismaloq bilan yozda terilgan ismaloq o‘rtasida C vitamini miqdori bo‘yicha uch baravar farq borligi aniqlangan. Bundan tashqari, mahalliy mahsulotlar uzoqdan olib kelingan mahsulotlarga qaraganda ham yangiroq, ham foydaliroqdir. Har bir faslda tabiat va iqlim o‘zgarishi bilan sizning tanangiz kabi farzandingiz organizmining ham ehtiyojlari o‘zgarishini unutmasligingiz kerak. Shu nuqtai nazardan, tabiatning mukammal tartibiga muvofiq ovqatlanish eng to‘g‘ri yo‘ldir.') WHERE id = '00332087-6a8f-4e62-b2f8-03640f4bf4b5';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingizni alohida yotoqda yotqizishni o‘ylayotgan bo‘lsangiz, hozir buning uchun eng qulay davr ekanini eslatib o‘tmoqchimiz. Ushbu o‘tish bosqichini osonlashtirish uchun uni muntazam maqtash va ruhlantirish orqali muvaffaqiyatga erishishiga yordam berishingiz mumkin. E’tibor berishingiz kerak bo‘lgan jihat shuki, bolangiz yangi karavotiga o‘rgangach, shunchaki buni uddalay olishini ko‘rsatish uchun katta karavotidan turib, tushishi mumkin. Agar o‘rnidan tursa, xotirjam, ammo qat’iyatli bo‘lishingiz kerak. Uni yana yotog‘iga olib borib, shunchaki uxlash vaqti kelganini aytib, yolg‘iz qoldirishingiz mumkin. Agar qarshilik ko‘rsatsa, uyqu bo‘yicha mutaxassislarning tavsiyalaridan foydalanishingiz mumkin: orqasini silang, hammasi joyida ekanini, ammo uxlash vaqti kelganini ayting. Uni qo‘lingizga olmang va yoniga yotmang; mehribon, ammo qat’iyatli bo‘ling. Besh daqiqa kutib, yana xabar oling. U uxlab qolguniga qadar har safar kutish vaqtini biroz uzaytirib, jarayonni takrorlang. Agar uxlash vaqti borasida izchil va qat’iy bo‘lsangiz, tunda uyg‘onishlar bir necha hafta ichida yo‘qoladi.') WHERE id = '4078f349-ac2c-48e1-a276-0ec6e642a5ee';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'So‘nggi paytlarda farzandingiz nutqida katta rivojlanishni sezayotgan bo‘lishingiz kerak. Masalan, u ikki-uch gapdan iborat suhbatlar qura oladi va so‘zlarga qo‘shimchalar qo‘shishni boshlaydi. «Bu o‘yinchoq» kabi grammatik jihatdan to‘g‘ri gaplar tuzadi; o‘yinchoq, hayvon, oziq-ovqat kabi toifalardan foydalanadi. Istak va kelasi zamon shakllarini qo‘llaydi, buyumlarni ochiq yoki yopiq deb ta’riflay oladi. So‘roq gaplarda so‘roq yuklamalaridan o‘rinli foydalanadi, so‘ralganda ism va familiyasini ayta oladi (garchi notanish odamlarga ismini aytishga har doim ham xohish bildirmasa-da). U bir-biriga bog‘liq bo‘lmagan ketma-ket ikkita topshiriqni bajara oladi. Masalan: «Yerdagi qog‘ozni olib, axlat qutisiga tashlay olasizmi?» — deyilganda, har ikkala harakatni ketma-ket bajaradi. Agar shunga qaramay, nutqi hali ham to‘liq tushunarli bo‘lmasa, unga ayrim nutq mashqlarini bajartirish foydali bo‘ladi.') WHERE id = '78c832c1-4c0d-4309-9e24-09ccab108546';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingiz tez-tez ich ketishidan aziyat cheksa, avvalo u iste’mol qilayotgan ovqatlarga e’tibor berishingiz kerak. Masalan, sabzavotli taomlar juda foydali, ammo tarkibidagi ortiqcha ziravorlar bolada ich ketishiga sabab bo‘lishi mumkin. Ayniqsa, achchiq qalampir shunday ta’sir ko‘rsatishi ma’lum. Qovurilgan ovqatlarni tez-tez iste’mol qilish ham yana bir sababdir; bola haftasiga bir martadan ko‘p qovurilgan taom yemasligi kerak. Ich ketishi hatto kattalarda ham qisqa vaqt ichida dehidratatsiya (suvsizlanish)ga olib kelishi mumkin, bolalarda esa uning oqibatlari bir necha barobar og‘irroq kechadi. Shu sababli farzandingizga beradigan har bir ovqatingiz uning sog‘lig‘iga bevosita ta’sir qilishini unutmasligingiz muhim.') WHERE id = 'c8770cc7-96b4-4f44-abc5-fe4118707f16';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingizni asta-sekin maktabgacha ta’limga tayyorlashingiz tavsiya etiladi. Ilgari maktabgacha ta’lim ko‘proq ishlaydigan onalar uchun yechim sifatida qaralgan bo‘lsa-da, hozir mutaxassislar barcha bolalar bunday ta’lim olishi kerak degan fikrga qo‘shiladilar. Farzandingiz rivojlanib, o‘z fikrini ifoda eta boshlagani sari, ota-ona sifatida uning barcha qiziqish va ehtiyojlarini yolg‘iz o‘zingiz qondirishingiz qiyinlashadi. Hozirgi zamon bolalari ko‘proq qiziquvchan va bilim olishga ochiqdirlar. Farzandingiz sog‘lom rivojlanishi va mustaqil shaxs sifatida shakllanishi uchun maktabgacha ta’lim juda muhim. Tadqiqotlar bu davrda bolalar juda tez va samarali o‘rganishini ko‘rsatadi. To‘g‘ri tashkil etilgan jismoniy va ijtimoiy muhitda tengdoshlari bilan muloqot qilishi uning kelajakdagi muvaffaqiyatlari uchun mustahkam poydevor yaratadi.') WHERE id = '09cc45a6-5357-478d-806f-e921dc4066af';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bu yoshda xuddi kattalar kabi depressiyani boshdan kechirishi mumkinligi xayolingizga kelganmi? Jamiyatda bu fikr unchalik qabul qilinmasa-da, mutaxassislar bolalar ham tez-tez tushkunlik va depressiyaga duch kelishini ta’kidlaydilar. Bolalarda depressiya belgilari kattalarnikidan farq qiladigan turli alomatlar bilan namoyon bo‘lishi mumkin. Umuman olganda, diqqatning tarqoqligi, giperfaollik, o‘rganishdagi qiyinchiliklar, xulq-atvor buzilishlari yoki doimiy qarshilik ko‘rsatish depressiya belgisi bo‘lishi mumkin. Ayniqsa, oilada yangi uka yoki singilning tug‘ilishi boladagi depressiyaning asosiy sabablaridan biridir. Bunday paytda bola «Endi ota-onam meni sevmaydimi?» degan xavotirga tushadi. U ba’zan chaqaloqqa nisbatan tajovuzkor, ba’zan esa aksincha, haddan tashqari mehribon munosabatda bo‘lishi mumkin. Klinik kuzatuvlarga ko‘ra, bunday ichki ziddiyatni boshdan kechirayotgan bola ko‘pincha his-tuyg‘ularini «Juda zerikyapman» degan jumla bilan ifodalaydi.') WHERE id = 'd5cee6e1-14a0-4774-a124-d29478e56e0b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolangizning harakat ko‘nikmalari bu bosqichda qanchalik rivojlanganini sezyapsizmi? U endi kiyinish, ovqatlanish, o‘yindan keyin o‘yinchoqlarini yig‘ish va tishlarini tozalash kabi kundalik ishlarni deyarli yordamsiz bajara oladigan darajaga yetdi. Uning o‘yinlarida ham o‘zgarishlar bo‘lganini sezgan bo‘lishingiz kerak. Endi u mustaqil ravishda o‘yinlar o‘ylab topa boshlaydi, hatto o‘zi tashkil qilgan o‘yinlarda sizga va o‘rtoqlariga topshiriqlar berayotganini ham kuzatishingiz mumkin. Bundan tashqari, farzandingiz endi sizning nazoratingiz ostida qaychi bilan turli shakllarni tartibsiz ravishda kesib ko‘ra oladigan bosqichga yetdi. Bu mashg‘ulot unga barmoqlarini yaxshiroq ishlatish va natijada mayda motorika ko‘nikmalarini rivojlantirishga yordam beradi. Shunga qaramay, qaychi kesuvchi va xavfli asbob ekanini unutmang, shu sababli bolani diqqat bilan kuzatib turishingiz kerak.') WHERE id = '52831199-fbe3-4b62-ad35-73e2e71edbc4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolangizning qiziquvchanligini rag‘batlantirish orqali uning aqliy salohiyatini rivojlantirishingiz mumkinligini bilarmidingiz? Farzandingizning fe’l-atvoriga mos o‘yinlar va ssenariylarni o‘ylab topib, uning intellektual rivojlanishiga katta hissa qo‘shishingiz mumkin. Masalan, buyumlarni yashirib, ularni topishini va bu buyum nima ekanini aytishini so‘rashingiz mumkin. Alyuminiy folgaga o‘ralgan turli buyumlarni paypaslab ko‘rishi va qiziquvchanligi yordamida nimaligini topishiga imkon bering. Bu buyumlar uydagi istalgan narsa — qoshiq, sevimli o‘yinchog‘i, plastik stakan yoki hatto pardoz vositalaringiz bo‘lishi mumkin. Qiziqishga boy muhitda bolangiz faol o‘rganish jarayoniga kirishadi. Qiziquvchanlikdan kuch oladigan bilim olish istagi bolaning aqliy rivojlanishiga qo‘shimcha hissa qo‘shish bilan birga, uni qiziqtirgan mavzuni tengdoshlariga qaraganda chuqurroq o‘zlashtirishiga yordam beradi.') WHERE id = '6725b944-c3f1-499c-a21a-3bbbd23afe4b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz, ayniqsa, bu haqda kimdandir eshitganida, asta-sekin o‘limga qiziqib, savollar bera boshlashi mumkin. “O‘lim nimani anglatadi?”, “Vafot etganlar qayerga ketadi?”, “Men ham o‘lamanmi?” kabi savollar berishi mumkin. Bu mavzu ko‘plab oilalarda xavotir uyg‘otsa-da, bunday savollarni javobsiz qoldirmasligingiz muhim. Chunki bolalar ham kattalar kabi bilgan narsalaridan emas, bilmagan narsalaridan qo‘rqib, xavotirga tushadilar. Bilish — tushunish va tashvishlardan xalos bo‘lishning kalitidir. Shu nuqtayi nazardan, yaqinlaringiz orasida o‘lim yuz bermasidan oldin, kundalik hayotdagi tabiiy misollar (masalan, o‘lgan kapalak, hayvonlar yoki o‘simliklar hayoti) orqali ortiqcha hissiy yuklamasiz o‘lim haqida suhbatlashishingiz mumkin. Farzandingizni xafa qilmaslik va himoya qilish maqsadida bu mavzudan qochsangiz, u haqiqiy hayotda bu haqiqatga duch kelganida keskin munosabat bildirishi va his-tuyg‘ularini boshqarishda qiynalishi mumkin.') WHERE id = '89a84db5-00a0-4250-8e17-5337f74b7208';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz uchun tunda 11 soat, kunduzi esa 1,5-2 soat uxlash yetarli. Biroq bu uyqu soatlarining tartibi ham juda muhim. Ayrim ota-onalar ertalab uzoqroq uxlash uchun farzandlariga kechgacha uyg‘oq qolishga ruxsat beradilar. Ammo bu noto‘g‘ri yondashuv. Chunki chaqalog‘ingiz organizmi zarur o‘sish gormonlaridan to‘liq foydalanishi uchun u kechki soat 21:00 dan kechiktirmay yotog‘ida bo‘lishi kerak. Shuningdek, yaxshi uyqu odati shakllanishi uchun bu muntazam tartibga aylanishi zarur. Noto‘g‘ri uyqu vaqti tufayli gormonlarning kerakli miqdorda ajralmasligi uzoq muddatda rivojlanishning ortda qolishiga sabab bo‘lishi mumkin. Bundan tashqari, uning miyasi yangi ma’lumotlarni qabul qilish uchun yetarlicha dam olmagan bo‘ladi. Shu sababli chaqalog‘ingizning tungi uyqusi 19:00-21:00 oralig‘ida boshlanishiga e’tibor berishingiz kerak.') WHERE id = '9bac81bd-cded-4b25-9404-36ce1f5fe50c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Har bir bola kabi sizning chaqalog‘ingiz ham o‘ziga xos genetik va fiziologik xususiyatlar bilan dunyoga kelgan. Shu bilan birga, erta bolalik davridagi tajribalar bolaning sog‘lom ijtimoiy-emotsional rivojlanishi uchun nihoyatda muhimdir. Tadqiqotlar ota-onaning o‘rnak bo‘lishi va ijobiy muloqoti bolaning rivojlanishida muhim o‘rin tutishini ko‘rsatadi. Uy sharoitida boshdan kechirgan his-tuyg‘ularingiz haqida farzandingiz bilan suhbatlashishingiz munosabatlaringizga ijobiy ta’sir qiladi va uning hislarni anglash qobiliyatini rivojlantiradi. Masalan, siz va turmush o‘rtog‘ingiz ortiqcha tafsilotlarga berilmasdan kuningiz qanday o‘tgani va his-tuyg‘ularingiz haqida gaplashishingiz mumkin: “Bugun tirbandlik meni juda charchatdi”, “To‘satdan tormoz bergan mashina meni qo‘rqitdi”, “Rahbarim ish kechikkanidan jahli chiqdi, men ham xafa bo‘ldim”, “Yo‘lda do‘stimni ko‘rdim va bundan juda xursand bo‘ldim”. His-tuyg‘ular haqida gaplashilishini eshitib ulg‘aygan bolaning o‘z tuyg‘ularini ifodalash va boshqarish qobiliyati ancha yaxshi rivojlanadi.') WHERE id = 'c1323801-3c49-4703-a7f2-cac086e9addc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz yoshiga mos bo‘lmagan xatti-harakatlarni namoyon qilsa, bu ko‘pincha o‘zini qanday ifodalashni bilmasligidan kelib chiqadi. Boshqacha aytganda, u ichki zo‘riqish va muammolarini boshqa yo‘l bilan ifodalay olmagani uchun shunday munosabat bildiradi. Masalan, jahli chiqqanida o‘rtog‘ini urishi, istagi amalga oshmaganida o‘zini yerga tashlashi, kimdir savol berganida haddan tashqari uyalishi yoki doimiy xavotirda yurishi shular jumlasidandir. Bunday vaziyatda eng samarali strategiyangiz, avvalo, chaqalog‘ingizga o‘zi his qilayotgan tuyg‘u nima ekanini tushuntirishdan iborat bo‘lishi kerak. His-tuyg‘ularini so‘zlar bilan to‘g‘ri ifodalay oladigan bolalarda xulq-atvor muammolari kamroq uchraydi. Masalan, biror narsadan jahli chiqqanida “Juda jahlim chiqdi”, deb ayta olsa, g‘azab portlashi va yig‘i xurujlari yuz berish ehtimoli kamayadi. Chaqalog‘ingizdan tez-tez o‘zini qanday his qilayotganini so‘rashingiz uning tuyg‘ularini anglash va ifodalash qobiliyatini rivojlantiradi hamda salbiy hislarni sog‘lomroq tarzda yengishiga yordam beradi.') WHERE id = 'c41a4ffe-aceb-49cc-a6db-32a8461961ac';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ko‘p savol berishi uning ham ziyrak va qiziquvchan, ham juda xavotirli ekanini ko‘rsatishi mumkin. Buni tushunishning eng yaxshi yo‘li — savollarning mazmuniga e’tibor berishdir. Agar savollar "Bu ovqatni yesam, kasal bo‘lib qolamanmi?", "Yuragim tez uryapti, o‘lib qolamanmi?", "Bu kecha uyga o‘g‘ri kiradimi?", "Chap qo‘lim bilan yesam, biror narsa bo‘ladimi?" kabi qo‘rquvga to‘la mavzularda bo‘lsa, mutaxassisdan yordam olishingiz foydali bo‘ladi. Har bir bola vaqti-vaqti bilan xavotirlanib, bunday savollarni berishi mumkin. Ammo bunday holatlar tez-tez takrorlansa, chaqalog‘ingizni diqqat bilan kuzatishingiz kerak. Uni qo‘rqitadigan va xavotirga soladigan vaziyatlarni aniqlash uning ruhiy salomatligi uchun juda muhim. O‘zingiz uddalay olmaydigan holatlarda mutaxassisga murojaat qilishdan tortinmang. Unutmang, o‘z vaqtida ko‘rilgan chora har doim eng to‘g‘ri tanlovdir.') WHERE id = 'd8d7160d-4daa-41aa-b77a-2dab3b64dfdc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning qiziquvchanligi faqat kitob va daftarlar orasida rivojlanmaydi. Nazariy o‘rganish shakli insonning tabiiy rivojlanishida 11-14 yoshgacha bo‘lgan davrda shakllanib boradi. Bu davrgacha chaqalog‘ingiz o‘rganganlarining katta qismini amalda bajarish, o‘yin o‘ynash yoki qiziquvchanligi orqali o‘zlashtiradi. Shu nuqtayi nazardan, ko‘proq savol berishda namoyon bo‘ladigan qiziquvchanlikni so‘ndirmasligingiz kerak. Chunki qiziquvchanligi so‘ndirilgan bola o‘smirlik davrigacha o‘z rivojlanishini sog‘lom tarzda yakunlay olmaydi. Shu sababli chaqalog‘ingizning savollariga sabr bilan javob berishingiz, hatto uni savol berishga undashingiz kerak. Javobini bilmagan savollaringizni esa u bilan birga o‘rganib, o‘zingiz ham yangi narsalarni bilib olishingiz mumkin.') WHERE id = 'c925eb18-ca4f-4e30-b127-cf5a2c698dac';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingizni maktabgacha ta’lim muassasasiga berishni o‘ylayotgan bo‘lsangiz, e’tibor qaratishingiz kerak bo‘lgan ayrim jihatlar bor. Chunki maktabga ilk bor borish davri bolalar uchun qanchalik hayajonli bo‘lsa, ota-onalar uchun ham shunchalik hayajonlidir. Oila sifatida siz qanchalik xotirjam bo‘lsangiz, chaqalog‘ingiz bu o‘tish davrini shunchalik yaxshi o‘tkazadi. Bu paytda vazmin bo‘lishingiz va ta’lim muassasasiga ishonishingiz juda muhim. Bog‘cha yoki tayyorlov guruhi chaqalog‘ingiz uydan uzoqda, yaqinlaridan hech kim yonida bo‘lmaydigan ilk joy bo‘ladi. Bu davrda sizning qo‘llab-quvvatlovchi munosabatingiz uning yangi muhitga moslashishini osonlashtiradi. Bu jarayon yakunlangach, chaqalog‘ingiz guruhda o‘zini alohida shaxs sifatida namoyon eta va ijtimoiylasha boshlaydi. Idroki juda faol bo‘lgan bu davrda u atrofidagi turli ta’sirlar yordamida yangi bilimlarni tez va samarali o‘zlashtiradi.') WHERE id = '88e562a2-5445-4b67-bbd0-d77c240f5606';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz endi 35 oylik. Boshqacha aytganda, 3 yoshga to‘lishiga sanoqli kunlar qoldi! Sizni tabriklaymiz! 😊 35 oylik chaqalog‘ingiz endi mustaqil qaror qabul qila oladigan shaxsdir. Shu sababli uni avvalgidek faqat o‘z fikringiz asosida yo‘naltirish qiyinlashadi. Bu davrda u turli vaziyatlarda sizdan turli narsalarni talab qilishi mumkin. Masalan: «Dadam ovqat pishirsin, onam men bilan o‘ynasin», deyishi mumkin. Chaqalog‘ingiz mustaqil bo‘lib borayotgan bo‘lsa-da, hali ham sizsiz biror narsa qilishga ikkilanib qolishi mumkin. Shu jihatdan ham mustaqilligini mustahkamlashi, ham o‘zini boshqarishni o‘rganishi uchun uni mustaqil o‘ynashga undashingiz kerak. Unutmang, u hali ham dunyoni anglashga urinayotgan kichkina chaqalog‘ingiz. Muammolarni hal qilishning eng samarali yo‘li esa u bilan gaplashish va muloqot qilishdir.') WHERE id = '209004b7-d29a-4345-ba5f-85059bbd8a7e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingizning o‘rtacha bo‘yi va vaznida keskin o‘zgarishlar kuzatilmasligi mumkin. 35 oylik o‘g‘il bolalarning vazni o‘rtacha 16 kg, qiz bolalarniki esa taxminan 15 kg atrofida bo‘ladi. Bu bosqichda vazn jins va irsiyatdan ko‘ra ko‘proq ovqatlanish odatlari hamda ishtahaga bog‘liq ravishda o‘zgaradi. Bo‘y uzunligi esa genetik ko‘rsatkichlar bilan chambarchas bog‘liq. Tadqiqotlar bo‘yni belgilovchi omillarning 80% genetik kod bilan bog‘liqligini ko‘rsatadi. Qisqacha aytganda, agar ota-ona baland bo‘yli bo‘lsa, chaqalog‘ingiz ham tengdoshlaridan balandroq bo‘lishi kutiladi. Shunga qaramay, persentil jadvali haqida ma’lumotga ega bo‘lish foydalidir. 35 oylik qiz bolalarning bo‘yi 87-102 sm, o‘g‘il bolalarniki esa 89-103 sm oralig‘ida bo‘lishi mumkin.') WHERE id = '8106725e-0710-4935-aa3f-544d3a83dba4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bu oylarda 10 gacha sanay olishi, «Nima, qayerda, kim?» kabi savollar berishni o‘rganishi mumkin. Bularning barchasi nutq rivojlanishi ancha yuqori darajaga yetganini ko‘rsatadi. Endi u ravonroq gapirishga harakat qiladi. Chunki uning so‘z boyligi ortib boradi va aqliy salohiyati rivojlangani sari tildan to‘g‘riroq foydalanishni o‘rganadi. Hatto bu davrda chaqalog‘ingiz siz bilan hazillashayotganiga guvoh bo‘lishingiz mumkin. Ba’zan u bu hazillar bilan sizni jahlingizni chiqarishdan ham zavqlanishi mumkin. Agar atrofida hazilkash insonlar bo‘lsa, ulardan o‘rnak olib, sizni kuldirish unga yoqadi. Chaqalog‘ingizda bu yoshda hazil tuyg‘usi shakllangani juda yaxshi. Biroq hazilning mazmuni va uning yoshiga mosligi muhimdir. Agar u boshqalardan salbiy o‘rnak olib hazillashsa, kulish o‘rniga u bilan gaplashib, vaziyatni tushuntirish kerak.') WHERE id = 'b3f8428e-6bca-4e17-b06f-253ecc4381cb';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingizning ishtahasizligi bilan bog‘liq muammolarga duch kelayotgan bo‘lsangiz, uni majburlash o‘rniga och qolishini kutishingiz kerak. Uni zo‘rlab ovqatlantirish ham ruhiyatiga, ham jismoniy salomatligiga salbiy ta’sir qilishi mumkin. Buning o‘rniga u yoqtirmaydigan mahsulotlarni ma’lum vaqt oralig‘ida qayta taklif qilish yaxshiroq usuldir. Ovqatlanish masalasida eng ko‘p e’tibor qaratishingiz kerak bo‘lgan jihatlardan biri — mukofotlash va jazolash usullaridir. Chaqalog‘ingiz ovqat yemagani uchun uni jazolash yoki ovqat yegani uchun mukofotlash to‘g‘ri emas. Unutmang, u ham siz kabi alohida shaxsdir. Har bir inson singari har bir bolaning ehtiyoji uchun zarur bo‘lgan oziq-ovqat miqdori ham turlicha bo‘lishi mumkin. Shu sababli mutaxassis bilan maslahatlashish foydalidir. Chaqalog‘ingizning kunlik kaloriya ehtiyojini shifokor ko‘rigida bilib olishingiz yoki diyetologdan unga mos ovqatlanish dasturini olishingiz mumkin.') WHERE id = '64ea6bc8-7775-4535-9a1e-fa17c68ef78b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '35 oylik chaqalog‘ingiz ko‘chaga chiqayotganda oyoq kiyimini endi mustaqil ravishda kiyib, yecha oladi. Biroq oyoq kiyimining ipini bog‘lashni o‘rganishi uchun hali biroz vaqt kerak. Shu bilan birga, u kiyimlarini mustaqil ravishda kiyib-yecha oladi, hatto tugmalarini taqish va fermuarini yopish kabi harakatlarni ham bajara oladi. Bularning barchasi uning mayda motorika ko‘nikmalari kundan-kunga rivojlanayotganining natijasidir. Endi u avval uddalay olmagan ko‘plab ishlarni bemalol bajara oladi: shaxsiy gigiyenasiga rioya qiladi, bir oyoqda sakraydi, legolardan minoralar quradi, kitob sahifalarini varaqlaydi va stakanni bir qo‘li bilan ushlaydi. Bu ko‘nikmalar yanada rivojlanishi uchun unga kerakli sharoit yaratishingiz lozim. Masalan, kiyimini to‘liq va to‘g‘ri kiya olmayapti deb o‘ylasangiz ham, unga buni mustaqil bajarish imkonini berishingiz hamda zarurat bo‘lmasa aralashmasligingiz kerak.') WHERE id = '163cc8b7-054e-465f-87c5-aa48d630b9cc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz kunduzi uxlashni istamasa, kechqurungi uyqu vaqtini ertaroqqa surishingiz kerak. Shkaf ichidan yoki karavot tagidan kimdir chiqib kelishidan yoxud qorong‘ilikdan qo‘rqish kabi holatlar kuzatilishi mumkin. Bunday paytda unga «Yo‘q, bu bekor gap!» yoki «Bu juda bema’ni qo‘rquv!» deya munosabat bildirmasligingiz kerak. Chunki bu uning qo‘rquvini yo‘qotmaydi, aksincha, rivojlanishiga ham jiddiy zarar yetkazishi mumkin. Qo‘rquv hissi chaqalog‘ingiz rivojlanishining muhim bosqichi ekanini unutmang. U qo‘rqqanida, uni tinchlantiradigan tarzda suhbatlashishingiz, kitob o‘qib berishingiz, haqiqat bilan tush o‘rtasidagi farqni tushuntirishingiz va u qo‘rqayotgan narsa haqida gaplashishingiz mumkin. Shu tariqa chaqalog‘ingizga qo‘rquv hissini to‘g‘ri tushunish va qo‘rqqanida qanday yo‘l tutishni o‘rganishda yordam berasiz.') WHERE id = '70f5b6ed-9e2c-4dc4-adbf-c9b127e85789';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Kefir chaqalog‘ingiz ratsionida bo‘lishi kerak bo‘lgan eng foydali ichimliklardan biridir. Farzandingizga muzli choy, gazli va qahvali ichimliklar o‘rniga kefir ichish kabi sog‘lom odatlarni singdirishingiz kerak. Shuningdek, do‘konlarda sotiladigan tayyor mahsulotlar o‘rniga uyda o‘zingiz bemalol kefir tayyorlashingiz mumkin. Dorixona yoki ziravorlar do‘konidan topish mumkin bo‘lgan kefir achitqisini xona haroratidagi bir idish sutga qo‘shib, yengil chayqatish orqali kefirni oson tayyorlashingiz mumkin. So‘ng idishning ustini yorug‘lik tushmaydigan qilib yopib, tindirishga qo‘ying. Xona haroratida kamida 1 kun turgach, plastik suzgich yordamida achitqini suyuqlikdan ajratishingiz mumkin. Kefir tayyorlashda e’tibor berishingiz kerak bo‘lgan yana bir jihat — metall idish yoki qoshiq ishlatmaslikdir. Chunki metall buyumlar achitqining ta’sirini yo‘qotishiga sabab bo‘lishi mumkin.') WHERE id = 'b9a410f0-fac4-4211-b529-90bd6f7038fb';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz sizga yoqmaydigan va nomaqbul ayrim xatti-harakatlarni qilayotganini ko‘rishingiz mumkin. Bunday hollarda uning ayni paytdagi hissiyotini qabul qilib, konstruktiv tarzda chegaralar belgilashingiz va albatta muqobil yo‘l taklif qilishingiz kerak. Masalan: «Ha, hozir jahling chiqqanini tushunaman, ammo uydagi buyumlar yerga otish uchun emas, ularning o‘rniga o‘yinchoqlaringni qutiga tashlashing mumkin», deyishingiz mumkin. Shu yo‘l bilan chaqalog‘ingiz uning hissiyotlari tushunilganini, o‘zi qabul qilinganini, faqat qilgan harakati noto‘g‘ri ekanini anglaydi. Agar taqiq qo‘yayotganda uning shaxsiyatini ham tanqid qilsangiz, chaqalog‘ingizning o‘ziga bo‘lgan hurmati zarar ko‘radi va u qaysarlik qilib, o‘sha harakatni davom ettirishi mumkin. Ya’ni «Sen yomon bolasan», deb uning shaxsiyatiga hujum qilish o‘rniga, hislarini tan olishingiz, xatti-harakat chegarasini tushuntirishingiz va unga foydaliroq mashg‘ulot taklif qilishingiz kerak. Bu usulni vazminlik bilan va izchil qo‘llashingiz juda muhim, chunki bir kuni taqiqlagan narsangizga boshqa kuni ruxsat berishingiz chaqalog‘ingizda noaniqlikni yuzaga keltiradi.') WHERE id = '4e533ab4-dd97-4697-9a7a-2763d84d0153';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ko‘plab mutaxassislarning ta’kidlashicha, bolalar 18-24 oy oralig‘ida mustaqillik belgilarini namoyon qila boshlaydi. Chaqalog‘ingiz 3 yoshga yetganida esa bu talablar yanada kuchayadi va u «Men alohida shaxsman», deya boshlaydi. Bu davrda chaqalog‘ingiz o‘z fikrlari borligini his qiladi va ularga hurmat bilan munosabatda bo‘lishlarini istaydi. Rivojlangan mamlakatlarda 3 yosh davriga nisbatan «kichik o‘smir» ma’nosini anglatuvchi «threenager» atamasi ishlatiladi. Ota-ona sifatida sabringiz tugaydigan paytlar bo‘lishi mumkin, ammo 3 yosh sindromi abadiy davom etmasligini unutmang! Ota-onalarni qiziqtiradigan yana bir masala — bu davr qancha davom etishidir. Boshqa bosqichlar kabi, 3 yosh sindromining ham aniq vaqt chegarasi yo‘q. Biroq umumiy fikrga ko‘ra, bu davr 2 yosh sindromiga qaraganda keskinroq kechsa-da, qisqaroq davom etadi.') WHERE id = 'ad73d53b-9ddf-47dd-846f-bc47a9465bbe';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz aytayotgan gaplar va tuzayotgan jumlalarning hali hatto yarmini ham tushunmasligingiz mumkin. Uning tengdoshlari orasida yaxshiroq muloqot qiladigan bolalar bo‘lishi mumkin, ammo ularni taqqoslashning hojati yo‘q. Rivojlanish bo‘yicha mutaxassislarning fikriga ko‘ra, chaqalog‘ingiz o‘rtacha 4 yoshga to‘lguniga qadar aytgan gaplari to‘liq tushunarli bo‘lmasligi odatiy hol. Qisqasi, bu tabiiy jarayondir. Biroq farzandingiz tengdoshlaridan ancha ortda qolgan deb o‘ylasangiz, mutaxassis bilan maslahatlashishingiz mumkin. Bu bosqichda chaqalog‘ingiz 3-4 so‘zdan iborat sodda jumlalar tuzishi, «O‘yinchog‘imni ol va menga olib kel» kabi ikki bosqichli topshiriqlarni bajarishi mumkin. Olmoshlar u uchun hali ham qiyin bo‘lishi mumkin, shu sababli «Ovqat ye», «Qornim ochdi» kabi qisqa va olmoshsiz jumlalarni eshitishingiz odatiy hol. Unga tez-tez kitob o‘qib berishingiz yoki birgalikda hikoyalar to‘qishingiz bu jarayonni ham qiziqarli qiladi, ham nutq rivojlanishini tezlashtiradi.') WHERE id = 'ec5bfd9e-b028-4a27-9161-19876bcbf319';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingizda ayrim hazm muammolari va qorin dam bo‘lishi kuzatilishi mumkin. Ba’zi mutaxassislarning fikriga ko‘ra, qo‘lida ovqat bilan yuradigan, o‘yin o‘ynab yoki televizor ko‘rib ovqatlanadigan bolalarda qorin dam bo‘lishi ko‘proq uchraydi. Bu nazariyaga ko‘ra, o‘yinga berilib, tez ovqatlanadigan va shoshilib yutadigan bolalar ko‘p havo yutgani uchun hazm qilishda noqulaylik yuzaga keladi. Farzandingizning qorni dam bo‘lishining oldini olish uchun uning oila davrasida dasturxon atrofida asta-sekin ovqatlanishini ta’minlash muhimdir. Ovqatni yetarli miqdorda va me’yoriy vaqt ichida tugatishi uni tez yeb bitirishidan yoki keragidan ortiq ovqatlanishidan ko‘ra sog‘lomroqdir. Shu sababli, farzandingizda tez ovqatlanish odati bo‘lsa, hali maktabgacha yoshdaligidayoq bu odatni bartaraf etishga harakat qilishingiz kerak. Shunda u kelajakda nafaqat xuddi shunday hazm muammolariga, balki vazn bilan bog‘liq muammolarga ham duch kelmaydi.') WHERE id = '2a5e6072-b787-4135-92b2-5c7dcfe3dd8a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Uyqu tartibi har bir davrda bo‘lgani kabi, chaqalog‘ingiz 3 yoshga yaqinlashayotgan bu bosqichda ham juda muhim. Agar uning yotog‘ini almashtirgan bo‘lsangiz va u bunga ko‘nikib, tun bo‘yi uyg‘onmay uxlayotgan bo‘lsa, bu muvaffaqiyati uchun uni maqtashingiz kerak. Agar yotog‘idan turib, yoningizga kelmoqchi bo‘lsa, xotirjam va mehribon ohangda yotog‘iga qaytib, uxlashi kerakligini ayting. Sababini tushunmay, o‘jarlik qilsa, unga tushunarli tilda qisqacha izoh bering. Shunga qaramay, u turli bahonalar bilan uxlamaslikka urinishi mumkin. Ammo bu boradagi qoidalaringizdan chekinmaslikka harakat qiling. Sabr-toqat va izchil yondashuv bilan bu muammoni hal qilishingiz mumkin. Agar darhol uxlashni istamasa, xonasida kitob o‘qish yoki vaqtini tinch o‘tkazish uni bo‘shashtirib, uyquga tayyorlaydi.') WHERE id = 'a45f03f4-7495-4f93-9e19-ea1e8ffa609b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingiz hojatxonaga o‘rgatish jarayonini hali yakunlamagan bo‘lsa, shu haftalarda uni boshlash haqida o‘ylab ko‘rishingiz mumkin. Agar rivojlanishda kechikish bo‘lmasa, 3 yosh hojatxonaga o‘rgatishni boshlash uchun maqbul hisoblangan davrning so‘nggi bosqichidir. Agar u kunduzi siydigini nazorat qila boshlagan bo‘lsa, uxlashdan 1 soat oldin suyuqlik berishni to‘xtatishingiz, uyqudan oldin hojatxonaga borishini ta’minlashingiz va tunda uxlayotganda tagligini yechishingiz kerak. Chunki kunduzi o‘zini nazorat qila oladigan bolaga kechasi taglik taqish bir-biriga zid yondashuv bo‘lib, muvaffaqiyatga erishishni kechiktirishi mumkin. Uyqusi qattiq bolalarda tungi nazorat biroz qiyinroq kechishi mumkin. Biroq bir muddat atrofning ifloslanishiga ko‘z yumishingiz jarayonni tezlashtiradi va bolaning chalg‘ib qolishining oldini oladi. Tozalashni osonlashtirish uchun yotoqqa mo‘ljallangan himoya tagliklaridan foydalanishingiz mumkin.') WHERE id = '10d272f3-fd20-44b4-9b09-1b4398b61ba5';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda farzandingizning ovqat tanlashi kundan kunga o‘zgarishi mumkin: bir kuni yoqtirib yegan taomini boshqa kuni rad etishi ehtimol. Eng muhimi, dasturxonda unga turli xil foydali mahsulotlarni taklif qiling, nimani va qancha yeyishini esa o‘zi tanlasin. U yaxshi biladigan va sevimli taomlari bilan birga, vaqti-vaqti bilan yangi taomdan kichik bir bo‘lak tatib ko‘rishga ham undashingiz kerak. Biroq uni majburlamaslik juda muhim. Yangi tatib ko‘rgan mahsulotidan darhol bir porsiya yeyishini kutmang. U biror mahsulotni yoqtirish yoki yoqtirmasligini kamida 6-7 marta sinab ko‘rgandan keyingina bilishingiz mumkin. Farzandingiz har bir ovqatlanishda oqsil, don mahsulotlari va sabzavotlar guruhiga mansub oziq-ovqatlarni iste’mol qilishi uning salomatligi uchun muhim. Tamaddiga shokolad va shirin mahsulotlar o‘rniga meva berish foydaliroq bo‘ladi.') WHERE id = 'ac9f56dc-94bf-4adb-a7ed-1d15446f273b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar 3 yosh inqirozini boshdan kechirayotgan farzandingiz o‘zini yerga tashlab, qichqirsa, qilishingiz mumkin bo‘lgan eng yaxshi ish — xotirjamlikni saqlash. Albatta, buni aytish oson, amalga oshirish esa qiyin. Biroq bolalar odatda sizning xatti-harakatlaringizni takrorlaydi. Inqiroz paytida xotirjam qolsangiz, farzandingizga kelajakda muammoga duch kelganida his-tuyg‘ularini boshqara olishini o‘rgatgan bo‘lasiz. 3 yoshga to‘lgan chaqalog‘ingiz mustaqilligini isbotlash uchun turli yo‘llarni sinab ko‘rishi mumkin. Nojo‘ya oqibatlar yuzaga kelmasligi uchun, sizga yoqmaydigan xatti-harakatlar bo‘lsa ham, jiddiy zarurat tug‘ilmaguncha aralashmasligingiz va unga ayrim ishlarni mustaqil bajarishga imkon berishingiz kerak. Bu davrda ota-onalar bolalar kiyimlarini o‘zlari tanlashni istashidan shikoyat qiladilar. Bunday hollarda mutaxassislar bolaga taklif etilgan variantlar orasidan tanlash imkonini berishni tavsiya qiladilar. Xavotir olmang, bu davr uzoq davom etmaydi! 😊') WHERE id = '77d3682e-ed32-46fd-bdc5-b4fcebf4896e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'So‘nggi paytlarda farzandingizning nutqiy rivojlanishida yangi sakrashlar kuzatilmoqda. Endi u gapirayotganda tuzgan jumlalari grammatik jihatdan shakllanayotganini kuzatishingiz mumkin. Shuningdek, u fikrlar o‘rtasidagi sabab-oqibat bog‘liqligini tushuna boshlagan. Uning so‘z boyligi o‘rtacha 300 ta turli so‘zdan iborat. U o‘zi bilan o‘zi, siz, o‘yinchoqlari va do‘stlari bilan uzoq vaqt gaplashishi mumkin. Yangi so‘zlarga qiziqishi ortgan. "Va" bog‘lovchisining gaplarda qanday maqsadda ishlatilishini anglay boshlagan. Hozirgi va kelasi zamonni, "men", "sen" kabi olmoshlarni tushunadi. Oddiy ko‘makchilar va olmoshlarni avvalgiga qaraganda to‘g‘riroq ishlatadi. Ranglarning nomlarini o‘rganmoqda, ammo rangni uning nomi bilan hali to‘liq va aniq moslashtira olmasligi mumkin. Masalan, qizil va pushti yoki sariq va to‘q sariq kabi bir-biriga yaqin ranglarni adashtirishi mumkin.') WHERE id = 'a7f6f0c5-f1b1-4f0e-b9c2-28b4975c766e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Deyarli 3 yoshga to‘lgan chaqalog‘ingiz bajara oladigan va eng ko‘p zavq oladigan mashg‘ulotlardan biri rasmlarni bo‘yashdir. Bo‘yash farzandingizning qo‘l-ko‘z muvofiqligini yaxshilash bilan birga, buyumlarni anglash qobiliyatini ham rivojlantiradi. Rasm chizish ham murakkab, ham qiyin jarayon bo‘lgani uchun unga qiziqarli bo‘yoqlar tanlashingiz va erkin rasm chizishi uchun joy yaratishingiz kerak. Mumli bo‘yoqlardan xavfsiz foydalanishingiz mumkin; buning uchun yo‘g‘onroq jumbo bo‘yoqlarni tanlash tavsiya etiladi. Chunki bola bo‘yashni yoqtirishi mumkin, ammo bo‘yoq to‘g‘ri tanlanmasa, bu mashg‘ulot uning uchun qiziqarsiz bo‘lib qoladi. Agar rangli qalam sotib olmoqchi bo‘lsangiz, bunda ham katta (jumbo) o‘lchamdagilarini tanlang. Bo‘yash paytida barmoqlarini bemalol harakatlantira olishi farzandingiz uchun eng muhim jihatlardan biridir.') WHERE id = 'ce9d6e51-8832-4d9d-bbb8-766b28abc2e6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bu bosqichda ayrim ishlarni mustaqil bajarishni o‘rgansa-da, hali hamma narsani uddalash uchun yetarli jismoniy qobiliyatga ega emas. Xuddi shuningdek, ko‘proq so‘zlarni bilsa va hatto ayrim gaplarni tuza olsa ham, hali barcha his-tuyg‘u va fikrlarini og‘zaki ifodalash ko‘nikmasini to‘liq egallamagan. Shu sababli biror ishni o‘zi xohlagandek bajara olmaganda yoki o‘zini tushuntira olmaganda, ba’zan jahli chiqib, keskin norozilik bildirishi mumkin. Jismoniy va nutqiy ko‘nikmalari cheklanganligi tufayli o‘zini to‘liq ifodalay olmaslik unda zo‘riqish uyg‘otadi. Shuningdek, zerikish, charchoq va ochlik kabi ehtiyojlarini har doim ham so‘z bilan aytishni bilmagani uchun baqirish, yig‘lash yoki o‘zini yerga tashlash orqali ehtiyojini bildirishga va sizdan uni tushunishingizni so‘rashga urinishi mumkin. Bularni bilishingiz va bunday holat shu yoshdagi bolalar uchun odatiy ekanini tushunishingiz farzandingizga bo‘lgan munosabatingizda katta ahamiyatga ega. Jahl va yig‘i xurujlari kamroq kuzatilishi uchun farzandingizga jahlingizni chiqarish o‘rniga, turli hissiy mashg‘ulotlar yordamida unga o‘z tuyg‘ularini tushunish va bir-biridan farqlashni o‘rgatishingiz mumkin. Bu unga his-tuyg‘u va fikrlarini maqbulroq usulda ifodalashga yordam beradi.') WHERE id = 'bc00e9df-4632-4728-bd4b-cc292b91d13e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Qoidalar va intizom farzandingiz kelajakda muvaffaqiyatliroq bo‘lishi uchun samarali tarbiyaning ajralmas qismidir. Chegaralar aniq va qat’iy belgilangan muhit farzandingizning rivojlanishini eng maqbul tarzda qo‘llab-quvvatlaydi. Qoidalar farzandingizning erkinligini cheklamaydi, aksincha, uning xavfsiz muhitda mustaqil bo‘lishiga, yaxshi bilan yomonni, to‘g‘ri bilan noto‘g‘rini farqlashiga va o‘zini boshqarish ko‘nikmasini shakllantirishiga yordam beradi. Biroq bu qoidalar muayyan tizimga asoslanishi va izchil qo‘llanishi juda muhim. Bir kuni ruxsat bergan narsangizga ertasi kuni ruxsat bermasligingiz farzandingizning qoidalarga bo‘lgan hurmatiga putur yetkazadi. Asossiz cheklovlar ham farzandingiz bu vaziyatni tushunmasligi va norozilik bildirishiga sabab bo‘lishi mumkin. Ammo tushunarli va sababini izohlash mumkin bo‘lgan vaziyatlar uchun belgilangan qoidalar farzandingiz uchun ancha asosli va ularga amal qilish osonroq bo‘ladi.') WHERE id = 'daec4206-a96e-46c2-8e87-38016160371c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Baliq qanchalik foydali ekanini bilsangiz ham, farzandingizni uni yeyishga qanday ko‘ndirishni bilmasligingiz mumkin. Avvalo, bu barcha oziq-ovqatlarga taalluqli bo‘lgani kabi, farzandingiz biror taomga ko‘nikishi va uni yoqtirib qolishi uchun o‘sha mahsulotni 10-20 marta ko‘rishi, uning oilaviy dasturxonda tez-tez iste’mol qilinishiga guvoh bo‘lishi kerak. Baliq boshqa mahsulotlarga qaraganda kattalar tomonidan ham kamroq iste’mol qilingani uchun farzandingizning unga ko‘nikish jarayoni boshqa oziq-ovqatlarga nisbatan ko‘proq vaqt olishi tabiiy. Hozir farzandingiz o‘jarlik qiladigan va ko‘plab taomlarni rad etishga moyil bo‘lgan davrda ekanini unutmasligingiz kerak. Shu bois taom tanlaydigan davrida farzandingizning baliqni rad etishi uning ta’mini yoqtirmasligi yoki uni hech qachon yoqtirmasligini anglatmaydi. Boshqa go‘shtlardan farqli ravishda, baliq ko‘pincha butun holda tortiladi. Farzandingiz baliqning boshi, dumi va unga qarab turgandek ko‘rinadigan ko‘zlaridan cho‘chishi mumkin. Agar farzandingizda ham shunday bo‘lsa, baliqni dasturxonga tortishda uni file yoki bo‘laklar shaklida tayyorlashingiz foydali bo‘lishi mumkin.') WHERE id = '3ce2c11b-ecd0-47c6-af07-b3a6d4a2ed23';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning nutq qobiliyati yanada rivojlangani uchun bu davrda sizga ko‘plab savollar bera boshlashi mumkin. “Barglar nega to‘kiladi?”, “Quyosh nega sariq?” yoki “Dengiz nega ko‘k?” kabi bilim olishga qaratilgan savollarni eshitishingiz mumkin. Bu davrda farzandingiz “o‘xshash” va “farqli” tushunchalarini ham anglay boshlaydi, buyumlarning o‘lchami, shakli va rangini taqqoslab, ularni farqlaydi. Tasavvuri jadal rivojlanayotgani sababli u taqlidga asoslangan o‘yinlarni endi yanada ijodkorona o‘ynayotganini kuzatishingiz mumkin. Shu bilan birga, rivojlanayotgan tasavvuri tufayli ilgari bo‘lmagan qo‘rquvlar paydo bo‘lishi mumkin. Masalan, u uy ichida yashirinib yurgan maxluq borligiga ishonishi yoki tunda u bilan birga uxlaydigan xayoliy o‘rtoq bor deb o‘ylashi mumkin. Shuningdek, siz aytib bergan hikoyalarning ayrim qismlarini bir muddatdan keyin eslab, xotirasida qolgan parchalarni sizga so‘zlab berayotganiga guvoh bo‘lishingiz mumkin.') WHERE id = 'd3b957d4-3ab1-417b-8bbe-00cb8a21a286';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz mansub bo‘lgan 2-6 yosh guruhidagi bolalarning taxminan 5%ida duduqlanish deb ataladigan nutq nuqsoni kuzatilishi mumkin. Hatto ushbu yosh guruhidagi 3-4 yoshli bolalarda fiziologik duduqlanish deb ataladigan holat ham paydo bo‘lishi mumkin. O‘g‘il bolalarda esa duduqlanish muammosi qizlarga nisbatan deyarli 2 marta ko‘proq uchraydi. Mutaxassislarning ta’kidlashicha, duduqlanish kabi nutq muammolari oilada va undan tashqarida jiddiy qiyinchiliklar, shuningdek, turli moslashuv muammolariga olib keladi. Shu sababli oilaviy tarixda ham nutq nuqsonlari bo‘lsa, albatta mutaxassisdan yordam olish muhim. Mutaxassisga kechiktirmasdan murojaat qilinsa va erta aralashuv amalga oshirilsa, duduqlanish muammosi o‘smirlik davriga yetmasdan 80% holatda tuzalishi mumkin. Agar chaqalog‘ingizda shunday muammo bo‘lsa, bu davrda uni ayblamasligingiz va unga bosim o‘tkazmasligingiz kerak.') WHERE id = '42f63232-fd9a-4cbc-b534-0404c45b38f0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Dukkaklilar tarkibida eng ko‘p kletchatka bo‘lgan oziq-ovqat guruhidir. Shu sababli ular oshqozonning bo‘shash tezligini va ingichka ichakda glyukozaning so‘rilishini sekinlashtirib, qondagi qand miqdorini me’yorda ushlab turadi. Ayni paytda qondagi xolesterin miqdori va qon bosimini ham maqbul darajada saqlashga yordam beradi. Oshqozonda suv bilan birga bo‘kib, to‘qlik hissini beradi va farzandingizning kun davomida zarur bo‘lgan energiya bilan ta’minlanishiga yordam beradi. Shu bilan birga, no‘xat, quruq loviya, brokkoli va gulkaram kabi ayrim sabzavotlar hamda quruq mahsulotlar foydali bo‘lishi bilan birga, gaz hosil qilish xususiyatiga ham ega. Farzandingizning bu mahsulotlarni iste’mol qilishi juda foydali! Ammo ularni ketma-ket va ko‘p miqdorda yemasligiga ishonch hosil qilishingiz kerak. Taom tayyorlash uchun dukkaklilarni ivitgan suvni albatta to‘kib tashlang, so‘ng ularni yaxshilab yuving. Taomlarga bir qoshiq arpabodiyon urug‘i yoki muskat yong‘og‘i qo‘shish ham gaz hosil bo‘lishining oldini olishga yordam beradi.') WHERE id = 'ef688bea-192e-4e4e-8e2b-89b299796329';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bir necha oydan beri yurib, atrofni o‘rganayotgan chaqalog‘ingizda masofa va yo‘nalish tushunchalari bilan birga xotira hamda idrok etish qobiliyatlari ham rivojlangan. Bu davrda u yo‘nalish tushunchalarini o‘rgana boshlaydi. Avval old-orqa kabi oddiy tushunchalarni, keyin esa ust-ost, ichkari-tashqari kabi boshqa qarama-qarshi tushunchalarni o‘rganishi mumkin. Shuningdek, o‘xshashlik va farqlilikni tushunadi, buyumlarning o‘lchami, shakli va rangini taqqoslab, bir-biridan ajrata oladi. Tasavvuri jadal rivojlanayotgani sababli endi taqlidiy o‘yinlarni yanada ijodkorona o‘ynayotganini kuzatishingiz mumkin. Sanalayotgan narsalarni ko‘zi bilan ko‘rmasa, hali ichida sanash qobiliyatiga ega bo‘lmasligi mumkin. O‘yinchoq kublarni 1, 2, 3 deb sanab, ustma-ust qo‘yishni o‘rgatish orqali bu qobiliyatining rivojlanishiga yordam berishingiz mumkin. Biroq uning yoshidan kattaroq bolalarga mo‘ljallangan o‘yin va o‘yinchoqlarni sotib olishdan saqlanishingiz kerak. Chunki bolaning doimo o‘z imkoniyatidan yuqori vazifalarga duch kelishi uning ruhiyatiga salbiy ta’sir ko‘rsatadi; yoshiga mos konstruktorlar va o‘yinlar rivojlanishi uchun ancha foydali bo‘ladi.') WHERE id = '41a7e71a-e46c-4110-ac09-a7e8357cae05';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '[[TARJIMA MUVAFFAQIYATSIZ]] Ushbu bo‘limni qayta ishlashda xatolik yuz berdi. Asl matn boshlanishi: "Farzandingizning til qobiliyati biroz d..."') WHERE id = 'aad2bc69-ad6a-413b-90fa-aefe2a168556';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '[[TARJIMA MUVAFFAQIYATSIZ]] Ushbu bo‘limni qayta ishlashda xatolik yuz berdi. Asl matn boshlanishi: 3 yoshdan boshlab farzandingizni...') WHERE id = '0d5b4196-e611-4d6d-85b3-4906d4cda8aa';
